-- ============================================================ 20261124120000_signin_trace_and_repair.sql
-- 0084 · Sign-in trace reports, and the two sign-in functions missing on the live database.
--
-- Some staff are sent back to the PIN step a few seconds after the e-mailed code was accepted,
-- while the database shows a healthy sign-in (approved, browser key made, never ended). The web
-- app now keeps a short trace of the sign-in in the browser and, when a tab loses its signed-in
-- person without the person choosing it, sends that trace here:
--   * client_event: one row per report (when, who if known, what kind, the trace, the browser).
--     Read by the manager only; nobody writes it directly.
--   * report_client_event(p_kind, p_detail): callable by visitors (anon) too, since the sign-in
--     may already be gone when the report is sent. It refuses a detail over 8 KB and stops taking
--     reports once 300 arrived in the last hour (abuse cap). It never answers anything back.
--   * check_request() (the 0081 gate) lets report_client_event through for a session that is not
--     (or no longer) approved; everything else in the gate is unchanged.
--
-- REPAIR: the live database ran an early draft of 0079 (20261120090000_session_hours.sql), so
-- extend_this_device(text) and signed_in_with_code() are missing there. They are created again
-- here exactly as committed in 0079 (no later migration redefines them), with the same grants.
-- Safe on a database that already has them (create or replace).

-- ---------------------------------------------------------------- 0079 repair
create or replace function signed_in_with_code()
returns boolean
language sql stable set search_path = public
as $$
  select exists (
    select 1
    from jsonb_array_elements(
      case when jsonb_typeof(auth.jwt() -> 'amr') = 'array' then auth.jwt() -> 'amr' else '[]'::jsonb end
    ) a
    where a ->> 'method' in ('otp', 'magiclink', 'email/signup', 'invite', 'recovery')
  )
$$;

create or replace function extend_this_device(p_token text)
returns timestamptz
language plpgsql security definer set search_path = public
as $$
declare
  v_end timestamptz;
begin
  if auth.uid() is null then
    return null;
  end if;
  update trusted_device
     set expires_at = now() + make_interval(hours => session_hours()), last_used_at = now()
   where token_hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex')
     and user_id = auth.uid() and revoked_at is null and expires_at > now()
  returning expires_at into v_end;
  return v_end;
end
$$;

grant execute on function signed_in_with_code(), extend_this_device(text) to authenticated;
revoke execute on function signed_in_with_code(), extend_this_device(text) from anon, public;

-- ---------------------------------------------------------------- reports from the browser
create table if not exists client_event (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  -- the signed-in person when the request still carried a valid sign-in, else null
  user_id uuid,
  -- the username the tab held (said by the browser, not checked)
  username text,
  kind text not null,
  detail jsonb not null default '{}'::jsonb,
  user_agent text
);
create index if not exists client_event_at_idx on client_event (at desc);
alter table client_event enable row level security;
revoke all on client_event from anon, authenticated;
grant select on client_event to authenticated;
drop policy if exists client_event_manager_reads on client_event;
create policy client_event_manager_reads on client_event
  for select to authenticated using (is_manager());

create or replace function report_client_event(p_kind text, p_detail jsonb)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_detail jsonb := coalesce(p_detail, '{}'::jsonb);
  v_agent text;
begin
  if coalesce(p_kind, '') !~ '^[a-z0-9_.-]{1,40}$' then
    raise exception 'unknown kind' using errcode = '22023';
  end if;
  if octet_length(v_detail::text) > 8192 then
    raise exception 'detail too large (8 KB at most)' using errcode = '22023';
  end if;
  if (select count(*) from client_event where at > now() - interval '1 hour') >= 300 then
    raise exception 'too many reports, try later' using errcode = '54000';
  end if;
  begin
    v_agent := left(current_setting('request.headers', true)::jsonb ->> 'user-agent', 300);
  exception when others then
    v_agent := null; -- no request headers (SQL editor, tests)
  end;
  insert into client_event (user_id, username, kind, detail, user_agent)
  values (
    auth.uid(),
    left(nullif(trim(case when jsonb_typeof(v_detail -> 'username') = 'string'
                          then v_detail ->> 'username' end), ''), 60),
    p_kind,
    v_detail,
    v_agent
  );
  -- housekeeping: reports are kept 90 days
  delete from client_event where at < now() - interval '90 days';
end
$$;

revoke all on function report_client_event(text, jsonb) from public;
grant execute on function report_client_event(text, jsonb) to anon, authenticated;

-- ---------------------------------------------------------------- the gate (0081) + report_client_event
-- Copied from 20261122090000_session_approval.sql; the only change is report_client_event in
-- the list of calls allowed before the approval or after the end.
create or replace function check_request()
returns void
language plpgsql stable set search_path = public
as $$
declare
  v_reason text;
begin
  if current_user is distinct from 'authenticated' then
    return; -- anon (visitors, public forms) and service_role (Edge Functions) are not touched
  end if;
  if not enforce_code_on() then
    return; -- kill switch
  end if;
  -- The only calls the app makes before the approval or after the end: sign-in (record_sign_in,
  -- use_trusted_device), the first PIN (my_must_change_pin, mark_pin_changed), activity and
  -- sign-out (touch_session, end_session, revoke_this_device, session_status), and the sign-in
  -- trace sent when a tab lost its sign-in (report_client_event). Each of them checks for itself
  -- what it may do; none of them reads or changes clinic data.
  if coalesce(current_setting('request.path', true), '') ~
     '^(/rest/v1)?/rpc/(record_sign_in|use_trusted_device|my_must_change_pin|mark_pin_changed|touch_session|end_session|revoke_this_device|session_status|report_client_event)/?$'
  then
    return;
  end if;
  v_reason := session_reason();
  if v_reason = 'ok' then
    return;
  end if;
  if v_reason = 'idle' then
    raise exception 'signed out after % hours without activity', session_hours()
      using errcode = 'PT401', hint = 'idle';
  end if;
  if v_reason = 'ended' then
    raise exception 'signed out: sign in again with the e-mailed code'
      using errcode = 'PT401', hint = 'ended';
  end if;
  raise exception 'sign-in not approved: sign in again with the e-mailed code'
    using errcode = 'PT401', hint = 'code_required';
end
$$;

grant execute on function check_request() to anon, authenticated, service_role;


-- ============================================================ 20261125090000_document_details.sql
-- 0084 · What the printed documents need: date of birth, phone, insurer, member number, weight,
-- allergies, the visit's reference, the prescriber's registration number and prescription numbers.
--
-- Frank: "Make the printed documents show date of birth, phone and member number". The document
-- builders (commit 35ad0aa) accept these fields; the screens could not read most of them.
--
--   * A  REGISTRATION NUMBER. profiles.registration_no (professional council number) and
--        profiles.registration_body (RMDC, NCNM, NPC, RAHPC…). Saved by the manager through the
--        manage-staff function, like the specialty. Read in staff_directory (manager),
--        my_placement() and my_session_profile() (the person themselves), and with each
--        prescriber / result author in visit_clinical, lab_worklist and desk_orders.
--   * B  VISIT REFERENCE. encounter.reference V-YYYY-NNNNNN (Kigali year of arrival), given when the
--        visit opens, existing visits numbered in order of arrival. The medical report prints
--        MR-{reference}.
--   * C  NO KNOWN ALLERGIES. patient.allergies_none: the nurse or doctor recorded "no known
--        allergies" (update_patient with allergies_none = true). Three states: allergies (text),
--        none (allergies_none), not recorded (neither). Writing an allergy clears "none".
--   * D  PRESCRIPTION NUMBERS. prescription_number(encounter): RX-YYYY-NNNNNN, one per printed
--        prescription of a visit, kept in prescription_doc (number, visit, lines, who, when). The
--        same number comes back while no line was added since; a new line gives a new number.
--        Rights: whoever reads the visit's prescriptions (prescription.read or clinical.read).
--   * E  DOCUMENT DETAILS in the existing reads (no new endpoint for reading):
--        visit_clinical:  patient + birthDate, sex, phone, insurer, memberNo, coveragePct,
--                         weightKg, weightAt, allergiesNone; visit {reference, at, …};
--                         prescriptions[].prescriber, orders[].result.byPerson
--        patient_file:    document {…the same patient details…}, visits[].reference
--        lab_worklist / desk_orders: the same patient details, visitReference, resultByPerson
--        visit_bill:      member_no, coverage_pct and the latest payment (receipt_no, method…)
--
-- Errcodes: 42501 not allowed, 22023 bad input (hint no_lines: nothing prescribed), P0002 not found.

-- ---------------------------------------------------------------- A registration number
alter table profiles add column if not exists registration_no text;
alter table profiles add column if not exists registration_body text;
alter table profiles drop constraint if exists profiles_registration_no_len;
alter table profiles add constraint profiles_registration_no_len
  check (registration_no is null or char_length(registration_no) between 1 and 40);
alter table profiles drop constraint if exists profiles_registration_body_len;
alter table profiles add constraint profiles_registration_body_len
  check (registration_body is null or char_length(registration_body) between 1 and 60);
comment on column profiles.registration_no is
  'Professional council registration number (RMDC, NCNM, Pharmacy Council…), printed on prescriptions and reports.';
comment on column profiles.registration_body is 'The council that registered the person (RMDC, NCNM, NPC, RAHPC…).';

-- the lists leave former employees out (0076); the registration is added at the end
create or replace view staff_directory with (security_invoker = true) as
  select p.id, p.username, p.full_name, p.role, p.station, p.dashboard, p.head_of, p.language, p.phone,
         p.active, p.must_change_pin, p.last_sign_in_at, p.pin_changed_at, p.deactivated_at, p.created_at,
         p.staff_id, p.email, p.department_id, d.name as department_name, p.position, p.specialty,
         coalesce((select jsonb_agg(jsonb_build_object('id', dd.id, 'name', dd.name, 'position', sd.position)
                                    order by (sd.department_id = p.department_id) desc, dd.name)
                   from staff_department sd join department dd on dd.id = sd.department_id and dd.deleted_at is null
                   where sd.profile_id = p.id), '[]'::jsonb) as departments,
         p.registration_no, p.registration_body
  from profiles p
  left join department d on d.id = p.department_id and d.deleted_at is null
  where p.deleted_at is null;

create or replace function my_placement()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'position', p.position, 'department', d.name, 'departmentId', d.id,
    'specialty', p.specialty, 'station', p.station,
    'registrationNo', p.registration_no, 'registrationBody', p.registration_body,
    'departments', coalesce((select jsonb_agg(jsonb_build_object('id', dd.id, 'name', dd.name, 'position', sd.position)
                                              order by (sd.department_id = p.department_id) desc, dd.name)
                             from staff_department sd join department dd on dd.id = sd.department_id and dd.deleted_at is null
                             where sd.profile_id = p.id), '[]'::jsonb)
  )
  from profiles p
  left join department d on d.id = p.department_id and d.deleted_at is null
  where p.id = auth.uid()
$$;

create or replace function my_session_profile()
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v profiles%rowtype;
begin
  select * into v from profiles where id = auth.uid();
  if not found or not v.active then
    raise exception 'this account is deactivated; ask the manager' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'id', v.id, 'username', v.username, 'full_name', v.full_name, 'role', v.role,
    'station', v.station, 'dashboard', v.dashboard, 'head_of', v.head_of,
    'language', v.language, 'must_change_pin', v.must_change_pin,
    'staff_id', v.staff_id, 'email', v.email,
    'specialty', v.specialty, 'registration_no', v.registration_no, 'registration_body', v.registration_body
  );
end
$$;

-- One staff member as a document prints them: name, role, specialty or title, registration.
create or replace function doc_person(p_profile_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object('id', p.id, 'name', p.full_name, 'role', p.role, 'specialty', p.specialty,
                            'registrationNo', p.registration_no, 'registrationBody', p.registration_body)
  from profiles p where p.id = p_profile_id
$$;

-- ---------------------------------------------------------------- B visit reference
alter table encounter add column if not exists reference text;

create or replace function assign_visit_reference()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_year integer := extract(year from (coalesce(new.arrived_at, now()) at time zone 'Africa/Kigali'))::integer;
begin
  if new.reference is null then
    new.reference := 'V-' || v_year || '-' || lpad(next_number('visit', v_year)::text, 6, '0');
  end if;
  return new;
end
$$;
drop trigger if exists trg_visit_reference on encounter;
create trigger trg_visit_reference before insert on encounter
  for each row execute function assign_visit_reference();

-- existing visits: numbered in order of arrival, per year (no audit row, no "updated" stamp)
alter table encounter disable trigger trg_audit;
alter table encounter disable trigger trg_touch;
with n as (
  select e.id, y.year,
         row_number() over (partition by y.year order by e.arrived_at, e.created_at, e.id)
           + coalesce((select s.last from number_series s where s.key = 'visit' and s.year = y.year), 0) as k
  from encounter e
  cross join lateral (select extract(year from (e.arrived_at at time zone 'Africa/Kigali'))::integer as year) y
  where e.reference is null
)
update encounter e set reference = 'V-' || n.year || '-' || lpad(n.k::text, 6, '0')
from n where e.id = n.id;
alter table encounter enable trigger trg_audit;
alter table encounter enable trigger trg_touch;
insert into number_series (key, year, last)
select 'visit', split_part(reference, '-', 2)::integer, max(split_part(reference, '-', 3)::integer)
from encounter where reference ~ '^V-[0-9]{4}-[0-9]+$'
group by 2
on conflict (key, year) do update set last = greatest(number_series.last, excluded.last);
create unique index if not exists encounter_reference_uq on encounter (reference);

-- The visit as a document prints it: reference, when, the service, the department, who referred.
create or replace function doc_visit(p_encounter_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'id', e.id, 'reference', e.reference, 'at', e.arrived_at, 'status', e.status, 'closedAt', e.closed_at,
    'service', e.service,
    'department', (select d.name from queue_entry q join department d on d.id = q.department_id
                   where q.encounter_id = e.id and q.deleted_at is null order by q.created_at desc limit 1),
    'referredBy', (select pr.full_name from queue_entry q join profiles pr on pr.id = q.referred_by
                   where q.encounter_id = e.id and q.deleted_at is null order by q.created_at desc limit 1))
  from encounter e where e.id = p_encounter_id
$$;

-- ---------------------------------------------------------------- C no known allergies
alter table patient add column if not exists allergies_none boolean not null default false;
comment on column patient.allergies_none is
  'The nurse or doctor recorded "no known allergies". allergies (text) = known allergies; neither = not recorded.';

create or replace function update_patient(p_patient_id uuid, p_fields jsonb)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_birth date := nullif(p_fields ->> 'birth_date', '')::date;
  v_age integer := nullif(p_fields ->> 'age_years', '')::integer;
  v_allergies text := nullif(trim(coalesce(p_fields ->> 'allergies', '')), '');
  v_none boolean;
begin
  if not has_perm('patient.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_fields ? 'extra' and jsonb_typeof(p_fields -> 'extra') <> 'object' then
    raise exception 'extra must be an object' using errcode = '22023';
  end if;
  if p_fields ? 'allergies_none' and jsonb_typeof(p_fields -> 'allergies_none') not in ('boolean', 'null') then
    raise exception 'allergies_none must be true or false' using errcode = '22023';
  end if;
  v_none := coalesce((p_fields ->> 'allergies_none')::boolean, false);
  if v_birth is null and v_age is not null then
    v_birth := (current_date - make_interval(years => v_age))::date;
  end if;
  update patient set
    surname = coalesce(nullif(trim(p_fields ->> 'surname'), ''), surname),
    given_names = coalesce(nullif(trim(p_fields ->> 'given_names'), ''), given_names),
    sex = coalesce((p_fields ->> 'sex')::sex, sex),
    birth_date = coalesce(v_birth, birth_date),
    age_estimated = case when v_birth is not null then (v_age is not null and (p_fields ->> 'birth_date') is null) else age_estimated end,
    national_id = case when p_fields ? 'national_id' then nullif(regexp_replace(coalesce(p_fields ->> 'national_id', ''), '[^0-9]', '', 'g'), '') else national_id end,
    phone_1 = case when p_fields ? 'phone_1' then nullif(trim(p_fields ->> 'phone_1'), '') else phone_1 end,
    phone_2 = case when p_fields ? 'phone_2' then nullif(trim(p_fields ->> 'phone_2'), '') else phone_2 end,
    district = case when p_fields ? 'district' then nullif(trim(p_fields ->> 'district'), '') else district end,
    sector = case when p_fields ? 'sector' then nullif(trim(p_fields ->> 'sector'), '') else sector end,
    cell = case when p_fields ? 'cell' then nullif(trim(p_fields ->> 'cell'), '') else cell end,
    village = case when p_fields ? 'village' then nullif(trim(p_fields ->> 'village'), '') else village end,
    occupation = case when p_fields ? 'occupation' then nullif(trim(p_fields ->> 'occupation'), '') else occupation end,
    emergency_name = case when p_fields ? 'emergency_name' then nullif(trim(p_fields ->> 'emergency_name'), '') else emergency_name end,
    emergency_phone = case when p_fields ? 'emergency_phone' then nullif(trim(p_fields ->> 'emergency_phone'), '') else emergency_phone end,
    blood_group = case when p_fields ? 'blood_group' then nullif(trim(p_fields ->> 'blood_group'), '') else blood_group end,
    -- an allergy written wins; "no known allergies" clears the text
    allergies = case when v_allergies is not null then v_allergies
                     when p_fields ? 'allergies' then null
                     when v_none then null
                     else allergies end,
    allergies_none = case when v_allergies is not null then false
                          when p_fields ? 'allergies_none' then v_none
                          else allergies_none end,
    notes = case when p_fields ? 'notes' then nullif(trim(p_fields ->> 'notes'), '') else notes end,
    ubudehe_category = case when p_fields ? 'ubudehe_category' then nullif(p_fields ->> 'ubudehe_category', '')::smallint else ubudehe_category end,
    language = coalesce((p_fields ->> 'language')::lang, language),
    preferred_channel = coalesce((p_fields ->> 'preferred_channel')::contact_channel, preferred_channel),
    -- Replace the whole map; the app always sends the full set of extra values.
    extra = case when p_fields ? 'extra' then p_fields -> 'extra' else extra end
  where id = p_patient_id and deleted_at is null;
  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;
end
$$;

-- The patient as a document prints them. With a visit: that visit's insurer (cash = none) and
-- the weight measured at that visit, else the last one in the 90 days before it. Without a
-- visit (the patient file): the current insurance and the last weight ever measured.
create or replace function doc_patient(p_patient_id uuid, p_encounter_id uuid default null)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'birthDate', p.birth_date, 'ageEstimated', p.age_estimated, 'sex', p.sex,
    'phone', coalesce(p.phone_1, p.phone_2),
    'allergies', p.allergies, 'allergiesNone', p.allergies_none and p.allergies is null,
    'bloodGroup', p.blood_group,
    'insurer', cv.insurer, 'insurerType', cv.type, 'memberNo', cv.member_number, 'coveragePct', cv.pct,
    'weightKg', w.value_num, 'weightAt', w.effective_at)
  from patient p
  left join encounter e on e.id = p_encounter_id and e.patient_id = p.id
  left join lateral (
    select py.name as insurer, py.type, c.member_number, pl.coverage_pct as pct
    from coverage c
    join payer py on py.id = c.payer_id and py.type <> 'cash'
    left join plan pl on pl.id = c.plan_id
    where c.deleted_at is null and c.patient_id = p.id
      and c.id = case
        when p_encounter_id is not null then
          coalesce((select i.coverage_id from invoice i where i.encounter_id = p_encounter_id and i.deleted_at is null),
                   e.coverage_id)
        else (select c2.id from coverage c2 join payer py2 on py2.id = c2.payer_id and py2.type <> 'cash'
              where c2.patient_id = p.id and c2.active and c2.deleted_at is null
                and (c2.valid_to is null or c2.valid_to >= (now() at time zone 'Africa/Kigali')::date)
              order by c2.created_at desc limit 1) end
  ) cv on true
  left join lateral (
    select o.value_num, o.effective_at
    from observation o join encounter oe on oe.id = o.encounter_id
    where oe.patient_id = p.id and o.code = 'weight' and o.deleted_at is null and o.value_num is not null
      and (p_encounter_id is null
           or o.encounter_id = p_encounter_id
           or (o.effective_at <= coalesce(e.closed_at, now())
               and o.effective_at >= coalesce(e.arrived_at, now()) - interval '90 days'))
    order by (o.encounter_id = p_encounter_id) desc, o.effective_at desc
    limit 1
  ) w on true
  where p.id = p_patient_id
$$;

-- ---------------------------------------------------------------- D prescription numbers
create table if not exists prescription_doc (
  id uuid primary key default gen_random_uuid(),
  number text not null unique,
  encounter_id uuid not null references encounter (id),
  line_ids uuid[] not null,
  issued_by uuid default auth.uid() references profiles (id) on delete set null,
  issued_at timestamptz not null default now()
);
create index if not exists prescription_doc_encounter_idx on prescription_doc (encounter_id, issued_at desc);
comment on table prescription_doc is
  'Printed prescriptions: RX-YYYY-NNNNNN for a set of prescribed lines of a visit (prescription_number).';
alter table prescription_doc enable row level security;
drop policy if exists prescription_doc_read on prescription_doc;
create policy prescription_doc_read on prescription_doc for select
  using (has_perm('prescription.read') or has_perm('clinical.read'));
revoke insert, update, delete on prescription_doc from authenticated, anon;
grant select on prescription_doc to authenticated;

-- The number of the visit's prescription: the last one issued while it still holds every line
-- prescribed now (no line added since; a cancelled line does not need a new number), else a new
-- RX-YYYY-NNNNNN. With it: the prescriber (the doctor who wrote the lines for the pharmacy, else
-- the first line) and who issued it.
create or replace function prescription_number(p_encounter_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_lines uuid[];
  v_doc prescription_doc%rowtype;
  v_new boolean := false;
  v_year integer := extract(year from (now() at time zone 'Africa/Kigali'))::integer;
  v_prescriber uuid;
begin
  if not (has_perm('prescription.read') or has_perm('clinical.read')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  -- one number at a time per visit (two printers at once get the same one)
  perform 1 from encounter where id = p_encounter_id and deleted_at is null for update;
  if not found then
    raise exception 'visit not found' using errcode = 'P0002';
  end if;
  select coalesce(array_agg(m.id order by m.created_at, m.id), '{}') into v_lines
  from medication_request m
  where m.encounter_id = p_encounter_id and m.deleted_at is null and m.cancelled_at is null;
  if cardinality(v_lines) = 0 then
    raise exception 'nothing is prescribed for this visit' using errcode = '22023', hint = 'no_lines';
  end if;
  select * into v_doc from prescription_doc
  where encounter_id = p_encounter_id order by issued_at desc, number desc limit 1;
  if v_doc.id is null or not (v_lines <@ v_doc.line_ids) then
    insert into prescription_doc (number, encounter_id, line_ids, issued_by)
    values ('RX-' || v_year || '-' || lpad(next_number('prescription', v_year)::text, 6, '0'),
            p_encounter_id, v_lines, auth.uid())
    returning * into v_doc;
    v_new := true;
  end if;
  select coalesce(m.prescriber_id, m.created_by) into v_prescriber
  from medication_request m
  where m.id = any (v_lines)
  order by (m.supply = 'room'), m.created_at
  limit 1;
  return jsonb_build_object(
    'number', v_doc.number, 'issuedAt', v_doc.issued_at, 'issuedById', v_doc.issued_by,
    'issuedBy', (select full_name from profiles where id = v_doc.issued_by),
    'lineIds', to_jsonb(v_doc.line_ids), 'isNew', v_new,
    'prescriber', doc_person(v_prescriber));
end
$$;

-- ---------------------------------------------------------------- E the reads
-- The visit's clinical record (0082), plus what the documents print.
create or replace function visit_clinical(p_encounter_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  -- clinicians; the lab and the pharmacy read the record too (their orders and prescriptions)
  select case when has_perm('clinical.read') or has_perm('orders.read') or has_perm('prescription.read')
              then jsonb_build_object(
    'diagnoses', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'text', c.text, 'icd10', c.icd10_code, 'type', c.type, 'provisional', c.provisional, 'at', c.created_at,
        'by', (select full_name from profiles where id = c.created_by)) order by c.created_at)
      from condition c where c.encounter_id = p_encounter_id and c.deleted_at is null), '[]'::jsonb),
    'notes', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'text', o.value_text, 'at', o.effective_at,
        'by', (select full_name from profiles where id = o.performer_id)) order by o.effective_at)
      from observation o where o.encounter_id = p_encounter_id and o.code = 'note' and o.deleted_at is null), '[]'::jsonb),
    'prescriptions', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'by', (select full_name from profiles where id = coalesce(m.prescriber_id, m.created_by)), 'item', i.name_generic || coalesce(' ' || i.strength, ''), 'dose', m.dose, 'route', m.route,
        'frequency', m.frequency, 'days', m.duration_days, 'quantity', m.quantity, 'instructions', m.instructions, 'at', m.created_at,
        'dispensed', m.supply = 'room' or exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null),
        'supply', m.supply, 'givenAt', m.given_at, 'givenBy', (select full_name from profiles where id = m.given_by),
        'notGivenAt', m.not_given_at, 'notGivenReason', m.not_given_reason,
        'prescriberId', coalesce(m.prescriber_id, m.created_by), 'pending', rx_pending(m),
        'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
        'cancelledBy', (select full_name from profiles where id = m.cancelled_by),
        'prescriber', doc_person(coalesce(m.prescriber_id, m.created_by))) order by m.created_at)
      from medication_request m join item i on i.id = m.item_id where m.encounter_id = p_encounter_id and m.deleted_at is null), '[]'::jsonb),
    'orders', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'test', s.name_en, 'category', r.category, 'station', coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end), 'status', r.status, 'reason', r.reason, 'at', r.created_at,
        'result', (select jsonb_build_object('findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
          'corrected', d.corrected_at is not null, 'correctionReason', d.correction_reason,
          'at', coalesce(d.verified_at, d.updated_at), 'by', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
          'byPerson', doc_person(coalesce(d.verified_by, d.created_by)))
          from diagnostic_report d where d.service_request_id = r.id and d.deleted_at is null)) order by r.created_at)
      from service_request r join service s on s.id = r.service_id where r.encounter_id = p_encounter_id and r.deleted_at is null), '[]'::jsonb),
    'patient', (select jsonb_build_object('id', p.id, 'allergies', p.allergies, 'bloodGroup', p.blood_group, 'notes', p.notes, 'flags', p.flags)
                       || doc_patient(p.id, e.id)
      from encounter e join patient p on p.id = e.patient_id where e.id = p_encounter_id),
    'visit', doc_visit(p_encounter_id)
  ) else null end
$$;

-- The patient file (0017), plus the document details and each visit's reference.
create or replace function patient_file(p_patient_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_patient jsonb;
  v_visits jsonb;
  v_vitals jsonb;
  v_conditions jsonb;
  v_bills jsonb;
begin
  if not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select to_jsonb(p) - 'photo_blob_id' - 'merged_into' - 'guardian_patient_id' into v_patient
  from patient p where p.id = p_patient_id and p.deleted_at is null;
  if v_patient is null then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', e.id, 'reference', e.reference, 'arrivedAt', e.arrived_at, 'status', e.status, 'type', e.type,
      'triage', e.triage_level, 'triageReason', e.triage_reason,
      'practitioner', (select names from practitioner where id = e.practitioner_id),
      'stations', (select coalesce(jsonb_agg(distinct q.station::text), '[]'::jsonb) from queue_entry q where q.encounter_id = e.id and q.deleted_at is null),
      'currentStation', (select q.station from queue_entry q where q.encounter_id = e.id and q.finished_at is null and q.deleted_at is null order by q.created_at desc limit 1),
      'diagnosis', (select c.text from condition c where c.encounter_id = e.id and c.type = 'primary' and c.deleted_at is null order by c.created_at desc limit 1),
      'total', (select i.total from invoice i where i.encounter_id = e.id),
      'balance', (select invoice_balance(i.id) from invoice i where i.encounter_id = e.id),
      'billStatus', (select i.status from invoice i where i.encounter_id = e.id),
      'closedAt', e.closed_at
    ) order by e.arrived_at desc), '[]'::jsonb) into v_visits
  from encounter e where e.patient_id = p_patient_id and e.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'encounterId', o.encounter_id, 'code', o.code, 'value', o.value_num, 'text', o.value_text,
      'unit', o.unit, 'at', o.effective_at, 'by', (select full_name from profiles where id = o.performer_id)
    ) order by o.effective_at desc), '[]'::jsonb) into v_vitals
  from observation o join encounter e on e.id = o.encounter_id
  where e.patient_id = p_patient_id and o.deleted_at is null and o.code <> 'note';

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'encounterId', c.encounter_id, 'text', c.text, 'icd10', c.icd10_code, 'type', c.type,
      'provisional', c.provisional, 'at', c.created_at, 'by', (select full_name from profiles where id = c.created_by)
    ) order by c.created_at desc), '[]'::jsonb) into v_conditions
  from condition c join encounter e on e.id = c.encounter_id
  where e.patient_id = p_patient_id and c.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'invoiceId', i.id, 'encounterId', i.encounter_id, 'number', i.number, 'status', i.status,
      'total', i.total, 'patientShare', i.patient_share, 'insurerShare', i.insurer_share,
      'balance', invoice_balance(i.id), 'payer', (select name from payer where id = i.payer_id),
      'at', i.created_at
    ) order by i.created_at desc), '[]'::jsonb) into v_bills
  from invoice i join encounter e on e.id = i.encounter_id
  where e.patient_id = p_patient_id and i.deleted_at is null;

  return jsonb_build_object('patient', v_patient, 'visits', v_visits, 'vitals', v_vitals,
                            'conditions', v_conditions, 'bills', v_bills,
                            'document', doc_patient(p_patient_id, null));
end
$$;

-- The lab / ultrasound worklist (0063), plus what the result report prints.
create or replace function lab_worklist(p_scope text default 'open')
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(x.j order by x.prio, x.at), '[]'::jsonb)
  from (
    select r.priority as prio, r.created_at as at, doc_patient(p.id, e.id) || jsonb_build_object(
      'id', r.id, 'encounterId', r.encounter_id, 'patientId', p.id,
      'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
      'sex', p.sex, 'birthDate', p.birth_date,
      'ticket', (select q.ticket_no from queue_entry q where q.encounter_id = r.encounter_id order by q.created_at limit 1),
      'triage', e.triage_level,
      'test', s.name_en, 'category', r.category, 'status', r.status, 'priority', r.priority,
      'reason', r.reason, 'orderedAt', r.created_at,
      'orderedBy', (select full_name from profiles where id = r.requester_id),
      'findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
      'corrected', d.corrected_at is not null,
      'resultAt', coalesce(d.verified_at, d.updated_at),
      'resultBy', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
      'resultByPerson', doc_person(coalesce(d.verified_by, d.created_by)),
      'visitReference', e.reference, 'visitAt', e.arrived_at
    ) as j
    from service_request r
    join encounter e on e.id = r.encounter_id and (p_scope = 'done' or e.status = 'open')
    join patient p on p.id = e.patient_id
    join service s on s.id = r.service_id
    left join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
    where r.deleted_at is null and has_perm('orders.read')
      and r.category = any (my_test_categories()) and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) in ('laboratory', 'ultrasound')
      and case when p_scope = 'done'
            then r.status in ('resulted', 'verified')
                 and (coalesce(d.verified_at, d.updated_at) at time zone 'Africa/Kigali')::date
                     = (now() at time zone 'Africa/Kigali')::date
            else r.status not in ('verified', 'cancelled') end
  ) x
$$;

-- Orders waiting at a desk other than the lab (0059), with the same details.
create or replace function desk_orders(p_station station)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(x.j order by x.prio, x.at), '[]'::jsonb)
  from (
    select r.priority as prio, r.created_at as at, doc_patient(p.id, e.id) || jsonb_build_object(
      'id', r.id, 'encounterId', r.encounter_id, 'patientId', p.id,
      'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
      'sex', p.sex, 'birthDate', p.birth_date,
      'ticket', (select q.ticket_no from queue_entry q where q.encounter_id = r.encounter_id order by q.created_at limit 1),
      'triage', e.triage_level,
      'test', s.name_en, 'category', r.category, 'status', r.status, 'priority', r.priority,
      'reason', r.reason, 'orderedAt', r.created_at,
      'orderedBy', (select full_name from profiles where id = r.requester_id),
      'findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
      'resultAt', coalesce(d.verified_at, d.updated_at),
      'resultBy', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
      'resultByPerson', doc_person(coalesce(d.verified_by, d.created_by)),
      'visitReference', e.reference, 'visitAt', e.arrived_at
    ) as j
    from service_request r
    join encounter e on e.id = r.encounter_id and e.status = 'open'
    join patient p on p.id = e.patient_id
    join service s on s.id = r.service_id
    left join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
    where r.deleted_at is null and r.station = p_station and p_station not in ('laboratory', 'ultrasound')
      and r.status not in ('verified', 'cancelled')
      and (has_perm('clinical.read') or has_perm('orders.read'))
  ) x
$$;

-- The visit's bill (0072), plus the member number, the cover and the latest payment (reprints).
create or replace view visit_bill with (security_invoker = true) as
  select i.id as invoice_id, i.encounter_id, i.status, i.payer_id, py.name as payer_name,
         i.total, i.patient_share, i.insurer_share, i.number,
         invoice_balance(i.id) as balance,
         (select coalesce(sum(p.amount), 0) from payment p where p.invoice_id = i.id and p.deleted_at is null) as paid,
         lp.paid_at as settled_at,
         lp.cashier as settled_by,
         invoice_refunded(i.id) as refunded,
         cv.member_number as member_no,
         cv.coverage_pct,
         lp.receipt_no,
         lp.method::text as receipt_method,
         lp.amount as receipt_amount,
         lp.reference as receipt_reference
  from invoice i
  left join payer py on py.id = i.payer_id
  left join lateral (
    select c.member_number, pl.coverage_pct
    from coverage c left join plan pl on pl.id = c.plan_id
    where c.id = i.coverage_id
  ) cv on true
  left join lateral (
    select p.paid_at, pr.full_name as cashier, p.receipt_no, p.method, p.amount, p.reference
    from payment p
    left join profiles pr on pr.id = p.cashier_id
    where p.invoice_id = i.id and p.deleted_at is null
    order by p.paid_at desc limit 1
  ) lp on true;

-- ---------------------------------------------------------------- grants
revoke all on function prescription_number(uuid) from public, anon;
grant execute on function prescription_number(uuid) to authenticated;
-- internal: only the checked functions call them
revoke all on function doc_person(uuid), doc_visit(uuid), doc_patient(uuid, uuid), assign_visit_reference()
  from public, anon, authenticated;


-- ============================================================ 20261126090000_departments_decide_desks.sql
-- 0085 · The departments a person works in decide the desks they use; the role is the ceiling.
--
-- Frank: "the departments he will belong in will be the one to determine the type of services that
-- he may access and work on"; "doctors working at the lab or pharmacy … roles that he does or
-- access are determined by the departments that he is in"; "we must have one head of department
-- and assistant, the members are the one who may be many".
--
--   * A  DESKS. A desk is a group of features: reception (register, start visits), triage (vitals
--        at triage and sending on), nursing (nurse tasks, beds), the treating desks (consultation,
--        dental, surgery, circ, fp, hiv: the clinical record, prescribing, ordering tests),
--        laboratory and ultrasound (worklist, samples, results, verify, correct) and pharmacy
--        (hand over, counter sale, the pharmacy and main stores). The keys are the service keys of
--        department.services (0071) plus the new key 'reception'.
--   * B  THE ROLE IS THE CEILING (role_desk): what a person of that role may ever use. Defaults
--        below; the manager changes them (Settings → Who may do what: set_role_desk, audited).
--        The manager always has every desk and is not stored.
--   * C  THE DEPARTMENTS DECIDE. may_use_desk(desk): the manager; or the desk is in the person's
--        ceiling and one of their active departments gives it (reception, triage and the treating
--        desks also need the switch their functions check). SAFETY NET: when no active department
--        of the clinic gives a desk, the role alone decides it, as before (the desk's permission:
--        visit.start, vitals.write, clinical.write, stock.dispense; the worklists: the lab tech, the
--        sonographer and the ultrasound doctor; a clinician still types the result of his own test).
--        The manager's "not allowed" for one employee on that permission takes the desk away; an
--        "allowed" never adds a desk. A nurse covering a doctor uses his treating desks and triage
--        (never the pharmacy, reception or a department's worklist).
--   * D  MONEY STAYS WITH THE ROLE. Payments, bills, charges and refunds keep their permissions and
--        the manager's switches; departments never give money rights (a return on a posted bill is
--        the person's own right). Room stores ("My store") stay with their holders.
--   * E  EVERY DESK FUNCTION ASKS. Results, sample status, corrections, the lab list (lab and
--        imaging by desk), the pharmacy (queue, hand over, counter sale, returns, "not given",
--        store management), triage (vitals at triage, sending on, who measured), nursing (tasks,
--        beds), the treating desks (notes, diagnoses, prescriptions, tests, closing, help) and
--        reception (start a visit; an emergency: the people who treat). The action permissions the
--        manager switches (clinical.write, vitals.write, visit.start, orders.write to order) are
--        still checked as well. A refusal: 42501 with hint 'no_desk' ("you do not work in a
--        department that does this; ask the manager"). The clinical tables are no longer written
--        directly: only through these functions.
--   * F  DAY ONE. Every active employee who uses a desk today (their usual desk, or what they did in
--        the last 90 days) and is in no department giving it keeps it: placed, as a member, in a
--        department giving it when nothing else changes (the patients sent to anyone, room stores,
--        the department's roles); otherwise kept by the rule of before (staff_desk_keep) until the
--        manager places them. Later, a department giving a desk for the first time places the
--        people who work there as usual the same way. The manager is told (notice 'desks_placed');
--        each placement is in the history.
--   * G  ONE HEAD AND ONE ASSISTANT per department (members many). A new assistant makes the
--        previous assistant a member; a new head makes the previous head the assistant (0073), who
--        then replaces the previous assistant. Departments with several assistants today keep the
--        latest named.
--   * H  THE APP READS THE DESKS: my_desks(), desks_of(profile), my_session_profile().desks,
--        staff_directory.desks, role_desk_matrix().
--
-- Errcodes: 42501 not allowed (hint no_desk: not in a department that does this), 22023 bad input.

-- ---------------------------------------------------------------- A desks
-- Every desk key: the services departments give (0071) and reception.
create or replace function desk_key(p_desk text)
returns boolean
language sql immutable
as $$
  select p_desk is not null and (p_desk = 'reception' or service_station(p_desk) is not null)
$$;

create or replace function all_desks()
returns text[]
language sql immutable
as $$
  select array['reception', 'triage', 'consultation', 'dental', 'surgery', 'circ', 'nursing', 'fp', 'hiv',
               'laboratory', 'ultrasound', 'pharmacy']
$$;

-- The desks where patients are treated (the clinical record, prescribing, ordering).
create or replace function treating_desks()
returns text[]
language sql immutable
as $$
  select array['consultation', 'dental', 'surgery', 'circ', 'nursing', 'fp', 'hiv']
$$;

-- The permission that decided the desk before departments did (the safety net).
create or replace function desk_permission(p_desk text)
returns text
language sql immutable
as $$
  select case
    when p_desk = 'reception' then 'visit.start'
    when p_desk = 'triage' then 'vitals.write'
    when p_desk in ('laboratory', 'ultrasound') then 'orders.write'
    when p_desk = 'pharmacy' then 'stock.dispense'
    when desk_key(p_desk) then 'clinical.write'
  end
$$;

-- Before departments, the worklists were run by the roles that worked there: the laboratory by the
-- lab tech, the imaging by the sonographer and the doctor whose usual desk is the ultrasound (his
-- station or specialty). A clinician still types the result of his own test while no department
-- gives that desk (record_result). The other desks: the permission alone, as before.
create or replace function desk_role_rule(p_role role_key, p_station text, p_specialty text, p_desk text)
returns boolean
language sql immutable
as $$
  select case
    when p_desk = 'laboratory' then p_role = 'lab_tech'
    when p_desk = 'ultrasound' then
      p_role = 'sonographer' or coalesce(role_serves(p_role, p_station, 'ultrasound', p_specialty), false)
    else true
  end
$$;

-- The desks of a place where patients wait (Theatre: surgery and circumcision; Beds: nursing).
create or replace function station_desks(p_station station)
returns text[]
language sql immutable
as $$
  select case p_station
    when 'reception' then array['reception']
    when 'triage' then array['triage']
    when 'consultation' then array['consultation']
    when 'dental' then array['dental']
    when 'theatre' then array['surgery', 'circ']
    when 'nursing' then array['nursing', 'fp', 'hiv']
    when 'beds' then array['nursing']
    when 'laboratory' then array['laboratory']
    when 'ultrasound' then array['ultrasound']
    when 'pharmacy' then array['pharmacy']
    else '{}'::text[]
  end
$$;

-- The desk of a test: its station, else its category (imaging → ultrasound).
create or replace function request_desk(p_station station, p_category request_category)
returns text
language sql immutable
as $$
  select case
    when p_station = 'ultrasound' then 'ultrasound'
    when p_station = 'laboratory' then 'laboratory'
    when p_category = 'imaging' then 'ultrasound'
    else 'laboratory'
  end
$$;

-- ---------------------------------------------------------------- B the ceiling of each role
create table if not exists role_desk (
  role role_key not null check (role <> 'manager'),
  desk text not null check (desk_key(desk)),
  set_by uuid default auth.uid(),
  set_at timestamptz not null default now(),
  primary key (role, desk)
);
alter table role_desk enable row level security;
drop policy if exists role_desk_select on role_desk;
create policy role_desk_select on role_desk for select to authenticated using (true);
revoke all on role_desk from anon, authenticated;
grant select on role_desk to authenticated;

-- The clinic's defaults …
insert into role_desk (role, desk, set_by)
select x.role::role_key, unnest(x.desks), null
from (values
  ('doctor', array['reception', 'triage', 'consultation', 'dental', 'surgery', 'circ', 'nursing', 'fp', 'hiv',
                   'laboratory', 'ultrasound', 'pharmacy']),
  ('nurse', array['reception', 'triage', 'consultation', 'dental', 'surgery', 'circ', 'nursing', 'fp', 'hiv',
                  'laboratory', 'ultrasound', 'pharmacy']),
  ('lab_tech', array['laboratory', 'ultrasound']),
  ('sonographer', array['ultrasound']),
  ('pharmacist', array['pharmacy']),
  ('receptionist', array['reception', 'triage'])
  -- the cashier: none of the desks (a role the manager allowed to start visits gains reception
  -- below)
) as x(role, desks)
on conflict do nothing;

-- … and whatever a role does today (the manager may have switched permissions on), so nobody loses
-- a desk on day one.
insert into role_desk (role, desk, set_by)
select rp.role, d.desk, null
from role_permissions rp
cross join unnest(all_desks()) as d(desk)
where rp.role <> 'manager' and rp.permission = desk_permission(d.desk)
  and desk_role_rule(rp.role, null, null, d.desk)
on conflict do nothing;

-- Desks an employee kept on day one by the rule of before (F): placing them in a department would
-- have changed something else (the patients sent to them, a room store, the department's roles),
-- or they only did that work lately. The manager places them, or takes the desk away
-- (forget_kept_desk). Read by desk_via only.
create table if not exists staff_desk_keep (
  profile_id uuid not null references profiles (id) on delete cascade,
  desk text not null check (desk_key(desk)),
  reason text not null,
  created_at timestamptz not null default now(),
  primary key (profile_id, desk)
);
alter table staff_desk_keep enable row level security;
revoke all on staff_desk_keep from anon, authenticated;

-- ---------------------------------------------------------------- C who may use a desk
-- The person's own permission (their exception first, else their role), without cover.
create or replace function staff_perm(p_user uuid, p_permission text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce(
    (select sp.allowed from staff_permission sp where sp.profile_id = p_user and sp.permission = p_permission),
    exists (select 1 from profiles p join role_permissions rp on rp.role = p.role
            where p.id = p_user and p.active and rp.permission = p_permission))
$$;

-- Does an active department of the clinic give this desk?
create or replace function desk_offered(p_desk text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from department d
                 where d.active and d.deleted_at is null and p_desk = any (d.services))
$$;

-- Is the person in an active department that gives this desk?
create or replace function in_desk_department(p_user uuid, p_desk text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from staff_department sd
                 join department d on d.id = sd.department_id and d.active and d.deleted_at is null
                 where sd.profile_id = p_user and p_desk = any (d.services))
$$;

-- Why the person may use the desk ('manager', 'department', 'kept', 'role'), or null.
--   * The manager's "not allowed" for this employee on the desk's permission takes the desk away.
--     An "allowed" exception never adds a desk outside the ceiling or the departments: it only
--     stands for the role's permission below.
--   * Reception, triage and the treating desks still need the switch their functions check
--     (visit.start, vitals.write, clinical.write), so a desk is not shown that cannot be used.
create or replace function desk_via(p_user uuid, p_desk text)
returns text
language sql stable security definer set search_path = public
as $$
  select case
    when p.role = 'manager' then 'manager'
    when not desk_key(p_desk) then null
    when ex.allowed = false then null
    -- the role's ceiling
    when not exists (select 1 from role_desk rd where rd.role = p.role and rd.desk = p_desk) then null
    when in_desk_department(p.id, p_desk)
         and (p_desk in ('laboratory', 'ultrasound', 'pharmacy') or coalesce(ex.allowed, rl.has)) then 'department'
    -- kept on day one by the rule of before (F)
    when coalesce(ex.allowed, rl.has)
         and exists (select 1 from staff_desk_keep k where k.profile_id = p.id and k.desk = p_desk) then 'kept'
    -- no department gives it: the role decides, as before
    when not desk_offered(p_desk) and coalesce(ex.allowed, rl.has)
         and desk_role_rule(p.role, p.station::text, p.specialty::text, p_desk) then 'role'
  end
  from profiles p
  cross join lateral (
    select exists (select 1 from role_permissions rp
                   where rp.role = p.role and rp.permission = desk_permission(p_desk)) as has
  ) rl
  left join staff_permission ex on ex.profile_id = p.id and ex.permission = desk_permission(p_desk)
  where p.id = p_user and p.active and p.deleted_at is null
$$;

-- May the signed-in person use this desk? Their own desks; a nurse covering a doctor also uses
-- his treating desks and triage (and the worklist of his own tests while no department gives it,
-- as before). Cover never passes on the pharmacy, reception or a department's worklist: the
-- doctor alone sets up cover, without the manager.
create or replace function may_use_desk(p_desk text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select desk_via(auth.uid(), p_desk) is not null
         or coalesce(
              (p_desk = any (treating_desks() || array['triage'])
               and desk_via(covering_for(auth.uid()), p_desk) is not null)
              or (p_desk in ('laboratory', 'ultrasound')
                  and desk_via(covering_for(auth.uid()), p_desk) = 'role'), false)
$$;

create or replace function may_use_any_desk(p_desks text[])
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from unnest(coalesce(p_desks, '{}')) as d(desk) where may_use_desk(d.desk))
$$;

-- The refusal every desk function gives (the app shows "ask the manager").
create or replace function assert_desk(p_desks text[], p_what text default null)
returns void
language plpgsql stable security definer set search_path = public
as $$
begin
  if not may_use_any_desk(p_desks) then
    raise exception 'not allowed: you do not work in a department that does this (%); ask the manager',
      coalesce(p_what, array_to_string(p_desks, ', '))
      using errcode = '42501', hint = 'no_desk';
  end if;
end
$$;

-- A task given to a role: nurse tasks go to the people who give nursing care when a department
-- does; otherwise (and for the other roles) the role decides, as before.
create or replace function task_for_me(p_assigned_role role_key)
returns boolean
language sql stable security definer set search_path = public
as $$
  select case
    when p_assigned_role is null then false
    when p_assigned_role = 'nurse' and desk_offered('nursing') then may_use_desk('nursing')
    else p_assigned_role = current_role_key()
  end
$$;

-- The desks of one employee (the staff list, the employee form) and of the signed-in person.
create or replace function desks_of(p_profile_id uuid)
returns text[]
language sql stable security definer set search_path = public
as $$
  select coalesce(array_agg(d.desk order by d.n), '{}')
  from unnest(all_desks()) with ordinality as d(desk, n)
  where auth.uid() is not null and desk_via(p_profile_id, d.desk) is not null
$$;

create or replace function my_desk_list()
returns text[]
language sql stable security definer set search_path = public
as $$
  select coalesce(array_agg(d.desk order by d.n), '{}')
  from unnest(all_desks()) with ordinality as d(desk, n)
  where may_use_desk(d.desk)
$$;

-- What the app needs to build menus and home pages:
--   desks    the desks the person may use now;
--   via      why, per desk: manager | department | kept (day one) | role (no department gives it) | cover;
--   offered  the desks some active department gives (the others follow the role);
--   ceiling  the desks the person's role may ever use.
create or replace function my_desks()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'desks', to_jsonb(my_desk_list()),
    'via', coalesce((
      select jsonb_object_agg(d.desk, coalesce(desk_via(auth.uid(), d.desk), 'cover'))
      from unnest(all_desks()) as d(desk) where may_use_desk(d.desk)), '{}'::jsonb),
    'offered', coalesce((
      select jsonb_agg(d.desk order by d.n) from unnest(all_desks()) with ordinality as d(desk, n)
      where desk_offered(d.desk)), '[]'::jsonb),
    'ceiling', case when is_manager() then to_jsonb(all_desks()) else coalesce((
      select jsonb_agg(d.desk order by d.n) from unnest(all_desks()) with ordinality as d(desk, n)
      where exists (select 1 from role_desk rd where rd.role = current_role_key() and rd.desk = d.desk)),
      '[]'::jsonb) end
  )
  where auth.uid() is not null
$$;

-- ---------------------------------------------------------------- B the manager sets the ceilings
create or replace function role_desk_matrix()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select case when is_manager() then jsonb_build_object(
    'desks', to_jsonb(all_desks()),
    'roles', coalesce((select jsonb_object_agg(r.role, r.desks) from (
        select rd.role::text as role, jsonb_agg(rd.desk order by array_position(all_desks(), rd.desk)) as desks
        from role_desk rd group by rd.role) r), '{}'::jsonb),
    'offered', coalesce((
      select jsonb_agg(d.desk order by d.n) from unnest(all_desks()) with ordinality as d(desk, n)
      where desk_offered(d.desk)), '[]'::jsonb)
  ) end
$$;

create or replace function set_role_desk(p_role role_key, p_desk text, p_allowed boolean)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not is_manager() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not desk_key(p_desk) then
    raise exception 'unknown desk %', p_desk using errcode = '22023';
  end if;
  if p_role = 'manager' then
    raise exception 'the manager keeps every desk' using errcode = '22023';
  end if;
  if p_allowed then
    insert into role_desk (role, desk) values (p_role, p_desk) on conflict do nothing;
  else
    delete from role_desk where role = p_role and desk = p_desk;
  end if;
  insert into audit_event (actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'settings', 'setting', null,
          jsonb_build_object('key', 'desks', 'role', p_role, 'desk', p_desk, 'allowed', p_allowed));
end
$$;

-- The manager takes away a desk kept on day one (F) — the employee then follows their departments.
create or replace function forget_kept_desk(p_profile_id uuid, p_desk text)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not is_manager() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  delete from staff_desk_keep where profile_id = p_profile_id and desk = p_desk;
  if found then
    insert into audit_event (actor_id, action, entity, entity_id, after, reason)
    values (auth.uid(), 'update', 'profiles', p_profile_id,
            jsonb_build_object('key', 'desk_kept_removed', 'desk', p_desk),
            'a desk kept from before departments decided desks was taken away');
  end if;
end
$$;

-- The desks kept on day one, per employee (the employee form shows them to the manager).
create or replace function kept_desks_of(p_profile_id uuid)
returns text[]
language sql stable security definer set search_path = public
as $$
  select coalesce(array_agg(k.desk order by array_position(all_desks(), k.desk)), '{}')
  from staff_desk_keep k
  where k.profile_id = p_profile_id and auth.uid() is not null
$$;

-- ---------------------------------------------------------------- departments may give reception
create or replace function upsert_department(
  p_id uuid,
  p_name text,
  p_description text,
  p_roles role_key[],
  p_services text[] default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid := p_id;
  v_bad text;
  v_new text[];
begin
  if not is_manager() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_name, ''))) < 2 then
    raise exception 'the department needs a name' using errcode = '22023';
  end if;
  -- the services of 0071, and reception (0085)
  select s into v_bad from unnest(coalesce(p_services, '{}')) s where not desk_key(s) limit 1;
  if v_bad is not null then
    raise exception 'unknown service %', v_bad using errcode = '22023';
  end if;
  -- the desks no department gives yet: once this one does, only departments decide them
  select array_agg(s) into v_new from unnest(coalesce(p_services, '{}')) s where not desk_offered(s);
  if v_id is null then
    insert into department (name, description, roles, services)
    values (trim(p_name), nullif(trim(coalesce(p_description, '')), ''), coalesce(p_roles, '{}'),
            coalesce(p_services, '{}'))
    returning id into v_id;
  else
    update department set name = trim(p_name), description = nullif(trim(coalesce(p_description, '')), ''),
                          roles = coalesce(p_roles, '{}'), services = coalesce(p_services, services)
    where id = v_id and deleted_at is null;
    if not found then
      raise exception 'department not found' using errcode = 'P0002';
    end if;
    -- Heads follow the department's name on their dashboard.
    update profiles set head_of = trim(p_name)
    where id in (select profile_id from staff_department where department_id = v_id and position = 'head');
  end if;
  -- a desk now given for the first time: the people who work there as usual are placed in it when
  -- nothing else changes for them; the manager is told who lost it (F)
  if exists (select 1 from unnest(coalesce(v_new, '{}')) s where desk_offered(s)) then
    perform place_staff_for_desks(false, v_new);
  end if;
  return v_id;
end
$$;

-- ---------------------------------------------------------------- G one head, one assistant
-- Departments with several assistants: the latest named stays assistant, the others are members.
with ranked as (
  select profile_id, department_id,
         row_number() over (partition by department_id order by created_at desc, profile_id) as n
  from staff_department where position = 'assistant'
)
update staff_department sd set position = 'member'
from ranked r
where r.profile_id = sd.profile_id and r.department_id = sd.department_id and r.n > 1;

update profiles p set position = 'member'
where p.position = 'assistant' and p.department_id is not null
  and exists (select 1 from staff_department sd where sd.profile_id = p.id
              and sd.department_id = p.department_id and sd.position = 'member');

-- Checked at the end of the statement: promoting the assistant to head makes the previous head the
-- assistant while the row being promoted is still written as assistant.
alter table staff_department drop constraint if exists staff_department_one_assistant;
alter table staff_department add constraint staff_department_one_assistant
  exclude using btree (department_id with =) where (position = 'assistant') deferrable initially deferred;

-- A new head: the previous head becomes the assistant (0073). A new assistant (or a previous head
-- made assistant): the previous assistant becomes a member.
create or replace function staff_department_one_head()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  -- the changes made below fire this trigger again: they are already decided here
  if coalesce(current_setting('mmc.lead_cascade', true), '') = 'on' then
    return new;
  end if;
  if new.position in ('head', 'assistant') then
    perform set_config('mmc.lead_cascade', 'on', true);
    if new.position = 'assistant'
       or exists (select 1 from staff_department where department_id = new.department_id
                  and position = 'head' and profile_id <> new.profile_id) then
      update staff_department set position = 'member'
      where department_id = new.department_id and position = 'assistant' and profile_id <> new.profile_id;
      update profiles set position = 'member'
      where department_id = new.department_id and position = 'assistant' and id <> new.profile_id;
    end if;
    if new.position = 'head' then
      update staff_department set position = 'assistant'
      where department_id = new.department_id and position = 'head' and profile_id <> new.profile_id;
      update profiles set position = 'assistant'
      where department_id = new.department_id and position = 'head' and id <> new.profile_id;
    end if;
    perform set_config('mmc.lead_cascade', '', true);
  end if;
  return new;
end
$$;
drop trigger if exists staff_department_one_head on staff_department;
create trigger staff_department_one_head before insert or update of position, department_id on staff_department
  for each row execute function staff_department_one_head();

-- ---------------------------------------------------------------- E laboratory and ultrasound
-- record_result (from 20261104090000_desks_last_items): results: the laboratory or ultrasound desk (by the test), or the clinical staff of the desk that did it.
create or replace function record_result(
  p_request_id uuid,
  p_findings text,
  p_impression text,
  p_verify boolean default true
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_test text;
  v_name text;
  v_station station;
  v_q queue_entry%rowtype;
  v_tests text;
begin
  select * into v_req from service_request where id = p_request_id and deleted_at is null;
  if not found then
    raise exception 'test order not found' using errcode = 'P0002';
  end if;
  -- Lab / ultrasound results: lab staff and clinicians who order; an order done at another desk
  -- (Nursing, Dental…): the clinical staff of that desk too.
  if not (may_use_desk(request_desk(v_req.station, v_req.category))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_req.status = 'cancelled' then
    raise exception 'this test was marked "not done": order it again if it is done after all' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_findings, '')), '') is null and nullif(trim(coalesce(p_impression, '')), '') is null then
    raise exception 'write the findings or the conclusion' using errcode = '22023';
  end if;
  if exists (select 1 from diagnostic_report where service_request_id = p_request_id
             and deleted_at is null and verified_at is not null) then
    raise exception 'this result is verified: correct it, giving the reason' using errcode = '22023';
  end if;
  insert into diagnostic_report (service_request_id, findings, impression, verified_by, verified_at)
  values (p_request_id, nullif(trim(coalesce(p_findings, '')), ''), nullif(trim(coalesce(p_impression, '')), ''),
          case when p_verify then auth.uid() end, case when p_verify then now() end)
  on conflict (service_request_id) do update
  set findings = excluded.findings, impression = excluded.impression,
      verified_by = excluded.verified_by, verified_at = excluded.verified_at, updated_at = now();
  update service_request set status = case when p_verify then 'verified'::request_status else 'resulted'::request_status end
  where id = p_request_id;
  -- Tell the doctor who ordered it.
  if v_req.requester_id is not null and v_req.requester_id is distinct from auth.uid() then
    select s.name_en into v_test from service s where s.id = v_req.service_id;
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('result',
            jsonb_build_object('test', v_test, 'name', v_name,
                               'impression', nullif(trim(coalesce(p_impression, '')), ''),
                               'verified', p_verify),
            '/app/visit?encounter=' || v_req.encounter_id,
            v_req.requester_id, auth.uid());
  end if;
  -- Last result of this desk written: the patient goes back to the doctor.
  v_station := coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end);
  perform after_desk_tests(v_req.encounter_id, v_station, v_req.requester_id);
end
$$;

-- set_request_status (from 20261102210000_desks_polished): sample taken, analysing, not done: as record_result.
create or replace function set_request_status(p_id uuid, p_status request_status, p_reason text default null)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_test text;
  v_name text;
  v_line uuid;
  v_invoice uuid;
begin
  select * into v_req from service_request where id = p_id;
  -- the lab and imaging (orders.write); an order done at another desk (Nursing, Dental…): the
  -- clinical staff of that desk too
  if not (may_use_desk(request_desk(v_req.station, v_req.category))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_status not in ('collected', 'in_process', 'cancelled') then
    raise exception 'use record_result for results' using errcode = '22023';
  end if;
  if p_status = 'cancelled' and nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'a reason is required to cancel a test' using errcode = '22023';
  end if;
  update service_request
  set status = p_status,
      reason = case when p_status = 'cancelled' then coalesce(reason || ' · ', '') || 'cancelled: ' || trim(p_reason) else reason end
  where id = p_id and deleted_at is null and status not in ('verified', 'cancelled');
  if not found then
    raise exception 'test not found or already finished' using errcode = 'P0002';
  end if;
  -- sample taken / analysing: the patient is being seen at that desk
  if p_status in ('collected', 'in_process') then
    update queue_entry q set started_at = coalesce(q.started_at, now()), called_at = coalesce(q.called_at, now()),
                             taken_by = coalesce(q.taken_by, auth.uid())
    where q.encounter_id = v_req.encounter_id and q.finished_at is null and q.deleted_at is null
      and q.station = coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end);
  end if;
  if p_status = 'cancelled' then
    select * into v_req from service_request where id = p_id;
    -- not done, not paid: its charge leaves the bill while the bill is open
    update invoice_line l
    set deleted_at = now(), manual_reason = coalesce(l.manual_reason || ' · ', '') || 'removed: test not done: ' || trim(p_reason)
    from invoice i
    where l.source_type = 'service_request' and l.source_id = p_id and l.deleted_at is null
      and i.id = l.invoice_id and i.status = 'draft'
    returning l.id, l.invoice_id into v_line, v_invoice;
    if v_invoice is not null then
      perform recompute_invoice(v_invoice);
    end if;
    -- the doctor who ordered it is told
    if v_req.requester_id is not null and v_req.requester_id is distinct from auth.uid() then
      select s.name_en into v_test from service s where s.id = v_req.service_id;
      select p.surname || ' ' || p.given_names into v_name
      from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
      insert into notification (kind, params, link, recipient_user, created_by)
      values ('test_cancelled', jsonb_build_object('test', v_test, 'name', v_name, 'reason', trim(p_reason)),
              '/app/visit?encounter=' || v_req.encounter_id, v_req.requester_id, auth.uid());
    end if;
    perform after_desk_tests(v_req.encounter_id,
      coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end),
      v_req.requester_id);
  end if;
end
$$;

-- lab_worklist (from 20261125090000_document_details): the lab list: the tests of the desks the person uses (read once, not per test).
create or replace function lab_worklist(p_scope text default 'open')
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(x.j order by x.prio, x.at), '[]'::jsonb)
  from (
    select r.priority as prio, r.created_at as at, doc_patient(p.id, e.id) || jsonb_build_object(
      'id', r.id, 'encounterId', r.encounter_id, 'patientId', p.id,
      'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
      'sex', p.sex, 'birthDate', p.birth_date,
      'ticket', (select q.ticket_no from queue_entry q where q.encounter_id = r.encounter_id order by q.created_at limit 1),
      'triage', e.triage_level,
      'test', s.name_en, 'category', r.category, 'status', r.status, 'priority', r.priority,
      'reason', r.reason, 'orderedAt', r.created_at,
      'orderedBy', (select full_name from profiles where id = r.requester_id),
      'findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
      'corrected', d.corrected_at is not null,
      'resultAt', coalesce(d.verified_at, d.updated_at),
      'resultBy', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
      'resultByPerson', doc_person(coalesce(d.verified_by, d.created_by)),
      'visitReference', e.reference, 'visitAt', e.arrived_at
    ) as j
    from service_request r
    join encounter e on e.id = r.encounter_id and (p_scope = 'done' or e.status = 'open')
    join patient p on p.id = e.patient_id
    join service s on s.id = r.service_id
    left join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
    where r.deleted_at is null and has_perm('orders.read')
      and r.category in (select unnest(my_test_categories())) and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) in ('laboratory', 'ultrasound')
      and case when p_scope = 'done'
            then r.status in ('resulted', 'verified')
                 and (coalesce(d.verified_at, d.updated_at) at time zone 'Africa/Kigali')::date
                     = (now() at time zone 'Africa/Kigali')::date
            else r.status not in ('verified', 'cancelled') end
  ) x
$$;

-- lab_summary (from 20261116090000_dashboards_by_period): the lab figures: as lab_worklist.
create or replace function lab_summary(p_from date default null, p_to date default null)
returns jsonb
language sql stable security definer set search_path = public
as $$
  with today as (
    select coalesce(p_from, k) as f, coalesce(p_to, p_from, k) as t
    from (select (now() at time zone 'Africa/Kigali')::date as k) z
  ),
  mine as (
    select r.*, d.verified_at, d.updated_at as result_at
    from service_request r
    join encounter e on e.id = r.encounter_id
    left join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
    where r.deleted_at is null and r.category in (select unnest(my_test_categories()))
      -- a finished visit's open test is no longer on the bench
      and (e.status = 'open' or r.status in ('resulted', 'verified', 'cancelled')) and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) in ('laboratory', 'ultrasound') and has_perm('orders.read')
  )
  select jsonb_build_object(
    'waiting', (select count(*) from mine where status = 'ordered'),
    'inProcess', (select count(*) from mine where status in ('collected', 'in_process')),
    'toVerify', (select count(*) from mine where status = 'resulted'),
    'doneToday', (select count(*) from mine, today
                  where status = 'verified' and (verified_at at time zone 'Africa/Kigali')::date between today.f and today.t),
    'urgent', (select count(*) from mine where status not in ('verified', 'cancelled') and priority <= 2),
    'orderedToday', (select count(*) from mine, today where (created_at at time zone 'Africa/Kigali')::date between today.f and today.t),
    'turnaroundMin', (select coalesce(round(avg(extract(epoch from verified_at - created_at) / 60)), 0)
                      from mine, today
                      where verified_at is not null and (verified_at at time zone 'Africa/Kigali')::date between today.f and today.t),
    'notDone', coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', m.id, 'test', s.name_en, 'at', m.updated_at, 'encounterId', m.encounter_id,
          'patient', p.surname || ' ' || p.given_names,
          'reason', nullif(regexp_replace(coalesce(m.reason, ''), '^.*cancelled: ', ''), '')
        ) order by m.updated_at desc)
      from mine m
      join service s on s.id = m.service_id
      join encounter e on e.id = m.encounter_id
      join patient p on p.id = e.patient_id, today
      where m.status = 'cancelled' and (m.updated_at at time zone 'Africa/Kigali')::date between today.f and today.t
    ), '[]'::jsonb),
    'served', (select count(distinct q.encounter_id) from queue_entry q, today
               where q.deleted_at is null and q.station in ('laboratory', 'ultrasound') and q.finished_at is not null
                 and (q.finished_at at time zone 'Africa/Kigali')::date between today.f and today.t),
    'byTest', coalesce((
      select jsonb_agg(jsonb_build_object('test', t.name, 'count', t.n) order by t.n desc)
      from (select s.name_en as name, count(*) as n
            from mine m join service s on s.id = m.service_id, today
            where (m.created_at at time zone 'Africa/Kigali')::date between today.f and today.t
            group by s.name_en order by count(*) desc limit 8) t
    ), '[]'::jsonb)
  )
$$;

-- correct_result (from 20261104090000_desks_last_items): a verified result corrected: as record_result, and the manager.
create or replace function correct_result(
  p_request_id uuid,
  p_findings text,
  p_impression text,
  p_reason text
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_rep diagnostic_report%rowtype;
  v_test text;
  v_name text;
begin
  select * into v_req from service_request where id = p_request_id and deleted_at is null;
  if not found then
    raise exception 'test order not found' using errcode = 'P0002';
  end if;
  if not (is_manager() or may_use_desk(request_desk(v_req.station, v_req.category))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the result is corrected' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_findings, '')), '') is null and nullif(trim(coalesce(p_impression, '')), '') is null then
    raise exception 'write the findings or the conclusion' using errcode = '22023';
  end if;
  select * into v_rep from diagnostic_report where service_request_id = p_request_id and deleted_at is null for update;
  if not found or v_rep.verified_at is null then
    raise exception 'only a verified result is corrected; edit the result instead' using errcode = '22023';
  end if;
  insert into report_correction (report_id, old_findings, old_impression, old_verified_by, old_verified_at, reason)
  values (v_rep.id, v_rep.findings, v_rep.impression, v_rep.verified_by, v_rep.verified_at, trim(p_reason));
  perform set_config('mmc.correcting_report', v_rep.id::text, true);
  update diagnostic_report
  set findings = nullif(trim(coalesce(p_findings, '')), ''), impression = nullif(trim(coalesce(p_impression, '')), ''),
      verified_by = auth.uid(), verified_at = now(), corrected_at = now(), correction_reason = trim(p_reason),
      updated_at = now()
  where id = v_rep.id;
  perform set_config('mmc.correcting_report', '', true);
  -- The doctor who ordered the test is told the result changed.
  if v_req.requester_id is not null and v_req.requester_id is distinct from auth.uid() then
    select s.name_en into v_test from service s where s.id = v_req.service_id;
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
    insert into notification (kind, params, link, recipient_user, urgent, created_by)
    values ('result',
            jsonb_build_object('test', v_test, 'name', v_name,
                               'impression', nullif(trim(coalesce(p_impression, '')), ''),
                               'verified', true, 'corrected', true, 'reason', trim(p_reason)),
            '/app/visit?encounter=' || v_req.encounter_id,
            v_req.requester_id, true, auth.uid());
  end if;
end
$$;

-- ---------------------------------------------------------------- E pharmacy
-- dispense_fefo (from 20261123090000_dispensing_fixes): the batches taken for a hand-over: the pharmacy desk.
create or replace function dispense_fefo(
  p_encounter_id uuid,
  p_item_id uuid,
  p_quantity integer,
  p_location_id uuid,
  p_medication_request_id uuid default null,
  p_substitution_reason text default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_remaining integer := p_quantity;
  v_row record;
  v_take integer;
  v_dispense_id uuid;
  v_first boolean := true;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  if p_quantity <= 0 then
    raise exception 'quantity must be positive' using errcode = '22023';
  end if;
  -- handed over and sold from an open pharmacy store only (room stores give with give_from_store)
  if not exists (select 1 from stock_location where id = p_location_id and type = 'pharmacy'
                 and active and deleted_at is null) then
    raise exception 'choose an open pharmacy store' using errcode = '22023';
  end if;
  -- the balance is read after the lock: nobody else takes the same units meanwhile
  perform lock_stock(p_item_id, p_location_id);
  for v_row in
    select s.batch_id, s.quantity
    from stock_on_hand s
    where s.item_id = p_item_id and s.location_id = p_location_id and s.quantity > 0 and s.batch_id is not null
      and (s.expiry is null or s.expiry >= current_date)   -- never an expired batch
    order by s.expiry asc nulls last
  loop
    exit when v_remaining <= 0;
    v_take := least(v_row.quantity, v_remaining);
    if v_first then
      insert into medication_dispense (medication_request_id, encounter_id, item_id, batch_id, quantity, substitution_reason)
      values (p_medication_request_id, p_encounter_id, p_item_id, v_row.batch_id, p_quantity, p_substitution_reason)
      returning id into v_dispense_id;
      v_first := false;
    end if;
    insert into stock_movement (item_id, batch_id, from_location_id, quantity, type, dispense_id, medication_request_id)
    values (p_item_id, v_row.batch_id, p_location_id, v_take, 'dispense', v_dispense_id, p_medication_request_id);
    v_remaining := v_remaining - v_take;
  end loop;
  if v_remaining > 0 then
    if exists (select 1 from stock_on_hand s where s.item_id = p_item_id and s.location_id = p_location_id
               and s.quantity > 0 and s.expiry < current_date) then
      raise exception 'not enough stock that is not expired: % unit(s) short (write the expired stock off)', v_remaining
        using errcode = '23514', hint = 'expired_short';
    end if;
    raise exception 'insufficient stock: % unit(s) short', v_remaining using errcode = '23514', hint = 'short';
  end if;
  return v_dispense_id;
end
$$;

-- dispense_prescription (from 20261123090000_dispensing_fixes): hand over a prescription: the pharmacy desk.
create or replace function dispense_prescription(p_medication_request_id uuid, p_location_id uuid default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_loc uuid;
  v_dispense uuid;
  v_charged boolean := false;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  select * into v_m from medication_request where id = p_medication_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  if v_m.cancelled_at is not null then
    raise exception 'the doctor cancelled this medicine' using errcode = '23505';
  end if;
  if v_m.given_at is not null or exists (select 1 from medication_dispense d where d.medication_request_id = v_m.id and d.deleted_at is null) then
    raise exception 'already dispensed' using errcode = '23505';
  end if;
  if v_m.not_given_at is not null then
    raise exception 'this medicine was marked as not given' using errcode = '23505';
  end if;
  -- The prescription is final once the doctor has finished (or sent the patient on). A sale written
  -- by the pharmacist themself is not held.
  if coalesce(v_m.prescriber_id, v_m.created_by) is distinct from auth.uid() and doctor_holds(v_m.encounter_id) then
    raise exception 'the doctor is still seeing this patient: hand the medicines over when the doctor has finished'
      using errcode = 'MS002', hint = 'doctor_holds';
  end if;
  if p_location_id is not null then
    if not exists (select 1 from stock_location where id = p_location_id and type = 'pharmacy'
                   and active and deleted_at is null) then
      raise exception 'choose an open pharmacy store' using errcode = '22023';
    end if;
    v_loc := p_location_id;
  else
    v_loc := main_pharmacy();
  end if;
  if v_loc is null then
    raise exception 'no pharmacy store yet: create one under Stock' using errcode = 'P0002';
  end if;
  v_dispense := dispense_fefo(v_m.encounter_id, v_m.item_id, ceil(v_m.quantity)::integer, v_loc, v_m.id, null);
  -- no price: handed over free (charged = false); no open bill: refused (MS001)
  begin
    perform add_charge_internal(v_m.encounter_id, 'pharmacy'::station, null, v_m.item_id, v_m.quantity,
                       null, null, null, null, 'medication_dispense', v_dispense);
    v_charged := true;
  exception when sqlstate 'P0002' then
    v_charged := false;
  end;
  update medication_request set given_at = now(), given_by = auth.uid() where id = v_m.id;
  -- the last line handed over: on to the cashier (money due) or the visit closes
  perform after_pharmacy(v_m.encounter_id);
  return jsonb_build_object('dispenseId', v_dispense, 'charged', v_charged, 'locationId', v_loc);
end
$$;

-- rx_not_given (from 20261102090000_lab_pharmacy_desks): "not given": the pharmacy desk.
create or replace function rx_not_given(p_medication_request_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_item text;
  v_name text;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  if length(trim(coalesce(p_reason, ''))) < 2 then
    raise exception 'say why the medicine is not given' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_medication_request_id for update;
  if not found or not rx_pending(v_m) then
    raise exception 'this medicine is no longer waiting at the pharmacy' using errcode = 'P0002';
  end if;
  update medication_request
  set not_given_at = now(), not_given_by = auth.uid(), not_given_reason = trim(p_reason)
  where id = v_m.id;
  select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
  if coalesce(v_m.prescriber_id, v_m.created_by) is not null
     and coalesce(v_m.prescriber_id, v_m.created_by) is distinct from auth.uid() then
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('rx_not_given', jsonb_build_object('item', v_item, 'name', v_name, 'reason', trim(p_reason)),
            '/app/visit?encounter=' || v_m.encounter_id, coalesce(v_m.prescriber_id, v_m.created_by), auth.uid());
  end if;
  perform after_pharmacy(v_m.encounter_id);
end
$$;

-- sell_medicine (from 20261123090000_dispensing_fixes): a counter sale line: the pharmacy desk.
create or replace function sell_medicine(
  p_encounter_id uuid,
  p_item_id uuid,
  p_quantity numeric,
  p_instructions text default null,
  p_location_id uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'the quantity must be more than zero' using errcode = '22023';
  end if;
  if not exists (select 1 from item where id = p_item_id and deleted_at is null) then
    raise exception 'medicine not found' using errcode = 'P0002';
  end if;
  insert into medication_request (encounter_id, item_id, quantity, instructions, supply, prescriber_id)
  values (p_encounter_id, p_item_id, p_quantity,
          coalesce(nullif(trim(coalesce(p_instructions, '')), ''), 'Pharmacy sale'), 'pharmacy', auth.uid())
  returning id into v_id;
  return dispense_prescription(v_id, p_location_id) || jsonb_build_object('requestId', v_id);
end
$$;

-- return_medicine (from 20261123090000_dispensing_fixes): a medicine brought back: the pharmacy desk (the manager has every desk).
create or replace function return_medicine(p_medication_request_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_d medication_dispense%rowtype;
  v_inv invoice%rowtype;
  v_mv record;
  v_back integer := 0;
  v_patient numeric := 0;
  v_insurer numeric := 0;
  v_total numeric := 0;
  v_lines jsonb;
  v_cn uuid;
  v_year integer := extract(year from now())::integer;
  v_balance numeric;
  v_name text;
  v_item text;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the medicine comes back' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_medication_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  select * into v_d from medication_dispense
  where medication_request_id = v_m.id and deleted_at is null order by created_at desc limit 1;
  if not found then
    raise exception 'this medicine was not handed over by the pharmacy' using errcode = 'P0002';
  end if;
  if not is_manager()
     and (v_d.created_at at time zone 'Africa/Kigali')::date <> (now() at time zone 'Africa/Kigali')::date then
    raise exception 'a hand-over of another day is undone by the manager' using errcode = '42501';
  end if;
  select * into v_inv from invoice where encounter_id = v_m.encounter_id;
  -- On a posted bill the return is money (a credit note, a smaller insurer claim): the person's
  -- own right, which a department or cover never gives.
  if v_inv.id is not null and v_inv.status <> 'draft'
     and not (is_manager() or staff_perm(auth.uid(), 'stock.dispense') or has_perm('billing.write')) then
    raise exception 'a medicine on a posted bill is taken back by the pharmacist or the manager'
      using errcode = '42501';
  end if;
  -- the units go back where they came from
  for v_mv in
    select item_id, batch_id, from_location_id, quantity from stock_movement
    where dispense_id = v_d.id and type = 'dispense' and deleted_at is null
  loop
    insert into stock_movement (item_id, batch_id, to_location_id, quantity, type, reason, dispense_id, medication_request_id)
    values (v_mv.item_id, v_mv.batch_id, v_mv.from_location_id, v_mv.quantity, 'return', trim(p_reason), v_d.id, v_m.id);
    v_back := v_back + v_mv.quantity;
  end loop;
  update medication_dispense set deleted_at = now() where id = v_d.id;

  if v_inv.id is null or v_inv.status = 'draft' then
    -- the bill is still open: the line leaves it, and the medicine waits at the pharmacy again
    update invoice_line set deleted_at = now(),
           manual_reason = coalesce(manual_reason || ' · ', '') || 'returned: ' || trim(p_reason)
    where source_type = 'medication_dispense' and source_id = v_d.id and deleted_at is null;
    if v_inv.id is not null then
      perform recompute_invoice(v_inv.id);
    end if;
    update medication_request set given_at = null, given_by = null where id = v_m.id;
    if exists (select 1 from encounter where id = v_m.encounter_id and status = 'open')
       and not exists (select 1 from queue_entry where encounter_id = v_m.encounter_id and station = 'pharmacy'
                       and finished_at is null and deleted_at is null) then
      insert into queue_entry (encounter_id, station, ticket_no)
      values (v_m.encounter_id, 'pharmacy',
              (select ticket_no from queue_entry where encounter_id = v_m.encounter_id order by created_at limit 1));
    end if;
    return jsonb_build_object('units', v_back, 'mode', 'bill', 'creditNoteId', null, 'credit', 0,
                              'balance', invoice_balance(v_inv.id));
  end if;

  -- The bill is posted: its lines never change. A credit note gives the line back: the patient's
  -- share lowers what they owe (or is money to give back at the cashier); the insurer's share
  -- leaves an open claim.
  select coalesce(sum(l.patient_share), 0), coalesce(sum(l.insurer_share), 0),
         coalesce(sum(round(l.unit_price * l.quantity)), 0),
         coalesce(jsonb_agg(jsonb_build_object('lineId', l.id, 'description', l.description, 'quantity', l.quantity,
                                               'unitPrice', l.unit_price, 'patientShare', l.patient_share,
                                               'insurerShare', l.insurer_share)), '[]'::jsonb)
  into v_patient, v_insurer, v_total, v_lines
  from invoice_line l
  where l.invoice_id = v_inv.id and l.source_type = 'medication_dispense' and l.source_id = v_d.id
    and l.deleted_at is null;
  if v_total > 0 then
    insert into credit_note (invoice_id, number, lines, total, reason, approver_id, patient_amount, insurer_amount,
                             source_type, source_id)
    values (v_inv.id, 'CN-' || v_year || '-' || lpad(next_number('credit_note', v_year)::text, 6, '0'),
            v_lines, v_total, 'returned: ' || trim(p_reason), auth.uid(), v_patient, v_insurer,
            'medication_dispense', v_d.id)
    returning id into v_cn;
    if v_insurer > 0 then
      update claim set amount = greatest(0, amount - v_insurer)
      where invoice_id = v_inv.id and status = 'open' and batch_id is null;
    end if;
  end if;
  -- the line is done: returned (it does not wait at the pharmacy again)
  update medication_request
  set given_at = null, given_by = null, not_given_at = now(), not_given_by = auth.uid(),
      not_given_reason = 'returned: ' || trim(p_reason)
  where id = v_m.id;
  v_balance := invoice_balance(v_inv.id);
  if v_balance < 0 then
    -- money to give back: the cashier is told
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
    select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
    insert into notification (kind, params, link, recipient_stations, created_by)
    values ('refund_due', jsonb_build_object('name', v_name, 'item', v_item, 'amount', -v_balance,
                                             'reason', trim(p_reason)),
            '/app/visit?encounter=' || v_m.encounter_id, array['cashier'::station], auth.uid());
  end if;
  return jsonb_build_object('units', v_back, 'mode', 'credit', 'creditNoteId', v_cn, 'credit', v_patient,
                            'balance', v_balance);
end
$$;

-- pharmacy_queue (from 20261123090000_dispensing_fixes): the pharmacy's list: the pharmacy desk.
create or replace function pharmacy_queue(p_location_id uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_loc uuid;
  v_stores jsonb;
  v_lines jsonb;
  v_patients jsonb;
begin
  -- the pharmacy and the manager only: the list carries allergies, prescriptions and bill amounts
  if not (may_use_desk('pharmacy') or is_manager()) then
    return jsonb_build_object('locationId', null, 'stores', '[]'::jsonb, 'lines', '[]'::jsonb, 'patients', '[]'::jsonb);
  end if;
  if p_location_id is not null then
    if not exists (select 1 from stock_location where id = p_location_id and type = 'pharmacy'
                   and active and deleted_at is null) then
      raise exception 'choose an open pharmacy store' using errcode = '22023';
    end if;
    v_loc := p_location_id;
  else
    v_loc := main_pharmacy();
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'isMain', l.id = main_pharmacy())
                            order by (l.id = main_pharmacy()) desc, l.created_at), '[]'::jsonb)
  into v_stores
  from stock_location l where l.type = 'pharmacy' and l.active and l.deleted_at is null;

  with lines as (
    select m.id, m.encounter_id, m.created_at, p.id as patient_id,
           p.surname || ' ' || p.given_names as patient, p.file_number, p.sex, p.birth_date, p.allergies,
           (select q.ticket_no from queue_entry q where q.encounter_id = m.encounter_id order by q.created_at limit 1) as ticket,
           m.item_id, i.name_generic || coalesce(' ' || i.strength, '') as item, i.selling_unit,
           i.prescribing_rule, m.quantity, m.dose, m.frequency, m.duration_days, m.instructions,
           pr.id as prescriber_id, pr.full_name as prescriber, pr.specialty,
           py.name as payer, cp.price as cash_price, pp.price as payer_price, pp.fallback,
           cov.pct,
           round(round(pp.price) * m.quantity) as line_total,
           doctor_holds(m.encounter_id) as holds
    from medication_request m
    join encounter e on e.id = m.encounter_id and e.status = 'open'
    join patient p on p.id = e.patient_id
    join item i on i.id = m.item_id
    left join invoice inv on inv.encounter_id = e.id
    left join payer py on py.id = inv.payer_id
    left join profiles pr on pr.id = coalesce(m.prescriber_id, m.created_by)
    left join lateral (select pf.price from price_for(null, m.item_id, null) pf) cp on true
    left join lateral (select pf.price, pf.fallback from price_for(null, m.item_id, inv.payer_id) pf) pp on true
    left join lateral (select coalesce(coverage_pct_for((select c.plan_id from coverage c where c.id = inv.coverage_id),
                                                        'pharmacy'::service_group), 0) as pct) cov on true
    where rx_pending(m)
  ), priced as (
    select l.*, round(coalesce(l.line_total, 0) * l.pct / 100) as insurer_share
    from lines l
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'requestId', x.id, 'encounterId', x.encounter_id, 'patientId', x.patient_id, 'patient', x.patient,
      'file', x.file_number, 'ticket', x.ticket,
      'itemId', x.item_id, 'item', x.item, 'unit', x.selling_unit,
      'quantity', x.quantity, 'dose', x.dose, 'frequency', x.frequency, 'days', x.duration_days,
      'instructions', x.instructions, 'prescriber', x.prescriber, 'prescriberId', x.prescriber_id, 'at', x.created_at,
      -- the cash price (as before) and what the bill will say
      'price', x.cash_price, 'cashPrice', x.cash_price, 'payerPrice', x.payer_price,
      'priced', x.payer_price is not null, 'payer', x.payer, 'coveragePct', x.pct,
      'lineTotal', coalesce(x.line_total, 0), 'insurerShare', x.insurer_share,
      'patientShare', coalesce(x.line_total, 0) - x.insurer_share,
      -- the stock of the store chosen at the desk
      'locationId', v_loc, 'pharmacyLocationId', v_loc,
      'onHandPharmacy', case when v_loc is null then 0 else usable_stock(x.item_id, v_loc) end,
      'expiredInPharmacy', (select coalesce(sum(s.quantity), 0)::integer from stock_on_hand s
                            where s.item_id = x.item_id and s.location_id = v_loc and s.quantity > 0
                              and s.expiry < current_date),
      'onHandElsewhere', (select coalesce(sum(s.quantity), 0)::integer from stock_on_hand s
                          join stock_location l on l.id = s.location_id
                          where s.item_id = x.item_id and l.id is distinct from v_loc and l.active and l.deleted_at is null
                            and s.quantity > 0 and (s.expiry is null or s.expiry >= current_date)),
      'doctorHolds', x.holds,
      -- the pharmacist's check
      'sex', x.sex, 'birthDate', x.birth_date,
      'ageYears', case when x.birth_date is not null then extract(year from age(current_date, x.birth_date))::integer end,
      'allergies', x.allergies,
      'prescribingRule', x.prescribing_rule, 'prescriberSpecialty', x.specialty,
      'ruleOk', rx_rule_ok(x.prescribing_rule, x.specialty)
    ) order by x.created_at), '[]'::jsonb)
  into v_lines
  from priced x;

  with lines as (
    select m.encounter_id, min(m.created_at) as first_at, count(*)::integer as n,
           sum(round(round(coalesce(pp.price, 0)) * m.quantity)) as total,
           sum(round(round(round(coalesce(pp.price, 0)) * m.quantity) * cov.pct / 100)) as insurer
    from medication_request m
    join encounter e on e.id = m.encounter_id and e.status = 'open'
    left join invoice inv on inv.encounter_id = e.id
    left join lateral (select pf.price from price_for(null, m.item_id, inv.payer_id) pf) pp on true
    left join lateral (select coalesce(coverage_pct_for((select c.plan_id from coverage c where c.id = inv.coverage_id),
                                                        'pharmacy'::service_group), 0) as pct) cov on true
    where rx_pending(m)
    group by m.encounter_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'encounterId', l.encounter_id, 'patientId', p.id, 'patient', p.surname || ' ' || p.given_names,
      'file', p.file_number,
      'ticket', (select q.ticket_no from queue_entry q where q.encounter_id = l.encounter_id order by q.created_at limit 1),
      'sex', p.sex, 'birthDate', p.birth_date,
      'ageYears', case when p.birth_date is not null then extract(year from age(current_date, p.birth_date))::integer end,
      'ageMonths', case when p.birth_date is not null
                        then (extract(year from age(current_date, p.birth_date)) * 12
                              + extract(month from age(current_date, p.birth_date)))::integer end,
      'allergies', p.allergies, 'payer', py.name,
      'lines', l.n, 'total', l.total, 'insurerShare', l.insurer, 'patientShare', l.total - l.insurer,
      'balance', invoice_balance(inv.id),
      'doctorHolds', doctor_holds(l.encounter_id)
    ) order by l.first_at), '[]'::jsonb)
  into v_patients
  from lines l
  join encounter e on e.id = l.encounter_id
  join patient p on p.id = e.patient_id
  left join invoice inv on inv.encounter_id = e.id
  left join payer py on py.id = inv.payer_id;

  return jsonb_build_object('locationId', v_loc, 'stores', v_stores, 'lines', v_lines, 'patients', v_patients);
end
$$;

-- stock_admin (from 20261124090000_stores_and_stock): the pharmacy and main stores (and the counter sales): the manager and the pharmacy desk.
create or replace function stock_admin()
returns boolean
language sql stable security definer set search_path = public
as $$
  select is_manager() or may_use_desk('pharmacy')
$$;

-- store_stock (from 20261124090000_stores_and_stock): a pharmacy store is managed by the pharmacy desk; a room store by its holders (unchanged).
create or replace function store_stock(p_location_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_l stock_location%rowtype;
  v_admin boolean := stock_admin();
  v_items jsonb;
  v_incoming jsonb;
begin
  select * into v_l from stock_location where id = p_location_id and deleted_at is null;
  if not found or v_l.type::text = 'transit' then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if not may_see_store(p_location_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'itemId', i.id, 'item', i.name_generic || coalesce(' ' || i.strength, ''), 'code', i.code,
      'unit', i.selling_unit, 'packSize', i.pack_size,
      'onHand', coalesce(t.on_hand, 0), 'usable', coalesce(t.usable, 0), 'expired', coalesce(t.expired, 0),
      'expiringSoon', coalesce(t.expiring, 0), 'earliestExpiry', t.next_expiry,
      'minLevel', m.min_level, 'low', m.min_level is not null and coalesce(t.usable, 0) < m.min_level,
      'price', (select pf.price from price_for(null, i.id, null) pf),
      'value', case when v_admin then coalesce(t.value, 0) end,
      'batches', coalesce(t.batches, '[]'::jsonb)
    ) order by i.name_generic), '[]'::jsonb)
  into v_items
  from item i
  left join store_item_level m on m.location_id = p_location_id and m.item_id = i.id
  left join lateral (
    select sum(s.quantity)::integer as on_hand,
           sum(s.quantity) filter (where s.expiry is null or s.expiry >= current_date)::integer as usable,
           sum(s.quantity) filter (where s.expiry < current_date)::integer as expired,
           sum(s.quantity) filter (where s.expiry between current_date and current_date + 90)::integer as expiring,
           min(s.expiry) filter (where s.expiry >= current_date) as next_expiry,
           sum(s.quantity * coalesce(b.unit_cost, 0)) as value,
           jsonb_agg(jsonb_build_object('batchId', s.batch_id, 'batchNo', b.batch_no, 'expiry', s.expiry,
                                        'quantity', s.quantity, 'expired', s.expiry < current_date,
                                        'unitCost', case when v_admin then b.unit_cost end)
                     order by s.expiry nulls last) as batches
    from stock_on_hand s left join batch b on b.id = s.batch_id
    where s.item_id = i.id and s.location_id = p_location_id and s.quantity > 0
  ) t on true
  where i.deleted_at is null and (t.on_hand is not null or m.min_level is not null);

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', t.id, 'number', t.number, 'direction', t.direction, 'sentAt', t.sent_at,
      'from', lf.name, 'to', lt.name,
      'lines', (select count(*) from stock_transfer_line x where x.transfer_id = t.id)::integer,
      'units', (select coalesce(sum(x.quantity), 0) from stock_transfer_line x where x.transfer_id = t.id)::integer
    ) order by t.sent_at), '[]'::jsonb)
  into v_incoming
  from stock_transfer t
  join stock_location lf on lf.id = t.from_location_id
  join stock_location lt on lt.id = t.to_location_id
  where t.status = 'in_transit' and (t.to_location_id = p_location_id or t.from_location_id = p_location_id);

  return jsonb_build_object(
    'store', jsonb_build_object('id', v_l.id, 'name', v_l.name, 'type', v_l.type, 'active', v_l.active,
                                'isMain', v_l.is_main, 'isRoom', is_room_type(v_l.type),
                                'holders', store_holders(v_l.id)),
    'held', holds_store(auth.uid(), v_l.id),
    -- count and write off: the holders (room store) or the pharmacy (pharmacy and main stores); the manager
    'canManage', is_manager() or case when is_room_type(v_l.type) then holds_store(auth.uid(), v_l.id)
                                       else may_use_desk('pharmacy') end,
    'items', v_items,
    'onTheWay', v_incoming,
    'value', case when v_admin then (select coalesce(sum(s.quantity * coalesce(b.unit_cost, 0)), 0)
                                     from stock_on_hand s left join batch b on b.id = s.batch_id
                                     where s.location_id = p_location_id and s.quantity > 0) end
  );
end
$$;

-- ---------------------------------------------------------------- E triage
-- record_vitals (from 20261119090000_audit_fixes): vitals of a patient waiting at triage: the triage desk (later measurements: vitals.write, as before).
create or replace function record_vitals(
  p_encounter_id uuid,
  p_vitals jsonb,
  p_triage triage_level default null,
  p_next_station station default null,
  p_reason text default null,
  p_measured_by uuid default null,
  p_measured_at timestamptz default null
)
returns text
language plpgsql security definer set search_path = public
as $$
declare
  v_ticket text;
  v_key text;
  v_val numeric;
  v_count integer := 0;
  v_by uuid := coalesce(p_measured_by, auth.uid());
  v_at timestamptz := coalesce(p_measured_at, now());
  v_arrived timestamptz;
  v_at_triage boolean;
  v_units jsonb := '{"bp_sys":"mmHg","bp_dia":"mmHg","pulse":"bpm","temp":"°C","resp":"/min","spo2":"%","weight":"kg","height":"cm","muac":"cm"}'::jsonb;
begin
  if not has_perm('vitals.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select arrived_at into v_arrived from encounter where id = p_encounter_id and status = 'open';
  if not found then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  select exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = 'triage'
                 and finished_at is null and deleted_at is null) into v_at_triage;
  -- At triage: the people of a department that does triage (when none does, as before).
  if v_at_triage then
    perform assert_desk(array['triage'], 'triage');
  end if;
  -- Sending on from triage is for whoever may work on the patient (as with "Send on"): reception
  -- that sent the patient to triage, or a nurse other than the one named, records only.
  if v_at_triage and p_next_station is not null and not may_route(p_encounter_id) then
    if current_role_key() = 'receptionist' then
      raise exception 'this patient is with %: record the measurements without choosing where they go next; the nurse there sends them on',
        coalesce(patient_holder(p_encounter_id), 'triage') using errcode = '42501';
    end if;
    perform assert_may_work_on(p_encounter_id, true);
  end if;
  -- Without clinical rights the person typing must name who measured.
  if not has_perm('clinical.write') and (p_measured_by is null or p_measured_by = auth.uid()) then
    raise exception 'choose the nurse who took the measurements' using errcode = '22023';
  end if;
  if not exists (select 1 from profiles where id = v_by and active) then
    raise exception 'unknown staff member for "measured by"' using errcode = '22023';
  end if;
  if v_at > now() + interval '5 minutes' then
    raise exception 'the measurement time is in the future' using errcode = '22023';
  end if;
  if v_at < v_arrived - interval '1 hour' then
    raise exception 'the measurement time is before the patient arrived' using errcode = '22023';
  end if;

  for v_key, v_val in
    select key, nullif(value, '')::numeric from jsonb_each_text(coalesce(p_vitals, '{}'::jsonb))
  loop
    if v_val is not null and v_units ? v_key then
      insert into observation (encounter_id, code, value_num, unit, performer_id, effective_at)
      values (p_encounter_id, v_key, v_val, v_units ->> v_key, v_by, v_at);
      v_count := v_count + 1;
    end if;
  end loop;
  if v_count = 0 then
    raise exception 'enter at least one measurement' using errcode = '22023';
  end if;

  if v_by <> auth.uid() then
    insert into audit_event (actor_id, action, entity, entity_id, after, reason)
    values (auth.uid(), 'create', 'observation', p_encounter_id,
            jsonb_build_object('measured_by', v_by, 'measured_at', v_at, 'count', v_count),
            'vitals entered on behalf of the person who measured');
  end if;

  if p_triage is not null then
    update encounter set triage_level = p_triage, triage_reason = coalesce(p_reason, triage_reason)
    where id = p_encounter_id;
    -- the colour reorders the places where the patient waits (red first)
    update queue_entry set priority = case p_triage when 'red' then 1 when 'yellow' then 2 else 3 end
    where encounter_id = p_encounter_id and finished_at is null and started_at is null and deleted_at is null;
  end if;

  select ticket_no into v_ticket from queue_entry where encounter_id = p_encounter_id order by created_at limit 1;

  -- At triage: close the triage turn and send the patient on. Later (e.g. the doctor typing
  -- the nurse's paper sheet): measurements only, the patient stays where they are.
  if v_at_triage and p_next_station is not null then
    update queue_entry set finished_at = now()
    where encounter_id = p_encounter_id and station = 'triage' and finished_at is null;
    insert into queue_entry (encounter_id, station, ticket_no, priority)
    values (p_encounter_id, p_next_station, v_ticket,
            case coalesce(p_triage, 'green') when 'red' then 1 when 'yellow' then 2 else 3 end);
  end if;
  return v_ticket;
end
$$;

-- send_from_triage (from 20261106090000_desks_wave8): send on from triage: the triage desk.
create or replace function send_from_triage(
  p_encounter_id uuid,
  p_triage triage_level,
  p_next_station station,
  p_reason text default null
)
returns text
language plpgsql security definer set search_path = public
as $$
declare
  v_ticket text;
begin
  if not (has_perm('clinical.write') or has_perm('vitals.write')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(array['triage'], 'triage');
  perform assert_may_work_on(p_encounter_id, true);
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  if not exists (select 1 from observation where encounter_id = p_encounter_id and deleted_at is null) then
    raise exception 'take the vitals first' using errcode = '22023';
  end if;
  update encounter set triage_level = p_triage, triage_reason = coalesce(nullif(trim(coalesce(p_reason, '')), ''), triage_reason)
  where id = p_encounter_id;
  select ticket_no into v_ticket from queue_entry where encounter_id = p_encounter_id order by created_at limit 1;
  update queue_entry set finished_at = now()
  where encounter_id = p_encounter_id and station = 'triage' and finished_at is null and deleted_at is null;
  if not exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = p_next_station
                 and finished_at is null and deleted_at is null) then
    insert into queue_entry (encounter_id, station, ticket_no, priority)
    values (p_encounter_id, p_next_station, v_ticket,
            case p_triage when 'red' then 1 when 'yellow' then 2 else 3 end);
  end if;
  return v_ticket;
end
$$;

-- vitals_takers (from 20261019150000_vitals_on_behalf): who measured: the people who work at triage.
create or replace function vitals_takers()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name, 'staffId', p.staff_id, 'role', p.role)
                            order by (p.role <> 'nurse'), p.full_name), '[]'::jsonb)
  from profiles p
  where p.active and p.role in ('nurse', 'doctor', 'manager')
    and (has_perm('vitals.write') or has_perm('clinical.write'))
    -- a department that does triage, or (when none does) the role, as before
    and desk_via(p.id, 'triage') is not null
$$;

-- ---------------------------------------------------------------- E nursing: tasks and beds
-- create_task (from 20261101180000_patients_belong_calls): a task for the nurses is given while treating.
create or replace function create_task(
  p_encounter_id uuid,
  p_title text,
  p_due_at timestamptz default null,
  p_detail text default null,
  p_assigned_role role_key default 'nurse'
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_patient uuid;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  perform assert_may_work_on(p_encounter_id);
  if length(trim(coalesce(p_title, ''))) < 2 then
    raise exception 'say what must be done' using errcode = '22023';
  end if;
  select patient_id into v_patient from encounter where id = p_encounter_id and status = 'open';
  if not found then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  insert into internal_task (encounter_id, patient_id, assigned_role, due_at, title, detail)
  values (p_encounter_id, v_patient, p_assigned_role, p_due_at, trim(p_title), nullif(trim(coalesce(p_detail, '')), ''))
  returning id into v_id;
  return v_id;
end
$$;

-- complete_task (from 20261030120000_cashier_tests_tasks): a nurse task is done by the nursing desk (when a department gives nursing care), the person named or the giver.
create or replace function complete_task(p_task_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_task internal_task%rowtype;
  v_name text;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if desk_offered('nursing') and exists (
       select 1 from internal_task k where k.id = p_task_id and k.assigned_role = 'nurse'
         and k.assigned_to is distinct from auth.uid() and k.created_by is distinct from auth.uid()) then
    perform assert_desk(array['nursing'], 'nursing care');
  end if;
  update internal_task set done_at = now(), done_by = auth.uid()
  where id = p_task_id and deleted_at is null and done_at is null
  returning * into v_task;
  if not found then
    raise exception 'task not found or already done' using errcode = 'P0002';
  end if;
  if v_task.created_by is not null and v_task.created_by is distinct from auth.uid() then
    select p.surname || ' ' || p.given_names into v_name from patient p where p.id = v_task.patient_id;
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('task_done',
            jsonb_build_object('title', v_task.title, 'name', v_name,
                               'by', (select full_name from profiles where id = auth.uid())),
            case when v_task.encounter_id is not null then '/app/visit?encounter=' || v_task.encounter_id end,
            v_task.created_by, auth.uid());
  end if;
end
$$;

-- cancel_task (from 20261104090000_desks_last_items): "not done": the giver, the manager, or the people the task is for.
create or replace function cancel_task(p_task_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_task internal_task%rowtype;
  v_name text;
  v_mine boolean;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why' using errcode = '22023';
  end if;
  select * into v_task from internal_task where id = p_task_id and deleted_at is null and done_at is null for update;
  if not found then
    raise exception 'task not found or already done' using errcode = 'P0002';
  end if;
  v_mine := v_task.created_by = auth.uid();
  -- the giver or the manager withdraws; otherwise only the nurses (to whom it was given) say "not done"
  if not (v_mine or is_manager()
          or task_for_me(v_task.assigned_role)
          or v_task.assigned_to = auth.uid()) then
    raise exception 'only the person who gave the task, the nurses or the manager' using errcode = '42501';
  end if;
  update internal_task set deleted_at = now(), cancel_reason = trim(p_reason), cancelled_by = auth.uid()
  where id = p_task_id;
  if v_task.created_by is not null and not v_mine then
    select p.surname || ' ' || p.given_names into v_name from patient p where p.id = v_task.patient_id;
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('task_done',
            jsonb_build_object('title', v_task.title, 'name', v_name, 'notDone', true, 'reason', trim(p_reason),
                               'by', (select full_name from profiles where id = auth.uid())),
            case when v_task.encounter_id is not null then '/app/visit?encounter=' || v_task.encounter_id end,
            v_task.created_by, auth.uid());
  end if;
end
$$;

-- open_tasks (from 20261103090000_loose_ends): the tasks for me: nurse tasks for the nursing desk.
create or replace function open_tasks()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', k.id, 'title', k.title, 'detail', k.detail, 'dueAt', k.due_at,
      'overdue', k.due_at is not null and k.due_at < now(),
      'encounterId', k.encounter_id,
      'patient', p.surname || ' ' || p.given_names,
      'by', pr.full_name
    ) order by k.due_at nulls last, k.created_at), '[]'::jsonb)
  from internal_task k
  left join patient p on p.id = k.patient_id
  -- a finished visit's task is over too
  left join encounter e on e.id = k.encounter_id
  left join profiles pr on pr.id = k.created_by
  where k.deleted_at is null and k.done_at is null and (k.encounter_id is null or e.status = 'open')
    and (k.assigned_to = auth.uid() or task_for_me(k.assigned_role) or is_manager())
$$;

-- home_summary (from 20261116090000_dashboards_by_period): the home page: nurse tasks for the nursing desk.
create or replace function home_summary(p_from date default null, p_to date default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_role role_key := current_role_key();
  v_practitioner uuid := (select id from practitioner where user_id = auth.uid() and active limit 1);
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_appts jsonb;
  v_inquiries jsonb;
  v_mine jsonb;
  v_to_accept jsonb;
  v_bills jsonb;
  v_paid jsonb;
  v_beds jsonb;
  v_tasks jsonb;
  v_results jsonb;
begin
  if v_role is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;

  -- today's booked patients (reception, doctors)
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'time', to_char(a.starts_at at time zone 'Africa/Kigali', 'HH24:MI'),
      'name', coalesce(p.surname || ' ' || p.given_names, a.contact_name),
      'doctor', coalesce(pr.names, ''), 'station', coalesce(a.category, ''),
      'status', case when a.status in ('arrived', 'in_progress', 'completed') then 'arrived'
                     when a.starts_at < now() then 'late' else 'due' end,
      'mine', (a.practitioner_id = v_practitioner),
      'encounterId', (select e.id from encounter e where e.appointment_id = a.id order by e.arrived_at desc limit 1)
    ) order by a.starts_at), '[]'::jsonb) into v_appts
  from appointment a
  left join patient p on p.id = a.patient_id
  left join practitioner pr on pr.id = a.practitioner_id
  where a.deleted_at is null and a.status in ('approved', 'confirmed', 'arrived', 'in_progress', 'completed')
    and (a.starts_at at time zone 'Africa/Kigali')::date between v_from and v_to;

  -- public inquiries waiting for reception
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', a.contact_name, 'phone', a.contact_phone, 'reference', a.reference,
      'category', a.category, 'doctor', pr.names, 'channel', a.contact_channel,
      'when', case when a.starts_at is null then null else to_char(a.starts_at at time zone 'Africa/Kigali', 'DD/MM HH24:MI') end,
      'note', a.reason
    ) order by a.created_at), '[]'::jsonb) into v_inquiries
  from appointment a
  left join practitioner pr on pr.id = a.practitioner_id
  where a.deleted_at is null and a.status = 'inquiry';

  -- approved bookings this practitioner still has to accept
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', coalesce(p.surname || ' ' || p.given_names, a.contact_name),
      'when', to_char(a.starts_at at time zone 'Africa/Kigali', 'DD/MM HH24:MI'), 'note', a.reason,
      'category', a.category, 'startsAt', a.starts_at
    ) order by a.starts_at), '[]'::jsonb) into v_to_accept
  from appointment a
  left join patient p on p.id = a.patient_id
  where a.deleted_at is null and a.status = 'approved' and a.practitioner_id = v_practitioner
    and a.starts_at > now() - interval '1 day';

  -- open bills: visits with something charged and a patient balance (cashier)
  select coalesce(jsonb_agg(jsonb_build_object(
      'encounterId', i.encounter_id, 'name', p.surname || ' ' || p.given_names, 'file', p.file_number,
      'ticket', (select ticket_no from queue_entry q where q.encounter_id = i.encounter_id order by q.created_at limit 1),
      'station', (select station from queue_entry q where q.encounter_id = i.encounter_id and q.finished_at is null order by q.created_at desc limit 1),
      'amount', i.patient_share, 'balance', invoice_balance(i.id), 'status', i.status
    ) order by i.updated_at desc), '[]'::jsonb) into v_bills
  from invoice i
  join encounter e on e.id = i.encounter_id
  join patient p on p.id = e.patient_id
  where i.deleted_at is null and i.total > 0 and e.status = 'open' and invoice_balance(i.id) > 0;

  select jsonb_build_object('count', count(*), 'amount', coalesce(sum(amount), 0)) into v_paid
  from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to;

  -- beds
  select coalesce(jsonb_agg(jsonb_build_object(
      'n', b.sort_order, 'name', b.name, 'state', b.status,
      'who', (select p.surname || ' ' || left(p.given_names, 1) || '.' from bed_stay s join encounter e on e.id = s.encounter_id join patient p on p.id = e.patient_id
              where s.bed_id = b.id and s.discharged_at is null limit 1)
    ) order by b.sort_order, b.name), '[]'::jsonb) into v_beds
  from bed b where b.deleted_at is null;

  -- tasks for my role or me
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', k.id, 'time', to_char(k.due_at at time zone 'Africa/Kigali', 'HH24:MI'), 'title', k.title,
      'detail', coalesce(k.detail, ''), 'overdue', (k.due_at < now()),
      'patient', (select p.surname || ' ' || p.given_names from patient p where p.id = k.patient_id)
    ) order by k.due_at), '[]'::jsonb) into v_tasks
  from internal_task k
  where k.deleted_at is null and k.done_at is null and (k.assigned_to = auth.uid() or task_for_me(k.assigned_role));

  -- lab / imaging results of the last two days (doctors)
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'encounterId', sr.encounter_id, 'test', s.name_en,
      'name', p.surname || ' ' || p.given_names, 'impression', coalesce(r.impression, r.findings, ''),
      'verified', (r.verified_at is not null), 'at', to_char(r.updated_at at time zone 'Africa/Kigali', 'HH24:MI'),
      'reviewed', (r.reviewed_at is not null), 'corrected', (r.corrected_at is not null)
    ) order by (r.reviewed_at is null) desc, r.updated_at desc), '[]'::jsonb) into v_results
  from diagnostic_report r
  join service_request sr on sr.id = r.service_request_id
  join service s on s.id = sr.service_id
  join encounter e on e.id = sr.encounter_id
  join patient p on p.id = e.patient_id
  where r.deleted_at is null
    and (r.updated_at > now() - interval '2 days' or (r.reviewed_at is null and r.updated_at > now() - interval '7 days'))
    -- a doctor's results are the tests they ordered
    and (v_role is distinct from 'doctor' or sr.requester_id = auth.uid());

  return jsonb_build_object(
    'role', v_role,
    -- the patients this person took and finished today (a doctor's "Seen")
    'seenToday', (select count(distinct q.encounter_id) from queue_entry q
                  where q.taken_by = auth.uid() and q.deleted_at is null and q.finished_at is not null
                    and (q.finished_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'appointments', v_appts,
    'inquiries', v_inquiries,
    'toAccept', v_to_accept,
    'openBills', v_bills,
    'paidToday', v_paid,
    'beds', v_beds,
    'tasks', v_tasks,
    'results', v_results
  );
end
$$;

-- admit_to_bed (from 20261021120000_beds_pricing): beds: the nursing desk.
create or replace function admit_to_bed(
  p_encounter_id uuid,
  p_bed_id uuid,
  p_nights integer default 1,
  p_period_price numeric default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_stay uuid;
  v_total numeric;
  v_price numeric;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(array['nursing'], 'nursing care');
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  if exists (select 1 from bed_stay where encounter_id = p_encounter_id and discharged_at is null and deleted_at is null) then
    raise exception 'this patient is already in a bed' using errcode = '23505';
  end if;
  update bed set status = 'occupied' where id = p_bed_id and status = 'free' and deleted_at is null
  returning nightly_price into v_price;
  if not found then
    raise exception 'this bed is not free' using errcode = 'P0002';
  end if;
  insert into bed_stay (encounter_id, bed_id, charge_mode, planned_nights, planned_until,
                        nightly_price, period_price)
  values (p_encounter_id, p_bed_id, 'day', p_nights, now() + make_interval(days => p_nights),
          v_price, p_period_price)
  returning id into v_stay;
  v_total := bill_bed_nights(v_stay, p_nights, p_period_price);
  return jsonb_build_object('stayId', v_stay, 'nights', p_nights, 'total', v_total);
end
$$;

-- extend_bed_stay (from 20261021120000_beds_pricing): beds: the nursing desk.
create or replace function extend_bed_stay(
  p_bed_id uuid,
  p_nights integer,
  p_period_price numeric default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_stay bed_stay%rowtype;
  v_total numeric;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(array['nursing'], 'nursing care');
  select * into v_stay from bed_stay
  where bed_id = p_bed_id and discharged_at is null and deleted_at is null;
  if not found then
    raise exception 'nobody is in this bed' using errcode = 'P0002';
  end if;
  v_total := bill_bed_nights(v_stay.id, p_nights, p_period_price);
  update bed_stay
  set planned_nights = coalesce(planned_nights, 0) + p_nights,
      planned_until = coalesce(planned_until, now()) + make_interval(days => p_nights),
      period_price = case when p_period_price is null then period_price
                          else coalesce(period_price, 0) + p_period_price end
  where id = v_stay.id;
  return jsonb_build_object('nights', p_nights, 'total', v_total);
end
$$;

-- discharge_bed (from 20261019190000_desk_operations): beds: the nursing desk.
create or replace function discharge_bed(p_bed_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(array['nursing'], 'nursing care');
  update bed_stay set discharged_at = now() where bed_id = p_bed_id and discharged_at is null and deleted_at is null;
  if not found then
    raise exception 'nobody is in this bed' using errcode = 'P0002';
  end if;
  update bed set status = 'cleaning' where id = p_bed_id;
end
$$;

-- bed_ready (from 20261019190000_desk_operations): beds: the nursing desk.
create or replace function bed_ready(p_bed_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(array['nursing'], 'nursing care');
  update bed set status = 'free' where id = p_bed_id and status in ('cleaning', 'out_of_service') and deleted_at is null;
  if not found then
    raise exception 'this bed cannot be marked ready' using errcode = 'P0002';
  end if;
end
$$;

-- ---------------------------------------------------------------- E the treating desks (consultation, dental, surgery, circumcision, nursing, FP, HIV)
-- add_clinical_note (from 20261101180000_patients_belong_calls): a note: a treating desk.
create or replace function add_clinical_note(p_encounter_id uuid, p_text text)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare v_id uuid;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  perform assert_may_work_on(p_encounter_id);
  if length(trim(coalesce(p_text, ''))) < 2 then
    raise exception 'the note is empty' using errcode = '22023';
  end if;
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  insert into observation (encounter_id, code, value_text) values (p_encounter_id, 'note', trim(p_text))
  returning id into v_id;
  return v_id;
end
$$;

-- add_diagnosis (from 20261101180000_patients_belong_calls): a diagnosis: a treating desk.
create or replace function add_diagnosis(p_encounter_id uuid, p_text text, p_icd10 text default null, p_type condition_type default 'primary', p_provisional boolean default false)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare v_id uuid;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  perform assert_may_work_on(p_encounter_id);
  if length(trim(coalesce(p_text, ''))) < 2 then
    raise exception 'the diagnosis needs a description' using errcode = '22023';
  end if;
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  insert into condition (encounter_id, text, icd10_code, type, provisional)
  values (p_encounter_id, trim(p_text), nullif(upper(trim(coalesce(p_icd10, ''))), ''), p_type, p_provisional)
  returning id into v_id;
  return v_id;
end
$$;

-- prescribe (from 20261123090000_dispensing_fixes): prescribing: a treating desk.
create or replace function prescribe(
  p_encounter_id uuid, p_item_id uuid, p_quantity numeric, p_dose text default null, p_route text default null,
  p_frequency text default null, p_duration_days integer default null, p_instructions text default null,
  p_supply text default 'pharmacy', p_station station default null, p_location_id uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_charged boolean := false;
  v_loc uuid;
  v_taken boolean := false;
  v_qty integer;
  v_supply text := coalesce(p_supply, 'pharmacy');
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  perform assert_may_work_on(p_encounter_id);
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'quantity must be more than zero' using errcode = '22023';
  end if;
  if v_supply not in ('pharmacy', 'room') then
    raise exception 'unknown supply' using errcode = '22023';
  end if;
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  if not exists (select 1 from item where id = p_item_id and deleted_at is null) then
    raise exception 'medicine not found' using errcode = 'P0002';
  end if;
  if v_supply = 'room' then
    -- Given here: only from a store that holds enough unexpired units; never given without stock.
    v_qty := ceil(p_quantity)::integer;
    v_loc := room_store_for(auth.uid(), p_item_id, v_qty, p_location_id, p_station);
    if v_loc is null then
      raise exception 'not enough of this medicine (not expired) in %: prescribe it for the pharmacy instead',
        case when p_location_id is null then 'a store you may give from' else 'that store' end
        using errcode = 'MS003', hint = 'room_short';
    end if;
  end if;
  insert into medication_request (encounter_id, item_id, dose, route, frequency, duration_days, quantity,
                                  instructions, supply, given_at, given_by)
  values (p_encounter_id, p_item_id, nullif(trim(coalesce(p_dose, '')), ''), nullif(trim(coalesce(p_route, '')), ''),
          nullif(trim(coalesce(p_frequency, '')), ''), p_duration_days, p_quantity,
          nullif(trim(coalesce(p_instructions, '')), ''), v_supply,
          case when v_supply = 'room' then now() end, case when v_supply = 'room' then auth.uid() end)
  returning id into v_id;
  if v_supply = 'room' then
    perform give_from_store(p_item_id, v_loc, v_qty, v_id, 'given in the room');
    v_taken := true;
    -- on the bill at the medicine's price (no price: given free); a closed bill refuses (MS001)
    begin
      perform add_charge_internal(p_encounter_id, coalesce(p_station, 'consultation'::station), null, p_item_id, p_quantity,
                         null, null, null, null, 'medication_request', v_id);
      v_charged := true;
    exception when sqlstate 'P0002' then
      v_charged := false;
    end;
  elsif not exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = 'pharmacy'
                    and finished_at is null and deleted_at is null) then
    insert into queue_entry (encounter_id, station, ticket_no)
    values (p_encounter_id, 'pharmacy', (select ticket_no from queue_entry where encounter_id = p_encounter_id order by created_at limit 1));
  end if;
  return jsonb_build_object('id', v_id, 'supply', v_supply, 'charged', v_charged,
                            'stockTaken', v_taken, 'locationId', v_loc,
                            'warnings', coalesce(rx_warnings(p_item_id, auth.uid()), '[]'::jsonb));
end
$$;

-- cancel_prescription (from 20261123090000_dispensing_fixes): cancelling one's prescription: a treating desk (or the manager).
create or replace function cancel_prescription(p_request_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_item text;
  v_name text;
  v_left integer;
begin
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the medicine is cancelled' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  if not (is_manager()
          or (has_perm('clinical.write') and coalesce(v_m.prescriber_id, v_m.created_by) = auth.uid())) then
    raise exception 'only the doctor who prescribed it (or the manager) can cancel it' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  if not rx_pending(v_m) then
    raise exception 'this medicine is no longer waiting at the pharmacy (handed over, not given or cancelled)'
      using errcode = 'P0002';
  end if;
  update medication_request
  set cancelled_at = now(), cancelled_by = auth.uid(), cancel_reason = trim(p_reason)
  where id = v_m.id;
  -- the pharmacy is told the line left its list
  select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
  insert into notification (kind, params, link, recipient_stations, created_by)
  values ('rx_cancelled',
          jsonb_build_object('item', v_item, 'name', v_name, 'reason', trim(p_reason),
                             'by', (select full_name from profiles where id = auth.uid())),
          '/app/visit?encounter=' || v_m.encounter_id, array['pharmacy'::station], auth.uid());
  -- nothing left at the pharmacy: the patient goes on (back, cashier, or the visit closes)
  perform after_pharmacy(v_m.encounter_id);
  select count(*)::integer into v_left from medication_request m
  where m.encounter_id = v_m.encounter_id and rx_pending(m);
  return jsonb_build_object('id', v_m.id, 'pending', v_left,
                            'balance', invoice_balance((select id from invoice where encounter_id = v_m.encounter_id)));
end
$$;

-- order_tests (from 20261102210000_desks_polished): ordering tests: a treating desk, or the laboratory / ultrasound desk.
create or replace function order_tests(
  p_encounter_id uuid,
  p_service_ids uuid[],
  p_reason text default null,
  p_from station default null,
  p_priority integer default 3
)
returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_service uuid;
  v_ids uuid[] := '{}';
begin
  if not has_perm('orders.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks() || array['laboratory', 'ultrasound'], 'ordering tests');
  perform assert_may_work_on(p_encounter_id);
  if coalesce(array_length(p_service_ids, 1), 0) = 0 then
    raise exception 'choose at least one test' using errcode = '22023';
  end if;
  foreach v_service in array p_service_ids loop
    -- urgent orders (1–2) go to the top of the lab's list
    v_ids := v_ids || order_test(p_encounter_id, v_service, p_reason, greatest(1, least(coalesce(p_priority, 3), 5)));
  end loop;
  -- Send the patient now: off the doctor's queue, onto the desks that do the orders, back after.
  if p_from is not null then
    update queue_entry set finished_at = now()
    where encounter_id = p_encounter_id and station = p_from and finished_at is null
      and p_from not in (select r.station from service_request r where r.id = any (v_ids));
    update queue_entry
    set referred_by = auth.uid(),
        referral_note = coalesce(nullif(trim(coalesce(p_reason, '')), ''), referral_note),
        return_station = p_from,
        return_to = auth.uid()
    where encounter_id = p_encounter_id and finished_at is null and deleted_at is null
      and station <> p_from
      and station in (select r.station from service_request r where r.id = any (v_ids));
  end if;
  return coalesce(array_length(v_ids, 1), 0);
end
$$;

-- order_test (from 20261102180000_desks_complete): ordering one test: as order_tests.
create or replace function order_test(p_encounter_id uuid, p_service_id uuid, p_reason text default null, p_priority integer default 3)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_group service_group;
  v_cat request_category;
  v_station station;
begin
  if not has_perm('orders.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks() || array['laboratory', 'ultrasound'], 'ordering tests');
  perform assert_may_work_on(p_encounter_id);
  select s.service_group,
         coalesce(c.order_station, case when s.service_group = 'imaging' then 'ultrasound'::station else 'laboratory'::station end)
  into v_group, v_station
  from service s left join service_category c on c.id = s.category_id
  where s.id = p_service_id and s.active and s.deleted_at is null;
  if v_group is null then
    raise exception 'unknown service' using errcode = '22023';
  end if;
  v_cat := case when v_station = 'ultrasound' then 'imaging'::request_category else 'lab'::request_category end;
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  insert into service_request (encounter_id, category, service_id, reason, priority, station)
  values (p_encounter_id, v_cat, p_service_id, nullif(trim(coalesce(p_reason, '')), ''), least(5, greatest(1, p_priority)), v_station)
  returning id into v_id;
  perform add_charge_internal(p_encounter_id, v_station, p_service_id, null, 1, null, null, null, null, 'service_request', v_id);
  if not exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = v_station and finished_at is null) then
    insert into queue_entry (encounter_id, station, ticket_no, priority)
    values (p_encounter_id, v_station, (select ticket_no from queue_entry where encounter_id = p_encounter_id order by created_at limit 1), least(5, greatest(1, p_priority)));
  end if;
  return v_id;
end
$$;

-- mark_result_reviewed (from 20261106090000_desks_wave8): a result seen: a treating desk (or the manager).
create or replace function mark_result_reviewed(p_report_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not (has_perm('clinical.write') or is_manager()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  update diagnostic_report set reviewed_at = now(), reviewed_by = auth.uid()
  where id = p_report_id and deleted_at is null and reviewed_at is null;
end
$$;

-- close_encounter (from 20261015180300_visits): closing the visit: a treating desk.
create or replace function close_encounter(p_encounter_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_type encounter_type;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  select type into v_type from encounter where id = p_encounter_id and status = 'open';
  if not found then
    raise exception 'encounter not found or already closed' using errcode = 'P0002';
  end if;
  if v_type in ('opd', 'dental', 'procedure', 'observation')
     and not exists (select 1 from condition where encounter_id = p_encounter_id and type = 'primary' and deleted_at is null) then
    raise exception 'a primary diagnosis is required before closing the visit' using errcode = '23514';
  end if;
  update encounter set status = 'closed', closed_at = now(), closed_by = auth.uid() where id = p_encounter_id;
  update queue_entry set finished_at = coalesce(finished_at, now()) where encounter_id = p_encounter_id;
end
$$;

-- ask_help (from 20261101180000_patients_belong_calls): asking a colleague for help: a treating desk.
create or replace function ask_help(p_encounter_id uuid, p_to_user uuid default null, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_by text;
  v_name text;
  v_ticket text;
begin
  select full_name into v_by from profiles where id = auth.uid() and active;
  if v_by is null or not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  perform assert_may_work_on(p_encounter_id);
  if p_to_user is not null and (p_to_user = auth.uid()
      or not exists (select 1 from profiles where id = p_to_user and active)) then
    raise exception 'choose an active colleague' using errcode = '22023';
  end if;
  insert into staff_call (kind, target, to_user, encounter_id, note)
  values ('help', case when p_to_user is null then 'doctors' else 'person' end, p_to_user, p_encounter_id,
          nullif(trim(coalesce(p_note, '')), ''))
  returning id into v_id;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = p_encounter_id;
  select ticket_no into v_ticket from queue_entry where encounter_id = p_encounter_id order by created_at limit 1;
  insert into notification (kind, params, link, recipient_user, recipient_role, urgent, created_by)
  values ('help', jsonb_build_object('call', v_id, 'by', v_by, 'name', v_name, 'ticket', v_ticket,
                                     'note', nullif(trim(coalesce(p_note, '')), '')),
          '/app/visit?encounter=' || p_encounter_id, p_to_user,
          case when p_to_user is null then 'doctor'::role_key end, true, auth.uid());
  return v_id;
end
$$;

-- ---------------------------------------------------------------- E reception
-- start_visit (from 20261101150000_who_may_do_what): starting a visit: the reception desk (and visit.start, as before).
create or replace function start_visit(
  p_patient_id uuid,
  p_emergency boolean default false,
  p_station station default 'consultation',
  p_type encounter_type default 'opd'
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_station station := case when p_emergency then p_station when triage_first() then 'triage'::station else p_station end;
  v_enc uuid;
  v_ticket text;
begin
  if not has_perm('queue.write') or not has_perm('visit.start') then
    raise exception 'you may not start visits (the manager has not allowed it)' using errcode = '42501';
  end if;
  -- A visit is started at reception; an emergency by the people who treat (at any treating desk,
  -- triage or reception), wherever reception is given.
  if not p_emergency then
    perform assert_desk(array['reception'], 'starting visits');
  else
    perform assert_desk(array['reception', 'triage'] || treating_desks(), 'emergency visits');
  end if;
  -- An emergency is treated on the spot, so only staff who treat may register one.
  if p_emergency and current_role_key() in ('receptionist', 'cashier') then
    raise exception 'only treating staff can register an emergency' using errcode = '42501';
  end if;
  if exists (select 1 from encounter where patient_id = p_patient_id and status = 'open') then
    raise exception 'this patient already has an open visit' using errcode = '23505';
  end if;
  perform set_config('mmc.visit_open', 'on', true);
  v_enc := open_encounter(p_patient_id, p_type, v_station);
  perform set_config('mmc.visit_open', '', true);
  if p_emergency then
    update encounter
    set triage_level = 'red', triage_reason = 'Emergency: registered directly at ' || p_station::text
    where id = v_enc;
    update queue_entry set priority = 1 where encounter_id = v_enc;
  end if;
  select ticket_no into v_ticket from queue_entry where encounter_id = v_enc order by created_at desc limit 1;
  return jsonb_build_object('encounter_id', v_enc, 'ticket_no', v_ticket, 'station', v_station);
end
$$;

-- begin_visit (from 20261111090000_triage_nurse_track): starting a visit: the reception desk; "I take the patient myself" also where a department of theirs gives that desk.
create or replace function begin_visit(
  p_patient_id uuid,
  p_station station default 'consultation',
  p_department_id uuid default null,
  p_note text default null,
  p_myself boolean default false,
  p_emergency boolean default false,
  p_service text default null,
  p_assigned_to uuid default null,
  p_triage_to uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_role role_key := current_role_key();
  v_desk station := coalesce(case when not p_myself then service_station(p_service) end, p_station);
  v_station station;
  v_enc uuid;
  v_q queue_entry%rowtype;
begin
  if not has_perm('queue.write') or not has_perm('visit.start') then
    raise exception 'you may not start visits (the manager has not allowed it)' using errcode = '42501';
  end if;
  -- A visit is started at reception. "I take the patient myself" is decided below (the person's
  -- own desk); an emergency by the people who treat, wherever reception is given.
  if not (p_myself or p_emergency) then
    perform assert_desk(array['reception'], 'starting visits');
  elsif p_emergency and not p_myself then
    perform assert_desk(array['reception', 'triage'] || treating_desks(), 'emergency visits');
  end if;
  if p_emergency and v_role in ('receptionist', 'cashier') then
    raise exception 'only treating staff can register an emergency' using errcode = '42501';
  end if;
  if p_service is not null and service_station(p_service) is null then
    raise exception 'unknown service' using errcode = '22023';
  end if;
  if p_myself and not (
       v_role = 'manager'
       or (v_role = 'doctor' and v_desk in ('consultation', 'dental', 'theatre', 'ultrasound'))
       or (v_role = 'nurse' and v_desk in ('triage', 'nursing', 'beds'))
       or (v_role = 'lab_tech' and v_desk = 'laboratory')
       or (v_role = 'sonographer' and v_desk = 'ultrasound')
       or (v_role = 'pharmacist' and v_desk = 'pharmacy')
       -- or a department of theirs gives that desk (a nurse of the Laboratory …)
       or exists (select 1 from unnest(station_desks(v_desk)) as d(desk)
                  where in_desk_department(auth.uid(), d.desk) and may_use_desk(d.desk))) then
    raise exception 'you do not work at % : send the patient there instead', initcap(v_desk::text)
      using errcode = '42501';
  end if;
  if p_assigned_to is not null and (p_service is null or not staff_serves(p_assigned_to, p_service)) then
    raise exception 'that person does not give this service' using errcode = '22023';
  end if;
  if p_triage_to is not null and not staff_serves(p_triage_to, 'triage') then
    raise exception 'that person does not work at triage' using errcode = '22023';
  end if;
  if p_department_id is not null and not exists (
       select 1 from department d where d.id = p_department_id and d.deleted_at is null
         and station_role(v_desk) = any (d.roles)) then
    raise exception 'that department does not work at %', initcap(v_desk::text) using errcode = '22023';
  end if;
  if exists (select 1 from encounter where patient_id = p_patient_id and status = 'open') then
    raise exception 'this patient already has an open visit' using errcode = '23505';
  end if;

  v_station := case
    when p_myself or p_emergency then v_desk
    when triage_first() then 'triage'::station
    else v_desk end;
  perform set_config('mmc.visit_open', 'on', true);
  v_enc := open_encounter(p_patient_id, 'opd', v_station);
  perform set_config('mmc.visit_open', '', true);
  -- the service and the person chosen stay with the visit (used after triage)
  update encounter
  set service = p_service, intended_to = case when p_myself then auth.uid() else p_assigned_to end,
      practitioner_id = case
        when p_assigned_to is not null and exists (select 1 from profiles where id = p_assigned_to and role = 'doctor')
        then ensure_practitioner(p_assigned_to) else practitioner_id end
  where id = v_enc;

  if p_emergency then
    update encounter
    set triage_level = 'red', triage_reason = 'Emergency: registered directly at ' || v_station::text
    where id = v_enc;
    update queue_entry set priority = 1 where encounter_id = v_enc;
  end if;

  select * into v_q from queue_entry
  where encounter_id = v_enc and station = v_station and finished_at is null and deleted_at is null
  order by created_at limit 1;
  update queue_entry
  set referral_note = coalesce(nullif(trim(coalesce(p_note, '')), ''), referral_note),
      service = p_service,
      department_id = case when v_station = v_desk and p_assigned_to is null then coalesce(p_department_id, department_id) else department_id end,
      assigned_to = case
        when v_station = 'triage' and not p_myself then coalesce(p_triage_to, assigned_to)
        when v_station = v_desk and not p_myself then coalesce(p_assigned_to, assigned_to)
        else assigned_to end,
      referred_by = auth.uid()
  where id = v_q.id
  returning * into v_q;
  if p_myself then
    perform take_patient(v_q.id);
    delete from notification where kind = 'queue' and params ->> 'queue' = v_q.id::text;
  elsif v_q.assigned_to is not null then
    -- the person chosen is told (instead of everyone at the desk)
    perform notify_queue_entry_row(v_q);
  end if;

  return jsonb_build_object(
    'encounter_id', v_enc,
    'ticket_no', v_q.ticket_no,
    'station', v_station,
    'myself', p_myself,
    'assigned', (select full_name from profiles where id = v_q.assigned_to),
    'department', (select name from department where id = p_department_id));
end
$$;

-- ---------------------------------------------------------------- E the lab list by desk
-- The tests of my list: laboratory for the laboratory desk, imaging for the ultrasound desk
-- (lab_worklist and lab_summary read it). Before: by role.
create or replace function my_test_categories()
returns request_category[]
language sql stable security definer set search_path = public
as $$
  select array_remove(array[
    case when may_use_desk('laboratory') then 'lab' end,
    case when may_use_desk('ultrasound') then 'imaging' end
  ]::request_category[], null)
$$;

-- The store tables (0083) ask stock_admin(), now the pharmacy desk: asked once per read, not per
-- row (the same rules as 0083).
drop policy if exists stock_movement_select on stock_movement;
create policy stock_movement_select on stock_movement for select to authenticated
  using ((select stock_admin()) or may_see_store(from_location_id) or may_see_store(to_location_id));
drop policy if exists batch_select on batch;
create policy batch_select on batch for select to authenticated using ((select stock_admin()));
drop policy if exists goods_receipt_select on goods_receipt;
create policy goods_receipt_select on goods_receipt for select to authenticated using ((select stock_admin()));
drop policy if exists goods_receipt_line_select on goods_receipt_line;
create policy goods_receipt_line_select on goods_receipt_line for select to authenticated
  using ((select stock_admin()));
drop policy if exists stock_transfer_line_select on stock_transfer_line;
create policy stock_transfer_line_select on stock_transfer_line for select to authenticated
  using ((select stock_admin()) or exists (select 1 from stock_transfer t where t.id = transfer_id
                                  and (may_see_store(t.from_location_id) or may_see_store(t.to_location_id))));
drop policy if exists counter_sale_select on counter_sale;
create policy counter_sale_select on counter_sale for select to authenticated
  using ((select stock_admin()) or (select has_perm('payment.take')));
drop policy if exists counter_sale_line_select on counter_sale_line;
create policy counter_sale_line_select on counter_sale_line for select to authenticated
  using ((select stock_admin()) or (select has_perm('payment.take')));

-- ---------------------------------------------------------------- H the app reads the desks
-- The employee list with the desks each person may use now (added at the end).
create or replace view staff_directory with (security_invoker = true) as
  select p.id, p.username, p.full_name, p.role, p.station, p.dashboard, p.head_of, p.language, p.phone,
         p.active, p.must_change_pin, p.last_sign_in_at, p.pin_changed_at, p.deactivated_at, p.created_at,
         p.staff_id, p.email, p.department_id, d.name as department_name, p.position, p.specialty,
         coalesce((select jsonb_agg(jsonb_build_object('id', dd.id, 'name', dd.name, 'position', sd.position)
                                    order by (sd.department_id = p.department_id) desc, dd.name)
                   from staff_department sd join department dd on dd.id = sd.department_id and dd.deleted_at is null
                   where sd.profile_id = p.id), '[]'::jsonb) as departments,
         p.registration_no, p.registration_body,
         desks_of(p.id) as desks, kept_desks_of(p.id) as kept_desks
  from profiles p
  left join department d on d.id = p.department_id and d.deleted_at is null
  where p.deleted_at is null;

create or replace function my_session_profile()
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v profiles%rowtype;
begin
  select * into v from profiles where id = auth.uid();
  if not found or not v.active then
    raise exception 'this account is deactivated; ask the manager' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'id', v.id, 'username', v.username, 'full_name', v.full_name, 'role', v.role,
    'station', v.station, 'dashboard', v.dashboard, 'head_of', v.head_of,
    'language', v.language, 'must_change_pin', v.must_change_pin,
    'staff_id', v.staff_id, 'email', v.email,
    'specialty', v.specialty, 'registration_no', v.registration_no, 'registration_body', v.registration_body,
    'desks', to_jsonb(my_desk_list())
  );
end
$$;

-- ---------------------------------------------------------------- F day one: nobody loses a desk
-- The desk a role works at as usual (the usual desk of 0071 / 0080; reception for reception; triage
-- for the nurse and the receptionist, who types the nurse's paper sheet).
create or replace function desk_usual(p_role role_key, p_station text, p_specialty text, p_desk text)
returns boolean
language sql immutable
as $$
  select case
    when p_desk = 'reception' then p_role = 'receptionist'
    when p_desk = 'triage' then p_role in ('receptionist', 'nurse')
      or coalesce(role_serves(p_role, p_station, p_desk, p_specialty), false)
    else coalesce(role_serves(p_role, p_station, p_desk, p_specialty), false)
  end
$$;

-- Did the person do this desk's work in the last 90 days?
create or replace function desk_used_recently(p_user uuid, p_desk text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select case
    -- opened a visit
    when p_desk = 'reception' then exists (
      select 1 from encounter e where e.created_by = p_user and e.created_at > now() - interval '90 days')
    -- measured (or typed the measurements) while the patient waited at triage
    when p_desk = 'triage' then exists (
      select 1 from observation o
      join queue_entry q on q.encounter_id = o.encounter_id and q.station = 'triage' and q.deleted_at is null
        and q.created_at <= o.created_at and (q.finished_at is null or q.finished_at >= o.created_at)
      where (o.created_by = p_user or o.performer_id = p_user) and o.created_at > now() - interval '90 days')
    -- wrote or verified a result of that desk
    when p_desk in ('laboratory', 'ultrasound') then exists (
      select 1 from diagnostic_report d join service_request r on r.id = d.service_request_id
      where (d.created_by = p_user or d.verified_by = p_user) and d.created_at > now() - interval '90 days'
        and coalesce(r.station::text, request_desk(null, r.category)) = p_desk)
    -- handed over medicines
    when p_desk = 'pharmacy' then exists (
      select 1 from medication_dispense m
      where (m.dispenser_id = p_user or m.created_by = p_user) and m.created_at > now() - interval '90 days')
    else
      -- took patients of that service
      exists (
        select 1 from queue_entry q join encounter e on e.id = q.encounter_id
        where q.taken_by = p_user and q.created_at > now() - interval '90 days'
          and q.station = service_station(p_desk)
          and coalesce(q.service, case when service_station(e.service) = q.station then e.service end,
                       case q.station when 'theatre' then 'surgery' else q.station::text end) = p_desk)
      -- nursing care: did nurse tasks, put patients in beds
      or (p_desk = 'nursing' and (
        exists (select 1 from internal_task k where k.done_by = p_user and k.done_at > now() - interval '90 days')
        or exists (select 1 from bed_stay s where s.created_by = p_user and s.created_at > now() - interval '90 days')))
  end
$$;

-- What reaches each employee now (staff_serves, for every desk): a placement must not change it.
create or replace function routing_snapshot()
returns text[]
language sql stable security definer set search_path = public
as $$
  select coalesce(array_agg(p.id::text || ':' || d.desk order by p.id, d.desk), '{}')
  from profiles p
  cross join unnest(all_desks()) as d(desk)
  where p.active and p.deleted_at is null and staff_serves(p.id, d.desk)
$$;

-- Every active employee who used a desk until now (the role's permission, and the rule of before)
-- but would lose it, because a department gives it and they are in none:
--   * their usual desk: placed, as a member, in an active department giving it that takes their
--     role (or every role) and holds no room store, only when nothing else changes: the patients
--     sent to anyone stay the same (routing_snapshot). A department's roles are never changed.
--   * otherwise (or when they only did that work lately): on day one (p_day_one) they keep the desk
--     by the rule of before (staff_desk_keep) until the manager places them; later (a department
--     giving a desk for the first time, upsert_department: p_desks) they lose it.
-- Each placement and kept desk is in the history; the manager gets one notice ('desks_placed')
-- listing who was placed, who keeps a desk and who lost one.
create or replace function place_staff_for_desks(p_day_one boolean default false, p_desks text[] default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  r record;
  v_desk text;
  v_dep department%rowtype;
  v_usual boolean;
  v_reason text;
  v_action text;
  v_before text[];
  v_lines jsonb := '[]'::jsonb;
  v_placed text;
  v_kept text;
  v_lost text;
begin
  if auth.uid() is not null and not is_manager() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  v_before := routing_snapshot();
  for r in
    select p.id, p.full_name, p.role, p.station::text as station, p.specialty::text as specialty
    from profiles p
    where p.active and p.deleted_at is null and p.role <> 'manager'
    order by p.full_name, p.id
  loop
    foreach v_desk in array all_desks() loop
      continue when p_desks is not null and not (v_desk = any (p_desks));
      -- they keep it anyway, or never had it
      continue when desk_via(r.id, v_desk) is not null;
      continue when not desk_offered(v_desk);
      continue when not exists (select 1 from role_desk rd where rd.role = r.role and rd.desk = v_desk);
      continue when not (staff_perm(r.id, desk_permission(v_desk))
                         and desk_role_rule(r.role, r.station, r.specialty, v_desk));
      v_usual := desk_usual(r.role, r.station, r.specialty, v_desk);
      continue when not (v_usual or desk_used_recently(r.id, v_desk));
      v_reason := null;
      select * into v_dep from department where false;
      if not v_usual then
        v_reason := 'recent_only';
      else
        -- a department that takes the role, one holding no room store first
        select * into v_dep from department d
        where d.active and d.deleted_at is null and v_desk = any (d.services)
          and (cardinality(d.roles) = 0 or r.role = any (d.roles))
        order by exists (select 1 from stock_location_holder h
                         where h.department_id = d.id and h.deleted_at is null),
                 d.sort_order, d.name, d.id
        limit 1;
        if v_dep.id is null then
          v_reason := 'role_not_accepted';
        elsif exists (select 1 from stock_location_holder h
                      where h.department_id = v_dep.id and h.deleted_at is null) then
          -- a member would hold its room store: the manager decides
          v_reason := 'holds_store';
        else
          begin
            insert into staff_department (profile_id, department_id, position)
            values (r.id, v_dep.id, 'member')
            on conflict (profile_id, department_id) do nothing;
            -- no main department yet: this one (the membership follows, 0051)
            update profiles set department_id = v_dep.id, position = 'member'
            where id = r.id and department_id is null;
            if routing_snapshot() is distinct from v_before then
              raise exception 'mmc: placement changes routing' using errcode = 'P0001';
            end if;
          exception when raise_exception then
            if sqlerrm <> 'mmc: placement changes routing' then
              raise;
            end if;
            -- undone: the patients sent to someone would change
            v_reason := 'routing';
          end;
        end if;
      end if;
      v_action := case when v_reason is null then 'placed' when p_day_one then 'kept' else 'lost' end;
      if v_action = 'placed' then
        insert into audit_event (actor_id, action, entity, entity_id, after, reason)
        values (auth.uid(), 'update', 'profiles', r.id,
                jsonb_build_object('key', 'desk_placement', 'department', v_dep.name, 'departmentId', v_dep.id,
                                   'desk', v_desk),
                'placed in a department so the employee keeps the desk they use (0085)');
      elsif v_action = 'kept' then
        insert into staff_desk_keep (profile_id, desk, reason) values (r.id, v_desk, v_reason)
        on conflict do nothing;
        insert into audit_event (actor_id, action, entity, entity_id, after, reason)
        values (auth.uid(), 'update', 'profiles', r.id,
                jsonb_build_object('key', 'desk_kept', 'desk', v_desk, 'why', v_reason),
                'keeps the desk by the rule of before until the manager places them (0085)');
      end if;
      v_lines := v_lines || jsonb_build_object(
        'profileId', r.id, 'name', r.full_name, 'role', r.role, 'desk', v_desk, 'action', v_action,
        'reason', v_reason, 'departmentId', v_dep.id, 'department', v_dep.name);
    end loop;
  end loop;
  if jsonb_array_length(v_lines) > 0 then
    select string_agg(x ->> 'name' || ' → ' || (x ->> 'department') || ' (' || (x ->> 'desk') || ')', '; '
                      order by x ->> 'name', x ->> 'desk') filter (where x ->> 'action' = 'placed'),
           string_agg(x ->> 'name' || ' (' || (x ->> 'desk') || ')', '; '
                      order by x ->> 'name', x ->> 'desk') filter (where x ->> 'action' = 'kept'),
           string_agg(x ->> 'name' || ' (' || (x ->> 'desk') || ')', '; '
                      order by x ->> 'name', x ->> 'desk') filter (where x ->> 'action' = 'lost')
    into v_placed, v_kept, v_lost
    from jsonb_array_elements(v_lines) x;
    insert into notification (kind, params, title, body, link, recipient_role, created_by)
    values ('desks_placed',
            jsonb_build_object('count', jsonb_array_length(v_lines), 'lines', v_lines, 'dayOne', p_day_one),
            case when p_day_one then 'Employees placed in departments'
                 else 'A department now gives a desk' end,
            case when p_day_one then 'Departments now decide the desks each person uses. '
                 else 'Only the members of departments giving a desk now use it. ' end
              || coalesce('Added as members: ' || v_placed || '. ', '')
              || coalesce('Keep their desk as before until you place them in a department that gives it: '
                          || v_kept || '. ', '')
              || coalesce('No longer use the desk (add them to a department that gives it if they still '
                          || 'work there): ' || v_lost || '. ', '')
              || 'Check Employees → Departments.',
            '/app/staff', 'manager', auth.uid());
  end if;
  return v_lines;
end
$$;

-- ---------------------------------------------------------------- E the clinician's own test
-- visit_clinical (from 20261125090000_document_details): each test says whether the signed-in
-- person ordered it ('mine'): while no department gives its desk, the clinician who ordered it
-- still types its result (record_result), and the visit page shows the button.
create or replace function visit_clinical(p_encounter_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  -- clinicians; the lab and the pharmacy read the record too (their orders and prescriptions)
  select case when has_perm('clinical.read') or has_perm('orders.read') or has_perm('prescription.read')
              then jsonb_build_object(
    'diagnoses', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'text', c.text, 'icd10', c.icd10_code, 'type', c.type, 'provisional', c.provisional, 'at', c.created_at,
        'by', (select full_name from profiles where id = c.created_by)) order by c.created_at)
      from condition c where c.encounter_id = p_encounter_id and c.deleted_at is null), '[]'::jsonb),
    'notes', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'text', o.value_text, 'at', o.effective_at,
        'by', (select full_name from profiles where id = o.performer_id)) order by o.effective_at)
      from observation o where o.encounter_id = p_encounter_id and o.code = 'note' and o.deleted_at is null), '[]'::jsonb),
    'prescriptions', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'by', (select full_name from profiles where id = coalesce(m.prescriber_id, m.created_by)), 'item', i.name_generic || coalesce(' ' || i.strength, ''), 'dose', m.dose, 'route', m.route,
        'frequency', m.frequency, 'days', m.duration_days, 'quantity', m.quantity, 'instructions', m.instructions, 'at', m.created_at,
        'dispensed', m.supply = 'room' or exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null),
        'supply', m.supply, 'givenAt', m.given_at, 'givenBy', (select full_name from profiles where id = m.given_by),
        'notGivenAt', m.not_given_at, 'notGivenReason', m.not_given_reason,
        'prescriberId', coalesce(m.prescriber_id, m.created_by), 'pending', rx_pending(m),
        'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
        'cancelledBy', (select full_name from profiles where id = m.cancelled_by),
        'prescriber', doc_person(coalesce(m.prescriber_id, m.created_by))) order by m.created_at)
      from medication_request m join item i on i.id = m.item_id where m.encounter_id = p_encounter_id and m.deleted_at is null), '[]'::jsonb),
    'orders', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'test', s.name_en, 'category', r.category, 'station', coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end), 'status', r.status, 'reason', r.reason, 'at', r.created_at, 'mine', coalesce(r.requester_id = auth.uid(), false),
        'result', (select jsonb_build_object('findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
          'corrected', d.corrected_at is not null, 'correctionReason', d.correction_reason,
          'at', coalesce(d.verified_at, d.updated_at), 'by', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
          'byPerson', doc_person(coalesce(d.verified_by, d.created_by)))
          from diagnostic_report d where d.service_request_id = r.id and d.deleted_at is null)) order by r.created_at)
      from service_request r join service s on s.id = r.service_id where r.encounter_id = p_encounter_id and r.deleted_at is null), '[]'::jsonb),
    'patient', (select jsonb_build_object('id', p.id, 'allergies', p.allergies, 'bloodGroup', p.blood_group, 'notes', p.notes, 'flags', p.flags)
                       || doc_patient(p.id, e.id)
      from encounter e join patient p on p.id = e.patient_id where e.id = p_encounter_id),
    'visit', doc_visit(p_encounter_id)
  ) else null end
$$;

-- ---------------------------------------------------------------- E opening a visit
-- open_encounter (from 20261015180300_visits): start_visit and begin_visit open visits (they check
-- the desks, then open it); called directly it needs "start a visit" and the reception desk.
create or replace function open_encounter(
  p_patient_id uuid,
  p_type encounter_type default 'opd',
  p_station station default 'triage',
  p_coverage_id uuid default null,
  p_appointment_id uuid default null,
  p_practitioner_id uuid default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_ticket text;
  v_prefix text := case p_station when 'dental' then 'D' when 'laboratory' then 'L' when 'ultrasound' then 'U' when 'pharmacy' then 'P' else 'A' end;
begin
  if not has_perm('queue.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if coalesce(current_setting('mmc.visit_open', true), '') <> 'on' then
    if not has_perm('visit.start') then
      raise exception 'you may not start visits (the manager has not allowed it)' using errcode = '42501';
    end if;
    perform assert_desk(array['reception'], 'starting visits');
  end if;
  insert into encounter (patient_id, type, coverage_id, appointment_id, practitioner_id)
  values (p_patient_id, p_type, p_coverage_id, p_appointment_id, p_practitioner_id)
  returning id into v_id;
  v_ticket := v_prefix || '-' || lpad(next_number('ticket_' || v_prefix, to_char(now(), 'YYYYDDD')::integer)::text, 3, '0');
  insert into queue_entry (encounter_id, station, ticket_no) values (v_id, p_station, v_ticket);
  if p_appointment_id is not null then
    update appointment set status = 'arrived' where id = p_appointment_id and status in ('confirmed', 'approved');
  end if;
  return v_id;
end
$$;

-- ---------------------------------------------------------------- E nursing: who works on the patient, who is told
-- may_work_on (from 20261103090000_loose_ends): a task on the visit counts for the people it is for
-- (nurse tasks: the nursing desk once a department gives it, task_for_me).
create or replace function may_work_on(p_encounter_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select is_manager()
    or exists (select 1 from queue_entry q
               where q.encounter_id = p_encounter_id and q.finished_at is null and q.deleted_at is null
                 and queue_entry_for_me(q.id))
    -- a task on this visit for me or the people it is for (the doctor asked the nurse for an injection…)
    or exists (select 1 from internal_task k
               where k.encounter_id = p_encounter_id and k.done_at is null and k.deleted_at is null
                 and (k.assigned_to = auth.uid() or task_for_me(k.assigned_role)))
    -- a colleague who accepted to help on this patient
    or exists (select 1 from staff_call c
               where c.encounter_id = p_encounter_id and c.kind = 'help' and c.status = 'accepted'
                 and c.answered_by = auth.uid())
    -- nobody holds the patient at a treating desk (e.g. now at the cashier): whoever treated
    -- them in this visit may still complete the record
    or (not exists (select 1 from queue_entry q
                    where q.encounter_id = p_encounter_id and q.finished_at is null and q.deleted_at is null
                      and station_role(q.station) in ('doctor', 'nurse', 'lab_tech', 'sonographer'))
        and exists (select 1 from queue_entry q
                    where q.encounter_id = p_encounter_id and q.deleted_at is null
                      and (q.taken_by = auth.uid() or q.assigned_to = auth.uid())))
$$;

-- notify_task (from 20261020120000_departments_notifications): a nurse task is told to the people
-- who give nursing care once a department gives it (each by name); otherwise to the role, as before.
create or replace function notify_task()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_name text;
  v_link text := case when new.encounter_id is not null then '/app/visit?encounter=' || new.encounter_id end;
begin
  select p.surname || ' ' || p.given_names into v_name from patient p where p.id = new.patient_id;
  if new.assigned_to is null and new.assigned_role = 'nurse' and desk_offered('nursing') then
    insert into notification (kind, params, link, recipient_user, created_by)
    select 'task', jsonb_build_object('title', new.title, 'name', v_name, 'due', new.due_at), v_link, p.id,
           auth.uid()
    from profiles p
    where p.active and p.deleted_at is null and p.role <> 'manager' and desk_via(p.id, 'nursing') is not null;
  else
    insert into notification (kind, params, link, recipient_role, recipient_user, created_by)
    values ('task',
            jsonb_build_object('title', new.title, 'name', v_name, 'due', new.due_at),
            v_link,
            case when new.assigned_to is null then new.assigned_role end,
            new.assigned_to,
            auth.uid());
  end if;
  return new;
end
$$;

-- ---------------------------------------------------------------- E no direct writes
-- The clinical tables are written by the desk functions only (they check the desks): the write
-- policies of 0015 (apply_rls) go, and the signed-in roles may no longer insert, change or delete
-- rows directly (reads are unchanged). The same rule as the store and money tables (0083).
do $$
declare
  t text;
begin
  foreach t in array array['service_request', 'diagnostic_report', 'observation', 'condition', 'procedure',
                           'bed', 'bed_stay', 'internal_task', 'encounter', 'queue_entry', 'vaccination',
                           'fp_event', 'hiv_test'] loop
    continue when to_regclass('public.' || quote_ident(t)) is null;
    execute format('revoke insert, update, delete on table %I from authenticated, anon', t);
    execute format('drop policy if exists %I on %I', t || '_insert', t);
    execute format('drop policy if exists %I on %I', t || '_update', t);
    execute format('drop policy if exists %I on %I', t || '_delete', t);
  end loop;
end
$$;

-- ---------------------------------------------------------------- rights
revoke all on function staff_perm(uuid, text), desk_offered(text), in_desk_department(uuid, text),
  desk_via(uuid, text), desk_used_recently(uuid, text), routing_snapshot(), place_staff_for_desks(boolean, text[])
  from public, anon, authenticated;
revoke all on function desk_key(text), all_desks(), treating_desks(), desk_permission(text),
  desk_role_rule(role_key, text, text, text), station_desks(station), request_desk(station, request_category),
  desk_usual(role_key, text, text, text), may_use_desk(text), may_use_any_desk(text[]),
  assert_desk(text[], text), task_for_me(role_key), desks_of(uuid), my_desk_list(), my_desks(),
  role_desk_matrix(), set_role_desk(role_key, text, boolean), forget_kept_desk(uuid, text),
  kept_desks_of(uuid)
  from public, anon;
grant execute on function desk_key(text), all_desks(), treating_desks(), desk_permission(text),
  desk_role_rule(role_key, text, text, text), station_desks(station), request_desk(station, request_category),
  desk_usual(role_key, text, text, text), may_use_desk(text), may_use_any_desk(text[]),
  assert_desk(text[], text), task_for_me(role_key), desks_of(uuid), my_desk_list(), my_desks(),
  role_desk_matrix(), set_role_desk(role_key, text, boolean), forget_kept_desk(uuid, text),
  kept_desks_of(uuid)
  to authenticated;

-- ---------------------------------------------------------------- F day one
select place_staff_for_desks(true);


-- ============================================================ 20261127090000_analytics.sql
-- 0086 · Analytics: the detailed views behind the dashboard cards, and an honest waiting time.
--
-- Frank: "on this part of who did what this month … when clicked it's seen in a detailed view and
-- also on that revenue by day"; "the average waiting time … it's not accurate … remove its
-- representation on the cards"; "create a page for analysis where when I click those highlighted
-- information that is in dashboard I am directed to a detailed view".
--
--   * A  WHO MAY LOOK. analytics_scope(): the manager sees the whole clinic (or one department he
--        picks), with money. The head or assistant of a department sees that department only (its
--        people, its desks, its visits) and never money. Anyone else: 42501. analytics_access()
--        tells the app which views a person may open.
--   * B  WHO DID WHAT. One list of work (analytics_staff_events) feeds staff_activity (everyone),
--        staff_activity_detail (one person: records, sign-ins, money) and the dashboard's
--        "Who did what". Patients seen: the visits where the person took the patient from a queue
--        or wrote a note, diagnosis, prescription, test order or procedure (taking the queue entry
--        alone was rarely recorded, so doctors showed close to 0). Medicines given: handed over at
--        the pharmacy and given from a room store (medication_request.given_by). Retired staff
--        keep the work they did.
--   * C  REVENUE. revenue_analysis(): collected, refunded, net, cancelled, per day and method,
--        against the period before; by source, service category, department (each bill's payments
--        spread over its lines, an estimate), payer, cashier; discounts, refunds, credit notes,
--        cancelled payments and debts. The manager only.
--   * D  PATIENTS AND VISITS. visits_analysis(): registrations, visits, new and returning,
--        bookings, by day, type, service group and hour; the treatments given.
--   * E  WAITING TIME, CORRECTED. wait_time_stats(): one wait is one queue entry at one desk, from
--        joining that desk's queue to being taken there (consultation, dental, theatre, nursing:
--        taken; laboratory, ultrasound: sample collected; triage: the first vitals measured;
--        cashier: the first payment; pharmacy: the first medicine handed over or given). Only
--        finished waits count, so a visit closed without anyone taking the patient, an entry left,
--        and the copies of a patient sent to several desks at once count nowhere (a pooled send
--        counts once, at the desk that took the patient). Waits over 12 hours or across midnight
--        are data errors, counted apart. Median and 90th percentile, never a mean on a card.
--   * F  THE CARDS. No average waiting time on any card any more (dashboard_summary, desk_summary,
--        department_summary, public_clinic_status lose it). "Waiting now" counts the patients who
--        joined a queue today; older entries still open are "forgotten" (please close them).
--        dashboard_summary: the staff rows carry the person's id and the corrected counts; the
--        reorder rows the item's id and full name with strength; revenue per day carries refunds
--        and net.
--
-- Errcodes: 42501 not allowed, 22023 bad input, P0002 not found.

-- ---------------------------------------------------------------- A who may look
-- The caller's scope. The manager: everything (or the department he picks). A head or assistant:
-- their department (the first one when none is given). Internal: not granted.
create or replace function analytics_scope(
  p_department uuid default null,
  out s_manager boolean,
  out s_department uuid,
  out s_desks text[],
  out s_stations station[],
  out s_members uuid[]
)
language plpgsql stable security definer set search_path = public
as $$
begin
  s_manager := is_manager();
  s_department := p_department;
  if not s_manager then
    if p_department is null then
      select sd.department_id into s_department
      from staff_department sd
      join department d on d.id = sd.department_id and d.deleted_at is null
      join profiles p on p.id = sd.profile_id and p.active
      where sd.profile_id = auth.uid() and sd.position in ('head', 'assistant')
      order by d.active desc, d.sort_order, d.name
      limit 1;
    end if;
    if s_department is null or not exists (
      select 1 from staff_department sd
      join department d on d.id = sd.department_id and d.deleted_at is null
      join profiles p on p.id = sd.profile_id and p.active
      where sd.profile_id = auth.uid() and sd.department_id = s_department
        and sd.position in ('head', 'assistant')) then
      raise exception 'not allowed' using errcode = '42501';
    end if;
  end if;
  if s_department is null then
    -- the manager, the whole clinic
    s_desks := null;
    s_stations := enum_range(null::station);
    s_members := null;
    return;
  end if;
  select coalesce(d.services, '{}') into s_desks from department d where d.id = s_department and d.deleted_at is null;
  if not found then
    raise exception 'department not found' using errcode = 'P0002';
  end if;
  select coalesce(array_agg(st order by st), '{}') into s_stations
  from unnest(enum_range(null::station)) st
  where station_desks(st) && s_desks;
  select coalesce(array_agg(sd.profile_id), '{}') into s_members
  from staff_department sd where sd.department_id = s_department;
end
$$;
revoke all on function analytics_scope(uuid) from public, anon, authenticated;

-- What the signed-in person may open on the Analytics page.
create or replace function analytics_access()
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_manager boolean := is_manager();
  v_deps jsonb;
  v_desks text[];
  v_views text[] := '{}';
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if v_manager then
    select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name, 'desks', to_jsonb(coalesce(d.services, '{}')))
                              order by d.sort_order, d.name), '[]'::jsonb)
    into v_deps
    from department d where d.deleted_at is null and d.active;
    v_views := array['revenue', 'staff', 'visits', 'treatments', 'lab', 'pharmacy', 'triage', 'stock', 'waiting'];
  else
    select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name, 'desks', to_jsonb(coalesce(d.services, '{}')))
                              order by d.sort_order, d.name), '[]'::jsonb)
    into v_deps
    from staff_department sd
    join department d on d.id = sd.department_id and d.deleted_at is null
    join profiles p on p.id = sd.profile_id and p.active
    where sd.profile_id = auth.uid() and sd.position in ('head', 'assistant');
    if jsonb_array_length(v_deps) > 0 then
      select coalesce(array_agg(distinct x), '{}') into v_desks
      from jsonb_array_elements(v_deps) dep, jsonb_array_elements_text(dep -> 'desks') x;
      v_views := array['staff', 'visits', 'treatments']
        || case when v_desks && array['laboratory', 'ultrasound'] then array['lab'] else '{}'::text[] end
        || case when 'pharmacy' = any (v_desks) then array['pharmacy'] else '{}'::text[] end
        || case when 'triage' = any (v_desks) then array['triage'] else '{}'::text[] end
        || case when 'pharmacy' = any (v_desks) then array['stock'] else '{}'::text[] end
        || array['waiting'];
    end if;
  end if;
  return jsonb_build_object('manager', v_manager, 'departments', v_deps, 'views', to_jsonb(v_views));
end
$$;
revoke all on function analytics_access() from public, anon;
grant execute on function analytics_access() to authenticated;

-- ---------------------------------------------------------------- B who did what
-- Every piece of work a person did between two moments, one row each (internal: not granted).
--   patientsSeen: one row per person and visit (the first act in the window).
--   vitals: one row per person and visit (the first measurement in the window).
--   Money kinds (payments, refunds, voided, handovers) only when p_money.
create or replace function analytics_staff_events(p_start timestamptz, p_end timestamptz, p_money boolean)
returns table (user_id uuid, at timestamptz, kind text, encounter_id uuid, patient_id uuid, amount numeric, what text)
language sql stable security definer set search_path = public
as $$
  -- registered
  select x.created_by, x.created_at, 'registered', null::uuid, x.id, null::numeric, null::text
  from patient x
  where x.deleted_at is null and x.created_by is not null and x.created_at >= p_start and x.created_at < p_end
  union all
  -- vitals, one per visit
  select v.u, v.at, 'vitals', v.enc, e.patient_id, null, null
  from (select o.performer_id as u, o.encounter_id as enc, min(o.effective_at) as at
        from observation o
        where o.deleted_at is null and o.code <> 'note' and o.performer_id is not null
          and o.effective_at >= p_start and o.effective_at < p_end
        group by 1, 2) v
  join encounter e on e.id = v.enc
  union all
  -- patients seen: took the patient from a queue, or wrote on the visit
  select s.u, s.at, 'patientsSeen', s.enc, e.patient_id, null, e.reference
  from (select a.u, a.enc, min(a.at) as at
        from (
          select q.taken_by as u, q.encounter_id as enc, coalesce(q.started_at, q.finished_at, q.created_at) as at
          from queue_entry q where q.deleted_at is null and q.taken_by is not null
          union all
          select c.created_by, c.encounter_id, c.created_at from condition c where c.deleted_at is null
          union all
          select m.prescriber_id, m.encounter_id, m.created_at from medication_request m where m.deleted_at is null
          union all
          select r.requester_id, r.encounter_id, r.created_at from service_request r where r.deleted_at is null
          union all
          select o.performer_id, o.encounter_id, o.effective_at from observation o where o.deleted_at is null and o.code = 'note'
          union all
          select x.performer_id, x.encounter_id, coalesce(x.performed_at, x.created_at) from procedure x where x.deleted_at is null
        ) a
        where a.u is not null and a.enc is not null and a.at >= p_start and a.at < p_end
        group by 1, 2) s
  join encounter e on e.id = s.enc
  union all
  -- diagnoses
  select c.created_by, c.created_at, 'diagnoses', c.encounter_id, e.patient_id, null,
         trim(coalesce(c.icd10_code || ' ', '') || coalesce(c.text, ''))
  from condition c join encounter e on e.id = c.encounter_id
  where c.deleted_at is null and c.created_by is not null and c.created_at >= p_start and c.created_at < p_end
  union all
  -- prescriptions
  select m.prescriber_id, m.created_at, 'prescriptions', m.encounter_id, e.patient_id, null,
         item_label(m.item_id) || coalesce(' · ' || nullif(m.dose, ''), '')
  from medication_request m join encounter e on e.id = m.encounter_id
  where m.deleted_at is null and m.prescriber_id is not null and m.created_at >= p_start and m.created_at < p_end
  union all
  -- test orders
  select r.requester_id, r.created_at, 'orders', r.encounter_id, e.patient_id, null, sv.name_en
  from service_request r join encounter e on e.id = r.encounter_id left join service sv on sv.id = r.service_id
  where r.deleted_at is null and r.requester_id is not null and r.created_at >= p_start and r.created_at < p_end
  union all
  -- results (verified, else typed)
  select coalesce(d.verified_by, d.created_by), coalesce(d.verified_at, d.created_at), 'results', r.encounter_id, e.patient_id, null, sv.name_en
  from diagnostic_report d
  join service_request r on r.id = d.service_request_id
  join encounter e on e.id = r.encounter_id
  left join service sv on sv.id = r.service_id
  where d.deleted_at is null and coalesce(d.verified_by, d.created_by) is not null
    and coalesce(d.verified_at, d.created_at) >= p_start and coalesce(d.verified_at, d.created_at) < p_end
  union all
  -- procedures
  select x.performer_id, coalesce(x.performed_at, x.created_at), 'procedures', x.encounter_id, e.patient_id, null, sv.name_en
  from procedure x join encounter e on e.id = x.encounter_id left join service sv on sv.id = x.service_id
  where x.deleted_at is null and x.performer_id is not null
    and coalesce(x.performed_at, x.created_at) >= p_start and coalesce(x.performed_at, x.created_at) < p_end
  union all
  -- medicines given: handed over at the pharmacy …
  select md.dispenser_id, md.created_at, 'medicinesGiven', md.encounter_id, e.patient_id, null,
         item_label(md.item_id) || ' × ' || trim_scale(md.quantity)::text
  from medication_dispense md left join encounter e on e.id = md.encounter_id
  where md.deleted_at is null and md.dispenser_id is not null and md.created_at >= p_start and md.created_at < p_end
  union all
  -- … and given from a room store (a pharmacy hand-over also sets given_by: it is counted above,
  -- through its medication_dispense row, so only requests without one come from here)
  select m.given_by, m.given_at, 'medicinesGiven', m.encounter_id, e.patient_id, null, item_label(m.item_id)
  from medication_request m join encounter e on e.id = m.encounter_id
  where m.deleted_at is null and m.given_by is not null and m.given_at >= p_start and m.given_at < p_end
    and not exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null)
  union all
  -- charges
  select l.entered_by, l.created_at, 'charges', i.encounter_id, e.patient_id, round(l.unit_price * l.quantity), l.description
  from invoice_line l join invoice i on i.id = l.invoice_id left join encounter e on e.id = i.encounter_id
  where l.deleted_at is null and l.entered_by is not null and l.created_at >= p_start and l.created_at < p_end
  union all
  -- admissions
  select b.created_by, coalesce(b.admitted_at, b.created_at), 'admissions', b.encounter_id, e.patient_id, null, bd.name
  from bed_stay b join encounter e on e.id = b.encounter_id left join bed bd on bd.id = b.bed_id
  where b.deleted_at is null and b.created_by is not null
    and coalesce(b.admitted_at, b.created_at) >= p_start and coalesce(b.admitted_at, b.created_at) < p_end
  union all
  -- tasks done
  select k.done_by, k.done_at, 'tasksDone', k.encounter_id, k.patient_id, null, k.title
  from internal_task k
  where k.deleted_at is null and k.done_by is not null and k.done_at >= p_start and k.done_at < p_end
  union all
  select v.created_by, v.created_at, 'vaccinations', v.encounter_id, v.patient_id, null, v.vaccine
  from vaccination v
  where v.deleted_at is null and v.created_by is not null and v.created_at >= p_start and v.created_at < p_end
  union all
  -- an HIV test: never its result
  select h.created_by, coalesce(h.tested_at, h.created_at), 'hivTests', h.encounter_id, h.patient_id, null, null
  from hiv_test h
  where h.deleted_at is null and h.created_by is not null
    and coalesce(h.tested_at, h.created_at) >= p_start and coalesce(h.tested_at, h.created_at) < p_end
  union all
  select f.created_by, f.created_at, 'familyPlanning', f.encounter_id, f.patient_id, null, f.method
  from fp_event f
  where f.deleted_at is null and f.created_by is not null and f.created_at >= p_start and f.created_at < p_end
  union all
  -- money (the manager only)
  select y.cashier_id, y.paid_at, 'payments', i.encounter_id, e.patient_id, y.amount, y.method::text
  from payment y left join invoice i on i.id = y.invoice_id left join encounter e on e.id = i.encounter_id
  where p_money and y.deleted_at is null and y.cashier_id is not null and y.paid_at >= p_start and y.paid_at < p_end
  union all
  select rf.cashier_id, rf.refunded_at, 'refunds', i.encounter_id, e.patient_id, rf.amount, rf.reason
  from refund rf join invoice i on i.id = rf.invoice_id left join encounter e on e.id = i.encounter_id
  where p_money and rf.deleted_at is null and rf.cashier_id is not null and rf.refunded_at >= p_start and rf.refunded_at < p_end
  union all
  select y.voided_by, y.voided_at, 'voided', i.encounter_id, e.patient_id, y.amount, y.void_reason
  from payment y left join invoice i on i.id = y.invoice_id left join encounter e on e.id = i.encounter_id
  where p_money and y.voided_by is not null and y.voided_at >= p_start and y.voided_at < p_end
  union all
  select cs.handed_over_by, cs.handed_over_at, 'handovers', null, null, cs.total, cs.number
  from counter_sale cs
  where p_money and cs.deleted_at is null and cs.handed_over_by is not null
    and cs.handed_over_at >= p_start and cs.handed_over_at < p_end
$$;
revoke all on function analytics_staff_events(timestamptz, timestamptz, boolean) from public, anon, authenticated;

-- The kinds of work in display order (money last, the manager only).
create or replace function analytics_kinds(p_money boolean)
returns text[]
language sql immutable
as $$
  select array['registered', 'vitals', 'patientsSeen', 'diagnoses', 'prescriptions', 'orders', 'results',
               'procedures', 'medicinesGiven', 'charges', 'admissions', 'tasksDone', 'vaccinations',
               'hivTests', 'familyPlanning']
         || case when p_money then array['payments', 'refunds', 'voided', 'handovers'] else '{}'::text[] end
$$;

-- Everyone's work in the period: per person, per day and kind, and the totals.
create or replace function staff_activity(p_from date default null, p_to date default null, p_department uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  s record;
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_kinds text[];
  v_result jsonb;
begin
  select * into s from analytics_scope(p_department);
  if v_to < v_from then
    select v_to, v_from into v_from, v_to;
  end if;
  v_kinds := analytics_kinds(s.s_manager);
  with ev as (
    select * from analytics_staff_events(v_from::timestamp at time zone 'Africa/Kigali',
                                         (v_to + 1)::timestamp at time zone 'Africa/Kigali', s.s_manager)
    where s.s_members is null or user_id = any (s.s_members)
  ),
  per as (
    select ev.user_id, ev.kind, count(*) as n, sum(ev.amount) as amount from ev group by 1, 2
  ),
  people as (
    select p.id, p.full_name, p.role, p.staff_id, p.active and p.deleted_at is null as active, p.last_sign_in_at,
           (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) order by d.sort_order, d.name), '[]'::jsonb)
            from staff_department sd join department d on d.id = sd.department_id and d.deleted_at is null
            where sd.profile_id = p.id) as departments,
           (select coalesce(jsonb_object_agg(k, coalesce((select per.n from per where per.user_id = p.id and per.kind = k), 0)), '{}'::jsonb)
            from unnest(v_kinds) k) as counts,
           (select coalesce(sum(per.n), 0) from per
            where per.user_id = p.id and per.kind not in ('patientsSeen', 'payments', 'refunds', 'voided', 'handovers')) as records,
           (select per.amount from per where per.user_id = p.id and per.kind = 'payments') as collected
    from profiles p
    where (s.s_members is null or p.id = any (s.s_members))
      and ((p.active and p.deleted_at is null) or exists (select 1 from per where per.user_id = p.id))
  )
  select jsonb_build_object(
    'from', v_from, 'to', v_to, 'manager', s.s_manager, 'department', s.s_department,
    'kinds', to_jsonb(v_kinds),
    'people', coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', x.id, 'name', x.full_name, 'role', x.role, 'staffId', x.staff_id, 'departments', x.departments,
          'active', x.active, 'lastSignIn', x.last_sign_in_at, 'counts', x.counts, 'records', x.records,
          'amount', case when s.s_manager then coalesce(x.collected, 0) end)
        order by x.records desc, x.full_name)
      from people x), '[]'::jsonb),
    'days', coalesce((
      select jsonb_agg(jsonb_build_object('day', d.day, 'userId', d.user_id, 'kind', d.kind, 'n', d.n,
                                          'amount', case when s.s_manager then d.amount end)
                       order by d.day, d.user_id, d.kind)
      from (select (ev.at at time zone 'Africa/Kigali')::date as day, ev.user_id, ev.kind, count(*) as n, sum(ev.amount) as amount
            from ev group by 1, 2, 3) d), '[]'::jsonb),
    'totals', (select coalesce(jsonb_object_agg(k, coalesce((select sum(per.n) from per where per.kind = k), 0)), '{}'::jsonb)
               from unnest(v_kinds) k),
    'summary', jsonb_build_object(
      'peopleActive', (select count(distinct ev.user_id) from ev),
      'patientsSeen', (select count(distinct ev.encounter_id) from ev where ev.kind = 'patientsSeen'),
      'records', (select count(*) from ev where ev.kind not in ('patientsSeen', 'payments', 'refunds', 'voided', 'handovers')),
      'collected', case when s.s_manager then (select coalesce(sum(ev.amount), 0) from ev where ev.kind = 'payments') end)
  ) into v_result;
  return v_result;
end
$$;
revoke all on function staff_activity(date, date, uuid) from public, anon;
grant execute on function staff_activity(date, date, uuid) to authenticated;

-- One person's work: records (newest first), sign-ins and, for the manager, money.
create or replace function staff_activity_detail(
  p_user uuid,
  p_from date default null,
  p_to date default null,
  p_kind text default null,
  p_limit integer default 500
)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_manager boolean := is_manager();
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_start timestamptz;
  v_end timestamptz;
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 500);
  v_person jsonb;
  v_result jsonb;
begin
  if not v_manager and not exists (
    select 1
    from staff_department mine
    join department d on d.id = mine.department_id and d.deleted_at is null
    join profiles me on me.id = mine.profile_id and me.active
    join staff_department theirs on theirs.department_id = mine.department_id
    where mine.profile_id = auth.uid() and mine.position in ('head', 'assistant') and theirs.profile_id = p_user) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_kind is not null and not (p_kind = any (analytics_kinds(v_manager))) then
    raise exception 'unknown kind of work' using errcode = '22023';
  end if;
  if v_to < v_from then
    select v_to, v_from into v_from, v_to;
  end if;
  v_start := v_from::timestamp at time zone 'Africa/Kigali';
  v_end := (v_to + 1)::timestamp at time zone 'Africa/Kigali';
  select jsonb_build_object('id', p.id, 'name', p.full_name, 'role', p.role, 'staffId', p.staff_id,
                            'active', p.active and p.deleted_at is null, 'lastSignIn', p.last_sign_in_at,
                            'departments', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) order by d.sort_order, d.name), '[]'::jsonb)
                                            from staff_department sd join department d on d.id = sd.department_id and d.deleted_at is null
                                            where sd.profile_id = p.id))
  into v_person
  from profiles p where p.id = p_user;
  if v_person is null then
    raise exception 'person not found' using errcode = 'P0002';
  end if;

  with ev as (
    select * from analytics_staff_events(v_start, v_end, v_manager) where user_id = p_user
  )
  select jsonb_build_object(
    'from', v_from, 'to', v_to, 'person', v_person,
    'counts', (select coalesce(jsonb_object_agg(k, coalesce((select count(*) from ev where ev.kind = k), 0)), '{}'::jsonb)
               from unnest(analytics_kinds(v_manager)) k),
    'days', coalesce((
      select jsonb_agg(jsonb_build_object('day', d.day, 'kind', d.kind, 'n', d.n) order by d.day, d.kind)
      from (select (ev.at at time zone 'Africa/Kigali')::date as day, ev.kind, count(*) as n from ev group by 1, 2) d), '[]'::jsonb),
    'total', (select count(*) from ev where p_kind is null or ev.kind = p_kind),
    'records', coalesce((
      select jsonb_agg(jsonb_build_object(
          'at', r.at, 'kind', r.kind, 'encounterId', r.encounter_id, 'patientId', r.pid,
          'patientName', r.pname, 'fileNumber', r.file_number, 'what', r.what,
          'amount', case when v_manager then r.amount end) order by r.at desc)
      from (
        select ev.at, ev.kind, ev.encounter_id, ev.what, ev.amount,
               -- an HIV test names its patient to the manager only
               case when ev.kind = 'hivTests' and not v_manager then null else ev.patient_id end as pid,
               case when ev.kind = 'hivTests' and not v_manager then null else pt.surname || ' ' || pt.given_names end as pname,
               case when ev.kind = 'hivTests' and not v_manager then null else pt.file_number end as file_number
        from ev left join patient pt on pt.id = ev.patient_id
        where p_kind is null or ev.kind = p_kind
        order by ev.at desc
        limit v_limit) r), '[]'::jsonb),
    'signIns', coalesce((
      select jsonb_agg(jsonb_build_object('at', a.at, 'ok', a.reason is null or a.reason not like 'wrong PIN%', 'reason', a.reason)
                       order by a.at desc)
      from (select at, reason from audit_event
            where actor_id = p_user and action = 'login' and at >= v_start and at < v_end
            order by at desc limit 200) a), '[]'::jsonb),
    'money', case when v_manager then jsonb_build_object(
      'byMethod', coalesce((
        select jsonb_agg(jsonb_build_object('method', m.method, 'count', m.n, 'amount', m.amount) order by m.amount desc)
        from (select method, count(*) as n, sum(amount) as amount from payment
              where cashier_id = p_user and deleted_at is null and paid_at >= v_start and paid_at < v_end
              group by method) m), '[]'::jsonb),
      'refunds', coalesce((
        select jsonb_agg(jsonb_build_object('at', rf.refunded_at, 'amount', rf.amount, 'method', rf.method, 'reason', rf.reason,
                                            'patient', pt.surname || ' ' || pt.given_names, 'fileNumber', pt.file_number,
                                            'encounterId', i.encounter_id) order by rf.refunded_at desc)
        from refund rf
        join invoice i on i.id = rf.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient pt on pt.id = e.patient_id
        where rf.cashier_id = p_user and rf.deleted_at is null and rf.refunded_at >= v_start and rf.refunded_at < v_end), '[]'::jsonb),
      'voided', coalesce((
        select jsonb_agg(jsonb_build_object('at', y.voided_at, 'paidAt', y.paid_at, 'amount', y.amount, 'method', y.method,
                                            'reason', y.void_reason, 'by', vb.full_name,
                                            'patient', coalesce(pt.surname || ' ' || pt.given_names, cs.buyer_name)) order by y.voided_at desc)
        from payment y
        left join profiles vb on vb.id = y.voided_by
        left join invoice i on i.id = y.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient pt on pt.id = e.patient_id
        left join counter_sale cs on cs.id = y.counter_sale_id
        where y.cashier_id = p_user and y.voided_at is not null and y.voided_at >= v_start and y.voided_at < v_end), '[]'::jsonb),
      'closes', coalesce((
        select jsonb_agg(jsonb_build_object('day', c.date, 'expected', c.expected, 'counted', c.counted, 'variance', c.variance)
                         order by c.date desc)
        from day_close c
        where c.cashier_id = p_user and c.deleted_at is null and c.date between v_from and v_to), '[]'::jsonb))
    end
  ) into v_result;
  return v_result;
end
$$;
revoke all on function staff_activity_detail(uuid, date, date, text, integer) from public, anon;
grant execute on function staff_activity_detail(uuid, date, date, text, integer) to authenticated;

-- ---------------------------------------------------------------- C revenue
-- The money figures of a window (internal: the period and the one before).
create or replace function revenue_totals(p_start timestamptz, p_end timestamptz)
returns jsonb
language sql stable security definer set search_path = public
as $$
  with ok as (
    select y.* from payment y where y.deleted_at is null and y.paid_at >= p_start and y.paid_at < p_end
  ),
  rf as (
    select r.* from refund r where r.deleted_at is null and r.refunded_at >= p_start and r.refunded_at < p_end
  ),
  -- what was charged: visit bill lines and walk-in (counter) sale lines, a cancelled sale left out
  ln as (
    select round(l.unit_price * l.quantity) as amount, l.list_price, l.unit_price, l.quantity
    from invoice_line l where l.deleted_at is null and l.created_at >= p_start and l.created_at < p_end
    union all
    select x.line_total, x.unit_price, x.unit_price, x.quantity
    from counter_sale_line x join counter_sale s on s.id = x.sale_id
    where x.deleted_at is null and s.deleted_at is null and s.status <> 'cancelled'
      and x.created_at >= p_start and x.created_at < p_end
  ),
  t as (
    select
      (select coalesce(sum(amount), 0) from ok) as collected,
      (select count(*) from ok) as payments,
      (select coalesce(sum(amount), 0) from ok where invoice_id is not null) as bills,
      (select coalesce(sum(amount), 0) from ok where counter_sale_id is not null) as counter_sales,
      (select count(distinct i.encounter_id) from ok join invoice i on i.id = ok.invoice_id) as paid_visits,
      (select coalesce(sum(amount), 0) from rf) as refunded,
      (select count(*) from rf) as refunds,
      (select coalesce(sum(amount), 0) from payment y
       where y.voided_at is not null and y.voided_at >= p_start and y.voided_at < p_end) as voided,
      (select count(*) from payment y
       where y.voided_at is not null and y.voided_at >= p_start and y.voided_at < p_end) as voided_count,
      (select coalesce(sum(amount), 0) from ln) as charged,
      (select coalesce(sum(round((list_price - unit_price) * quantity)), 0) from ln where list_price > unit_price) as discounts,
      (select coalesce(sum(total), 0) from credit_note c
       where c.deleted_at is null and c.created_at >= p_start and c.created_at < p_end) as credit_notes
  )
  select jsonb_build_object(
    'collected', t.collected, 'refunded', t.refunded, 'net', t.collected - t.refunded,
    'refunds', t.refunds, 'voided', t.voided, 'voidedCount', t.voided_count,
    'payments', t.payments, 'paidVisits', t.paid_visits,
    'avgPerVisit', case when t.paid_visits > 0 then round(t.bills / t.paid_visits) end,
    'bills', t.bills, 'counterSales', t.counter_sales,
    'charged', t.charged, 'discounts', t.discounts, 'creditNotes', t.credit_notes)
  from t
$$;
revoke all on function revenue_totals(timestamptz, timestamptz) from public, anon, authenticated;

create or replace function revenue_analysis(p_from date default null, p_to date default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_len integer;
  v_start timestamptz;
  v_end timestamptz;
  v_pharmacy uuid;
  v_result jsonb;
begin
  if not is_manager() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_to < v_from then
    select v_to, v_from into v_from, v_to;
  end if;
  v_len := v_to - v_from + 1;
  v_start := v_from::timestamp at time zone 'Africa/Kigali';
  v_end := (v_to + 1)::timestamp at time zone 'Africa/Kigali';
  -- medicines count as the pharmacy's
  select d.id into v_pharmacy from department d
  where d.active and d.deleted_at is null and 'pharmacy' = any (d.services)
  order by d.sort_order, d.name limit 1;

  with ok as (
    select y.* from payment y where y.deleted_at is null and y.paid_at >= v_start and y.paid_at < v_end
  ),
  rf as (
    select r.* from refund r where r.deleted_at is null and r.refunded_at >= v_start and r.refunded_at < v_end
  ),
  vd as (
    select y.* from payment y where y.voided_at is not null and y.voided_at >= v_start and y.voided_at < v_end
  ),
  -- every bill line with its category and department; bill = the visit bill or the counter sale
  lk as (
    select l.id, l.invoice_id as bill_id, l.created_at, round(l.unit_price * l.quantity) as amount,
           l.list_price, l.unit_price, l.quantity::numeric as quantity, l.discount_reason,
           c.id as cat_id, coalesce(c.base_group::text, case when sv.id is null then 'pharmacy' else 'other' end) as cat_group,
           c.name_en, c.name_kin, c.name_fr,
           case when sv.id is null then v_pharmacy else sv.department_id end as dept_id,
           case when sv.id is null then 'pharmacy' when sv.department_id is null then 'none' else 'department' end as dept_key
    from invoice_line l
    left join service sv on sv.id = l.service_id
    left join service_category c on c.id = sv.category_id
    where l.deleted_at is null
    union all
    -- walk-in medicine sales (counter sales) are the pharmacy's; a cancelled sale is left out
    select x.id, x.sale_id, x.created_at, x.line_total, x.unit_price, x.unit_price, x.quantity::numeric, null::text,
           null::uuid, 'pharmacy', null::text, null::text, null::text, v_pharmacy, 'pharmacy'
    from counter_sale_line x join counter_sale s on s.id = x.sale_id
    where x.deleted_at is null and s.deleted_at is null and s.status <> 'cancelled'
  ),
  ln as (select * from lk where lk.created_at >= v_start and lk.created_at < v_end),
  -- each bill's payments in the period spread over its lines by their amount (an estimate)
  est as (
    select lk.*, ok.amount * lk.amount / bt.total as collected
    from ok
    join (select bill_id, sum(amount) as total from lk group by bill_id having sum(amount) > 0) bt
      on bt.bill_id = coalesce(ok.invoice_id, ok.counter_sale_id)
    join lk on lk.bill_id = bt.bill_id
  ),
  dd as (
    select d::date as day from generate_series(v_from, v_to, interval '1 day') d
    where v_len <= 400
    union
    select (paid_at at time zone 'Africa/Kigali')::date from ok
    union
    select (refunded_at at time zone 'Africa/Kigali')::date from rf
    union
    select (voided_at at time zone 'Africa/Kigali')::date from vd
  )
  select jsonb_build_object(
    'from', v_from, 'to', v_to,
    'totals', revenue_totals(v_start, v_end),
    'prev', revenue_totals((v_from - v_len)::timestamp at time zone 'Africa/Kigali', v_start),
    'prevFrom', v_from - v_len, 'prevTo', v_from - 1,
    'days', coalesce((
      select jsonb_agg(jsonb_build_object(
          'day', dd.day,
          'cash', coalesce(p.cash, 0), 'momo', coalesce(p.momo, 0), 'airtel', coalesce(p.airtel, 0), 'other', coalesce(p.other, 0),
          'payments', coalesce(p.n, 0), 'refunds', coalesce(r.amount, 0), 'voided', coalesce(v.amount, 0),
          'net', coalesce(p.total, 0) - coalesce(r.amount, 0), 'visits', coalesce(p.visits, 0),
          'counterSales', coalesce(p.counter, 0)) order by dd.day)
      from dd
      left join (
        select (ok.paid_at at time zone 'Africa/Kigali')::date as day,
               sum(ok.amount) filter (where ok.method = 'cash') as cash,
               sum(ok.amount) filter (where ok.method = 'momo') as momo,
               sum(ok.amount) filter (where ok.method = 'airtel') as airtel,
               sum(ok.amount) filter (where ok.method not in ('cash', 'momo', 'airtel')) as other,
               sum(ok.amount) as total, count(*) as n,
               sum(ok.amount) filter (where ok.counter_sale_id is not null) as counter,
               count(distinct i.encounter_id) as visits
        from ok left join invoice i on i.id = ok.invoice_id
        group by 1) p on p.day = dd.day
      left join (select (refunded_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount from rf group by 1) r on r.day = dd.day
      left join (select (voided_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount from vd group by 1) v on v.day = dd.day
    ), '[]'::jsonb),
    'byMethod', coalesce((
      select jsonb_agg(jsonb_build_object('method', m.method, 'amount', m.amount, 'count', m.n,
                                          'share', round(100.0 * m.amount / nullif((select sum(amount) from ok), 0), 1))
                       order by m.amount desc)
      from (select method, sum(amount) as amount, count(*) as n from ok group by method) m), '[]'::jsonb),
    'bySource', jsonb_build_object(
      'bills', jsonb_build_object('amount', (select coalesce(sum(amount), 0) from ok where invoice_id is not null),
                                  'count', (select count(*) from ok where invoice_id is not null)),
      'counterSales', jsonb_build_object('amount', (select coalesce(sum(amount), 0) from ok where counter_sale_id is not null),
                                         'count', (select count(*) from ok where counter_sale_id is not null))),
    'byCategory', coalesce((
      select jsonb_agg(jsonb_build_object('id', g.cat_id, 'group', g.cat_group, 'name', g.name_en, 'nameKin', g.name_kin,
                                          'nameFr', g.name_fr, 'charged', g.charged, 'collectedEst', round(g.collected),
                                          'lines', g.lines) order by g.charged desc, g.collected desc)
      from (
        select k.cat_id, k.cat_group, max(k.name_en) as name_en, max(k.name_kin) as name_kin, max(k.name_fr) as name_fr,
               coalesce(sum(k.charged), 0) as charged, coalesce(sum(k.collected), 0) as collected, coalesce(sum(k.lines), 0) as lines
        from (
          select cat_id, cat_group, name_en, name_kin, name_fr, amount as charged, 0::numeric as collected, 1 as lines from ln
          union all
          select cat_id, cat_group, name_en, name_kin, name_fr, 0, collected, 0 from est
        ) k
        group by k.cat_id, k.cat_group) g), '[]'::jsonb),
    'byDepartment', coalesce((
      select jsonb_agg(jsonb_build_object('id', g.dept_id, 'key', g.dept_key, 'name', d.name, 'charged', g.charged,
                                          'collectedEst', round(g.collected), 'lines', g.lines) order by g.charged desc, g.collected desc)
      from (
        select k.dept_id, case when k.dept_id is not null then 'department' else max(k.dept_key) end as dept_key,
               coalesce(sum(k.charged), 0) as charged, coalesce(sum(k.collected), 0) as collected, coalesce(sum(k.lines), 0) as lines
        from (
          select dept_id, dept_key, amount as charged, 0::numeric as collected, 1 as lines from ln
          union all
          select dept_id, dept_key, 0, collected, 0 from est
        ) k
        group by k.dept_id, case when k.dept_id is null then k.dept_key end) g
      left join department d on d.id = g.dept_id), '[]'::jsonb),
    'byPayer', coalesce((
      select jsonb_agg(jsonb_build_object('payerId', b.payer_id, 'name', py.name, 'type', coalesce(py.type::text, 'cash'),
                                          'bills', b.bills, 'patientShare', b.patient_share, 'insurerShare', b.insurer_share,
                                          'paid', b.paid, 'owed', b.owed) order by b.bills desc)
      from (
        select i.payer_id, count(*) as bills, sum(i.patient_share) as patient_share, sum(i.insurer_share) as insurer_share,
               sum((select coalesce(sum(y.amount), 0) from payment y where y.invoice_id = i.id and y.deleted_at is null)) as paid,
               sum(greatest(invoice_balance(i.id), 0)) as owed
        from invoice i
        where i.deleted_at is null and i.total > 0 and i.created_at >= v_start and i.created_at < v_end
        group by i.payer_id) b
      left join payer py on py.id = b.payer_id), '[]'::jsonb),
    'byCashier', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', pr.full_name,
                                          'payments', (select count(*) from ok where ok.cashier_id = c.id),
                                          'amount', (select coalesce(sum(amount), 0) from ok where ok.cashier_id = c.id),
                                          'refunds', (select coalesce(sum(amount), 0) from rf where rf.cashier_id = c.id),
                                          'voided', (select count(*) from vd where vd.cashier_id = c.id),
                                          'variance', (select sum(dc.variance) from day_close dc
                                                       where dc.cashier_id = c.id and dc.deleted_at is null
                                                         and dc.date between v_from and v_to))
                       order by pr.full_name)
      from (select cashier_id as id from ok union select cashier_id from rf union select cashier_id from vd
            union select cashier_id from day_close where deleted_at is null and date between v_from and v_to) c
      join profiles pr on pr.id = c.id), '[]'::jsonb),
    'discounts', jsonb_build_object(
      'lines', (select count(*) from ln where list_price > unit_price),
      'amount', (select coalesce(sum(round((list_price - unit_price) * quantity)), 0) from ln where list_price > unit_price),
      'byReason', coalesce((
        select jsonb_agg(jsonb_build_object('reason', x.reason, 'lines', x.n, 'amount', x.amount) order by x.amount desc)
        from (select nullif(trim(coalesce(discount_reason, '')), '') as reason, count(*) as n,
                     sum(round((list_price - unit_price) * quantity)) as amount
              from ln where list_price > unit_price group by 1) x), '[]'::jsonb)),
    'refunds', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select rf.refunded_at as at,
               jsonb_build_object('id', rf.id, 'at', rf.refunded_at, 'amount', rf.amount, 'method', rf.method, 'reason', rf.reason,
                                  'by', pr.full_name, 'invoiceId', rf.invoice_id, 'encounterId', i.encounter_id,
                                  'patient', pt.surname || ' ' || pt.given_names, 'fileNumber', pt.file_number) as j
        from rf
        join invoice i on i.id = rf.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient pt on pt.id = e.patient_id
        left join profiles pr on pr.id = rf.cashier_id
        order by rf.refunded_at desc limit 200) x), '[]'::jsonb),
    'creditNotes', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select c.created_at as at,
               jsonb_build_object('id', c.id, 'at', c.created_at, 'number', c.number, 'amount', c.total,
                                  'patientAmount', c.patient_amount, 'insurerAmount', c.insurer_amount, 'reason', c.reason,
                                  'by', pr.full_name, 'invoiceId', c.invoice_id, 'encounterId', i.encounter_id,
                                  'patient', pt.surname || ' ' || pt.given_names, 'fileNumber', pt.file_number) as j
        from credit_note c
        join invoice i on i.id = c.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient pt on pt.id = e.patient_id
        left join profiles pr on pr.id = coalesce(c.approver_id, c.created_by)
        where c.deleted_at is null and c.created_at >= v_start and c.created_at < v_end
        order by c.created_at desc limit 200) x), '[]'::jsonb),
    'voided', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select vd.voided_at as at,
               jsonb_build_object('id', vd.id, 'at', vd.voided_at, 'paidAt', vd.paid_at, 'amount', vd.amount, 'method', vd.method,
                                  'reason', vd.void_reason, 'by', vb.full_name, 'cashier', cb.full_name, 'receiptNo', vd.receipt_no,
                                  'encounterId', i.encounter_id,
                                  'patient', coalesce(pt.surname || ' ' || pt.given_names, cs.buyer_name),
                                  'fileNumber', pt.file_number) as j
        from vd
        left join profiles vb on vb.id = vd.voided_by
        left join profiles cb on cb.id = vd.cashier_id
        left join invoice i on i.id = vd.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient pt on pt.id = e.patient_id
        left join counter_sale cs on cs.id = vd.counter_sale_id
        order by vd.voided_at desc limit 200) x), '[]'::jsonb),
    -- what is owed now (not a period figure)
    'debts', (
      select jsonb_build_object(
        'openCount', count(*) filter (where b.open), 'openDue', coalesce(sum(b.due) filter (where b.open), 0),
        'closedCount', count(*) filter (where not b.open), 'closedDue', coalesce(sum(b.due) filter (where not b.open), 0),
        'top', coalesce((
          select jsonb_agg(jsonb_build_object('invoiceId', t.id, 'number', coalesce(t.number, t.provisional_no),
                                              'encounterId', t.encounter_id, 'patient', t.patient, 'fileNumber', t.file_number,
                                              'due', t.due, 'open', t.open, 'arrivedAt', t.arrived_at) order by t.due desc)
          from (select * from (
                  select i.id, i.number, i.provisional_no, i.encounter_id, invoice_balance(i.id) as due, e.status = 'open' as open,
                         e.arrived_at, pt.surname || ' ' || pt.given_names as patient, pt.file_number
                  from invoice i join encounter e on e.id = i.encounter_id join patient pt on pt.id = e.patient_id
                  where i.deleted_at is null and i.total > 0) z
                where z.due > 0 order by z.due desc limit 20) t), '[]'::jsonb))
      from (select invoice_balance(i.id) as due, e.status = 'open' as open
            from invoice i join encounter e on e.id = i.encounter_id
            where i.deleted_at is null and i.total > 0) b
      where b.due > 0)
  ) into v_result;
  return v_result;
end
$$;
revoke all on function revenue_analysis(date, date) from public, anon;
grant execute on function revenue_analysis(date, date) to authenticated;

-- ---------------------------------------------------------------- D patients and visits
-- The visits of a window in scope (all, or those with a queue entry at one of the stations). A
-- department counts a visit only when one of its own people took or was given the patient there,
-- or the visit was sent to it: a visit at a desk several departments give is not counted for each.
create or replace function analytics_visits(p_start timestamptz, p_end timestamptz, p_stations station[],
                                            p_members uuid[] default null)
returns table (id uuid, patient_id uuid, type encounter_type, arrived_at timestamptz, is_new boolean)
language sql stable security definer set search_path = public
as $$
  select e.id, e.patient_id, e.type, e.arrived_at,
         not exists (select 1 from encounter x where x.patient_id = e.patient_id and x.deleted_at is null
                     and (x.arrived_at < e.arrived_at or (x.arrived_at = e.arrived_at and x.id < e.id)))
  from encounter e
  where e.deleted_at is null and e.arrived_at >= p_start and e.arrived_at < p_end
    and (p_stations is null or exists (select 1 from queue_entry q where q.encounter_id = e.id and q.deleted_at is null
                                       and q.station = any (p_stations)
                                       and (p_members is null
                                            or q.taken_by = any (p_members) or q.assigned_to = any (p_members)
                                            or exists (select 1 from staff_department sd
                                                       where sd.department_id = q.department_id
                                                         and sd.profile_id = any (p_members)))))
$$;
revoke all on function analytics_visits(timestamptz, timestamptz, station[], uuid[]) from public, anon, authenticated;

create or replace function visits_totals(p_start timestamptz, p_end timestamptz, p_stations station[], p_members uuid[])
returns jsonb
language sql stable security definer set search_path = public
as $$
  with v as (select * from analytics_visits(p_start, p_end, p_stations, p_members)),
  ap as (
    select a.status from appointment a
    left join practitioner pr on pr.id = a.practitioner_id
    where a.deleted_at is null and coalesce(a.starts_at, a.created_at) >= p_start and coalesce(a.starts_at, a.created_at) < p_end
      and (p_members is null or pr.user_id = any (p_members))
  )
  select jsonb_build_object(
    'registered', (select count(*) from patient x
                   where x.deleted_at is null and x.created_at >= p_start and x.created_at < p_end
                     and (p_stations is null or exists (select 1 from v where v.patient_id = x.id))),
    'visits', (select count(*) from v),
    'newPatients', (select count(*) from v where v.is_new),
    'returning', (select count(*) from v where not v.is_new),
    'booked', (select count(*) from ap where status in ('confirmed', 'arrived', 'in_progress', 'completed', 'no_show')),
    'kept', (select count(*) from ap where status in ('arrived', 'in_progress', 'completed')),
    'missed', (select count(*) from ap where status = 'no_show'),
    'pending', (select count(*) from ap where status = 'inquiry'))
$$;
revoke all on function visits_totals(timestamptz, timestamptz, station[], uuid[]) from public, anon, authenticated;

create or replace function visits_analysis(p_from date default null, p_to date default null, p_department uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  s record;
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_len integer;
  v_start timestamptz;
  v_end timestamptz;
  v_stations station[];
  v_result jsonb;
begin
  select * into s from analytics_scope(p_department);
  if v_to < v_from then
    select v_to, v_from into v_from, v_to;
  end if;
  v_len := v_to - v_from + 1;
  v_start := v_from::timestamp at time zone 'Africa/Kigali';
  v_end := (v_to + 1)::timestamp at time zone 'Africa/Kigali';
  v_stations := case when s.s_department is null then null else s.s_stations end;

  with v as (select * from analytics_visits(v_start, v_end, v_stations,
                                            case when s.s_department is null then null else s.s_members end)),
  -- the bill lines of the window (a department: its own services)
  ln as (
    select l.*, sv.category_id, sv.department_id as service_department
    from invoice_line l
    join invoice i on i.id = l.invoice_id
    left join service sv on sv.id = l.service_id
    where l.deleted_at is null and l.created_at >= v_start and l.created_at < v_end
      and (s.s_department is null
           or sv.department_id = s.s_department
           or exists (select 1 from service_department sd where sd.service_id = sv.id and sd.department_id = s.s_department))
  ),
  dd as (
    select d::date as day from generate_series(v_from, v_to, interval '1 day') d where v_len <= 400
    union
    select (arrived_at at time zone 'Africa/Kigali')::date from v
  )
  select jsonb_build_object(
    'from', v_from, 'to', v_to, 'manager', s.s_manager, 'department', s.s_department,
    'totals', visits_totals(v_start, v_end, v_stations, s.s_members),
    'prev', visits_totals((v_from - v_len)::timestamp at time zone 'Africa/Kigali', v_start, v_stations, s.s_members),
    'prevFrom', v_from - v_len, 'prevTo', v_from - 1,
    'days', coalesce((
      select jsonb_agg(jsonb_build_object(
          'day', dd.day, 'visits', coalesce(a.visits, 0), 'newPatients', coalesce(a.new_patients, 0),
          'returning', coalesce(a.visits, 0) - coalesce(a.new_patients, 0),
          'registered', (select count(*) from patient x
                         where x.deleted_at is null and (x.created_at at time zone 'Africa/Kigali')::date = dd.day
                           and (v_stations is null or exists (select 1 from v where v.patient_id = x.id))),
          'byType', coalesce(a.by_type, '{}'::jsonb)) order by dd.day)
      from dd
      left join (
        select t.day, sum(t.n) as visits, sum(t.new_patients) as new_patients, jsonb_object_agg(t.type, t.n) as by_type
        from (select (arrived_at at time zone 'Africa/Kigali')::date as day, type::text as type, count(*) as n,
                     count(*) filter (where is_new) as new_patients
              from v group by 1, 2) t
        group by t.day) a on a.day = dd.day), '[]'::jsonb),
    'byGroup', coalesce((
      select jsonb_agg(jsonb_build_object('group', g.grp, 'categoryId', g.cat_id, 'name', g.name, 'nameKin', g.kin,
                                          'nameFr', g.fr, 'count', g.n) order by g.n desc)
      from (
        select coalesce(c.base_group::text, case when ln.service_id is null then 'pharmacy' else 'other' end) as grp,
               c.id as cat_id, c.name_en as name, c.name_kin as kin, c.name_fr as fr, count(distinct i.encounter_id) as n
        from ln
        join invoice i on i.id = ln.invoice_id
        left join service_category c on c.id = ln.category_id
        group by c.id, 1, 3, 4, 5) g), '[]'::jsonb),
    'byType', coalesce((
      select jsonb_agg(jsonb_build_object('type', t.type, 'count', t.n) order by t.n desc)
      from (select type::text as type, count(*) as n from v group by 1) t), '[]'::jsonb),
    'byHour', (
      select jsonb_agg(coalesce(h.n, 0) order by g.hour)
      from generate_series(0, 23) g(hour)
      left join (select extract(hour from arrived_at at time zone 'Africa/Kigali')::int as hour, count(*) as n from v group by 1) h
        on h.hour = g.hour),
    'treatmentTotals', jsonb_build_object(
      'lines', (select count(*) from ln),
      'distinct', (select count(distinct ln.description) from ln),
      'charged', case when s.s_manager then (select coalesce(sum(round(ln.unit_price * ln.quantity)), 0) from ln) end),
    'treatments', coalesce((
      select jsonb_agg(jsonb_build_object('description', t.description, 'categoryId', t.cat_id, 'category', t.cat_name,
                                          'categoryKin', t.cat_kin, 'categoryFr', t.cat_fr,
                                          'count', t.n, 'amount', case when s.s_manager then t.amount end)
                       order by t.n desc, t.description)
      from (select ln.description, c.id as cat_id, c.name_en as cat_name, c.name_kin as cat_kin, c.name_fr as cat_fr,
                   count(*) as n, sum(round(ln.unit_price * ln.quantity)) as amount
            from ln left join service_category c on c.id = ln.category_id
            group by ln.description, c.id, c.name_en, c.name_kin, c.name_fr
            order by count(*) desc, ln.description
            limit 300) t), '[]'::jsonb)
  ) into v_result;
  return v_result;
end
$$;
revoke all on function visits_analysis(date, date, uuid) from public, anon;
grant execute on function visits_analysis(date, date, uuid) to authenticated;

-- ---------------------------------------------------------------- E waiting time, corrected
-- The queues right now: waiting = joined today (Kigali) and not yet taken; forgotten = still open
-- from an earlier day (please close); busy = being seen. Internal: not granted.
create or replace function queue_now(p_stations station[] default null)
returns table (station text, waiting integer, busy integer, longest integer, forgotten integer)
language sql stable security definer set search_path = public
as $$
  with k as (select ((now() at time zone 'Africa/Kigali')::date)::timestamp at time zone 'Africa/Kigali' as midnight)
  select q.station::text,
         (count(*) filter (where q.finished_at is null and q.started_at is null and e.status = 'open' and q.created_at >= k.midnight))::int,
         (count(*) filter (where q.finished_at is null and q.started_at is not null and e.status = 'open'))::int,
         round(max(extract(epoch from now() - q.created_at) / 60)
               filter (where q.finished_at is null and q.started_at is null and e.status = 'open' and q.created_at >= k.midnight))::int,
         (count(*) filter (where q.finished_at is null and q.started_at is null and e.status = 'open' and q.created_at < k.midnight))::int
  from queue_entry q
  join encounter e on e.id = q.encounter_id
  cross join k
  where q.deleted_at is null and (p_stations is null or q.station = any (p_stations))
    and ((q.finished_at is null and e.status = 'open') or q.created_at >= k.midnight)
  group by q.station
$$;
revoke all on function queue_now(station[]) from public, anon, authenticated;

create or replace function wait_time_stats(p_from date default null, p_to date default null, p_department uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  s record;
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_len integer;
  v_start timestamptz;
  v_end timestamptz;
  -- the desks where a wait is measured (reception and beds: not)
  v_measured station[] := array['triage', 'consultation', 'dental', 'theatre', 'nursing', 'laboratory', 'ultrasound',
                                'pharmacy', 'cashier']::station[];
  v_stations station[];
  v_result jsonb;
begin
  select * into s from analytics_scope(p_department);
  if v_to < v_from then
    select v_to, v_from into v_from, v_to;
  end if;
  v_len := v_to - v_from + 1;
  v_start := v_from::timestamp at time zone 'Africa/Kigali';
  v_end := (v_to + 1)::timestamp at time zone 'Africa/Kigali';
  select coalesce(array_agg(x order by array_position(v_measured, x)), '{}') into v_stations
  from unnest(v_measured) x where x = any (s.s_stations);

  with w as (
    -- one wait per queue entry: from joining the desk's queue to the desk's end event
    select q.id, q.station, q.encounter_id, q.created_at as start_at,
           case
             when q.station in ('consultation', 'dental', 'theatre', 'nursing', 'laboratory', 'ultrasound') then q.started_at
             when q.station = 'triage' then (
               select min(o.effective_at) from observation o
               where o.encounter_id = q.encounter_id and o.deleted_at is null and o.code <> 'note'
                 and o.effective_at >= q.created_at and o.effective_at <= coalesce(q.finished_at, now()))
             when q.station = 'cashier' then (
               select min(y.paid_at) from payment y join invoice i on i.id = y.invoice_id
               where i.encounter_id = q.encounter_id and y.paid_at >= q.created_at and y.paid_at <= coalesce(q.finished_at, now()))
             when q.station = 'pharmacy' then (
               select min(x.at) from (
                 select md.created_at as at from medication_dispense md
                 where md.encounter_id = q.encounter_id and md.deleted_at is null
                 union all
                 select m.given_at from medication_request m
                 where m.encounter_id = q.encounter_id and m.deleted_at is null and m.given_at is not null) x
               where x.at >= q.created_at and x.at <= coalesce(q.finished_at, now()))
           end as end_at
    from queue_entry q
    where q.deleted_at is null and q.station = any (v_stations)
      and q.created_at < v_end and q.created_at >= v_start - interval '2 days'
  ),
  d as (
    select w.*, extract(epoch from w.end_at - w.start_at)::float8 / 60 as minutes,
           (w.end_at at time zone 'Africa/Kigali')::date as day,
           (w.end_at - w.start_at > interval '12 hours'
            or (w.start_at at time zone 'Africa/Kigali')::date <> (w.end_at at time zone 'Africa/Kigali')::date) as excluded
    from w
    where w.end_at is not null and w.end_at >= w.start_at and w.end_at >= v_start and w.end_at < v_end
  ),
  -- arrival to the first desk where a patient is seen (triage, consultation, dental)
  fe as (
    select w.encounter_id, min(w.end_at) as end_at from w
    where w.station in ('triage', 'consultation', 'dental') and w.end_at is not null and w.end_at >= w.start_at
    group by w.encounter_id
  ),
  ar as (
    select extract(epoch from fe.end_at - e.arrived_at)::float8 / 60 as minutes,
           (fe.end_at - e.arrived_at > interval '12 hours'
            or (e.arrived_at at time zone 'Africa/Kigali')::date <> (fe.end_at at time zone 'Africa/Kigali')::date) as excluded
    from fe join encounter e on e.id = fe.encounter_id and e.deleted_at is null
    where fe.end_at >= v_start and fe.end_at < v_end and fe.end_at >= e.arrived_at
  ),
  per as (
    select d.station,
           count(*) filter (where not d.excluded) as n,
           round((percentile_cont(0.5) within group (order by d.minutes) filter (where not d.excluded))::numeric, 1) as median,
           round((percentile_cont(0.9) within group (order by d.minutes) filter (where not d.excluded))::numeric, 1) as p90,
           round((avg(d.minutes) filter (where not d.excluded))::numeric, 1) as mean,
           count(*) filter (where d.excluded) as excluded
    from d group by d.station
  ),
  dd as (
    select g::date as day from generate_series(v_from, v_to, interval '1 day') g where v_len <= 400
    union
    select d.day from d where not d.excluded
  )
  select jsonb_build_object(
    'from', v_from, 'to', v_to, 'department', s.s_department,
    'rules', jsonb_build_object('minN', 5, 'maxHours', 12),
    'desks', coalesce((
      select jsonb_agg(jsonb_build_object(
          'station', st::text, 'n', coalesce(per.n, 0), 'median', per.median, 'p90', per.p90, 'mean', per.mean,
          'excluded', coalesce(per.excluded, 0), 'waitingNow', coalesce(l.waiting, 0), 'longestNow', l.longest,
          'forgotten', coalesce(l.forgotten, 0)) order by array_position(v_stations, st))
      from unnest(v_stations) st
      left join per on per.station = st
      left join queue_now(v_stations) l on l.station = st::text), '[]'::jsonb),
    'overall', (
      select jsonb_build_object(
        'n', count(*) filter (where not d.excluded),
        'median', round((percentile_cont(0.5) within group (order by d.minutes) filter (where not d.excluded))::numeric, 1),
        'p90', round((percentile_cont(0.9) within group (order by d.minutes) filter (where not d.excluded))::numeric, 1),
        'excluded', count(*) filter (where d.excluded))
      from d),
    'arrival', (
      select jsonb_build_object(
        'n', count(*) filter (where not ar.excluded),
        'median', round((percentile_cont(0.5) within group (order by ar.minutes) filter (where not ar.excluded))::numeric, 1),
        'p90', round((percentile_cont(0.9) within group (order by ar.minutes) filter (where not ar.excluded))::numeric, 1),
        'excluded', count(*) filter (where ar.excluded))
      from ar),
    'days', coalesce((
      select jsonb_agg(jsonb_build_object('day', dd.day, 'n', coalesce(x.n, 0), 'median', x.median) order by dd.day)
      from dd
      left join (select d.day, count(*) as n,
                        round((percentile_cont(0.5) within group (order by d.minutes))::numeric, 1) as median
                 from d where not d.excluded group by d.day) x on x.day = dd.day), '[]'::jsonb),
    -- tests: from the order to the verified result (turnaround, not waiting)
    'turnaround', coalesce((
      select jsonb_agg(jsonb_build_object('station', t.desk, 'n', t.n, 'median', t.median, 'p90', t.p90) order by t.desk)
      from (
        select request_desk(r.station, r.category) as desk, count(*) as n,
               round((percentile_cont(0.5) within group (order by extract(epoch from rep.verified_at - r.created_at)::float8 / 60))::numeric, 1) as median,
               round((percentile_cont(0.9) within group (order by extract(epoch from rep.verified_at - r.created_at)::float8 / 60))::numeric, 1) as p90
        from service_request r
        join diagnostic_report rep on rep.service_request_id = r.id and rep.deleted_at is null
        where r.deleted_at is null and rep.verified_at >= v_start and rep.verified_at < v_end and rep.verified_at >= r.created_at
          and (s.s_desks is null or request_desk(r.station, r.category) = any (s.s_desks))
        group by 1) t), '[]'::jsonb)
  ) into v_result;
  return v_result;
end
$$;
revoke all on function wait_time_stats(date, date, uuid) from public, anon;
grant execute on function wait_time_stats(date, date, uuid) to authenticated;

-- ---------------------------------------------------------------- F the cards
-- dashboard_summary (from 20261109090000_bookings_by_role): no average wait; waiting today only,
-- forgotten apart; staff rows by id with the corrected counts (retired staff keep their work);
-- reorder rows by id with the full name; revenue per day with refunds and net.
create or replace function dashboard_summary(p_from date, p_to date)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_manager boolean := is_manager();
  v_days integer := greatest(1, p_to - p_from + 1);
  v_prev_from date := p_from - v_days;
  v_prev_to date := p_from - 1;
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_midnight timestamptz := ((now() at time zone 'Africa/Kigali')::date)::timestamp at time zone 'Africa/Kigali';
  v_tiles jsonb;
  v_rev30 jsonb;
  v_rev_period jsonb;
  v_collections jsonb;
  v_receivables jsonb;
  v_visits jsonb;
  v_wait jsonb;
  v_top jsonb;
  v_staff jsonb;
  v_reorder jsonb;
  v_expiring jsonb;
  v_noshow jsonb;
  v_messages jsonb;
  v_claims jsonb;
  v_logins jsonb;
  v_services jsonb;
begin
  if not (v_manager or exists (select 1 from profiles where id = auth.uid() and active and dashboard is not null)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  -- headline tiles
  select jsonb_build_object(
    'registered', (select count(*) from patient where deleted_at is null and (created_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'registeredPrev', (select count(*) from patient where deleted_at is null and (created_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to),
    'visits', (select count(*) from encounter where deleted_at is null and (arrived_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'visitsPrev', (select count(*) from encounter where deleted_at is null and (arrived_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to),
    -- patients who joined a queue today and are not taken yet (one patient sent to several desks counts once)
    'waitingNow', (select count(distinct q.encounter_id) from queue_entry q join encounter e on e.id = q.encounter_id
                   where q.deleted_at is null and q.finished_at is null and q.started_at is null and e.status = 'open'
                     and q.created_at >= v_midnight),
    -- still open from an earlier day: forgotten in a queue (please close)
    'forgottenNow', (select count(distinct q.encounter_id) from queue_entry q join encounter e on e.id = q.encounter_id
                     where q.deleted_at is null and q.finished_at is null and q.started_at is null and e.status = 'open'
                       and q.created_at < v_midnight),
    'revenue', case when v_manager then (select coalesce(sum(amount), 0) from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between p_from and p_to) end,
    'revenuePrev', case when v_manager then (select coalesce(sum(amount), 0) from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to) end,
    'refunded', case when v_manager then (select coalesce(sum(amount), 0) from refund where deleted_at is null and (refunded_at at time zone 'Africa/Kigali')::date between p_from and p_to) end,
    'openBills', case when v_manager then (select count(*) from invoice i join encounter e on e.id = i.encounter_id where i.deleted_at is null and i.total > 0 and e.status = 'open' and invoice_balance(i.id) > 0) end,
    'openBillsDue', case when v_manager then (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id where i.deleted_at is null and i.total > 0 and e.status = 'open' and invoice_balance(i.id) > 0) end,
    'debts', case when v_manager then (select count(*) from invoice i join encounter e on e.id = i.encounter_id
                                       where i.deleted_at is null and e.status <> 'open' and invoice_balance(i.id) > 0) end,
    'debtsDue', case when v_manager then (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id
                                          where i.deleted_at is null and e.status <> 'open' and invoice_balance(i.id) > 0) end,
    'bedsOccupied', (select count(*) from bed where deleted_at is null and status = 'occupied'),
    'bedsTotal', (select count(*) from bed where deleted_at is null and status <> 'out_of_service')
  ) into v_tiles;

  -- revenue per day, last 30 days ending today: collected, refunded and net
  select coalesce(jsonb_agg(jsonb_build_object('day', d::date, 'amount', coalesce(s.amount, 0),
                                               'refunds', coalesce(r.amount, 0),
                                               'net', coalesce(s.amount, 0) - coalesce(r.amount, 0)) order by d), '[]'::jsonb) into v_rev30
  from generate_series(v_today - 29, v_today, interval '1 day') d
  left join (
    select (paid_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount
    from payment where deleted_at is null and paid_at >= (v_today - 29)::timestamp at time zone 'Africa/Kigali'
    group by 1
  ) s on s.day = d::date
  left join (
    select (refunded_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount
    from refund where deleted_at is null and refunded_at >= (v_today - 29)::timestamp at time zone 'Africa/Kigali'
    group by 1
  ) r on r.day = d::date;

  -- the same for the chosen period (up to 92 days; longer: see Analytics)
  if v_days <= 92 then
    select coalesce(jsonb_agg(jsonb_build_object('day', d::date, 'amount', coalesce(s.amount, 0),
                                                 'refunds', coalesce(r.amount, 0),
                                                 'net', coalesce(s.amount, 0) - coalesce(r.amount, 0)) order by d), '[]'::jsonb)
    into v_rev_period
    from generate_series(p_from, p_to, interval '1 day') d
    left join (
      select (paid_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount
      from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between p_from and p_to
      group by 1
    ) s on s.day = d::date
    left join (
      select (refunded_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount
      from refund where deleted_at is null and (refunded_at at time zone 'Africa/Kigali')::date between p_from and p_to
      group by 1
    ) r on r.day = d::date;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('method', m, 'amount', coalesce(s.amount, 0)) order by s.amount desc nulls last), '[]'::jsonb) into v_collections
  from unnest(array['cash', 'momo', 'airtel', 'card', 'bank']::payment_method[]) m
  left join (
    select method, sum(amount) as amount from payment
    where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by method
  ) s on s.method = m;

  select coalesce(jsonb_agg(jsonb_build_object('payer', py.name, 'count', c.n, 'amount', c.amount) order by c.amount desc), '[]'::jsonb) into v_receivables
  from (
    select payer_id, count(*) as n, sum(amount) as amount from claim
    where deleted_at is null and status in ('open', 'batched', 'submitted', 'rejected', 'resubmitted')
    group by payer_id
  ) c join payer py on py.id = c.payer_id;

  -- visits by service group (charged lines in the range)
  select coalesce(jsonb_agg(jsonb_build_object('group', g.grp, 'categoryId', g.cat_id, 'name', g.name, 'nameKin', g.kin,
                                                'nameFr', g.fr, 'count', g.n) order by g.n desc), '[]'::jsonb) into v_visits
  from (
    -- by the clinic's own categories; medicines (no service) count as pharmacy
    select coalesce(c.base_group::text, case when s.id is null then 'pharmacy' else 'other' end) as grp,
           c.id as cat_id, c.name_en as name, c.name_kin as kin, c.name_fr as fr, count(distinct i.encounter_id) as n
    from invoice_line l
    join invoice i on i.id = l.invoice_id
    left join service s on s.id = l.service_id
    left join service_category c on c.id = s.category_id
    where l.deleted_at is null and (l.created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by c.id, 1, 3, 4, 5
  ) g;

  -- the queues right now (no average: see Analytics → Waiting times)
  select coalesce(jsonb_agg(jsonb_build_object('station', w.station, 'waiting', w.waiting, 'busy', w.busy,
                                               'longest', w.longest, 'forgotten', w.forgotten) order by w.station), '[]'::jsonb)
  into v_wait
  from queue_now(null) w;

  -- top treatments in the range
  select coalesce(jsonb_agg(jsonb_build_object('name', x.name, 'count', x.n, 'amount', case when v_manager then x.amount end) order by x.n desc), '[]'::jsonb) into v_top
  from (
    select l.description as name, count(*) as n, sum(round(l.unit_price * l.quantity)) as amount
    from invoice_line l
    where l.deleted_at is null and (l.created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by l.description
    order by count(*) desc
    limit 10
  ) x;

  -- who did what (accountability): the same counts as Analytics → Who did what
  with ev as (
    select * from analytics_staff_events(p_from::timestamp at time zone 'Africa/Kigali',
                                         (p_to + 1)::timestamp at time zone 'Africa/Kigali', v_manager)
  ),
  a as (
    select ev.user_id,
           count(*) filter (where kind = 'registered') as registrations,
           count(*) filter (where kind = 'vitals') as vitals,
           count(*) filter (where kind = 'charges') as charges,
           count(*) filter (where kind = 'patientsSeen') as patients,
           count(*) filter (where kind = 'results') as results,
           count(*) filter (where kind = 'medicinesGiven') as dispensed,
           count(*) filter (where kind = 'payments') as payments,
           coalesce(sum(amount) filter (where kind = 'payments'), 0) as collected
    from ev group by ev.user_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.full_name, 'role', p.role, 'staffId', p.staff_id,
      'active', p.active and p.deleted_at is null,
      'registrations', coalesce(a.registrations, 0), 'vitals', coalesce(a.vitals, 0), 'charges', coalesce(a.charges, 0),
      'patients', coalesce(a.patients, 0), 'results', coalesce(a.results, 0), 'dispensed', coalesce(a.dispensed, 0),
      'payments', case when v_manager then coalesce(a.payments, 0) end,
      'collected', case when v_manager then coalesce(a.collected, 0) end,
      'lastSignIn', p.last_sign_in_at
    ) order by (coalesce(a.registrations, 0) + coalesce(a.vitals, 0) + coalesce(a.charges, 0) + coalesce(a.payments, 0)
                + coalesce(a.patients, 0) + coalesce(a.results, 0) + coalesce(a.dispensed, 0)) desc, p.full_name), '[]'::jsonb) into v_staff
  from profiles p
  left join a on a.user_id = p.id
  where (p.active and p.deleted_at is null)
     or (a.user_id is not null and (a.registrations + a.vitals + a.charges + a.patients + a.results + a.dispensed + a.payments) > 0);

  -- stock: the item's id and full name (with strength)
  select coalesce(jsonb_agg(jsonb_build_object('id', r.item_id, 'name', item_label(r.item_id), 'onHand', r.on_hand, 'min', r.reorder_level)
                            order by (r.on_hand::numeric / greatest(r.reorder_level, 1)), item_label(r.item_id)), '[]'::jsonb) into v_reorder
  from items_below_reorder r;

  select jsonb_build_object(
    'expired', count(distinct s.item_id) filter (where s.expiry < v_today),
    'd30', count(distinct s.item_id) filter (where s.expiry >= v_today and s.expiry <= v_today + 30),
    'd60', count(distinct s.item_id) filter (where s.expiry > v_today + 30 and s.expiry <= v_today + 60),
    'd90', count(distinct s.item_id) filter (where s.expiry > v_today + 60 and s.expiry <= v_today + 90)
  ) into v_expiring
  from (select item_id, batch_id, expiry, sum(quantity) as q from stock_on_hand where expiry is not null
        group by item_id, batch_id, expiry) s
  where s.q > 0;

  -- bookings
  select jsonb_build_object(
    'booked', count(*) filter (where status in ('confirmed', 'arrived', 'in_progress', 'completed', 'no_show')),
    'missed', count(*) filter (where status = 'no_show'),
    'pending', (select count(*) from appointment where deleted_at is null and status = 'inquiry')
  ) into v_noshow
  from appointment where deleted_at is null and (coalesce(starts_at, created_at) at time zone 'Africa/Kigali')::date between p_from and p_to;

  select coalesce(jsonb_agg(jsonb_build_object('channel', ch, 'sent', coalesce(s.sent, 0), 'failed', coalesce(s.failed, 0)) order by ch), '[]'::jsonb) into v_messages
  from unnest(array['whatsapp', 'sms', 'email']::message_channel[]) ch
  left join (
    select channel, count(*) filter (where status in ('sent', 'delivered')) as sent, count(*) filter (where status = 'failed') as failed
    from message where deleted_at is null and (created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by channel
  ) s on s.channel = ch;

  select coalesce(jsonb_agg(jsonb_build_object('payer', py.name, 'count', c.n, 'amount', case when v_manager then c.amount end) order by c.amount desc), '[]'::jsonb) into v_claims
  from (select payer_id, count(*) as n, sum(amount) as amount from claim where deleted_at is null and status = 'open' group by payer_id) c
  join payer py on py.id = c.payer_id;

  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name, 'role', p.role, 'at', a.at, 'reason', a.reason) order by a.at desc), '[]'::jsonb) into v_logins
  from (select actor_id, at, reason from audit_event where action = 'login' and at > now() - interval '1 day' order by at desc limit 12) a
  join profiles p on p.id = a.actor_id;

  select jsonb_build_object('active', count(*) filter (where active), 'total', count(*)) into v_services from service where deleted_at is null;

  return jsonb_build_object(
    'from', p_from, 'to', p_to, 'manager', v_manager, 'generatedAt', now(),
    -- money for the manager only (heads of department see the activity, not the money)
    'tiles', v_tiles,
    'revenue30d', case when v_manager then v_rev30 else '[]'::jsonb end,
    'revenuePeriod', case when v_manager then v_rev_period end,
    'collections', case when v_manager then v_collections else '[]'::jsonb end,
    'receivables', case when v_manager then v_receivables else '[]'::jsonb end,
    'visitsByGroup', v_visits, 'waitByStation', v_wait, 'topTreatments', v_top, 'staff', v_staff,
    'reorder', v_reorder, 'expiring', v_expiring, 'bookings', v_noshow, 'messages', v_messages,
    'claims', v_claims, 'logins', v_logins, 'services', v_services
  );
end
$$;

-- desk_summary (from 20261116090000_dashboards_by_period): no average waits; waiting today only.
create or replace function desk_summary(p_from date default null, p_to date default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_me uuid := auth.uid();
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_midnight timestamptz := ((now() at time zone 'Africa/Kigali')::date)::timestamp at time zone 'Africa/Kigali';
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  -- the period just before, as long (yesterday for today), for the arrows
  v_prev_to date := v_from - 1;
  v_prev_from date := v_from - (v_to - v_from + 1);
  v_tiles jsonb;
  v_stations jsonb;
  v_hours jsonb;
  v_mine jsonb;
begin
  if not exists (select 1 from profiles where id = v_me and active) then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'registeredToday', (select count(*) from patient where deleted_at is null and (created_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'registeredYesterday', (select count(*) from patient where deleted_at is null and (created_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to),
    'visitsToday', (select count(*) from encounter where deleted_at is null and (arrived_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'visitsYesterday', (select count(*) from encounter where deleted_at is null and (arrived_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to),
    'inClinic', (select count(*) from encounter where deleted_at is null and status = 'open'),
    'waitingNow', (select count(distinct q.encounter_id) from queue_entry q join encounter e on e.id = q.encounter_id
                   where q.deleted_at is null and q.finished_at is null and q.started_at is null and e.status = 'open'
                     and q.created_at >= v_midnight),
    'forgottenNow', (select count(distinct q.encounter_id) from queue_entry q join encounter e on e.id = q.encounter_id
                     where q.deleted_at is null and q.finished_at is null and q.started_at is null and e.status = 'open'
                       and q.created_at < v_midnight),
    'triageWaiting', (select count(*) from queue_entry q join encounter e on e.id = q.encounter_id
                      where q.deleted_at is null and q.station = 'triage' and q.finished_at is null and e.status = 'open'
                        and q.created_at >= v_midnight),
    'triageRed', (select count(*) from encounter e where e.deleted_at is null and e.status = 'open' and e.triage_level = 'red'),
    'triageYellow', (select count(*) from encounter e where e.deleted_at is null and e.status = 'open' and e.triage_level = 'yellow'),
    'triageGreen', (select count(*) from encounter e where e.deleted_at is null and e.status = 'open' and e.triage_level = 'green'),
    'triageNone', (select count(*) from encounter e where e.deleted_at is null and e.status = 'open' and e.triage_level is null),
    -- patients still waiting for their first measurements (the Vitals page)
    'needVitals', (select count(*) from encounter e where e.deleted_at is null and e.status = 'open'
                   and not exists (select 1 from observation o where o.encounter_id = e.id and o.deleted_at is null and o.code <> 'note')),
    'vitalsToday', (select count(distinct encounter_id) from observation where deleted_at is null and code <> 'note' and (effective_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'vitalsYesterday', (select count(distinct encounter_id) from observation where deleted_at is null and code <> 'note' and (effective_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to),
    'apptsToday', (select count(*) from appointment where deleted_at is null
                   and status in ('approved', 'confirmed', 'arrived', 'in_progress', 'completed')
                   and (starts_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'inquiriesPending', (select count(*) from appointment where deleted_at is null and status = 'inquiry'),
    'bedsOccupied', (select count(*) from bed where deleted_at is null and status = 'occupied'),
    'bedsTotal', (select count(*) from bed where deleted_at is null and status <> 'out_of_service')
  ) into v_tiles;

  -- Where patients are right now: waiting (joined today) / being seen / forgotten per station.
  select coalesce(jsonb_agg(jsonb_build_object('station', s.station, 'waiting', s.waiting, 'busy', s.busy,
                                               'longest', s.longest, 'forgotten', s.forgotten)
                            order by s.station), '[]'::jsonb) into v_stations
  from queue_now(null) s;

  -- Arrivals per hour (06:00–21:00, plus any hour outside that had arrivals).
  select coalesce(jsonb_agg(jsonb_build_object('hour', h.hour, 'count', coalesce(a.n, 0)) order by h.hour), '[]'::jsonb) into v_hours
  from (
    select generate_series(6, 21) as hour
    union
    select extract(hour from arrived_at at time zone 'Africa/Kigali')::int
    from encounter where deleted_at is null and (arrived_at at time zone 'Africa/Kigali')::date between v_from and v_to
  ) h
  left join (
    select extract(hour from arrived_at at time zone 'Africa/Kigali')::int as hour, count(*) as n
    from encounter where deleted_at is null and (arrived_at at time zone 'Africa/Kigali')::date between v_from and v_to
    group by 1
  ) a on a.hour = h.hour;

  -- The caller's own work (accountability, and a little motivation).
  select jsonb_build_object(
    'registrations', (select count(*) from patient where deleted_at is null and created_by = v_me and (created_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'visitsStarted', (select count(*) from encounter where deleted_at is null and created_by = v_me and (arrived_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'vitals', (select count(distinct encounter_id) from observation where deleted_at is null and code <> 'note' and performer_id = v_me and (effective_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'charges', (select count(*) from invoice_line where deleted_at is null and entered_by = v_me and (created_at at time zone 'Africa/Kigali')::date between v_from and v_to)
  ) into v_mine;

  return jsonb_build_object('tiles', v_tiles, 'stations', v_stations, 'arrivals', v_hours, 'mine', v_mine);
end
$$;

-- department_summary (from 20261104090000_desks_last_items): no average wait; waiting today only;
-- the people's counts as in Who did what (patients seen, medicines given from room stores too).
create or replace function department_summary(p_department_id uuid, p_from date, p_to date)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_dept department%rowtype;
  v_days integer := greatest(1, p_to - p_from + 1);
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_midnight timestamptz := ((now() at time zone 'Africa/Kigali')::date)::timestamp at time zone 'Africa/Kigali';
  v_stations station[];
  v_members jsonb;
  v_queue jsonb;
  v_tiles jsonb;
  v_services jsonb;
begin
  if not (is_manager() or exists (
    select 1 from staff_department sd join profiles p on p.id = sd.profile_id
    where sd.profile_id = auth.uid() and sd.department_id = p_department_id
      and sd.position in ('head', 'assistant') and p.active)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_dept from department where id = p_department_id and deleted_at is null;
  if not found then
    raise exception 'department not found' using errcode = 'P0002';
  end if;
  select coalesce(array_agg(s), '{}') into v_stations
  from unnest(enum_range(null::station)) s
  where station_role(s) = any (v_dept.roles);

  -- the people of the department and what each did in the period
  with ev as (
    select ev.user_id, ev.kind
    from analytics_staff_events(p_from::timestamp at time zone 'Africa/Kigali',
                                (p_to + 1)::timestamp at time zone 'Africa/Kigali', false) ev
    where ev.user_id in (select sd.profile_id from staff_department sd where sd.department_id = p_department_id)
      and ev.kind in ('patientsSeen', 'registered', 'vitals', 'results', 'medicinesGiven', 'tasksDone')
  ),
  a as (
    select ev.user_id,
           count(*) filter (where kind = 'patientsSeen') as patients,
           count(*) filter (where kind = 'registered') as registrations,
           count(*) filter (where kind = 'vitals') as vitals,
           count(*) filter (where kind = 'results') as results,
           count(*) filter (where kind = 'medicinesGiven') as dispensed,
           count(*) filter (where kind = 'tasksDone') as tasks_done
    from ev group by ev.user_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.full_name, 'role', p.role, 'position', sd.position, 'station', p.station,
      'lastSignIn', p.last_sign_in_at, 'active', p.active,
      'patients', coalesce(a.patients, 0),
      'registrations', coalesce(a.registrations, 0),
      'vitals', coalesce(a.vitals, 0),
      'results', coalesce(a.results, 0),
      'dispensed', coalesce(a.dispensed, 0),
      'payments', (select count(*) from payment y where y.deleted_at is null and y.cashier_id = p.id
                   and (y.paid_at at time zone 'Africa/Kigali')::date between p_from and p_to),
      'tasksDone', coalesce(a.tasks_done, 0),
      'busyNow', (select count(*) from queue_entry q join encounter e on e.id = q.encounter_id
                  where q.taken_by = p.id and q.deleted_at is null and q.finished_at is null and e.status = 'open')
    ) order by case sd.position when 'head' then 0 when 'assistant' then 1 else 2 end, p.full_name), '[]'::jsonb)
  into v_members
  from staff_department sd join profiles p on p.id = sd.profile_id
  left join a on a.user_id = p.id
  where sd.department_id = p_department_id;

  -- the department's desks right now
  select coalesce(jsonb_agg(jsonb_build_object('station', w.station, 'waiting', w.waiting, 'busy', w.busy,
                                               'longest', w.longest, 'forgotten', w.forgotten) order by w.station), '[]'::jsonb)
  into v_queue
  from queue_now(v_stations) w;

  select jsonb_build_object(
    'patients', (select count(distinct q.encounter_id) from queue_entry q
                 where q.deleted_at is null and q.station = any (v_stations) and q.finished_at is not null
                   and (q.finished_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'patientsPrev', (select count(distinct q.encounter_id) from queue_entry q
                     where q.deleted_at is null and q.station = any (v_stations) and q.finished_at is not null
                       and (q.finished_at at time zone 'Africa/Kigali')::date between p_from - v_days and p_from - 1),
    'waitingNow', (select count(*) from queue_entry q join encounter e on e.id = q.encounter_id
                   where q.deleted_at is null and q.station = any (v_stations) and q.finished_at is null
                     and q.started_at is null and e.status = 'open' and q.created_at >= v_midnight),
    'forgottenNow', (select count(*) from queue_entry q join encounter e on e.id = q.encounter_id
                     where q.deleted_at is null and q.station = any (v_stations) and q.finished_at is null
                       and q.started_at is null and e.status = 'open' and q.created_at < v_midnight),
    'ordersOpen', (select count(*) from service_request r join encounter e on e.id = r.encounter_id
                   where r.deleted_at is null and e.status = 'open'
                     and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) = any (v_stations)
                     and r.status not in ('resulted', 'verified', 'cancelled')),
    'ordersNotDone', (select count(*) from service_request r
                      where r.deleted_at is null and r.status = 'cancelled'
                        and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) = any (v_stations)
                        and (r.updated_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'tasksOpen', (select count(*) from internal_task k join encounter e on e.id = k.encounter_id
                  where k.deleted_at is null and k.done_at is null and e.status = 'open'
                    and k.assigned_role = any (v_dept.roles)),
    'members', jsonb_array_length(v_members),
    'signedInToday', (select count(*) from staff_department sd join profiles p on p.id = sd.profile_id
                      where sd.department_id = p_department_id
                        and (p.last_sign_in_at at time zone 'Africa/Kigali')::date = v_today)
  ) into v_tiles;

  -- the department's treatments done in the period (count only)
  select coalesce(jsonb_agg(jsonb_build_object('name', x.name, 'count', x.n) order by x.n desc), '[]'::jsonb) into v_services
  from (
    select l.description as name, count(*) as n
    from invoice_line l
    join service_department sv on sv.service_id = l.service_id and sv.department_id = p_department_id
    where l.deleted_at is null and (l.created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by l.description order by count(*) desc limit 10
  ) x;

  return jsonb_build_object('department', jsonb_build_object('id', v_dept.id, 'name', v_dept.name, 'roles', v_dept.roles),
                            'stations', to_jsonb(v_stations), 'tiles', v_tiles, 'members', v_members,
                            'queue', v_queue, 'services', v_services);
end
$$;

-- public_clinic_status (from 20261107090000_desks_wave9): no "current wait about X"; waiting =
-- patients who joined a queue today and are still in it (one patient counts once).
create or replace function public_clinic_status()
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_local timestamp := now() at time zone 'Africa/Kigali';
  v_midnight timestamptz := (v_local::date)::timestamp at time zone 'Africa/Kigali';
  v_hours jsonb := coalesce((select value -> 'days' from setting where key = 'clinic.hours'), '{}'::jsonb);
  v_span jsonb := v_hours -> extract(dow from v_local)::int::text;
  v_waiting integer;
  v_open boolean := false;
  v_next_day date;
  v_next jsonb;
  i integer;
begin
  select count(distinct q.encounter_id) into v_waiting
  from queue_entry q
  join encounter e on e.id = q.encounter_id
  where q.finished_at is null and q.deleted_at is null and e.status = 'open' and q.created_at >= v_midnight;
  if v_span is not null and jsonb_array_length(v_span) = 2 then
    v_open := v_local::time >= (v_span ->> 0)::time and v_local::time < (v_span ->> 1)::time;
  end if;
  -- the next opening: today if not open yet, else the next day with hours
  if not v_open then
    for i in 0..7 loop
      v_next_day := v_local::date + i;
      v_next := v_hours -> extract(dow from v_next_day)::int::text;
      if v_next is not null and jsonb_array_length(v_next) = 2
         and (i > 0 or v_local::time < (v_next ->> 0)::time) then
        exit;
      end if;
      v_next := null;
    end loop;
  end if;
  return jsonb_build_object(
    'waiting', coalesce(v_waiting, 0),
    'open', v_open,
    'opens_at', case when v_open then v_span ->> 0 else v_next ->> 0 end,
    'opens_on', case when v_open or v_next is null then null else v_next_day end,
    'closes_at', case when v_open then v_span ->> 1 end,
    'as_of', now()
  );
end
$$;


-- ============================================================ 20261128090000_switches_enforced.sql
-- 0087 · Every switch of "Who may do what" decides, in the database too.
--
-- Frank: "I have allowed and disallowed some features for nurse but still nothing happened, they
-- are still there, fix it also." The manager switches a feature on or off for a role, or makes an
-- exception for one employee (Settings → Who may do what). Most functions already asked has_perm()
-- (the employee's exception wins, else the role); these did not, or asked the wrong thing:
--
--   * A  TAKE PAYMENTS (payment.take) decides every money act at the desk. record_payment,
--        post_invoice, refund_payment and void_payment accepted billing.write instead, so a cashier
--        switched off could still record, refund and cancel payments by calling them. Now
--        payment.take (the manager as before for refunds, cancellations and posting). The cash
--        count (close_cash_day) is for those who take payments, and for anyone switched off during
--        the day who still has payments of that day to count.
--   * B  SWITCHED ON, IT WORKS. Someone given "Take payments" whose role does not read the money
--        (a nurse, a pharmacist…) now reads what taking a payment needs: the bills, their lines,
--        the payments (paid, receipt), the credit notes (refunds due); cashier_summary shows the
--        cashier and reception the whole desk as before, and anyone else allowed to take payments
--        their own payments, refunds and cash count with the bills waiting to be paid.
--   * C  TEST RESULTS (orders.write). The laboratory and ultrasound desks come with the department
--        whatever the switch, so record_result, set_request_status and correct_result accepted the
--        desk alone: they now also need orders.write there.
--   * D  BOOKINGS (appointment.approve). Someone given "Approve bookings" whose role does not read
--        bookings now sees the requests and the day's bookings (inquiries_open, appointments_day,
--        appointment_detail, the appointment rows).
--   * E  STOCK (stock.write). The pharmacy's stock was managed by the pharmacy desk alone
--        (stock_admin), so the switch did nothing. stock_manager() = the manager, or the pharmacy
--        desk AND stock.write: receiving deliveries, sending to room stores and cancelling those
--        notes, confirming returns, declining refills, counts and write-offs of the pharmacy,
--        moving stock, pharmacy stores and room minimums. Dispensing, counter sales and reading
--        stay with the pharmacy desk (stock_admin); a room store's holders keep their own work.
--
--   * F  VITAL SIGNS (vitals.write) were already enforced (record_vitals, and the triage desk that
--        send_from_triage needs comes only with vitals.write); both now say why they refuse.
--
-- The desks still apply on top (a desk feature needs the desk and the switch); money never comes
-- from a desk. my_permissions() already returns the effective switches (exception, else role, or
-- the doctor being covered): unchanged.
--
-- A refusal by a switch: 42501 with hint 'not_permitted' ("… the manager has not allowed it").
-- Errcodes: 42501 not allowed, 22023 bad input, P0002 not found.

-- ---------------------------------------------------------------- E helpers
-- The pharmacy's stock is managed by the manager, or by the pharmacy desk with "Manage stock".
create or replace function stock_manager()
returns boolean
language sql stable security definer set search_path = public
as $$
  select is_manager() or (may_use_desk('pharmacy') and has_perm('stock.write'))
$$;

-- At the pharmacy desk without "Manage stock": say so (the callers raise their own words otherwise).
create or replace function assert_stock_write()
returns void
language plpgsql stable security definer set search_path = public
as $$
begin
  if stock_admin() and not stock_manager() then
    raise exception 'you may not manage the stock (the manager has not allowed it)'
      using errcode = '42501', hint = 'not_permitted';
  end if;
end
$$;

-- ---------------------------------------------------------------- A take payments
-- record_payment (from 20261102120000_desks_connected): payment.take only (billing.write no longer takes money).
create or replace function record_payment(
  p_invoice_id uuid,
  p_method payment_method,
  p_amount numeric,
  p_reference text default null,
  p_payer_phone text default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_year integer := extract(year from now())::integer;
begin
  -- the cashier, and anyone the manager allows to take payments (Settings → Who may do what)
  if not has_perm('payment.take') then
    raise exception 'you may not take payments (the manager has not allowed it)' using errcode = '42501', hint = 'not_permitted';
  end if;
  if p_method in ('momo', 'airtel', 'card', 'bank') and nullif(trim(coalesce(p_reference, '')), '') is null then
    raise exception 'a transaction reference is required for %', p_method using errcode = '22023';
  end if;
  insert into payment (invoice_id, method, amount, reference, payer_phone, receipt_no)
  values (p_invoice_id, p_method, p_amount, p_reference, p_payer_phone,
          'RCT-' || v_year || '-' || lpad(next_number('receipt', v_year)::text, 6, '0'))
  returning id into v_id;
  return v_id;
end
$$;

-- post_invoice (from 20261102120000_desks_connected): payment.take, or the manager.
create or replace function post_invoice(p_invoice_id uuid)
returns text
language plpgsql security definer set search_path = public
as $$
begin
  if not (is_manager() or has_perm('payment.take')) then
    raise exception 'you may not take payments (the manager has not allowed it)' using errcode = '42501', hint = 'not_permitted';
  end if;
  return post_invoice_now(p_invoice_id);
end
$$;

-- refund_payment (from 20261105090000_desks_wave7): giving money back is taking payments (payment.take), or the manager.
create or replace function refund_payment(
  p_encounter_id uuid,
  p_amount numeric,
  p_method payment_method,
  p_reason text,
  p_reference text default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_inv invoice%rowtype;
  v_over numeric;
  v_id uuid;
begin
  if not (is_manager() or has_perm('payment.take')) then
    raise exception 'you may not take payments (the manager has not allowed it)' using errcode = '42501', hint = 'not_permitted';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the money is given back' using errcode = '22023';
  end if;
  if p_method::text not in ('cash', 'momo', 'airtel') then
    raise exception 'cash, MTN MoMo or Airtel Money only' using errcode = '22023';
  end if;
  if p_method::text <> 'cash' and nullif(trim(coalesce(p_reference, '')), '') is null then
    raise exception 'give the transaction reference' using errcode = '22023';
  end if;
  select * into v_inv from invoice where encounter_id = p_encounter_id and deleted_at is null for update;
  if not found then
    raise exception 'no bill for this visit' using errcode = 'P0002';
  end if;
  v_over := -invoice_balance(v_inv.id);
  if v_over <= 0 then
    raise exception 'nothing to give back: the bill is not overpaid' using errcode = '22023';
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > v_over + 0.5 then
    raise exception 'give back at most % RWF', v_over using errcode = '22023';
  end if;
  insert into refund (invoice_id, amount, method, reference, reason)
  values (v_inv.id, round(p_amount), p_method, nullif(trim(coalesce(p_reference, '')), ''), trim(p_reason))
  returning id into v_id;
  insert into audit_event (actor_id, action, entity, entity_id, reason)
  values (auth.uid(), 'update', 'refund', v_id, trim(p_reason));
  return jsonb_build_object('id', v_id, 'balance', invoice_balance(v_inv.id));
end
$$;

-- void_payment (from 20261124090000_stores_and_stock): the person who took it, while still allowed to take payments; the manager.
create or replace function void_payment(p_payment_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_p payment%rowtype;
  v_enc uuid;
  v_sale counter_sale%rowtype;
begin
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the payment is cancelled' using errcode = '22023';
  end if;
  select * into v_p from payment where id = p_payment_id and deleted_at is null for update;
  if not found then
    raise exception 'payment not found or already cancelled' using errcode = 'P0002';
  end if;
  if not is_manager() then
    if not has_perm('payment.take') then
      raise exception 'you may not take payments (the manager has not allowed it): ask the manager to cancel it'
        using errcode = '42501', hint = 'not_permitted';
    end if;
    if v_p.cashier_id is distinct from auth.uid() then
      raise exception 'only the person who took the payment (or the manager) can cancel it' using errcode = '42501';
    end if;
    if (v_p.paid_at at time zone 'Africa/Kigali')::date <> (now() at time zone 'Africa/Kigali')::date then
      raise exception 'a payment of another day is cancelled by the manager' using errcode = '42501';
    end if;
    if v_p.day_close_id is not null then
      raise exception 'the cash of that day is already counted: ask the manager' using errcode = '42501';
    end if;
  end if;
  if v_p.counter_sale_id is not null then
    select * into v_sale from counter_sale where id = v_p.counter_sale_id for update;
    if v_sale.status = 'handed_over' then
      raise exception 'the medicines of this sale were already handed over' using errcode = '23514';
    end if;
  end if;
  update payment set deleted_at = now(), void_reason = trim(p_reason), voided_by = auth.uid(), voided_at = now()
  where id = p_payment_id;
  if v_p.counter_sale_id is not null then
    -- the units taken at payment go back on the shelf
    insert into stock_movement (item_id, batch_id, to_location_id, quantity, type, reason, unit_cost, counter_sale_id)
    select h.item_id, h.batch_id, v_sale.location_id, h.quantity, 'return',
           'payment cancelled: ' || v_sale.number, h.unit_cost, v_sale.id
    from counter_sale_held(v_sale.id) h;
    update counter_sale set status = 'open', paid_at = null, payment_id = null where id = v_p.counter_sale_id;
    return jsonb_build_object('encounterId', null, 'counterSaleId', v_p.counter_sale_id, 'balance', v_sale.total);
  end if;
  select encounter_id into v_enc from invoice where id = v_p.invoice_id;
  return jsonb_build_object('encounterId', v_enc, 'balance', invoice_balance(v_p.invoice_id));
end
$$;

-- close_cash_day (from 20261124090000_stores_and_stock): those who take payments; someone switched off during the day still counts what they took.
create or replace function close_cash_day(p_day date, p_counted jsonb, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_day date := coalesce(p_day, (now() at time zone 'Africa/Kigali')::date);
  v_expected jsonb;
  v_counted jsonb := '{}'::jsonb;
  v_variance numeric;
  v_id uuid;
  v_key text;
  v_val text;
begin
  if not (is_manager() or has_perm('payment.take')
          or exists (select 1 from payment where cashier_id = auth.uid() and deleted_at is null
                     and (paid_at at time zone 'Africa/Kigali')::date = v_day)
          or exists (select 1 from refund where cashier_id = auth.uid() and deleted_at is null
                     and (refunded_at at time zone 'Africa/Kigali')::date = v_day)) then
    raise exception 'you may not take payments (the manager has not allowed it)' using errcode = '42501', hint = 'not_permitted';
  end if;
  select coalesce(jsonb_object_agg(n.method, n.amount), '{}'::jsonb) into v_expected
  from (select m.method, sum(m.amount) as amount from (
          select method::text as method, amount from payment
          where deleted_at is null and cashier_id = auth.uid() and (paid_at at time zone 'Africa/Kigali')::date = v_day
          union all
          select method::text, -amount from refund
          where deleted_at is null and cashier_id = auth.uid() and (refunded_at at time zone 'Africa/Kigali')::date = v_day
        ) m group by m.method) n;
  for v_key, v_val in select key, value from jsonb_each_text(coalesce(p_counted, '{}'::jsonb)) loop
    if v_key in ('cash', 'momo', 'airtel', 'card', 'bank') and v_val ~ '^[0-9]+$' then
      v_counted := v_counted || jsonb_build_object(v_key, v_val::numeric);
    end if;
  end loop;
  v_variance := coalesce((select sum(value::numeric) from jsonb_each_text(v_counted)), 0)
              - coalesce((select sum(value::numeric) from jsonb_each_text(v_expected)), 0);
  insert into day_close (date, cashier_id, expected, counted, variance, note)
  values (v_day, auth.uid(), v_expected, v_counted, v_variance, nullif(trim(coalesce(p_note, '')), ''))
  on conflict (date, cashier_id) do update
  set expected = excluded.expected, counted = excluded.counted, variance = excluded.variance,
      note = excluded.note, updated_at = now()
  returning id into v_id;
  update payment set day_close_id = v_id
  where deleted_at is null and cashier_id = auth.uid() and (paid_at at time zone 'Africa/Kigali')::date = v_day;
  return jsonb_build_object('id', v_id, 'expected', v_expected, 'counted', v_counted, 'variance', v_variance);
end
$$;

-- cashier_summary (from 20261124090000_stores_and_stock): the cashier and reception (billing.read)
-- see the whole desk as before; anyone else allowed to take payments, or who still has payments of
-- their own to count, sees their own payments, refunds and cash count (and, with "Take payments",
-- the bills and counter sales waiting to be paid).
create or replace function cashier_summary(p_day date default null, p_from date default null, p_to date default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, p_day, v_today);
  v_to date := coalesce(p_to, p_day, p_from, v_today);
  v_day date;
  v_len integer;
  v_me uuid := auth.uid();
  v_all boolean := has_perm('billing.read');
  v_take boolean := has_perm('payment.take');
begin
  if not (v_all or v_take
          or exists (select 1 from payment where cashier_id = v_me and deleted_at is null and day_close_id is null)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_to < v_from then
    select v_to, v_from into v_from, v_to;
  end if;
  v_day := coalesce(p_day, v_to);
  v_len := v_to - v_from + 1;
  return jsonb_build_object(
    'day', v_day,
    'from', v_from,
    'to', v_to,
    'scope', case when v_all then 'desk' else 'mine' end,
    'total', (select coalesce(sum(amount), 0) from payment
              where deleted_at is null and (v_all or cashier_id = v_me)
                and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'count', (select count(*) from payment
              where deleted_at is null and (v_all or cashier_id = v_me)
                and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'previousTotal', (select coalesce(sum(amount), 0) from payment
                      where deleted_at is null and (v_all or cashier_id = v_me)
                        and (paid_at at time zone 'Africa/Kigali')::date between v_from - v_len and v_from - 1
                        and (v_to <> v_today or paid_at <= now() - make_interval(days => v_len))),
    'served', case when v_all then
                (select count(distinct q.encounter_id) from queue_entry q
                 where q.deleted_at is null and q.station = 'cashier' and q.finished_at is not null
                   and (q.finished_at at time zone 'Africa/Kigali')::date between v_from and v_to)
              else
                (select count(distinct coalesce(i.encounter_id, pa.counter_sale_id)) from payment pa
                 left join invoice i on i.id = pa.invoice_id
                 where pa.deleted_at is null and pa.cashier_id = v_me
                   and (pa.paid_at at time zone 'Africa/Kigali')::date between v_from and v_to)
              end,
    'refunded', (select coalesce(sum(amount), 0) from refund
                 where deleted_at is null and (v_all or cashier_id = v_me)
                   and (refunded_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'refunds', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select r.refunded_at as at, jsonb_build_object(
            'id', r.id, 'at', r.refunded_at, 'method', r.method, 'amount', r.amount, 'reference', r.reference,
            'reason', r.reason, 'patient', p.surname || ' ' || p.given_names,
            'cashier', (select full_name from profiles where id = r.cashier_id), 'mine', r.cashier_id = v_me
          ) as j
        from refund r
        join invoice i on i.id = r.invoice_id
        join encounter e on e.id = i.encounter_id
        join patient p on p.id = e.patient_id
        where r.deleted_at is null and (v_all or r.cashier_id = v_me)
          and (r.refunded_at at time zone 'Africa/Kigali')::date between v_from and v_to
        order by r.refunded_at desc limit 500) x
    ), '[]'::jsonb),
    'debts', case when v_all or v_take then
               (select count(*) from invoice i join encounter e on e.id = i.encounter_id
                where i.deleted_at is null and e.status <> 'open' and invoice_balance(i.id) > 0)
             else 0 end,
    'debtsDue', case when v_all or v_take then
                  (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id
                   where i.deleted_at is null and e.status <> 'open' and invoice_balance(i.id) > 0)
                else 0 end,
    'mine', (select coalesce(sum(amount), 0) from payment
             where deleted_at is null and cashier_id = v_me
               and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'byMethod', coalesce((
      select jsonb_agg(jsonb_build_object('method', m.method, 'amount', m.amount, 'count', m.n) order by m.amount desc)
      from (select method::text as method, sum(amount) as amount, count(*) as n from payment
            where deleted_at is null and (v_all or cashier_id = v_me)
              and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to
            group by method) m
    ), '[]'::jsonb),
    'byCashier', coalesce((
      select jsonb_agg(jsonb_build_object('name', c.name, 'amount', c.amount, 'count', c.n) order by c.amount desc)
      from (select coalesce(pr.full_name, '—') as name, sum(pa.amount) as amount, count(*) as n
            from payment pa left join profiles pr on pr.id = pa.cashier_id
            where pa.deleted_at is null and (v_all or pa.cashier_id = v_me)
              and (pa.paid_at at time zone 'Africa/Kigali')::date between v_from and v_to
            group by pr.full_name) c
    ), '[]'::jsonb),
    -- the payments of the period: visits' bills and counter sales
    'payments', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select pa.paid_at as at, jsonb_build_object(
            'id', pa.id, 'at', pa.paid_at, 'method', pa.method, 'amount', pa.amount, 'reference', pa.reference,
            'invoice', i.number, 'encounterId', i.encounter_id,
            'patient', coalesce(p.surname || ' ' || p.given_names, cs.buyer_name),
            'fileNumber', p.file_number,
            'counterSaleId', cs.id, 'counterSale', cs.number,
            'cashier', pr.full_name, 'receipt', pa.receipt_no,
            'mine', pa.cashier_id = v_me, 'counted', pa.day_close_id is not null
          ) as j
        from payment pa
        left join invoice i on i.id = pa.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient p on p.id = e.patient_id
        left join counter_sale cs on cs.id = pa.counter_sale_id
        left join profiles pr on pr.id = pa.cashier_id
        where pa.deleted_at is null and (v_all or pa.cashier_id = v_me)
          and (pa.paid_at at time zone 'Africa/Kigali')::date between v_from and v_to
        order by pa.paid_at desc limit 500) x
    ), '[]'::jsonb),
    'voided', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select pa.voided_at as at, jsonb_build_object(
            'id', pa.id, 'at', pa.paid_at, 'method', pa.method, 'amount', pa.amount, 'receipt', pa.receipt_no,
            'patient', coalesce(p.surname || ' ' || p.given_names, cs.buyer_name),
            'counterSale', cs.number, 'reason', pa.void_reason,
            'by', (select full_name from profiles where id = pa.voided_by), 'voidedAt', pa.voided_at
          ) as j
        from payment pa
        left join invoice i on i.id = pa.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient p on p.id = e.patient_id
        left join counter_sale cs on cs.id = pa.counter_sale_id
        where pa.deleted_at is not null and pa.voided_at is not null and (v_all or pa.cashier_id = v_me)
          and (pa.paid_at at time zone 'Africa/Kigali')::date between v_from and v_to
        order by pa.voided_at desc limit 500) x
    ), '[]'::jsonb),
    'closes', coalesce((
      select jsonb_agg(jsonb_build_object(
          'cashier', pr.full_name, 'mine', d.cashier_id = v_me, 'expected', d.expected,
          'counted', d.counted, 'variance', d.variance, 'note', d.note, 'at', d.updated_at
        ) order by pr.full_name)
      from day_close d left join profiles pr on pr.id = d.cashier_id
      where d.deleted_at is null and d.date = v_day and (v_all or d.cashier_id = v_me)
    ), '[]'::jsonb),
    'myExpected', coalesce((
      select jsonb_object_agg(n.method, n.amount) from (select m.method, sum(m.amount) as amount from (
          select method::text as method, amount from payment
          where deleted_at is null and cashier_id = v_me and (paid_at at time zone 'Africa/Kigali')::date = v_day
          union all
          select method::text, -amount from refund
          where deleted_at is null and cashier_id = v_me and (refunded_at at time zone 'Africa/Kigali')::date = v_day
        ) m group by m.method) n
    ), '{}'::jsonb),
    'openBills', case when v_all or v_take then
                   (select count(*) from invoice i join encounter e on e.id = i.encounter_id
                    where i.deleted_at is null and i.status = 'draft' and e.status = 'open' and invoice_balance(i.id) > 0)
                 else 0 end,
    'openDue', case when v_all or v_take then
                 (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id
                  where i.deleted_at is null and i.status = 'draft' and e.status = 'open' and invoice_balance(i.id) > 0)
               else 0 end,
    -- counter sales (walk-in buyers): paid in the period, and those waiting to pay now
    'counterSales', jsonb_build_object(
      'count', (select count(*) from payment where deleted_at is null and counter_sale_id is not null
                and (v_all or cashier_id = v_me)
                and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to),
      'total', (select coalesce(sum(amount), 0) from payment where deleted_at is null and counter_sale_id is not null
                and (v_all or cashier_id = v_me)
                and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to)),
    'counterToPay', case when v_all or v_take then coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', s.id, 'number', s.number, 'buyer', s.buyer_name, 'phone', s.buyer_phone, 'total', s.total,
          'at', s.created_at, 'by', (select full_name from profiles where id = s.created_by),
          'lines', (select count(*) from counter_sale_line x where x.sale_id = s.id and x.deleted_at is null)
        ) order by s.created_at)
      from counter_sale s where s.deleted_at is null and s.status = 'open'
    ), '[]'::jsonb) else '[]'::jsonb end
  );
end
$$;

-- ---------------------------------------------------------------- vital signs: the refusal says why
-- record_vitals (from 20261126090000_departments_decide_desks): switched off: say that the manager has not allowed it.
create or replace function record_vitals(
  p_encounter_id uuid,
  p_vitals jsonb,
  p_triage triage_level default null,
  p_next_station station default null,
  p_reason text default null,
  p_measured_by uuid default null,
  p_measured_at timestamptz default null
)
returns text
language plpgsql security definer set search_path = public
as $$
declare
  v_ticket text;
  v_key text;
  v_val numeric;
  v_count integer := 0;
  v_by uuid := coalesce(p_measured_by, auth.uid());
  v_at timestamptz := coalesce(p_measured_at, now());
  v_arrived timestamptz;
  v_at_triage boolean;
  v_units jsonb := '{"bp_sys":"mmHg","bp_dia":"mmHg","pulse":"bpm","temp":"°C","resp":"/min","spo2":"%","weight":"kg","height":"cm","muac":"cm"}'::jsonb;
begin
  if not has_perm('vitals.write') then
    raise exception 'you may not record vital signs (the manager has not allowed it)' using errcode = '42501', hint = 'not_permitted';
  end if;
  select arrived_at into v_arrived from encounter where id = p_encounter_id and status = 'open';
  if not found then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  select exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = 'triage'
                 and finished_at is null and deleted_at is null) into v_at_triage;
  -- At triage: the people of a department that does triage (when none does, as before).
  if v_at_triage then
    perform assert_desk(array['triage'], 'triage');
  end if;
  -- Sending on from triage is for whoever may work on the patient (as with "Send on"): reception
  -- that sent the patient to triage, or a nurse other than the one named, records only.
  if v_at_triage and p_next_station is not null and not may_route(p_encounter_id) then
    if current_role_key() = 'receptionist' then
      raise exception 'this patient is with %: record the measurements without choosing where they go next; the nurse there sends them on',
        coalesce(patient_holder(p_encounter_id), 'triage') using errcode = '42501';
    end if;
    perform assert_may_work_on(p_encounter_id, true);
  end if;
  -- Without clinical rights the person typing must name who measured.
  if not has_perm('clinical.write') and (p_measured_by is null or p_measured_by = auth.uid()) then
    raise exception 'choose the nurse who took the measurements' using errcode = '22023';
  end if;
  if not exists (select 1 from profiles where id = v_by and active) then
    raise exception 'unknown staff member for "measured by"' using errcode = '22023';
  end if;
  -- the person named as having measured must be allowed to record vital signs themselves
  if v_by <> auth.uid() and not staff_perm(v_by, 'vitals.write') then
    raise exception 'the person named as "measured by" is not allowed to take vital signs'
      using errcode = '42501', hint = 'not_permitted';
  end if;
  if v_at > now() + interval '5 minutes' then
    raise exception 'the measurement time is in the future' using errcode = '22023';
  end if;
  if v_at < v_arrived - interval '1 hour' then
    raise exception 'the measurement time is before the patient arrived' using errcode = '22023';
  end if;

  for v_key, v_val in
    select key, nullif(value, '')::numeric from jsonb_each_text(coalesce(p_vitals, '{}'::jsonb))
  loop
    if v_val is not null and v_units ? v_key then
      insert into observation (encounter_id, code, value_num, unit, performer_id, effective_at)
      values (p_encounter_id, v_key, v_val, v_units ->> v_key, v_by, v_at);
      v_count := v_count + 1;
    end if;
  end loop;
  if v_count = 0 then
    raise exception 'enter at least one measurement' using errcode = '22023';
  end if;

  if v_by <> auth.uid() then
    insert into audit_event (actor_id, action, entity, entity_id, after, reason)
    values (auth.uid(), 'create', 'observation', p_encounter_id,
            jsonb_build_object('measured_by', v_by, 'measured_at', v_at, 'count', v_count),
            'vitals entered on behalf of the person who measured');
  end if;

  if p_triage is not null then
    update encounter set triage_level = p_triage, triage_reason = coalesce(p_reason, triage_reason)
    where id = p_encounter_id;
    -- the colour reorders the places where the patient waits (red first)
    update queue_entry set priority = case p_triage when 'red' then 1 when 'yellow' then 2 else 3 end
    where encounter_id = p_encounter_id and finished_at is null and started_at is null and deleted_at is null;
  end if;

  select ticket_no into v_ticket from queue_entry where encounter_id = p_encounter_id order by created_at limit 1;

  -- At triage: close the triage turn and send the patient on. Later (e.g. the doctor typing
  -- the nurse's paper sheet): measurements only, the patient stays where they are.
  if v_at_triage and p_next_station is not null then
    update queue_entry set finished_at = now()
    where encounter_id = p_encounter_id and station = 'triage' and finished_at is null;
    insert into queue_entry (encounter_id, station, ticket_no, priority)
    values (p_encounter_id, p_next_station, v_ticket,
            case coalesce(p_triage, 'green') when 'red' then 1 when 'yellow' then 2 else 3 end);
  end if;
  return v_ticket;
end
$$;

-- send_from_triage (from 20261126090000_departments_decide_desks): sending on from triage is triage work: vitals.write (the triage desk needs it too).
create or replace function send_from_triage(
  p_encounter_id uuid,
  p_triage triage_level,
  p_next_station station,
  p_reason text default null
)
returns text
language plpgsql security definer set search_path = public
as $$
declare
  v_ticket text;
begin
  if not (has_perm('clinical.write') or has_perm('vitals.write')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not has_perm('vitals.write') then
    raise exception 'you may not record vital signs (the manager has not allowed it)' using errcode = '42501', hint = 'not_permitted';
  end if;
  perform assert_desk(array['triage'], 'triage');
  perform assert_may_work_on(p_encounter_id, true);
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  if not exists (select 1 from observation where encounter_id = p_encounter_id and deleted_at is null) then
    raise exception 'take the vitals first' using errcode = '22023';
  end if;
  update encounter set triage_level = p_triage, triage_reason = coalesce(nullif(trim(coalesce(p_reason, '')), ''), triage_reason)
  where id = p_encounter_id;
  select ticket_no into v_ticket from queue_entry where encounter_id = p_encounter_id order by created_at limit 1;
  update queue_entry set finished_at = now()
  where encounter_id = p_encounter_id and station = 'triage' and finished_at is null and deleted_at is null;
  if not exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = p_next_station
                 and finished_at is null and deleted_at is null) then
    insert into queue_entry (encounter_id, station, ticket_no, priority)
    values (p_encounter_id, p_next_station, v_ticket,
            case p_triage when 'red' then 1 when 'yellow' then 2 else 3 end);
  end if;
  return v_ticket;
end
$$;

-- ---------------------------------------------------------------- C test results
-- record_result (from 20261126090000_departments_decide_desks): at the laboratory or ultrasound desk, also orders.write.
create or replace function record_result(
  p_request_id uuid,
  p_findings text,
  p_impression text,
  p_verify boolean default true
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_test text;
  v_name text;
  v_station station;
  v_q queue_entry%rowtype;
  v_tests text;
begin
  select * into v_req from service_request where id = p_request_id and deleted_at is null;
  if not found then
    raise exception 'test order not found' using errcode = 'P0002';
  end if;
  -- Lab / ultrasound results: lab staff and clinicians who order; an order done at another desk
  -- (Nursing, Dental…): the clinical staff of that desk too.
  if not ((may_use_desk(request_desk(v_req.station, v_req.category))
               and (request_desk(v_req.station, v_req.category) not in ('laboratory', 'ultrasound')
                    or has_perm('orders.write')))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    if may_use_desk(request_desk(v_req.station, v_req.category)) and not has_perm('orders.write') then
      raise exception 'you may not work on tests (the manager has not allowed it)'
        using errcode = '42501', hint = 'not_permitted';
    end if;
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_req.status = 'cancelled' then
    raise exception 'this test was marked "not done": order it again if it is done after all' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_findings, '')), '') is null and nullif(trim(coalesce(p_impression, '')), '') is null then
    raise exception 'write the findings or the conclusion' using errcode = '22023';
  end if;
  if exists (select 1 from diagnostic_report where service_request_id = p_request_id
             and deleted_at is null and verified_at is not null) then
    raise exception 'this result is verified: correct it, giving the reason' using errcode = '22023';
  end if;
  insert into diagnostic_report (service_request_id, findings, impression, verified_by, verified_at)
  values (p_request_id, nullif(trim(coalesce(p_findings, '')), ''), nullif(trim(coalesce(p_impression, '')), ''),
          case when p_verify then auth.uid() end, case when p_verify then now() end)
  on conflict (service_request_id) do update
  set findings = excluded.findings, impression = excluded.impression,
      verified_by = excluded.verified_by, verified_at = excluded.verified_at, updated_at = now();
  update service_request set status = case when p_verify then 'verified'::request_status else 'resulted'::request_status end
  where id = p_request_id;
  -- Tell the doctor who ordered it.
  if v_req.requester_id is not null and v_req.requester_id is distinct from auth.uid() then
    select s.name_en into v_test from service s where s.id = v_req.service_id;
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('result',
            jsonb_build_object('test', v_test, 'name', v_name,
                               'impression', nullif(trim(coalesce(p_impression, '')), ''),
                               'verified', p_verify),
            '/app/visit?encounter=' || v_req.encounter_id,
            v_req.requester_id, auth.uid());
  end if;
  -- Last result of this desk written: the patient goes back to the doctor.
  v_station := coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end);
  perform after_desk_tests(v_req.encounter_id, v_station, v_req.requester_id);
end
$$;

-- set_request_status (from 20261126090000_departments_decide_desks): at the laboratory or ultrasound desk, also orders.write.
create or replace function set_request_status(p_id uuid, p_status request_status, p_reason text default null)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_test text;
  v_name text;
  v_line uuid;
  v_invoice uuid;
begin
  select * into v_req from service_request where id = p_id;
  -- the lab and imaging (orders.write); an order done at another desk (Nursing, Dental…): the
  -- clinical staff of that desk too
  if not ((may_use_desk(request_desk(v_req.station, v_req.category))
               and (request_desk(v_req.station, v_req.category) not in ('laboratory', 'ultrasound')
                    or has_perm('orders.write')))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    if may_use_desk(request_desk(v_req.station, v_req.category)) and not has_perm('orders.write') then
      raise exception 'you may not work on tests (the manager has not allowed it)'
        using errcode = '42501', hint = 'not_permitted';
    end if;
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_status not in ('collected', 'in_process', 'cancelled') then
    raise exception 'use record_result for results' using errcode = '22023';
  end if;
  if p_status = 'cancelled' and nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'a reason is required to cancel a test' using errcode = '22023';
  end if;
  update service_request
  set status = p_status,
      reason = case when p_status = 'cancelled' then coalesce(reason || ' · ', '') || 'cancelled: ' || trim(p_reason) else reason end
  where id = p_id and deleted_at is null and status not in ('verified', 'cancelled');
  if not found then
    raise exception 'test not found or already finished' using errcode = 'P0002';
  end if;
  -- sample taken / analysing: the patient is being seen at that desk
  if p_status in ('collected', 'in_process') then
    update queue_entry q set started_at = coalesce(q.started_at, now()), called_at = coalesce(q.called_at, now()),
                             taken_by = coalesce(q.taken_by, auth.uid())
    where q.encounter_id = v_req.encounter_id and q.finished_at is null and q.deleted_at is null
      and q.station = coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end);
  end if;
  if p_status = 'cancelled' then
    select * into v_req from service_request where id = p_id;
    -- not done, not paid: its charge leaves the bill while the bill is open
    update invoice_line l
    set deleted_at = now(), manual_reason = coalesce(l.manual_reason || ' · ', '') || 'removed: test not done: ' || trim(p_reason)
    from invoice i
    where l.source_type = 'service_request' and l.source_id = p_id and l.deleted_at is null
      and i.id = l.invoice_id and i.status = 'draft'
    returning l.id, l.invoice_id into v_line, v_invoice;
    if v_invoice is not null then
      perform recompute_invoice(v_invoice);
    end if;
    -- the doctor who ordered it is told
    if v_req.requester_id is not null and v_req.requester_id is distinct from auth.uid() then
      select s.name_en into v_test from service s where s.id = v_req.service_id;
      select p.surname || ' ' || p.given_names into v_name
      from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
      insert into notification (kind, params, link, recipient_user, created_by)
      values ('test_cancelled', jsonb_build_object('test', v_test, 'name', v_name, 'reason', trim(p_reason)),
              '/app/visit?encounter=' || v_req.encounter_id, v_req.requester_id, auth.uid());
    end if;
    perform after_desk_tests(v_req.encounter_id,
      coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end),
      v_req.requester_id);
  end if;
end
$$;

-- correct_result (from 20261126090000_departments_decide_desks): at the laboratory or ultrasound desk, also orders.write.
create or replace function correct_result(
  p_request_id uuid,
  p_findings text,
  p_impression text,
  p_reason text
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_rep diagnostic_report%rowtype;
  v_test text;
  v_name text;
begin
  select * into v_req from service_request where id = p_request_id and deleted_at is null;
  if not found then
    raise exception 'test order not found' using errcode = 'P0002';
  end if;
  if not (is_manager() or (may_use_desk(request_desk(v_req.station, v_req.category))
               and (request_desk(v_req.station, v_req.category) not in ('laboratory', 'ultrasound')
                    or has_perm('orders.write')))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    if may_use_desk(request_desk(v_req.station, v_req.category)) and not has_perm('orders.write') then
      raise exception 'you may not work on tests (the manager has not allowed it)'
        using errcode = '42501', hint = 'not_permitted';
    end if;
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the result is corrected' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_findings, '')), '') is null and nullif(trim(coalesce(p_impression, '')), '') is null then
    raise exception 'write the findings or the conclusion' using errcode = '22023';
  end if;
  select * into v_rep from diagnostic_report where service_request_id = p_request_id and deleted_at is null for update;
  if not found or v_rep.verified_at is null then
    raise exception 'only a verified result is corrected; edit the result instead' using errcode = '22023';
  end if;
  insert into report_correction (report_id, old_findings, old_impression, old_verified_by, old_verified_at, reason)
  values (v_rep.id, v_rep.findings, v_rep.impression, v_rep.verified_by, v_rep.verified_at, trim(p_reason));
  perform set_config('mmc.correcting_report', v_rep.id::text, true);
  update diagnostic_report
  set findings = nullif(trim(coalesce(p_findings, '')), ''), impression = nullif(trim(coalesce(p_impression, '')), ''),
      verified_by = auth.uid(), verified_at = now(), corrected_at = now(), correction_reason = trim(p_reason),
      updated_at = now()
  where id = v_rep.id;
  perform set_config('mmc.correcting_report', '', true);
  -- The doctor who ordered the test is told the result changed.
  if v_req.requester_id is not null and v_req.requester_id is distinct from auth.uid() then
    select s.name_en into v_test from service s where s.id = v_req.service_id;
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
    insert into notification (kind, params, link, recipient_user, urgent, created_by)
    values ('result',
            jsonb_build_object('test', v_test, 'name', v_name,
                               'impression', nullif(trim(coalesce(p_impression, '')), ''),
                               'verified', true, 'corrected', true, 'reason', trim(p_reason)),
            '/app/visit?encounter=' || v_req.encounter_id,
            v_req.requester_id, true, auth.uid());
  end if;
end
$$;

-- ---------------------------------------------------------------- D bookings
-- inquiries_open (from 20261106090000_desks_wave8): also for those allowed to approve bookings.
create or replace function inquiries_open()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'name', a.contact_name, 'phone', a.contact_phone, 'reference', a.reference,
    'category', a.category, 'channel', a.contact_channel, 'note', a.reason,
    'doctor', pr.names, 'doctorUserId', pr.user_id,
    'startsAt', a.starts_at, 'preferredAt', a.preferred_at, 'createdAt', a.created_at,
    'insurer', a.insurer_text,
    'patientId', m.id, 'patientFile', m.file_number,
    'patientName', case when m.id is null then null else m.surname || ' ' || m.given_names end,
    'matches', m.n
  ) order by a.created_at), '[]'::jsonb)
  from appointment a
  left join practitioner pr on pr.id = a.practitioner_id
  left join lateral (
    select count(*)::integer as n,
           case when count(*) = 1 then (array_agg(p.id))[1] end as id,
           case when count(*) = 1 then (array_agg(p.file_number))[1] end as file_number,
           case when count(*) = 1 then (array_agg(p.surname))[1] end as surname,
           case when count(*) = 1 then (array_agg(p.given_names))[1] end as given_names
    from patient p
    where p.deleted_at is null and p.merged_into is null
      and phone_key(p.phone_1) = phone_key(a.contact_phone) and phone_key(a.contact_phone) <> ''
  ) m on true
  where (has_perm('appointment.read') or has_perm('appointment.approve')) and a.deleted_at is null and a.status = 'inquiry'
$$;

-- appointments_day (from 20261106090000_desks_wave8): also for those allowed to approve bookings.
create or replace function appointments_day(p_day date default null)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id,
      'time', to_char(a.starts_at at time zone 'Africa/Kigali', 'HH24:MI'),
      'startsAt', a.starts_at,
      'status', a.status,
      'patientId', a.patient_id,
      'fileNumber', p.file_number,
      'name', coalesce(p.surname || ' ' || p.given_names, a.contact_name),
      'phone', coalesce(p.phone_1, a.contact_phone),
      'doctor', pr.names,
      'reason', a.reason,
      'reference', a.reference,
      'source', a.source,
      'channel', a.contact_channel,
      'late', a.status in ('approved', 'confirmed') and a.starts_at < now() - interval '15 minutes',
      'doctorUserId', pr.user_id,
      'encounterId', (select e.id from encounter e where e.appointment_id = a.id order by e.arrived_at desc limit 1),
      'declineReason', case when a.status = 'declined' then a.cancel_reason end,
      -- a declined booking already booked again (a later booking of the same patient)
      'rebooked', a.status = 'declined' and exists (
        select 1 from appointment b
        where b.patient_id = a.patient_id and b.id <> a.id and b.deleted_at is null
          and b.created_at > a.updated_at
          and b.status not in ('declined', 'rejected', 'cancelled'))
    ) order by a.starts_at), '[]'::jsonb)
  from appointment a
  left join patient p on p.id = a.patient_id
  left join practitioner pr on pr.id = a.practitioner_id
  where (has_perm('appointment.read') or has_perm('appointment.approve')) and a.deleted_at is null
    and a.status in ('approved', 'confirmed', 'arrived', 'in_progress', 'completed', 'no_show', 'cancelled', 'declined')
    and (a.starts_at at time zone 'Africa/Kigali')::date = coalesce(p_day, (now() at time zone 'Africa/Kigali')::date)
$$;

-- appointment_detail (from 20261027090000_flow_payments_appointments): also for those allowed to approve bookings.
create or replace function appointment_detail(p_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'id', a.id, 'status', a.status, 'source', a.source, 'reference', a.reference,
    'startsAt', a.starts_at, 'endsAt', a.ends_at, 'preferredAt', a.preferred_at, 'createdAt', a.created_at,
    'reason', a.reason, 'cancelReason', a.cancel_reason, 'category', a.category, 'insurer', a.insurer_text,
    'channel', a.contact_channel, 'contactName', a.contact_name, 'contactPhone', a.contact_phone,
    'patientId', p.id, 'patientFile', p.file_number,
    'patientName', case when p.id is null then null else p.surname || ' ' || p.given_names end,
    'patientPhone', p.phone_1,
    'doctor', pr.names, 'doctorUserId', pr.user_id,
    'approvedBy', ap.full_name, 'approvedAt', a.approved_at,
    'acceptedBy', ac.full_name, 'acceptedAt', a.accepted_at,
    'encounterId', (select e.id from encounter e where e.appointment_id = a.id order by e.created_at desc limit 1),
    'late', a.status in ('approved', 'confirmed') and a.starts_at < now() - interval '15 minutes'
  )
  from appointment a
  left join patient p on p.id = a.patient_id
  left join practitioner pr on pr.id = a.practitioner_id
  left join profiles ap on ap.id = a.approved_by
  left join profiles ac on ac.id = a.accepted_by
  where (has_perm('appointment.read') or has_perm('appointment.approve')) and a.id = p_id and a.deleted_at is null
$$;

-- ---------------------------------------------------------------- E managing the stock
-- save_location (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function save_location(p_id uuid, p_name text, p_type stock_location_type, p_department_id uuid default null)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid := p_id;
  v_old stock_location%rowtype;
begin
  if length(trim(coalesce(p_name, ''))) < 2 then
    raise exception 'the store needs a name' using errcode = '22023';
  end if;
  if p_type::text = 'transit' then
    raise exception 'this store type is kept by the system' using errcode = '22023';
  end if;
  if v_id is not null then
    select * into v_old from stock_location where id = v_id and deleted_at is null;
    if not found then
      raise exception 'store not found' using errcode = 'P0002';
    end if;
    if v_old.type::text = 'transit' then
      raise exception 'this store is kept by the system' using errcode = '22023';
    end if;
  end if;
  if p_type = 'main_store' and (v_id is null or v_old.type <> 'main_store') then
    raise exception 'deliveries are received into the pharmacy: a new main store is not created'
      using errcode = '22023', hint = 'no_main_store';
  end if;
  -- who may: the pharmacy stores by the pharmacy or the manager, the room stores by the manager
  if is_room_type(p_type) or (v_id is not null and is_room_type(v_old.type)) then
    if not is_manager() then
      raise exception 'only the manager creates and changes room stores' using errcode = '42501';
    end if;
  elsif not stock_manager() then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_id is null then
    insert into stock_location (name, type, department_id) values (trim(p_name), p_type, p_department_id)
    returning id into v_id;
  else
    if v_old.type <> p_type and (
         exists (select 1 from stock_on_hand where location_id = v_id and quantity <> 0)
         or exists (select 1 from stock_transfer t where t.status = 'in_transit'
                    and (t.from_location_id = v_id or t.to_location_id = v_id))) then
      raise exception 'a store that holds stock keeps its type' using errcode = '23514', hint = 'store_has_stock';
    end if;
    update stock_location set name = trim(p_name), type = p_type, department_id = p_department_id, updated_at = now()
    where id = v_id;
    if v_old.is_main and p_type <> 'pharmacy' then
      update stock_location set is_main = false where id = v_id;
    end if;
  end if;
  -- a room store given to a department: the department holds it
  if is_room_type(p_type) and p_department_id is not null
     and not exists (select 1 from stock_location_holder where location_id = v_id and department_id = p_department_id
                     and deleted_at is null) then
    insert into stock_location_holder (location_id, department_id) values (v_id, p_department_id);
  end if;
  return v_id;
end
$$;

-- set_location_active (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function set_location_active(p_id uuid, p_active boolean)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_l stock_location%rowtype;
begin
  select * into v_l from stock_location where id = p_id and deleted_at is null for update;
  if not found then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if v_l.type::text = 'transit' then
    raise exception 'this store is kept by the system' using errcode = '22023';
  end if;
  if is_room_type(v_l.type) then
    if not is_manager() then
      raise exception 'only the manager closes and reopens room stores' using errcode = '42501';
    end if;
  elsif not stock_manager() then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not p_active then
    if exists (select 1 from stock_on_hand where location_id = p_id and quantity > 0) then
      raise exception 'this store still holds stock: return it to the pharmacy (or send it on) first'
        using errcode = '23514', hint = 'store_has_stock';
    end if;
    if exists (select 1 from stock_transfer t where t.status = 'in_transit'
               and (t.from_location_id = p_id or t.to_location_id = p_id)) then
      raise exception 'a transfer note to or from this store is still on the way: receive or cancel it first'
        using errcode = '23514', hint = 'notes_in_transit';
    end if;
    update store_request set status = 'cancelled', decided_at = now(), decided_by = auth.uid(),
           decline_reason = 'store closed'
    where location_id = p_id and status = 'open';
  end if;
  update stock_location set active = p_active, updated_at = now(),
         is_main = case when p_active then is_main else false end
  where id = p_id;
  -- the main pharmacy closed: the next open pharmacy store receives
  if not p_active and v_l.is_main then
    update stock_location set is_main = true
    where id = (select id from stock_location where type = 'pharmacy' and active and deleted_at is null
                order by created_at limit 1);
  end if;
end
$$;

-- set_store_min (from 20261124090000_stores_and_stock): the holders, or stock_manager().
create or replace function set_store_min(p_location_id uuid, p_item_id uuid, p_min integer)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not exists (select 1 from stock_location where id = p_location_id and deleted_at is null and is_room_type(type)) then
    raise exception 'choose a room store' using errcode = '22023', hint = 'not_room_store';
  end if;
  if not (stock_manager() or holds_store(auth.uid(), p_location_id)) then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not exists (select 1 from item where id = p_item_id and deleted_at is null) then
    raise exception 'medicine not found' using errcode = 'P0002';
  end if;
  if p_min is not null and p_min < 0 then
    raise exception 'the minimum must be zero or more' using errcode = '22023';
  end if;
  if coalesce(p_min, 0) = 0 then
    delete from store_item_level where location_id = p_location_id and item_id = p_item_id;
    delete from low_stock_flag where item_id = p_item_id and scope = p_location_id::text;
  else
    insert into store_item_level (location_id, item_id, min_level) values (p_location_id, p_item_id, p_min)
    on conflict (location_id, item_id) do update set min_level = excluded.min_level, updated_at = now(),
                                                     updated_by = auth.uid();
    perform check_room_low(p_item_id, p_location_id);
  end if;
end
$$;

-- receive_stock (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function receive_stock(
  p_item_id uuid, p_location_id uuid, p_quantity integer, p_unit_cost numeric,
  p_batch_no text default null, p_expiry date default null, p_supplier text default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_l stock_location%rowtype;
begin
  select * into v_l from stock_location where id = p_location_id and deleted_at is null;
  if not found then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if v_l.type = 'pharmacy' then
    if not stock_manager() then
      perform assert_stock_write();
      raise exception 'not allowed' using errcode = '42501';
    end if;
  elsif v_l.type = 'lab' then
    if not (is_manager() or (has_perm('stock.write') and holds_store(auth.uid(), p_location_id))) then
      raise exception 'not allowed' using errcode = '42501';
    end if;
  else
    raise exception 'deliveries are received into the pharmacy; room stores are supplied by the pharmacy with a transfer note'
      using errcode = '22023', hint = 'receive_into_pharmacy';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'quantity must be more than zero' using errcode = '22023';
  end if;
  if p_unit_cost is null or p_unit_cost < 0 then
    raise exception 'the cost per unit must be zero or more' using errcode = '22023';
  end if;
  return receive_batch(p_item_id, p_location_id, p_quantity, p_unit_cost, p_batch_no, p_expiry,
                       supplier_for(p_supplier), nullif(trim(coalesce(p_supplier, '')), ''), null);
end
$$;

-- receive_delivery (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function receive_delivery(
  p_supplier text, p_reference text, p_lines jsonb, p_delivered_on date default null,
  p_location_id uuid default null, p_note text default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_loc uuid;
  v_sup uuid;
  v_ref text := nullif(trim(coalesce(p_reference, '')), '');
  v_on date := coalesce(p_delivered_on, (now() at time zone 'Africa/Kigali')::date);
  v_id uuid;
  v_number text;
  v_line jsonb;
  v_n integer;
  v_item uuid;
  v_code text;
  v_r medicine_reference%rowtype;
  v_unit text;
  v_qty numeric;
  v_pack integer;
  v_units integer;
  v_cost numeric;
  v_unit_cost numeric;
  v_line_cost numeric;
  v_expiry date;
  v_batch uuid;
  v_total numeric := 0;
  v_all_units integer := 0;
  v_state text;
  v_msg text;
  v_hint text;
begin
  if not stock_manager() then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  v_loc := coalesce(p_location_id, main_pharmacy());
  if v_loc is null or not exists (select 1 from stock_location where id = v_loc and type = 'pharmacy' and active
                                  and deleted_at is null) then
    raise exception 'deliveries are received into an open pharmacy store' using errcode = '22023', hint = 'receive_into_pharmacy';
  end if;
  if length(trim(coalesce(p_supplier, ''))) < 2 then
    raise exception 'name the supplier' using errcode = '22023', hint = 'supplier';
  end if;
  if v_on > (now() at time zone 'Africa/Kigali')::date then
    raise exception 'the delivery date is in the future' using errcode = '22023';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'add at least one medicine' using errcode = '22023';
  end if;
  v_sup := supplier_for(p_supplier);
  if v_ref is not null and exists (select 1 from goods_receipt g where g.supplier_id = v_sup and lower(g.reference) = lower(v_ref)
                                   and g.deleted_at is null) then
    raise exception 'delivery note % of this supplier was already received', v_ref using errcode = '23505', hint = 'duplicate_delivery';
  end if;
  v_number := day_number('GRN', 'goods-receipt');
  insert into goods_receipt (supplier_id, received_on, note, number, reference, delivered_on, location_id, supplier_name)
  values (v_sup, now(), nullif(trim(coalesce(p_note, '')), ''), v_number, v_ref, v_on, v_loc, trim(p_supplier))
  returning id into v_id;

  for v_line, v_n in select x.value, x.ordinality from jsonb_array_elements(p_lines) with ordinality as x loop
    begin
      v_item := nullif(v_line ->> 'itemId', '')::uuid;
      v_code := nullif(upper(trim(coalesce(v_line ->> 'refCode', ''))), '');
      if v_item is null and v_code is not null then
        select id into v_item from item where code = v_code and deleted_at is null;
        if v_item is null then
          -- a medicine new at the clinic, from the reference list (RHIA): added with its selling price
          select * into v_r from medicine_reference where code = v_code;
          if not found then
            raise exception 'this medicine is not on the reference list' using errcode = 'P0002';
          end if;
          v_item := upsert_item(null, v_r.generic,
                                coalesce(nullif(v_line ->> 'sellingPrice', '')::numeric, v_r.price),
                                v_r.presentation, null, v_r.unit, true, v_r.code);
        end if;
      end if;
      if v_item is null or not exists (select 1 from item where id = v_item and deleted_at is null) then
        raise exception 'choose the medicine' using errcode = '22023';
      end if;
      v_unit := coalesce(nullif(v_line ->> 'unit', ''), 'unit');
      if v_unit not in ('box', 'unit') then
        raise exception 'count in boxes or in units' using errcode = '22023';
      end if;
      v_qty := nullif(v_line ->> 'quantity', '')::numeric;
      if v_qty is null or v_qty <= 0 then
        raise exception 'quantity must be more than zero' using errcode = '22023';
      end if;
      if v_unit = 'box' then
        v_pack := coalesce(nullif(v_line ->> 'packSize', '')::integer, (select pack_size from item where id = v_item));
        if v_pack is null or v_pack < 1 then
          raise exception 'say how many units are in one box' using errcode = '22023', hint = 'pack_size';
        end if;
        update item set pack_size = v_pack where id = v_item and pack_size is null;
      else
        v_pack := 1;
      end if;
      v_units := round(v_qty * v_pack)::integer;
      if v_units <> v_qty * v_pack or v_units <= 0 then
        raise exception 'the quantity must come to whole units' using errcode = '22023';
      end if;
      v_cost := nullif(v_line ->> 'cost', '')::numeric;
      if v_cost is null or v_cost < 0 then
        raise exception 'the cost must be zero or more' using errcode = '22023';
      end if;
      v_unit_cost := round(v_cost / v_pack, 2);
      v_line_cost := round(v_cost * v_qty, 2);
      v_expiry := nullif(v_line ->> 'expiry', '')::date;
      perform set_cash_price_if_none(v_item, nullif(v_line ->> 'sellingPrice', '')::numeric);
      v_batch := receive_batch(v_item, v_loc, v_units, v_unit_cost, v_line ->> 'batchNo', v_expiry, v_sup,
                               trim(p_supplier) || coalesce(' · ' || v_ref, '') || ' · ' || v_number, v_id);
      insert into goods_receipt_line (receipt_id, item_id, batch_id, batch_no, expiry, unit, packs, pack_size, units,
                                      unit_cost, pack_cost, line_cost)
      values (v_id, v_item, v_batch, (select batch_no from batch where id = v_batch), v_expiry, v_unit, v_qty, v_pack,
              v_units, v_unit_cost, case when v_unit = 'box' then v_cost end, v_line_cost);
      v_total := v_total + v_line_cost;
      v_all_units := v_all_units + v_units;
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text, v_hint = pg_exception_hint;
      raise exception 'line %: %', v_n, v_msg using errcode = v_state, hint = coalesce(nullif(v_hint, ''), 'line');
    end;
  end loop;
  update goods_receipt set total_cost = v_total where id = v_id;
  return jsonb_build_object('id', v_id, 'number', v_number, 'locationId', v_loc,
                            'lines', jsonb_array_length(p_lines), 'units', v_all_units, 'totalCost', v_total);
end
$$;

-- assert_store_work (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function assert_store_work(p_location_id uuid)
returns stock_location
language plpgsql stable security definer set search_path = public
as $$
declare
  v_l stock_location%rowtype;
begin
  select * into v_l from stock_location where id = p_location_id and deleted_at is null;
  if not found then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if v_l.type::text = 'transit' then
    raise exception 'the units on the way belong to their transfer note' using errcode = '22023';
  end if;
  if is_room_type(v_l.type) then
    if not (is_manager() or holds_store(auth.uid(), p_location_id)) then
      raise exception 'only the people who hold this store (or the manager) work its stock'
        using errcode = '42501', hint = 'not_holder';
    end if;
  elsif not stock_manager() then
    perform assert_stock_write();
    raise exception 'only the pharmacy (or the manager) works the pharmacy stock' using errcode = '42501';
  end if;
  return v_l;
end
$$;

-- adjust_stock (from 20261124090000_stores_and_stock): a room store counted up: stock_manager().
create or replace function adjust_stock(p_item_id uuid, p_location_id uuid, p_counted integer, p_reason text)
returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_on_hand integer;
  v_diff integer;
  v_remaining integer;
  v_row record;
  v_take integer;
  v_batch uuid;
  v_l stock_location%rowtype;
begin
  v_l := assert_store_work(p_location_id);
  if p_counted is null or p_counted < 0 then
    raise exception 'the count must be zero or more' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the count changes' using errcode = '22023';
  end if;
  perform lock_stock(p_item_id, p_location_id);
  select coalesce(sum(quantity), 0)::integer into v_on_hand
  from stock_on_hand where item_id = p_item_id and location_id = p_location_id;
  v_diff := p_counted - v_on_hand;
  -- a room store is supplied only by the pharmacy's transfer notes: its holders do not count it up
  if is_room_type(v_l.type) and v_diff > 0 and not stock_manager() then
    raise exception 'more on the shelf than the system says: ask the pharmacy to send it with a transfer note'
      using errcode = '22023', hint = 'use_transfer_note';
  end if;
  if v_diff < 0 then
    v_remaining := -v_diff;
    for v_row in
      select s.batch_id, s.quantity from stock_on_hand s
      where s.item_id = p_item_id and s.location_id = p_location_id and s.quantity > 0
      order by s.expiry asc nulls last
    loop
      exit when v_remaining <= 0;
      v_take := least(v_row.quantity, v_remaining);
      insert into stock_movement (item_id, batch_id, from_location_id, quantity, type, reason)
      values (p_item_id, v_row.batch_id, p_location_id, v_take, 'adjustment', 'count: ' || trim(p_reason));
      v_remaining := v_remaining - v_take;
    end loop;
    if is_room_type(v_l.type) then
      perform notify_room_loss(p_item_id, v_l, -v_diff, 'count: ' || trim(p_reason));
    end if;
  elsif v_diff > 0 then
    -- more on the shelf: the latest batch this store has held, else the medicine's latest batch
    select b.id into v_batch from batch b
    where b.item_id = p_item_id and b.deleted_at is null
    order by exists (select 1 from stock_movement m where m.batch_id = b.id and m.to_location_id = p_location_id
                     and m.deleted_at is null) desc,
             b.received_on desc
    limit 1;
    if v_batch is null then
      raise exception 'no batch of this item yet: receive it instead' using errcode = 'P0002';
    end if;
    insert into stock_movement (item_id, batch_id, to_location_id, quantity, type, reason)
    values (p_item_id, v_batch, p_location_id, v_diff, 'adjustment', 'count: ' || trim(p_reason));
  end if;
  return v_diff;
end
$$;

-- transfer_stock (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function transfer_stock(
  p_item_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_quantity integer, p_reason text default null
)
returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_remaining integer := p_quantity;
  v_row record;
  v_take integer;
  v_from stock_location%rowtype;
  v_to stock_location%rowtype;
begin
  if not stock_manager() then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'quantity must be more than zero' using errcode = '22023';
  end if;
  if p_from_location_id = p_to_location_id then
    raise exception 'choose a different destination' using errcode = '22023';
  end if;
  select * into v_from from stock_location where id = p_from_location_id and deleted_at is null;
  select * into v_to from stock_location where id = p_to_location_id and deleted_at is null;
  if v_from.id is null or v_to.id is null then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if v_from.type not in ('pharmacy', 'main_store') or v_to.type <> 'pharmacy' then
    raise exception 'a room store is supplied with a transfer note, and sends back with a return note'
      using errcode = '22023', hint = 'use_transfer_note';
  end if;
  if not v_to.active then
    raise exception 'this store is closed: reopen it first' using errcode = '22023', hint = 'store_closed';
  end if;
  perform lock_stock(p_item_id, p_from_location_id);
  for v_row in
    select s.batch_id, s.quantity, b.unit_cost from stock_on_hand s left join batch b on b.id = s.batch_id
    where s.item_id = p_item_id and s.location_id = p_from_location_id and s.quantity > 0
      and (s.expiry is null or s.expiry >= current_date)   -- expired stock is not sent on
    order by s.expiry asc nulls last
  loop
    exit when v_remaining <= 0;
    v_take := least(v_row.quantity, v_remaining);
    insert into stock_movement (item_id, batch_id, from_location_id, to_location_id, quantity, type, reason, unit_cost)
    values (p_item_id, v_row.batch_id, p_from_location_id, p_to_location_id, v_take, 'transfer',
            nullif(trim(coalesce(p_reason, '')), ''), v_row.unit_cost);
    v_remaining := v_remaining - v_take;
  end loop;
  if v_remaining > 0 then
    raise exception 'not enough stock in that store: % unit(s) short', v_remaining using errcode = '23514', hint = 'short';
  end if;
  return p_quantity;
end
$$;

-- decline_refill (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function decline_refill(p_request_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_r store_request%rowtype;
begin
  if not stock_manager() then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the request is declined' using errcode = '22023';
  end if;
  select * into v_r from store_request where id = p_request_id and deleted_at is null for update;
  if not found or v_r.status <> 'open' then
    raise exception 'this request is no longer open' using errcode = 'P0002';
  end if;
  update store_request set status = 'declined', decided_by = auth.uid(), decided_at = now(), decline_reason = trim(p_reason)
  where id = v_r.id;
  insert into notification (kind, params, link, recipient_user, created_by)
  values ('refill_declined', jsonb_build_object('number', v_r.number,
                                                'store', (select name from stock_location where id = v_r.location_id),
                                                'reason', trim(p_reason),
                                                'by', (select full_name from profiles where id = auth.uid())),
          '/app/stock?tab=mine&store=' || v_r.location_id, v_r.created_by, auth.uid());
end
$$;

-- send_to_room (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function send_to_room(
  p_location_id uuid, p_lines jsonb, p_request_id uuid default null, p_note text default null,
  p_from_location_id uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_to stock_location%rowtype;
  v_from uuid := coalesce(p_from_location_id, main_pharmacy());
  v_r store_request%rowtype;
  v_id uuid;
  v_number text;
  v_line record;
begin
  if not stock_manager() then
    perform assert_stock_write();
    raise exception 'only the pharmacy (or the manager) sends stock to a room store' using errcode = '42501';
  end if;
  select * into v_to from stock_location where id = p_location_id and deleted_at is null and active;
  if not found or not is_room_type(v_to.type) then
    raise exception 'choose an open room store' using errcode = '22023', hint = 'not_room_store';
  end if;
  -- nobody would be told or could confirm it: the manager assigns a holder first
  if not exists (select 1 from stock_location_holder where location_id = p_location_id and deleted_at is null) then
    raise exception 'this room store has no holder yet: the manager assigns one first'
      using errcode = '22023', hint = 'no_holder';
  end if;
  if v_from is null or not exists (select 1 from stock_location where id = v_from and type = 'pharmacy' and active
                                   and deleted_at is null) then
    raise exception 'room stores are supplied from an open pharmacy store' using errcode = '22023';
  end if;
  if p_request_id is not null then
    select * into v_r from store_request where id = p_request_id and deleted_at is null for update;
    if not found or v_r.status <> 'open' then
      raise exception 'this request is no longer open' using errcode = 'P0002';
    end if;
    if v_r.location_id <> p_location_id then
      raise exception 'this request is for another store' using errcode = '22023';
    end if;
  end if;
  v_number := day_number('T', 'transfer');
  insert into stock_transfer (number, direction, from_location_id, to_location_id, request_id, note)
  values (v_number, 'to_room', v_from, p_location_id, p_request_id, nullif(trim(coalesce(p_note, '')), ''))
  returning id into v_id;
  for v_line in select * from note_lines(p_lines) loop
    if not exists (select 1 from item where id = v_line.item_id and deleted_at is null) then
      raise exception 'medicine not found' using errcode = 'P0002';
    end if;
    perform transfer_out(v_id, v_from, v_line.item_id, v_line.quantity, false);
  end loop;
  if p_request_id is not null then
    update store_request set status = 'fulfilled', transfer_id = v_id, decided_by = auth.uid(), decided_at = now()
    where id = p_request_id;
  end if;
  perform notify_holders(p_location_id, 'transfer_sent',
                         jsonb_build_object('number', v_number, 'store', v_to.name, 'transferId', v_id,
                                            'lines', (select count(distinct item_id) from stock_transfer_line where transfer_id = v_id),
                                            'by', (select full_name from profiles where id = auth.uid())),
                         '/app/stock?tab=mine&store=' || p_location_id || '&note=' || v_id);
  return transfer_note_totals(v_id);
end
$$;

-- confirm_receipt (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function confirm_receipt(p_transfer_id uuid, p_lines jsonb default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_t stock_transfer%rowtype;
  v_transit uuid := transit_store();
  v_line stock_transfer_line%rowtype;
  v_given jsonb;
  v_recv integer;
  v_diff integer;
  v_reason text;
  v_action text;
  v_in integer := 0;
  v_back integer := 0;
  v_lost integer := 0;
  v_store text;
begin
  select * into v_t from stock_transfer where id = p_transfer_id and deleted_at is null for update;
  if not found then
    raise exception 'transfer note not found' using errcode = 'P0002';
  end if;
  if v_t.direction = 'to_room' then
    if not (is_manager() or holds_store(auth.uid(), v_t.to_location_id)) then
      raise exception 'only the people who hold this store confirm what arrived' using errcode = '42501', hint = 'not_holder';
    end if;
  elsif not stock_manager() then
    perform assert_stock_write();
    raise exception 'only the pharmacy confirms what came back' using errcode = '42501';
  end if;
  -- two people: the one who sent the note does not also confirm it (the manager excepted)
  if v_t.created_by = auth.uid() and not is_manager() then
    raise exception 'the person who sent this note does not confirm it: the receiver does'
      using errcode = '42501', hint = 'own_note';
  end if;
  if v_t.status <> 'in_transit' then
    raise exception 'this note was already %', case v_t.status when 'received' then 'received' else 'cancelled' end
      using errcode = '23505';
  end if;
  if not exists (select 1 from stock_location where id = v_t.to_location_id and active) then
    raise exception 'the receiving store is closed: reopen it first' using errcode = '22023', hint = 'store_closed';
  end if;
  if p_lines is not null and jsonb_typeof(p_lines) <> 'array' then
    raise exception 'the lines are a list' using errcode = '22023';
  end if;
  if p_lines is not null and exists (
       select 1 from jsonb_array_elements(p_lines) x
       where not exists (select 1 from stock_transfer_line l where l.transfer_id = v_t.id
                         and l.id = nullif(x ->> 'lineId', '')::uuid)) then
    raise exception 'a line is not on this note' using errcode = '22023';
  end if;
  for v_line in select * from stock_transfer_line where transfer_id = v_t.id and deleted_at is null order by created_at for update loop
    v_given := null;
    select x.v into v_given from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) as x(v)
    where (x.v ->> 'lineId')::uuid = v_line.id limit 1;
    v_recv := coalesce(nullif(v_given ->> 'received', '')::numeric, v_line.quantity);
    if v_recv < 0 or v_recv > v_line.quantity or v_recv <> round(v_recv) then
      raise exception 'received: a whole number between 0 and % for %', v_line.quantity, item_label(v_line.item_id)
        using errcode = '22023';
    end if;
    v_diff := v_line.quantity - v_recv;
    v_reason := nullif(trim(coalesce(v_given ->> 'reason', '')), '');
    v_action := case coalesce(nullif(v_given ->> 'action', ''), 'returned') when 'return' then 'returned' when 'lost' then 'loss'
                     else coalesce(nullif(v_given ->> 'action', ''), 'returned') end;
    if v_diff > 0 and length(coalesce(v_reason, '')) < 3 then
      raise exception 'say why % of % did not arrive', v_diff, item_label(v_line.item_id)
        using errcode = '22023', hint = 'difference_reason';
    end if;
    if v_diff > 0 and v_action not in ('returned', 'loss') then
      raise exception 'a difference goes back (returned) or is a loss' using errcode = '22023';
    end if;
    if v_recv > 0 then
      insert into stock_movement (item_id, batch_id, from_location_id, to_location_id, quantity, type, reason, unit_cost, stock_transfer_id)
      values (v_line.item_id, v_line.batch_id, v_transit, v_t.to_location_id, v_recv, 'transfer', 'received: ' || v_t.number,
              v_line.unit_cost, v_t.id);
      v_in := v_in + v_recv;
    end if;
    if v_diff > 0 and v_action = 'returned' then
      insert into stock_movement (item_id, batch_id, from_location_id, to_location_id, quantity, type, reason, unit_cost, stock_transfer_id)
      values (v_line.item_id, v_line.batch_id, v_transit, v_t.from_location_id, v_diff, 'transfer',
              'not received (' || v_t.number || '): ' || v_reason, v_line.unit_cost, v_t.id);
      v_back := v_back + v_diff;
    elsif v_diff > 0 then
      insert into stock_movement (item_id, batch_id, from_location_id, quantity, type, reason, unit_cost, stock_transfer_id)
      values (v_line.item_id, v_line.batch_id, v_transit, v_diff, 'adjustment',
              'lost on the way (' || v_t.number || '): ' || v_reason, v_line.unit_cost, v_t.id);
      v_lost := v_lost + v_diff;
    end if;
    update stock_transfer_line
    set received_quantity = v_recv, difference_action = case when v_diff > 0 then v_action end,
        difference_reason = case when v_diff > 0 then v_reason end
    where id = v_line.id;
  end loop;
  update stock_transfer
  set status = 'received', received_by = auth.uid(), confirmed_at = now(),
      receive_note = nullif(trim(coalesce(p_note, '')), ''), has_difference = (v_back + v_lost) > 0
  where id = v_t.id;
  v_store := (select name from stock_location where id = case when v_t.direction = 'to_room' then v_t.to_location_id
                                                               else v_t.from_location_id end);
  -- the sender is told it arrived
  insert into notification (kind, params, link, recipient_user, created_by)
  values ('transfer_received', jsonb_build_object('number', v_t.number, 'store', v_store, 'transferId', v_t.id,
                                                  'by', (select full_name from profiles where id = auth.uid()),
                                                  'missing', v_back + v_lost),
          case when v_t.direction = 'to_room' then '/app/stock?tab=rooms&note=' || v_t.id
               else '/app/stock?tab=mine&store=' || v_t.from_location_id || '&note=' || v_t.id end,
          v_t.created_by, auth.uid());
  -- a difference: the manager and the pharmacy are told
  if v_back + v_lost > 0 then
    insert into notification (kind, params, link, recipient_role, created_by)
    values ('transfer_difference', jsonb_build_object('number', v_t.number, 'store', v_store, 'transferId', v_t.id,
                                                      'returned', v_back, 'lost', v_lost,
                                                      'by', (select full_name from profiles where id = auth.uid())),
            '/app/stock?tab=rooms&note=' || v_t.id, 'manager', auth.uid());
    insert into notification (kind, params, link, recipient_stations, created_by)
    values ('transfer_difference', jsonb_build_object('number', v_t.number, 'store', v_store, 'transferId', v_t.id,
                                                      'returned', v_back, 'lost', v_lost,
                                                      'by', (select full_name from profiles where id = auth.uid())),
            '/app/stock?tab=rooms&note=' || v_t.id, array['pharmacy'::station], auth.uid());
  end if;
  return jsonb_build_object('id', v_t.id, 'number', v_t.number, 'status', 'received',
                            'received', v_in, 'returned', v_back, 'lost', v_lost);
end
$$;

-- cancel_transfer (from 20261124090000_stores_and_stock): the pharmacy side needs stock_manager() (pharmacy desk and stock.write), not the desk alone.
create or replace function cancel_transfer(p_transfer_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_t stock_transfer%rowtype;
  v_transit uuid := transit_store();
  v_line stock_transfer_line%rowtype;
  v_units integer := 0;
  v_store text;
begin
  select * into v_t from stock_transfer where id = p_transfer_id and deleted_at is null for update;
  if not found then
    raise exception 'transfer note not found' using errcode = 'P0002';
  end if;
  if v_t.direction = 'to_room' then
    if not stock_manager() then
      perform assert_stock_write();
      raise exception 'only the pharmacy (or the manager) cancels a note it sent' using errcode = '42501';
    end if;
  elsif not (is_manager() or holds_store(auth.uid(), v_t.from_location_id)) then
    raise exception 'only the people who hold this store (or the manager) cancel its return note' using errcode = '42501', hint = 'not_holder';
  end if;
  if v_t.status <> 'in_transit' then
    raise exception 'this note was already %', case v_t.status when 'received' then 'received' else 'cancelled' end
      using errcode = '23505';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the note is cancelled' using errcode = '22023';
  end if;
  for v_line in select * from stock_transfer_line where transfer_id = v_t.id and deleted_at is null loop
    insert into stock_movement (item_id, batch_id, from_location_id, to_location_id, quantity, type, reason, unit_cost, stock_transfer_id)
    values (v_line.item_id, v_line.batch_id, v_transit, v_t.from_location_id, v_line.quantity, 'transfer',
            'cancelled (' || v_t.number || '): ' || trim(p_reason), v_line.unit_cost, v_t.id);
    v_units := v_units + v_line.quantity;
  end loop;
  update stock_transfer set status = 'cancelled', cancelled_by = auth.uid(), cancelled_at = now(), cancel_reason = trim(p_reason)
  where id = v_t.id;
  -- a refill request served by this note is open again
  update store_request set status = 'open', transfer_id = null, decided_by = null, decided_at = null
  where transfer_id = v_t.id and status = 'fulfilled';
  if v_t.direction = 'to_room' then
    v_store := (select name from stock_location where id = v_t.to_location_id);
    perform notify_holders(v_t.to_location_id, 'transfer_cancelled',
                           jsonb_build_object('number', v_t.number, 'store', v_store, 'reason', trim(p_reason),
                                              'by', (select full_name from profiles where id = auth.uid())));
  else
    v_store := (select name from stock_location where id = v_t.from_location_id);
    insert into notification (kind, params, link, recipient_stations, created_by)
    values ('transfer_cancelled', jsonb_build_object('number', v_t.number, 'store', v_store, 'reason', trim(p_reason),
                                                     'by', (select full_name from profiles where id = auth.uid())),
            '/app/stock?tab=rooms&note=' || v_t.id, array['pharmacy'::station], auth.uid());
  end if;
  return jsonb_build_object('id', v_t.id, 'number', v_t.number, 'status', 'cancelled', 'units', v_units);
end
$$;

-- transfer_notes (from 20261124090000_stores_and_stock): what the reader may do: stock_manager() on the pharmacy side.
create or replace function transfer_notes(
  p_status text default null, p_location_id uuid default null, p_from date default null, p_to date default null
)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(x.j order by x.open desc, x.at desc), '[]'::jsonb)
  from (
    select t.status = 'in_transit' as open, t.sent_at as at, jsonb_build_object(
      'id', t.id, 'number', t.number, 'direction', t.direction, 'status', t.status,
      'fromId', t.from_location_id, 'from', lf.name, 'toId', t.to_location_id, 'to', lt.name,
      'sentAt', t.sent_at, 'sentBy', (select full_name from profiles where id = t.created_by),
      'receivedAt', t.confirmed_at, 'receivedBy', (select full_name from profiles where id = t.received_by),
      'cancelledAt', t.cancelled_at, 'cancelledBy', (select full_name from profiles where id = t.cancelled_by),
      'cancelReason', t.cancel_reason, 'note', t.note, 'receiveNote', t.receive_note,
      'requestId', t.request_id, 'requestNumber', (select r.number from store_request r where r.id = t.request_id),
      'hasDifference', t.has_difference,
      'lines', (select count(distinct x.item_id) from stock_transfer_line x where x.transfer_id = t.id)::integer,
      'units', (select coalesce(sum(x.quantity), 0) from stock_transfer_line x where x.transfer_id = t.id)::integer,
      'value', case when stock_admin() then (select coalesce(sum(x.quantity * x.unit_cost), 0)
                                             from stock_transfer_line x where x.transfer_id = t.id) end,
      -- what the reader may do with it now
      'canReceive', t.status = 'in_transit' and case when t.direction = 'to_room'
                      then is_manager() or holds_store(auth.uid(), t.to_location_id) else stock_manager() end,
      'canCancel', t.status = 'in_transit' and case when t.direction = 'to_room'
                      then stock_manager() else is_manager() or holds_store(auth.uid(), t.from_location_id) end
    ) as j
    from stock_transfer t
    join stock_location lf on lf.id = t.from_location_id
    join stock_location lt on lt.id = t.to_location_id
    where t.deleted_at is null
      and (p_status is null or t.status = p_status)
      and (p_location_id is null or t.from_location_id = p_location_id or t.to_location_id = p_location_id)
      and (p_from is null or (t.sent_at at time zone 'Africa/Kigali')::date >= p_from)
      and (p_to is null or (t.sent_at at time zone 'Africa/Kigali')::date <= p_to)
      and (stock_admin() or holds_store(auth.uid(), t.from_location_id) or holds_store(auth.uid(), t.to_location_id))
    order by t.sent_at desc
    limit 300
  ) x
$$;

-- store_stock (from 20261126090000_departments_decide_desks): canManage: stock_manager() for a pharmacy store.
create or replace function store_stock(p_location_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_l stock_location%rowtype;
  v_admin boolean := stock_admin();
  v_items jsonb;
  v_incoming jsonb;
begin
  select * into v_l from stock_location where id = p_location_id and deleted_at is null;
  if not found or v_l.type::text = 'transit' then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if not may_see_store(p_location_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'itemId', i.id, 'item', i.name_generic || coalesce(' ' || i.strength, ''), 'code', i.code,
      'unit', i.selling_unit, 'packSize', i.pack_size,
      'onHand', coalesce(t.on_hand, 0), 'usable', coalesce(t.usable, 0), 'expired', coalesce(t.expired, 0),
      'expiringSoon', coalesce(t.expiring, 0), 'earliestExpiry', t.next_expiry,
      'minLevel', m.min_level, 'low', m.min_level is not null and coalesce(t.usable, 0) < m.min_level,
      'price', (select pf.price from price_for(null, i.id, null) pf),
      'value', case when v_admin then coalesce(t.value, 0) end,
      'batches', coalesce(t.batches, '[]'::jsonb)
    ) order by i.name_generic), '[]'::jsonb)
  into v_items
  from item i
  left join store_item_level m on m.location_id = p_location_id and m.item_id = i.id
  left join lateral (
    select sum(s.quantity)::integer as on_hand,
           sum(s.quantity) filter (where s.expiry is null or s.expiry >= current_date)::integer as usable,
           sum(s.quantity) filter (where s.expiry < current_date)::integer as expired,
           sum(s.quantity) filter (where s.expiry between current_date and current_date + 90)::integer as expiring,
           min(s.expiry) filter (where s.expiry >= current_date) as next_expiry,
           sum(s.quantity * coalesce(b.unit_cost, 0)) as value,
           jsonb_agg(jsonb_build_object('batchId', s.batch_id, 'batchNo', b.batch_no, 'expiry', s.expiry,
                                        'quantity', s.quantity, 'expired', s.expiry < current_date,
                                        'unitCost', case when v_admin then b.unit_cost end)
                     order by s.expiry nulls last) as batches
    from stock_on_hand s left join batch b on b.id = s.batch_id
    where s.item_id = i.id and s.location_id = p_location_id and s.quantity > 0
  ) t on true
  where i.deleted_at is null and (t.on_hand is not null or m.min_level is not null);

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', t.id, 'number', t.number, 'direction', t.direction, 'sentAt', t.sent_at,
      'from', lf.name, 'to', lt.name,
      'lines', (select count(*) from stock_transfer_line x where x.transfer_id = t.id)::integer,
      'units', (select coalesce(sum(x.quantity), 0) from stock_transfer_line x where x.transfer_id = t.id)::integer
    ) order by t.sent_at), '[]'::jsonb)
  into v_incoming
  from stock_transfer t
  join stock_location lf on lf.id = t.from_location_id
  join stock_location lt on lt.id = t.to_location_id
  where t.status = 'in_transit' and (t.to_location_id = p_location_id or t.from_location_id = p_location_id);

  return jsonb_build_object(
    'store', jsonb_build_object('id', v_l.id, 'name', v_l.name, 'type', v_l.type, 'active', v_l.active,
                                'isMain', v_l.is_main, 'isRoom', is_room_type(v_l.type),
                                'holders', store_holders(v_l.id)),
    'held', holds_store(auth.uid(), v_l.id),
    -- count and write off: the holders (room store) or the pharmacy (pharmacy and main stores); the manager
    'canManage', is_manager() or case when is_room_type(v_l.type) then holds_store(auth.uid(), v_l.id)
                                       else stock_manager() end,
    'items', v_items,
    'onTheWay', v_incoming,
    'value', case when v_admin then (select coalesce(sum(s.quantity * coalesce(b.unit_cost, 0)), 0)
                                     from stock_on_hand s left join batch b on b.id = s.batch_id
                                     where s.location_id = p_location_id and s.quantity > 0) end
  );
end
$$;

-- ---------------------------------------------------------------- B reading what taking a payment needs
-- The visit's bill (visit_bill, visit_charges), the payments on it (paid, the receipt to reprint)
-- and the credit notes (refunds due) for anyone allowed to take payments; their own cash counts.
drop policy if exists invoice_select_taker on invoice;
create policy invoice_select_taker on invoice for select to authenticated
  using ((select has_perm('payment.take')));
drop policy if exists invoice_line_select_taker on invoice_line;
create policy invoice_line_select_taker on invoice_line for select to authenticated
  using ((select has_perm('payment.take')));
drop policy if exists payment_select_taker on payment;
create policy payment_select_taker on payment for select to authenticated
  using ((select has_perm('payment.take')));
drop policy if exists credit_note_select_taker on credit_note;
create policy credit_note_select_taker on credit_note for select to authenticated
  using ((select has_perm('payment.take')));
drop policy if exists day_close_select_own on day_close;
create policy day_close_select_own on day_close for select to authenticated
  using (cashier_id = (select auth.uid()));

-- ---------------------------------------------------------------- D the bookings to approve
drop policy if exists appointment_select_approver on appointment;
create policy appointment_select_approver on appointment for select to authenticated
  using ((select has_perm('appointment.approve')));

-- ---------------------------------------------------------------- rights
revoke all on function stock_manager() from public, anon;
grant execute on function stock_manager() to authenticated;
-- internal: only the checked functions call it
revoke all on function assert_stock_write() from public, anon, authenticated;


-- ============================================================ 20261129090000_handover.sql
-- 0088 · Hand one patient over to a colleague; "Cover for me" retired.
--
-- Frank: "for that to happen the patient must come to doctor X and when he feels like he wants
-- another doctor to cover for him and treat him, he sends through the system the patient to that
-- doctor to continue with him ... avoid any missing security".
--
--   * A  HAND OVER. The clinician who has the patient at a treating desk (taken by them, or sent to
--        them by name and not yet taken) picks a colleague who works at the same desk (serves the
--        section, uses the desk through their department or role, in the patient's department when
--        the patient was sent to one, may write clinical notes, active, not themselves) and writes
--        why and what is still to do. The colleague is told. Until they answer, the patient stays
--        with the sender, who keeps working and may cancel.
--   * B  TAKE. The colleague takes the patient: the queue entry becomes theirs (sent to and taken
--        by them), patients expected back by the sender (a test sent to the laboratory…) come back
--        to them, and a doctor becomes the visit's treating doctor when the sender was. The sender
--        loses the patient (unless they are in the visit for another reason: a task, a help
--        accepted). The sender is told. A patient at the laboratory or ultrasound whose result is
--        due back to the sender (return_to) is handed over too ("via return"): on Take only who
--        the patient comes back to moves. Result notices (and the way back without a return
--        asked) follow the handovers taken: result_recipient; "ordered by" stays.
--   * C  DECLINE, with a reason: nothing moves; the sender is told why.
--   * D  CANCEL: the sender (or the manager) withdraws a handover still waiting; the colleague is
--        told. A handover still waiting lapses by itself when the patient leaves the sender (sent
--        on, finished, taken by someone else), and ends when either colleague leaves the clinic
--        (deactivated or deleted); the other one is told. Every answer removes the colleague's
--        "hands over to you" notice.
--   * E  Everything is kept: patient_handover rows (who, when, the note, the answer, the reason)
--        with the audit trigger; the visit's track (visit_journey.handovers), the queue
--        (queue_board.handover_*), visit_access (canHandOver, handover), my_handovers().
--   * F  "COVER FOR ME" RETIRED (doctor and nurse cover). has_perm, may_use_desk and
--        queue_entry_for_me no longer look at clinician_cover; covering_for() is always null;
--        start_cover and end_cover refuse (hint cover_retired); my_cover() is empty; covers still
--        running end now; no new cover row can be written. The old rows stay readable (history).
--
-- Hints (the app translates them): handover_not_holder, handover_not_colleague, handover_note,
-- handover_reason, handover_pending, handover_not_yours, handover_gone, cover_retired,
-- not_permitted. Errcodes: 42501 not allowed, 22023 bad input, 23505 already done / changed,
-- P0002 not found.

-- ---------------------------------------------------------------- A the record
create table if not exists patient_handover (
  like mmc_base including all,
  encounter_id uuid not null references encounter (id),
  queue_id uuid not null references queue_entry (id),
  station station not null,
  -- true: the sender had no entry of their own at the desk but the patient was to come back to
  -- them (sent to the laboratory or ultrasound with the result due back): queue_id is that entry
  -- and only "who the patient comes back to" moves on Take
  via_return boolean not null default false,
  from_user uuid not null references profiles (id),
  to_user uuid not null references profiles (id),
  note text not null,
  -- pending → taken | declined | cancelled (by the sender or the manager) | lapsed (the patient left the sender)
  status text not null default 'pending'
    check (status in ('pending', 'taken', 'declined', 'cancelled', 'lapsed')),
  answered_at timestamptz,
  answered_by uuid references profiles (id),
  reason text,
  check (from_user <> to_user)
);
create unique index if not exists patient_handover_one_pending on patient_handover (queue_id)
  where status = 'pending' and deleted_at is null;
create index if not exists patient_handover_to_idx on patient_handover (to_user, status);
create index if not exists patient_handover_from_idx on patient_handover (from_user, status);
create index if not exists patient_handover_encounter_idx on patient_handover (encounter_id, created_at);
select install_common_triggers('patient_handover');

-- Read by the two colleagues, the manager and whoever reads clinical records (the queue badge,
-- the track); written through the functions below only.
alter table patient_handover enable row level security;
drop policy if exists patient_handover_read on patient_handover;
create policy patient_handover_read on patient_handover for select to authenticated
  using (from_user = auth.uid() or to_user = auth.uid() or is_manager() or has_perm('clinical.read'));
revoke insert, update, delete on patient_handover from anon, authenticated;
grant select on patient_handover to authenticated;

-- ---------------------------------------------------------------- F cover retired
-- The person's own rights only (the manager's exception first, else the role): no cover.
create or replace function has_perm(p_permission text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce((
    select sp.allowed from staff_permission sp
    join profiles me on me.id = sp.profile_id and me.active
    where sp.profile_id = auth.uid() and sp.permission = p_permission
  ), exists (
    select 1
    from profiles p
    join role_permissions rp on rp.role = p.role
    where p.id = auth.uid() and p.active and rp.permission = p_permission
  ))
$$;

-- Kept for the functions that still ask: nobody covers anyone any more.
create or replace function covering_for(p_user uuid)
returns uuid
language sql stable security definer set search_path = public
as $$
  select null::uuid
$$;

-- may_use_desk (from 20261126090000_departments_decide_desks): the person's own desks only.
create or replace function may_use_desk(p_desk text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select desk_via(auth.uid(), p_desk) is not null
$$;

-- queue_entry_for_me (from 20261112090000_sections_not_roles): without cover. A patient handed
-- over to me is mine only once I take them (take_handover).
create or replace function queue_entry_for_me(p_queue_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1
    from queue_entry q
    join profiles me on me.id = auth.uid() and me.active
    where q.id = p_queue_id and q.deleted_at is null
      and (
        me.role = 'manager'
        or me.id = q.assigned_to or me.id = q.taken_by or me.id = q.return_to
        -- sent to the section: anyone who works in it
        or (q.assigned_to is null and q.taken_by is null
            and serves_station(me.id, q.station, q.service)
            and (q.department_id is null
                 or me.department_id = q.department_id
                 or exists (select 1 from staff_department sd
                            where sd.profile_id = me.id and sd.department_id = q.department_id)))
      )
  )
$$;

create or replace function start_cover(
  p_nurse uuid,
  p_until timestamptz,
  p_note text default null,
  p_doctor uuid default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
begin
  raise exception 'cover is no longer used: hand the patient over to a colleague from the visit'
    using errcode = '42501', hint = 'cover_retired';
end
$$;

create or replace function end_cover(p_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  raise exception 'cover is no longer used: every cover has ended'
    using errcode = '42501', hint = 'cover_retired';
end
$$;

create or replace function my_cover()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object('covering', '[]'::jsonb, 'coveredBy', '[]'::jsonb)
$$;

-- Covers still running end now (patients an early version moved to the nurse go back).
do $$
declare
  v_id uuid;
begin
  for v_id in update clinician_cover set ended_at = now()
              where ended_at is null returning id loop
    perform give_back_covered(v_id);
  end loop;
end
$$;

-- No new cover row, whoever writes it.
create or replace function clinician_cover_retired()
returns trigger
language plpgsql
as $$
begin
  raise exception 'cover is no longer used: hand the patient over to a colleague from the visit'
    using errcode = '42501', hint = 'cover_retired';
end
$$;
drop trigger if exists trg_cover_retired on clinician_cover;
create trigger trg_cover_retired before insert on clinician_cover
  for each row execute function clinician_cover_retired();

-- ---------------------------------------------------------------- A who may hand over, to whom
-- The open queue entry by which this person has the patient: first an entry at a treating desk
-- taken by them, or sent to them by name and not taken yet (the latest one); else an open entry
-- elsewhere that brings the patient back to them (at the laboratory or ultrasound, the result
-- due back to them: return_to).
create or replace function handover_held_queue(p_encounter_id uuid, p_user uuid)
returns uuid
language sql stable security definer set search_path = public
as $$
  select x.id from (
    select q.id, 0 as rank, q.created_at
    from queue_entry q
    where q.encounter_id = p_encounter_id and q.finished_at is null and q.deleted_at is null
      and exists (select 1 from unnest(station_desks(q.station)) as d(desk) where d.desk = any (treating_desks()))
      and (q.taken_by = p_user or (q.taken_by is null and q.assigned_to = p_user))
    union all
    select q.id, 1 as rank, q.created_at
    from queue_entry q
    where q.encounter_id = p_encounter_id and q.finished_at is null and q.deleted_at is null
      and q.return_to = p_user
  ) x
  join encounter e on e.id = p_encounter_id and e.status = 'open' and e.deleted_at is null
  where p_user is not null
  order by x.rank, x.created_at desc
  limit 1
$$;

-- Does the person have the patient by this entry itself (taken, or sent to them by name), or only
-- because the patient comes back to them (return_to)?
create or replace function handover_via_return(p_queue_id uuid, p_user uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select not coalesce((select q.taken_by = p_user or (q.taken_by is null and q.assigned_to = p_user)
                       from queue_entry q where q.id = p_queue_id), false)
$$;

-- The desk the handover is about: the entry's own desk, or (via return) the treating desk the
-- patient comes back to, with the service and department of the sender's entry there.
create or replace function handover_desk(p_queue_id uuid, p_return boolean)
returns table (station station, service text, department_id uuid)
language sql stable security definer set search_path = public
as $$
  select q.station, q.service, q.department_id
  from queue_entry q where q.id = p_queue_id and not p_return
  union all
  select coalesce(q.return_station, x.station), x.service, x.department_id
  from queue_entry q
  left join lateral (
    select x.station, x.service, x.department_id from queue_entry x
    where x.encounter_id = q.encounter_id and x.id <> q.id and x.deleted_at is null
      and (x.taken_by = q.return_to or x.assigned_to = q.return_to)
      and (q.return_station is null or x.station = q.return_station)
      and exists (select 1 from unnest(station_desks(x.station)) as d(desk) where d.desk = any (treating_desks()))
    order by x.created_at desc limit 1) x on true
  where q.id = p_queue_id and p_return
$$;

-- Does this colleague work where the patient is? Active, may write clinical notes, serves the
-- section (staff_serves), uses the desk (their department, or their role while no department
-- gives it; the manager's "not allowed" takes it away), and is in the patient's department when
-- the patient was sent to one.
create or replace function handover_colleague_ok(p_queue_id uuid, p_user uuid, p_return boolean default false)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1
    from handover_desk(p_queue_id, p_return) k
    join profiles y on y.id = p_user and y.active and y.deleted_at is null
    where k.station is not null
      and staff_perm(y.id, 'clinical.write')
      and serves_station(y.id, k.station, k.service)
      and exists (select 1 from unnest(station_desks(k.station)) as d(desk)
                  where d.desk = any (treating_desks())
                    and (k.service is null or not (k.service = any (station_desks(k.station)))
                         or d.desk = k.service)
                    and desk_via(y.id, d.desk) is not null)
      and (k.department_id is null
           or y.department_id = k.department_id
           or exists (select 1 from staff_department sd
                      where sd.profile_id = y.id and sd.department_id = k.department_id))
  )
$$;

-- One handover as the screens show it.
create or replace function handover_json(h patient_handover)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'id', h.id, 'status', h.status, 'encounterId', h.encounter_id, 'queueId', h.queue_id,
    'station', h.station, 'service', q.service,
    'patientId', p.id, 'name', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
    'ticket', q.ticket_no,
    'fromId', h.from_user, 'fromName', f.full_name, 'toId', h.to_user, 'toName', t.full_name,
    'note', h.note, 'at', h.created_at, 'answeredAt', h.answered_at,
    'answeredBy', (select full_name from profiles where id = h.answered_by), 'reason', h.reason)
  from encounter e
  join patient p on p.id = e.patient_id
  join queue_entry q on q.id = h.queue_id
  join profiles f on f.id = h.from_user
  join profiles t on t.id = h.to_user
  where e.id = h.encounter_id
$$;

-- ---------------------------------------------------------------- A the colleagues to choose from
create or replace function handover_colleagues(p_encounter_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_qid uuid := handover_held_queue(p_encounter_id, auth.uid());
  v_return boolean;
begin
  if v_qid is null or not exists (select 1 from profiles where id = auth.uid() and active) then
    raise exception 'only the clinician who has the patient can hand them over'
      using errcode = '42501', hint = 'handover_not_holder';
  end if;
  v_return := handover_via_return(v_qid, auth.uid());
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', y.id, 'name', y.full_name, 'role', y.role, 'station', y.station,
             'specialty', y.specialty,
             -- patients they have now (taken, not finished)
             'patients', (select count(*) from queue_entry q2
                          join encounter e2 on e2.id = q2.encounter_id and e2.status = 'open'
                          where q2.taken_by = y.id and q2.finished_at is null and q2.deleted_at is null))
           order by y.full_name)
    from profiles y
    where y.id <> auth.uid() and y.active and y.deleted_at is null
      and handover_colleague_ok(v_qid, y.id, v_return)), '[]'::jsonb);
end
$$;

-- ---------------------------------------------------------------- A hand over
create or replace function handover_patient(p_encounter_id uuid, p_to uuid, p_note text)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_me text;
  v_qid uuid;
  v_q queue_entry%rowtype;
  v_note text := nullif(trim(coalesce(p_note, '')), '');
  v_id uuid;
  v_name text;
  v_return boolean;
  v_station station;
begin
  select full_name into v_me from profiles where id = auth.uid() and active;
  if v_me is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not has_perm('clinical.write') then
    raise exception 'you may not hand patients over (the manager has not allowed it)'
      using errcode = '42501', hint = 'not_permitted';
  end if;
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open' and deleted_at is null) then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  v_qid := handover_held_queue(p_encounter_id, auth.uid());
  if v_qid is null then
    raise exception 'only the clinician who has the patient can hand them over'
      using errcode = '42501', hint = 'handover_not_holder';
  end if;
  select * into v_q from queue_entry where id = v_qid for update;
  v_return := handover_via_return(v_qid, auth.uid());
  select k.station into v_station from handover_desk(v_qid, v_return) k;
  if v_note is null or length(v_note) < 3 then
    raise exception 'say why you hand the patient over and what is still to do'
      using errcode = '22023', hint = 'handover_note';
  end if;
  if length(v_note) > 1000 then
    raise exception 'the note is too long (1000 characters at most)' using errcode = '22023', hint = 'handover_note';
  end if;
  if p_to is null or p_to = auth.uid() or v_station is null
     or not handover_colleague_ok(v_qid, p_to, v_return) then
    raise exception 'choose an active colleague who works at this desk'
      using errcode = '42501', hint = 'handover_not_colleague';
  end if;
  if exists (select 1 from patient_handover
             where queue_id = v_qid and status = 'pending' and deleted_at is null) then
    raise exception 'this patient is already being handed over: cancel that first'
      using errcode = '23505', hint = 'handover_pending';
  end if;
  insert into patient_handover (encounter_id, queue_id, station, via_return, from_user, to_user, note)
  values (p_encounter_id, v_qid, v_station, v_return, auth.uid(), p_to, v_note)
  returning id into v_id;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = p_encounter_id;
  insert into notification (kind, params, link, recipient_user, urgent, created_by)
  values ('handover',
          jsonb_build_object('handover', v_id, 'by', v_me, 'name', v_name, 'ticket', v_q.ticket_no,
                             'station', v_station, 'note', v_note),
          '/app/visit?encounter=' || p_encounter_id, p_to, true, auth.uid());
  return v_id;
end
$$;

-- ---------------------------------------------------------------- B take
create or replace function take_handover(p_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_me text;
  v_h patient_handover%rowtype;
  v_q queue_entry%rowtype;
  v_name text;
  v_from_name text;
  v_qid uuid;
begin
  select full_name into v_me from profiles where id = auth.uid() and active;
  if v_me is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  -- Lock the queue entry before the handover, in the order of a queue change (whose trigger
  -- handover_follow_queue then updates the handover): no deadlock between the two.
  select queue_id into v_qid from patient_handover where id = p_id and deleted_at is null;
  if v_qid is null then
    raise exception 'handover not found' using errcode = 'P0002', hint = 'handover_gone';
  end if;
  select * into v_q from queue_entry where id = v_qid for update;
  select * into v_h from patient_handover where id = p_id and deleted_at is null for update;
  if not found then
    raise exception 'handover not found' using errcode = 'P0002', hint = 'handover_gone';
  end if;
  if v_h.to_user <> auth.uid() then
    raise exception 'this patient was not handed over to you' using errcode = '42501', hint = 'handover_not_yours';
  end if;
  if v_h.status <> 'pending' then
    raise exception 'this handover is no longer waiting (%)', v_h.status using errcode = '23505', hint = 'handover_gone';
  end if;
  if not has_perm('clinical.write') then
    raise exception 'you may not take patients over (the manager has not allowed it)'
      using errcode = '42501', hint = 'not_permitted';
  end if;
  select full_name into v_from_name from profiles where id = v_h.from_user;
  if v_q.finished_at is not null or v_q.deleted_at is not null
     or (v_h.via_return and v_q.return_to is distinct from v_h.from_user)
     or (not v_h.via_return
         and not coalesce(v_q.taken_by = v_h.from_user
                          or (v_q.taken_by is null and v_q.assigned_to = v_h.from_user), false)) then
    raise exception 'the patient is no longer with %', coalesce(v_from_name, 'the colleague')
      using errcode = '23505', hint = 'handover_gone';
  end if;
  if not handover_colleague_ok(v_q.id, auth.uid(), v_h.via_return) then
    raise exception 'you no longer work at this desk' using errcode = '42501', hint = 'handover_not_colleague';
  end if;
  -- the answer first, so the queue change below does not count as the patient leaving the sender
  update patient_handover set status = 'taken', answered_at = now(), answered_by = auth.uid()
  where id = p_id;
  -- the notice "X hands … over to you" has been answered
  delete from notification where kind = 'handover' and params ->> 'handover' = p_id::text;
  if not v_h.via_return then
    if v_q.pool_id is not null then
      perform 1 from queue_entry where pool_id = v_q.pool_id for update;
    end if;
    update queue_entry
    set assigned_to = auth.uid(), taken_by = auth.uid(),
        called_at = coalesce(called_at, now()), started_at = coalesce(started_at, now())
    where id = v_q.id;
    if v_q.pool_id is not null then
      update queue_entry set finished_at = now()
      where pool_id = v_q.pool_id and id <> v_q.id and finished_at is null;
    end if;
    -- the change of hands above is not a new referral (trg_notify_referral_update would tell me
    -- the patient was "sent" to me by the triage or reception, with their old note)
    delete from notification where kind in ('queue', 'referral') and params ->> 'queue' = v_q.id::text;
  end if;
  -- patients expected back by the sender come back to me (via return: this is the handover;
  -- the laboratory or ultrasound entry itself stays with whoever does the test)
  update queue_entry set return_to = auth.uid()
  where encounter_id = v_q.encounter_id and return_to = v_h.from_user
    and finished_at is null and deleted_at is null;
  -- the treating doctor of the visit, when it was the sender (or nobody yet)
  if current_role_key() = 'doctor' then
    update encounter set practitioner_id = ensure_practitioner(auth.uid())
    where id = v_q.encounter_id
      and (practitioner_id is null
           or practitioner_id in (select id from practitioner where user_id = v_h.from_user));
  end if;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = v_q.encounter_id;
  insert into notification (kind, params, link, recipient_user, urgent, created_by)
  values ('handover_answer',
          jsonb_build_object('handover', p_id, 'taken', true, 'by', v_me, 'name', v_name,
                             'ticket', v_q.ticket_no),
          '/app/visit?encounter=' || v_q.encounter_id, v_h.from_user, false, auth.uid());
  return jsonb_build_object('encounterId', v_q.encounter_id, 'queueId', v_q.id, 'station', v_q.station);
end
$$;

-- ---------------------------------------------------------------- C decline
create or replace function decline_handover(p_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_me text;
  v_h patient_handover%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_name text;
  v_ticket text;
begin
  select full_name into v_me from profiles where id = auth.uid() and active;
  if v_me is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_h from patient_handover where id = p_id and deleted_at is null for update;
  if not found then
    raise exception 'handover not found' using errcode = 'P0002', hint = 'handover_gone';
  end if;
  if v_h.to_user <> auth.uid() then
    raise exception 'this patient was not handed over to you' using errcode = '42501', hint = 'handover_not_yours';
  end if;
  if v_h.status <> 'pending' then
    raise exception 'this handover is no longer waiting (%)', v_h.status using errcode = '23505', hint = 'handover_gone';
  end if;
  if v_reason is null or length(v_reason) < 3 then
    raise exception 'say why you cannot take the patient' using errcode = '22023', hint = 'handover_reason';
  end if;
  update patient_handover
  set status = 'declined', answered_at = now(), answered_by = auth.uid(), reason = left(v_reason, 1000)
  where id = p_id;
  delete from notification where kind = 'handover' and params ->> 'handover' = p_id::text;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = v_h.encounter_id;
  select ticket_no into v_ticket from queue_entry where id = v_h.queue_id;
  insert into notification (kind, params, link, recipient_user, urgent, created_by)
  values ('handover_answer',
          jsonb_build_object('handover', p_id, 'taken', false, 'by', v_me, 'name', v_name,
                             'ticket', v_ticket, 'reason', left(v_reason, 1000)),
          '/app/visit?encounter=' || v_h.encounter_id, v_h.from_user, true, auth.uid());
end
$$;

-- ---------------------------------------------------------------- D cancel
create or replace function cancel_handover(p_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_me text;
  v_h patient_handover%rowtype;
  v_name text;
  v_ticket text;
begin
  select full_name into v_me from profiles where id = auth.uid() and active;
  if v_me is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_h from patient_handover where id = p_id and deleted_at is null for update;
  if not found then
    raise exception 'handover not found' using errcode = 'P0002', hint = 'handover_gone';
  end if;
  if v_h.from_user <> auth.uid() and not is_manager() then
    raise exception 'only the colleague who handed the patient over can cancel it'
      using errcode = '42501', hint = 'handover_not_yours';
  end if;
  if v_h.status <> 'pending' then
    raise exception 'this handover is no longer waiting (%)', v_h.status using errcode = '23505', hint = 'handover_gone';
  end if;
  update patient_handover set status = 'cancelled', answered_at = now(), answered_by = auth.uid()
  where id = p_id;
  -- the colleague's notice "X hands … over to you" goes; the cancel notice below replaces it
  delete from notification where kind = 'handover' and params ->> 'handover' = p_id::text;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = v_h.encounter_id;
  select ticket_no into v_ticket from queue_entry where id = v_h.queue_id;
  insert into notification (kind, params, link, recipient_user, urgent, created_by)
  values ('handover_cancelled',
          jsonb_build_object('handover', p_id, 'by', v_me, 'name', v_name, 'ticket', v_ticket),
          '/app/visit?encounter=' || v_h.encounter_id, v_h.to_user, false, auth.uid());
  -- the manager cancelled it: the sender is told too
  if v_h.from_user <> auth.uid() then
    insert into notification (kind, params, link, recipient_user, urgent, created_by)
    values ('handover_cancelled',
            jsonb_build_object('handover', p_id, 'by', v_me, 'name', v_name, 'ticket', v_ticket),
            '/app/visit?encounter=' || v_h.encounter_id, v_h.from_user, false, auth.uid());
  end if;
end
$$;

-- ---------------------------------------------------------------- D lapse: the patient left the sender
create or replace function handover_follow_queue()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  r record;
begin
  for r in
    update patient_handover h
    set status = 'lapsed', answered_at = now()
    where h.queue_id = new.id and h.status = 'pending' and h.deleted_at is null
      and (new.finished_at is not null or new.deleted_at is not null
           or (h.via_return and new.return_to is distinct from h.from_user)
           or (not h.via_return
               and not coalesce(new.taken_by = h.from_user
                                or (new.taken_by is null and new.assigned_to = h.from_user), false)))
    returning h.id, h.to_user, h.from_user, h.encounter_id
  loop
    -- the colleague's notice goes, and they are told the patient moved on
    delete from notification where kind = 'handover' and params ->> 'handover' = r.id::text;
    insert into notification (kind, params, link, recipient_user, urgent, created_by)
    select 'handover_cancelled',
           jsonb_build_object('handover', r.id, 'by', f.full_name,
                              'name', p.surname || ' ' || p.given_names, 'ticket', new.ticket_no,
                              'lapsed', true),
           '/app/visit?encounter=' || r.encounter_id, r.to_user, false, auth.uid()
    from encounter e
    join patient p on p.id = e.patient_id
    join profiles f on f.id = r.from_user
    where e.id = r.encounter_id;
  end loop;
  return null;
end
$$;
drop trigger if exists trg_handover_follow on queue_entry;
create trigger trg_handover_follow
  after update of finished_at, deleted_at, taken_by, assigned_to, return_to on queue_entry
  for each row execute function handover_follow_queue();

-- A colleague who leaves the clinic (deactivated, or deleted: retire_staff deactivates too): the
-- handovers still waiting from or to them end, and the other colleague is told.
create or replace function handover_follow_profile()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  r record;
begin
  for r in
    update patient_handover h
    set status = 'cancelled', answered_at = now(), answered_by = auth.uid(),
        reason = 'colleague no longer works here'
    where h.status = 'pending' and h.deleted_at is null
      and (h.from_user = new.id or h.to_user = new.id)
    returning h.id, h.to_user, h.from_user, h.encounter_id, h.queue_id
  loop
    delete from notification where kind = 'handover' and params ->> 'handover' = r.id::text;
    insert into notification (kind, params, link, recipient_user, urgent, created_by)
    select 'handover_cancelled',
           jsonb_build_object('handover', r.id, 'by', f.full_name,
                              'name', p.surname || ' ' || p.given_names, 'ticket', q.ticket_no,
                              'left', true, 'toName', t.full_name,
                              'leftName', case when r.from_user = new.id then f.full_name else t.full_name end),
           '/app/visit?encounter=' || r.encounter_id,
           case when r.from_user = new.id then r.to_user else r.from_user end, true, auth.uid()
    from encounter e
    join patient p on p.id = e.patient_id
    join profiles f on f.id = r.from_user
    join profiles t on t.id = r.to_user
    left join queue_entry q on q.id = r.queue_id
    where e.id = r.encounter_id;
  end loop;
  return null;
end
$$;
drop trigger if exists trg_handover_follow_profile on profiles;
create trigger trg_handover_follow_profile
  after update of active on profiles
  for each row when (old.active and not new.active)
  execute function handover_follow_profile();

-- ---------------------------------------------------------------- E my handovers
--   incoming  patients handed over to me, waiting for my answer;
--   outgoing  my handovers still waiting, and those answered in the last 12 hours.
create or replace function my_handovers()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'incoming', coalesce((
      select jsonb_agg(handover_json(h) order by h.created_at)
      from patient_handover h
      where h.to_user = auth.uid() and h.status = 'pending' and h.deleted_at is null), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(handover_json(h) order by h.created_at desc)
      from patient_handover h
      where h.from_user = auth.uid() and h.deleted_at is null
        and (h.status = 'pending' or h.answered_at > now() - interval '12 hours')), '[]'::jsonb)
  )
  where exists (select 1 from profiles where id = auth.uid() and active)
$$;

-- ---------------------------------------------------------------- E the visit page
-- visit_access (from 20261101180000_patients_belong_calls) + canHandOver and the handover waiting.
create or replace function visit_access(p_encounter_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'canWork', may_work_on(p_encounter_id),
    'canRoute', may_route(p_encounter_id),
    'holder', patient_holder(p_encounter_id),
    'helping', exists (select 1 from staff_call c
                       where c.encounter_id = p_encounter_id and c.kind = 'help'
                         and c.status = 'accepted' and c.answered_by = auth.uid()),
    'help', coalesce((
      select jsonb_agg(jsonb_build_object(
               'callId', c.id, 'status', c.status, 'asker', a.full_name,
               'helper', coalesce(h.full_name, t.full_name), 'mine', c.from_user = auth.uid(),
               'helperIsMe', c.answered_by = auth.uid(),
               'note', c.note) order by c.created_at)
      from staff_call c
      join profiles a on a.id = c.from_user
      left join profiles h on h.id = c.answered_by
      left join profiles t on t.id = c.to_user
      where c.encounter_id = p_encounter_id and c.kind = 'help' and c.status in ('open', 'accepted')), '[]'::jsonb),
    -- 0088: I have the patient at a treating desk and may hand them over
    'canHandOver', handover_held_queue(p_encounter_id, auth.uid()) is not null and has_perm('clinical.write'),
    -- 0088: the handover waiting for an answer on this visit (to me, from me, or anyone's for
    -- those who read clinical records: the note is clinical)
    'handover', (
      select handover_json(h) || jsonb_build_object('mine', h.from_user = auth.uid(), 'forMe', h.to_user = auth.uid())
      from patient_handover h
      where h.encounter_id = p_encounter_id and h.status = 'pending' and h.deleted_at is null
        and (h.from_user = auth.uid() or h.to_user = auth.uid() or has_perm('clinical.read'))
      order by h.created_at desc limit 1)
  )
  where exists (select 1 from profiles where id = auth.uid() and active)
$$;

-- queue_board (from 20261112090000_sections_not_roles): + the latest handover of the entry
-- (waiting or taken); a patient handed over to me counts as mine to look at (for_me) though I
-- work on them only once I take them (can_work).
create or replace view queue_board with (security_invoker = true) as
  select q.id as queue_id, q.encounter_id, q.station, q.ticket_no, q.priority,
         q.created_at as queued_at, q.called_at, q.started_at, q.finished_at,
         e.patient_id, e.triage_level, e.arrived_at, e.type as encounter_type,
         p.file_number, p.surname, p.given_names, p.sex, p.birth_date, p.phone_1,
         q.pool_id, tb.full_name as taken_by_name,
         q.assigned_to, asg.full_name as assigned_name, rb.full_name as referred_by_name,
         q.referral_note, q.return_station,
         v.effective_at as vitals_at, v.measured_by as vitals_by,
         q.department_id, dep.name as department_name, queue_entry_for_me(q.id) as can_work,
         q.taken_by, coalesce(q.service, e.service) as service,
         (q.assigned_to = auth.uid() or q.taken_by = auth.uid()
          or (q.assigned_to is null and q.taken_by is null
              and serves_station(auth.uid(), q.station, q.service))
          or coalesce(ho.status = 'pending' and ho.to_user = auth.uid(), false)) as for_me,
         ho.id as handover_id, ho.status as handover_status,
         ho.from_user as handover_from, hf.full_name as handover_from_name,
         ho.to_user as handover_to, ht.full_name as handover_to_name,
         ho.note as handover_note, ho.created_at as handover_at, ho.answered_at as handover_answered_at
  from queue_entry q
  join encounter e on e.id = q.encounter_id
  join patient p on p.id = e.patient_id
  left join profiles tb on tb.id = q.taken_by
  left join profiles asg on asg.id = q.assigned_to
  left join profiles rb on rb.id = q.referred_by
  left join department dep on dep.id = q.department_id
  left join lateral last_vitals_stamp(q.encounter_id) v on true
  left join lateral (select h.* from patient_handover h
                     where h.queue_id = q.id and h.status in ('pending', 'taken') and h.deleted_at is null
                     order by h.created_at desc limit 1) ho on true
  left join profiles hf on hf.id = ho.from_user
  left join profiles ht on ht.id = ho.to_user
  where q.deleted_at is null and e.status = 'open';

-- visit_journey (from 20261123090000_dispensing_fixes): + the handovers of the visit.
create or replace function visit_journey(p_encounter_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_steps jsonb;
  v_vitals jsonb;
  v_dx jsonb;
  v_meds jsonb;
  v_tests jsonb;
  v_charges jsonb;
  v_payments jsonb;
  v_bill jsonb;
  v_handovers jsonb;
  v_clinical boolean := has_perm('clinical.read');
  v_enc encounter%rowtype;
begin
  if not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_enc from encounter where id = p_encounter_id and deleted_at is null;
  if not found then
    raise exception 'visit not found' using errcode = 'P0002';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'station', q.station, 'queuedAt', q.created_at, 'calledAt', q.called_at, 'startedAt', q.started_at,
      'finishedAt', q.finished_at, 'takenBy', tb.full_name, 'assignedTo', asg.full_name,
      'referredBy', rb.full_name, 'note', q.referral_note, 'enteredBy', eb.full_name,
      'service', q.service, 'department', (select d.name from department d where d.id = q.department_id)
    ) order by q.created_at), '[]'::jsonb) into v_steps
  from queue_entry q
  left join profiles tb on tb.id = q.taken_by
  left join profiles asg on asg.id = q.assigned_to
  left join profiles rb on rb.id = q.referred_by
  left join profiles eb on eb.id = q.entered_by
  where q.encounter_id = p_encounter_id and q.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'code', o.code, 'value', o.value_num, 'unit', o.unit, 'at', o.effective_at,
      'by', (select full_name from profiles where id = o.performer_id)
    ) order by o.effective_at), '[]'::jsonb) into v_vitals
  from observation o where o.encounter_id = p_encounter_id and o.deleted_at is null and o.code <> 'note';

  select coalesce(jsonb_agg(jsonb_build_object(
      'text', c.text, 'icd10', c.icd10_code, 'type', c.type, 'provisional', c.provisional, 'at', c.created_at,
      'by', (select full_name from profiles where id = c.created_by)
    ) order by c.created_at), '[]'::jsonb) into v_dx
  from condition c where c.encounter_id = p_encounter_id and c.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'item', i.name_generic || coalesce(' ' || i.strength, ''), 'quantity', m.quantity, 'dose', m.dose,
      'frequency', m.frequency, 'days', m.duration_days, 'supply', m.supply, 'givenAt', m.given_at,
      'givenBy', (select full_name from profiles where id = m.given_by), 'at', m.created_at,
      'by', (select full_name from profiles where id = m.created_by),
      'dispensed', exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null),
      'notGivenAt', m.not_given_at, 'notGivenReason', m.not_given_reason,
      'notGivenBy', (select full_name from profiles where id = m.not_given_by),
      'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
      'cancelledBy', (select full_name from profiles where id = m.cancelled_by)
    ) order by m.created_at), '[]'::jsonb) into v_meds
  from medication_request m join item i on i.id = m.item_id
  where m.encounter_id = p_encounter_id and m.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'test', s.name_en, 'status', r.status, 'priority', r.priority, 'at', r.created_at,
      'by', (select full_name from profiles where id = r.created_by),
      'result', (select coalesce(dr.impression, dr.findings) from diagnostic_report dr where dr.service_request_id = r.id and dr.deleted_at is null order by dr.created_at desc limit 1)
    ) order by r.created_at), '[]'::jsonb) into v_tests
  from service_request r left join service s on s.id = r.service_id
  where r.encounter_id = p_encounter_id and r.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'description', l.description, 'quantity', l.quantity, 'unitPrice', l.unit_price,
      'total', round(l.quantity * l.unit_price), 'office', l.office, 'at', l.created_at,
      'by', (select full_name from profiles where id = l.entered_by)
    ) order by l.created_at), '[]'::jsonb) into v_charges
  from invoice_line l join invoice i on i.id = l.invoice_id
  where i.encounter_id = p_encounter_id and l.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'amount', p.amount, 'method', p.method, 'reference', p.reference, 'at', p.paid_at,
      'by', (select full_name from profiles where id = p.cashier_id)
    ) order by p.paid_at), '[]'::jsonb) into v_payments
  from payment p join invoice i on i.id = p.invoice_id
  where i.encounter_id = p_encounter_id and p.deleted_at is null;

  select jsonb_build_object('status', b.status, 'total', b.total, 'balance', b.balance, 'paid', b.paid,
                            'number', b.number, 'settledBy', b.settled_by, 'settledAt', b.settled_at)
  into v_bill from visit_bill b where b.encounter_id = p_encounter_id;

  -- 0088: who handed the patient over to whom, when, why, and the answer (the note and the
  -- reason are clinical: for the two colleagues and those who read clinical records)
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', h.id, 'station', h.station, 'at', h.created_at, 'from', f.full_name, 'to', t.full_name,
      'note', case when v_clinical or auth.uid() in (h.from_user, h.to_user) then h.note end,
      'status', h.status, 'answeredAt', h.answered_at,
      'answeredBy', (select full_name from profiles where id = h.answered_by),
      'reason', case when v_clinical or auth.uid() in (h.from_user, h.to_user) then h.reason end
    ) order by h.created_at), '[]'::jsonb) into v_handovers
  from patient_handover h
  join profiles f on f.id = h.from_user
  join profiles t on t.id = h.to_user
  where h.encounter_id = p_encounter_id and h.deleted_at is null;

  return jsonb_build_object(
    'encounterId', v_enc.id, 'arrivedAt', v_enc.arrived_at, 'status', v_enc.status, 'closedAt', v_enc.closed_at,
    'triage', v_enc.triage_level, 'triageReason', v_enc.triage_reason,
    'closedBy', (select full_name from profiles where id = v_enc.closed_by),
    -- the track: treatment finished, why the patient left, what they came for
    'treatmentDoneAt', v_enc.clinical_done_at, 'leftReason', v_enc.left_reason, 'service', v_enc.service,
    'steps', v_steps, 'vitals', v_vitals, 'diagnoses', v_dx, 'medicines', v_meds, 'tests', v_tests,
    'charges', v_charges, 'payments', v_payments, 'bill', v_bill, 'handovers', v_handovers
  );
end
$$;

-- ---------------------------------------------------------------- B results follow the handover
-- Who is told about a test result (and who the patient goes back to without a return asked):
-- the person who ordered it, or the colleague they handed the patient over to and who took them
-- (and so on, each handover taken after the one before). service_request.requester_id stays as
-- it is: "ordered by" is history.
create or replace function result_recipient(p_encounter uuid, p_requester uuid)
returns uuid
language plpgsql stable security definer set search_path = public
as $$
declare
  v_user uuid := p_requester;
  v_at timestamptz := '-infinity';
  v_next uuid;
  v_next_at timestamptz;
  v_hops integer := 0;
begin
  while v_user is not null and v_hops < 20 loop
    select h.to_user, h.answered_at into v_next, v_next_at
    from patient_handover h
    where h.encounter_id = p_encounter and h.from_user = v_user and h.status = 'taken'
      and h.deleted_at is null and h.answered_at > v_at
    order by h.answered_at
    limit 1;
    exit when v_next is null;
    v_user := v_next;
    v_at := v_next_at;
    v_next := null;
    v_hops := v_hops + 1;
  end loop;
  return v_user;
end
$$;

-- record_result (from 20261128090000_switches_enforced): the result notice goes to whoever
-- has the patient now (result_recipient).
create or replace function record_result(
  p_request_id uuid,
  p_findings text,
  p_impression text,
  p_verify boolean default true
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_test text;
  v_name text;
  v_station station;
  v_q queue_entry%rowtype;
  v_tests text;
  v_to uuid;
begin
  select * into v_req from service_request where id = p_request_id and deleted_at is null;
  if not found then
    raise exception 'test order not found' using errcode = 'P0002';
  end if;
  -- Lab / ultrasound results: lab staff and clinicians who order; an order done at another desk
  -- (Nursing, Dental…): the clinical staff of that desk too.
  if not ((may_use_desk(request_desk(v_req.station, v_req.category))
               and (request_desk(v_req.station, v_req.category) not in ('laboratory', 'ultrasound')
                    or has_perm('orders.write')))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    if may_use_desk(request_desk(v_req.station, v_req.category)) and not has_perm('orders.write') then
      raise exception 'you may not work on tests (the manager has not allowed it)'
        using errcode = '42501', hint = 'not_permitted';
    end if;
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_req.status = 'cancelled' then
    raise exception 'this test was marked "not done": order it again if it is done after all' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_findings, '')), '') is null and nullif(trim(coalesce(p_impression, '')), '') is null then
    raise exception 'write the findings or the conclusion' using errcode = '22023';
  end if;
  if exists (select 1 from diagnostic_report where service_request_id = p_request_id
             and deleted_at is null and verified_at is not null) then
    raise exception 'this result is verified: correct it, giving the reason' using errcode = '22023';
  end if;
  insert into diagnostic_report (service_request_id, findings, impression, verified_by, verified_at)
  values (p_request_id, nullif(trim(coalesce(p_findings, '')), ''), nullif(trim(coalesce(p_impression, '')), ''),
          case when p_verify then auth.uid() end, case when p_verify then now() end)
  on conflict (service_request_id) do update
  set findings = excluded.findings, impression = excluded.impression,
      verified_by = excluded.verified_by, verified_at = excluded.verified_at, updated_at = now();
  update service_request set status = case when p_verify then 'verified'::request_status else 'resulted'::request_status end
  where id = p_request_id;
  -- Tell the doctor who ordered it (0088: or the colleague they handed the patient over to).
  v_to := result_recipient(v_req.encounter_id, v_req.requester_id);
  if v_to is not null and v_to is distinct from auth.uid() then
    select s.name_en into v_test from service s where s.id = v_req.service_id;
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('result',
            jsonb_build_object('test', v_test, 'name', v_name,
                               'impression', nullif(trim(coalesce(p_impression, '')), ''),
                               'verified', p_verify),
            '/app/visit?encounter=' || v_req.encounter_id,
            v_to, auth.uid());
  end if;
  -- Last result of this desk written: the patient goes back to the doctor.
  v_station := coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end);
  perform after_desk_tests(v_req.encounter_id, v_station, v_req.requester_id);
end
$$;


-- set_request_status (from 20261128090000_switches_enforced): "test not done" goes to whoever
-- has the patient now (result_recipient).
create or replace function set_request_status(p_id uuid, p_status request_status, p_reason text default null)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_test text;
  v_name text;
  v_line uuid;
  v_invoice uuid;
  v_to uuid;
begin
  select * into v_req from service_request where id = p_id;
  -- the lab and imaging (orders.write); an order done at another desk (Nursing, Dental…): the
  -- clinical staff of that desk too
  if not ((may_use_desk(request_desk(v_req.station, v_req.category))
               and (request_desk(v_req.station, v_req.category) not in ('laboratory', 'ultrasound')
                    or has_perm('orders.write')))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    if may_use_desk(request_desk(v_req.station, v_req.category)) and not has_perm('orders.write') then
      raise exception 'you may not work on tests (the manager has not allowed it)'
        using errcode = '42501', hint = 'not_permitted';
    end if;
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_status not in ('collected', 'in_process', 'cancelled') then
    raise exception 'use record_result for results' using errcode = '22023';
  end if;
  if p_status = 'cancelled' and nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'a reason is required to cancel a test' using errcode = '22023';
  end if;
  update service_request
  set status = p_status,
      reason = case when p_status = 'cancelled' then coalesce(reason || ' · ', '') || 'cancelled: ' || trim(p_reason) else reason end
  where id = p_id and deleted_at is null and status not in ('verified', 'cancelled');
  if not found then
    raise exception 'test not found or already finished' using errcode = 'P0002';
  end if;
  -- sample taken / analysing: the patient is being seen at that desk
  if p_status in ('collected', 'in_process') then
    update queue_entry q set started_at = coalesce(q.started_at, now()), called_at = coalesce(q.called_at, now()),
                             taken_by = coalesce(q.taken_by, auth.uid())
    where q.encounter_id = v_req.encounter_id and q.finished_at is null and q.deleted_at is null
      and q.station = coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end);
  end if;
  if p_status = 'cancelled' then
    select * into v_req from service_request where id = p_id;
    -- not done, not paid: its charge leaves the bill while the bill is open
    update invoice_line l
    set deleted_at = now(), manual_reason = coalesce(l.manual_reason || ' · ', '') || 'removed: test not done: ' || trim(p_reason)
    from invoice i
    where l.source_type = 'service_request' and l.source_id = p_id and l.deleted_at is null
      and i.id = l.invoice_id and i.status = 'draft'
    returning l.id, l.invoice_id into v_line, v_invoice;
    if v_invoice is not null then
      perform recompute_invoice(v_invoice);
    end if;
    -- the doctor who ordered it is told (0088: or the colleague they handed the patient over to)
    v_to := result_recipient(v_req.encounter_id, v_req.requester_id);
    if v_to is not null and v_to is distinct from auth.uid() then
      select s.name_en into v_test from service s where s.id = v_req.service_id;
      select p.surname || ' ' || p.given_names into v_name
      from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
      insert into notification (kind, params, link, recipient_user, created_by)
      values ('test_cancelled', jsonb_build_object('test', v_test, 'name', v_name, 'reason', trim(p_reason)),
              '/app/visit?encounter=' || v_req.encounter_id, v_to, auth.uid());
    end if;
    perform after_desk_tests(v_req.encounter_id,
      coalesce(v_req.station, case when v_req.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end),
      v_req.requester_id);
  end if;
end
$$;


-- correct_result (from 20261128090000_switches_enforced): the corrected result goes to whoever
-- has the patient now (result_recipient).
create or replace function correct_result(
  p_request_id uuid,
  p_findings text,
  p_impression text,
  p_reason text
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
  v_rep diagnostic_report%rowtype;
  v_test text;
  v_name text;
  v_to uuid;
begin
  select * into v_req from service_request where id = p_request_id and deleted_at is null;
  if not found then
    raise exception 'test order not found' using errcode = 'P0002';
  end if;
  if not (is_manager() or (may_use_desk(request_desk(v_req.station, v_req.category))
               and (request_desk(v_req.station, v_req.category) not in ('laboratory', 'ultrasound')
                    or has_perm('orders.write')))
          or (has_perm('clinical.write') and coalesce(v_req.station, 'laboratory') not in ('laboratory', 'ultrasound')
              and may_use_any_desk(station_desks(v_req.station)))
          -- the clinician's own test while no department gives that desk (as before 0085)
          or (has_perm('orders.write') and v_req.requester_id = auth.uid()
              and not desk_offered(request_desk(v_req.station, v_req.category)))) then
    if may_use_desk(request_desk(v_req.station, v_req.category)) and not has_perm('orders.write') then
      raise exception 'you may not work on tests (the manager has not allowed it)'
        using errcode = '42501', hint = 'not_permitted';
    end if;
    perform assert_desk(array[request_desk(v_req.station, v_req.category)]);
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the result is corrected' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_findings, '')), '') is null and nullif(trim(coalesce(p_impression, '')), '') is null then
    raise exception 'write the findings or the conclusion' using errcode = '22023';
  end if;
  select * into v_rep from diagnostic_report where service_request_id = p_request_id and deleted_at is null for update;
  if not found or v_rep.verified_at is null then
    raise exception 'only a verified result is corrected; edit the result instead' using errcode = '22023';
  end if;
  insert into report_correction (report_id, old_findings, old_impression, old_verified_by, old_verified_at, reason)
  values (v_rep.id, v_rep.findings, v_rep.impression, v_rep.verified_by, v_rep.verified_at, trim(p_reason));
  perform set_config('mmc.correcting_report', v_rep.id::text, true);
  update diagnostic_report
  set findings = nullif(trim(coalesce(p_findings, '')), ''), impression = nullif(trim(coalesce(p_impression, '')), ''),
      verified_by = auth.uid(), verified_at = now(), corrected_at = now(), correction_reason = trim(p_reason),
      updated_at = now()
  where id = v_rep.id;
  perform set_config('mmc.correcting_report', '', true);
  -- The doctor who ordered the test is told the result changed (0088: or the colleague they
  -- handed the patient over to).
  v_to := result_recipient(v_req.encounter_id, v_req.requester_id);
  if v_to is not null and v_to is distinct from auth.uid() then
    select s.name_en into v_test from service s where s.id = v_req.service_id;
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_req.encounter_id;
    insert into notification (kind, params, link, recipient_user, urgent, created_by)
    values ('result',
            jsonb_build_object('test', v_test, 'name', v_name,
                               'impression', nullif(trim(coalesce(p_impression, '')), ''),
                               'verified', true, 'corrected', true, 'reason', trim(p_reason)),
            '/app/visit?encounter=' || v_req.encounter_id,
            v_to, true, auth.uid());
  end if;
end
$$;


-- after_desk_tests (from 20261119090000_audit_fixes): with no return asked, the patient goes back
-- to whoever has them now (result_recipient), not always to who ordered the tests.
create or replace function after_desk_tests(p_encounter_id uuid, p_station station, p_requester uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_q queue_entry%rowtype;
  v_back station;
  v_to uuid;
  v_tests text;
begin
  if exists (select 1 from service_request r
             where r.encounter_id = p_encounter_id and r.deleted_at is null
               and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) = p_station
               and r.status not in ('resulted', 'verified', 'cancelled')) then
    return;
  end if;
  select * into v_q from queue_entry
  where encounter_id = p_encounter_id and station = p_station and finished_at is null and deleted_at is null
  order by created_at desc limit 1;
  if not found then
    return;
  end if;
  v_back := v_q.return_station;
  v_to := v_q.return_to;
  if v_back is null and p_requester is not null then
    -- 0088: the colleague the requester handed the patient over to, when they took them
    v_to := result_recipient(p_encounter_id, p_requester);
    select q.station into v_back from queue_entry q
    where q.encounter_id = p_encounter_id and q.station <> p_station
      and (q.taken_by = v_to or q.assigned_to = v_to)
    order by q.created_at desc limit 1;
    if v_back is null then
      select case p.role when 'doctor' then 'consultation'::station when 'nurse' then 'nursing'::station end
      into v_back from profiles p where p.id = v_to;
    end if;
  end if;
  -- someone who left the clinic (deactivated or deleted): anyone in the section takes the patient
  v_to := active_staff_or_null(v_to);
  if v_back is null then
    -- nobody asked for the patient back (came straight to the lab): the lab's part is over;
    -- on to the cashier if money is due, otherwise the visit ends when nothing else is left
    update queue_entry set finished_at = now() where id = v_q.id;
    if exists (select 1 from queue_entry q where q.encounter_id = p_encounter_id and q.finished_at is null
               and q.deleted_at is null and station_role(q.station) in ('doctor', 'nurse', 'lab_tech', 'sonographer')) then
      return;
    end if;
    if exists (select 1 from invoice i where i.encounter_id = p_encounter_id and invoice_balance(i.id) > 0) then
      if not exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = 'cashier'
                     and finished_at is null and deleted_at is null) then
        insert into queue_entry (encounter_id, station, ticket_no, priority, referred_by, referral_note)
        values (p_encounter_id, 'cashier', v_q.ticket_no, v_q.priority, auth.uid(), 'Tests done');
      end if;
    else
      perform settle_visit(p_encounter_id);
    end if;
    return;
  end if;
  update queue_entry set finished_at = now() where id = v_q.id;
  if not exists (select 1 from queue_entry where encounter_id = p_encounter_id
                 and station = v_back and finished_at is null and deleted_at is null) then
    select string_agg(s.name_en || case when r.status = 'cancelled' then ' (not done)' else '' end, ', ' order by r.created_at)
    into v_tests
    from service_request r join service s on s.id = r.service_id
    where r.encounter_id = p_encounter_id and r.deleted_at is null
      and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) = p_station
      and (r.status in ('resulted', 'verified') or (r.status = 'cancelled' and r.updated_at > now() - interval '1 day'));
    insert into queue_entry (encounter_id, station, ticket_no, priority, assigned_to, referred_by, referral_note)
    values (p_encounter_id, v_back, v_q.ticket_no, v_q.priority, v_to, auth.uid(),
            'Results ready: ' || coalesce(v_tests, ''));
  end if;
end
$$;


-- ---------------------------------------------------------------- grants
revoke all on function handover_held_queue(uuid, uuid), handover_colleague_ok(uuid, uuid, boolean),
  handover_via_return(uuid, uuid), handover_desk(uuid, boolean), handover_follow_profile(),
  result_recipient(uuid, uuid),
  handover_json(patient_handover), handover_follow_queue(), clinician_cover_retired()
  from public, anon, authenticated;
revoke all on function handover_colleagues(uuid), handover_patient(uuid, uuid, text), take_handover(uuid),
  decline_handover(uuid, text), cancel_handover(uuid), my_handovers()
  from public, anon;
grant execute on function handover_colleagues(uuid), handover_patient(uuid, uuid, text), take_handover(uuid),
  decline_handover(uuid, text), cancel_handover(uuid), my_handovers()
  to authenticated;
grant select on queue_board to authenticated;


-- ============================================================ 20261130090000_patient_privacy.sql
-- 0088 · Patient record privacy: four levels, access requests, emergency access, the access log.
--
-- Frank: "when a patient is marked as left or finished treatment ... manager and the heads of
-- departments in charge may be the ones to view sensitive information ... when a person treating
-- needs data or view to previous treatments ... when he is not the head he may request access to
-- the head and approves him or the manager depending on who is available". Decided with him:
-- assistant heads neither see full records nor approve; an approved access lasts until the
-- patient's current visit closes; emergency access exists; a doctor always sees the visits they
-- treated; the safety summary as proposed.
--
--   * A  FOUR LEVELS.
--        1 identity    name, file number, age, sex, phone, payer: every employee (patient.read).
--        2 summary     allergies, chronic conditions, current medicines, blood group, last vital
--                      signs, alerts (patient notes and flags): whoever treats the patient now
--                      (treating_visit: a clinical reader holding the patient at a desk other
--                      than reception or the cashier, with a task or help call on the visit, or
--                      who took part in it).
--        3 this visit  the open visit's clinical record (visit_view = 'visit'): the people working
--                      on it (may_work_on, took part, the visit waits at a desk they use, a test of
--                      the visit is open at their laboratory/ultrasound desk, a medicine waits at
--                      their pharmacy desk) and the manager.
--        4 history     every past visit's notes, diagnoses, results, prescriptions, documents:
--                      the manager; the HEAD (not the assistant) of a department in charge of one
--                      of the patient's visits (visit_departments: a treating desk, laboratory or
--                      ultrasound served the visit); the clinician for the visits they treated
--                      themselves (treated: 'own'); anyone with an approved request or an emergency
--                      access for this patient while the visit it was asked in stays open.
--        The reading functions return only what the level allows: patient_file, visit_clinical,
--        patient_results, visit_journey; the clinical tables' read policies too (observation,
--        condition, service_request, diagnostic_report, procedure, medication_request,
--        medication_dispense, prescription_doc, vaccination, fp_event, hiv_test, document).
--        The desks keep their worklists (lab_worklist, desk_orders, pharmacy_queue…): they read
--        what their work needs and are unchanged. The current visit's documents still print.
--   * B  REQUEST ACCESS (request_record_access): only while treating the patient, with a reason.
--        The manager and the heads in charge are told (notice 'access_request'); the first to
--        answer approves or refuses with a reason (answer_record_access); the requester is told
--        ('access_answer'). The access ends when the visit closes. record_access_requests() lists
--        them for the approvers and the requester.
--   * C  EMERGENCY ACCESS (emergency_record_access): while treating the patient, opened at once
--        with a reason; urgent notice to the manager and the heads in charge ('access_emergency');
--        a red entry in the access log; the manager reviews it (review_emergency_access).
--   * D  THE ACCESS LOG (record_access_entry): every opening of past records (who, patient, visit,
--        when, how: own visit / head / approved request / emergency / manager), once per half
--        hour for the same person, patient, visit and way (the screens refresh). The manager's
--        page reads record_access_log(); the patient file shows who looked (patient_access_log).
--   * E  THE SAFETY FIELDS stay safe at level 1: update_patient no longer clears or replaces the
--        allergies, "no known allergies", blood group or notes someone at level 1 cannot see (the
--        patient form sends them empty); they may still add one where none is recorded.
--
--   * H  THE OTHER WAYS IN: visit_vitals shows a closed visit's vital signs only where its record
--        may be seen; the patient, encounter and queue_entry tables no longer give the safety
--        fields, the triage reason or the referral note when read directly (column privileges;
--        queue_board reads them with its owner's rights); the patient search gives the allergy
--        mark to clinical readers only; a colleague's analytics hide what was written in visits
--        one may not see; a request still waiting when its visit closes is cancelled.
--   'Own' visit (closed) = treated it (treated()): took the patient at a treating desk, diagnosis,
--   clinical note, prescription, test ordered, ultrasound report, procedure, help. The wider
--   took_part (vital signs, results…) counts only while the visit is open.
--   A department is in charge of a visit when the visit was sent to it; only a visit sent to no
--   department falls to every department giving that desk.
--
-- Errcodes: 42501 not allowed (hints: not_treating, not_approver, not_manager), 22023 bad input
-- (hints: reason_needed, already_answered, already_allowed, visit_closed), P0002 not found (hint:
-- not_found).

-- ---------------------------------------------------------------- tables
create table if not exists record_access_request (
  id uuid primary key default gen_random_uuid(),
  patient_id uuid not null references patient (id),
  -- the open visit the requester treats: the access ends when it closes
  encounter_id uuid not null references encounter (id),
  requested_by uuid not null default auth.uid() references profiles (id),
  kind text not null default 'request' check (kind in ('request', 'emergency')),
  reason text not null check (length(trim(reason)) >= 3),
  status text not null default 'pending' check (status in ('pending', 'approved', 'refused', 'cancelled')),
  answered_by uuid references profiles (id) on delete set null,
  answered_at timestamptz,
  answer_note text,
  -- emergencies: the manager's review
  reviewed_by uuid references profiles (id) on delete set null,
  reviewed_at timestamptz,
  review_note text,
  created_at timestamptz not null default now()
);
create index if not exists record_access_request_patient_idx
  on record_access_request (patient_id, requested_by, status);
create index if not exists record_access_request_status_idx on record_access_request (status, created_at desc);
comment on table record_access_request is
  'Requests to see a patient''s past records (and emergency accesses), answered by the manager or a head in charge (0088).';
alter table record_access_request enable row level security;
revoke all on record_access_request from anon, authenticated;

create table if not exists record_access_entry (
  id uuid primary key default gen_random_uuid(),
  at timestamptz not null default now(),
  actor_id uuid not null references profiles (id),
  patient_id uuid not null references patient (id),
  -- the past visit opened (null: the patient file or the results of every visit)
  encounter_id uuid references encounter (id),
  via text not null check (via in ('own', 'head', 'request', 'emergency', 'manager')),
  what text not null default 'file' check (what in ('file', 'visit', 'results', 'journey', 'emergency')),
  request_id uuid references record_access_request (id)
);
create index if not exists record_access_entry_at_idx on record_access_entry (at desc);
create index if not exists record_access_entry_patient_idx on record_access_entry (patient_id, at desc);
create index if not exists record_access_entry_actor_idx on record_access_entry (actor_id, patient_id, at desc);
comment on table record_access_entry is
  'Who opened a patient''s past records, when and how (0088). Written by the reading functions only.';
alter table record_access_entry enable row level security;
revoke all on record_access_entry from anon, authenticated;

-- ---------------------------------------------------------------- helpers
-- Reads clinical records at all (as visit_clinical asked before).
create or replace function clinical_reader()
returns boolean
language sql stable security definer set search_path = public
as $$
  select has_perm('clinical.read') or has_perm('orders.read') or has_perm('prescription.read')
$$;

-- Did this person take part in the visit (their own visit)? Took the patient, wrote a diagnosis,
-- a note or a vital sign, prescribed, ordered a test, entered or validated a result, performed a
-- procedure, or helped on the patient.
create or replace function took_part(p_encounter_id uuid, p_user uuid default auth.uid())
returns boolean
language sql stable security definer set search_path = public
as $$
  select p_user is not null and (
    exists (select 1 from queue_entry q
            where q.encounter_id = p_encounter_id and q.deleted_at is null and q.taken_by = p_user
              and q.station not in ('reception', 'cashier'))
    or exists (select 1 from condition c
               where c.encounter_id = p_encounter_id and c.deleted_at is null and c.created_by = p_user)
    or exists (select 1 from observation o
               where o.encounter_id = p_encounter_id and o.deleted_at is null
                 and (o.performer_id = p_user or o.created_by = p_user))
    or exists (select 1 from medication_request m
               where m.encounter_id = p_encounter_id and m.deleted_at is null
                 and coalesce(m.prescriber_id, m.created_by) = p_user)
    or exists (select 1 from service_request r
               where r.encounter_id = p_encounter_id and r.deleted_at is null and r.requester_id = p_user)
    or exists (select 1 from service_request r
               join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
               where r.encounter_id = p_encounter_id and (d.created_by = p_user or d.verified_by = p_user))
    or exists (select 1 from procedure pr
               where pr.encounter_id = p_encounter_id and pr.deleted_at is null and pr.performer_id = p_user)
    or exists (select 1 from staff_call c
               where c.encounter_id = p_encounter_id and c.kind = 'help' and c.answered_by = p_user
                 and c.status in ('accepted', 'done'))
  )
$$;

-- Did this person TREAT the visit (a closed visit stays theirs: 'own')? Narrower than took_part:
-- took the patient at a treating desk, wrote a diagnosis or a clinical note, prescribed, ordered a
-- test, wrote an ultrasound report, performed a procedure, or helped on the patient. Measuring
-- vital signs, typing the nurse's sheet, entering a laboratory result or dispensing does not open
-- the whole closed visit: the desks' own lists keep that part.
create or replace function treated(p_encounter_id uuid, p_user uuid default auth.uid())
returns boolean
language sql stable security definer set search_path = public
as $$
  select p_user is not null and (
    exists (select 1 from queue_entry q
            where q.encounter_id = p_encounter_id and q.deleted_at is null and q.taken_by = p_user
              and station_desks(q.station) && treating_desks())
    or exists (select 1 from condition c
               where c.encounter_id = p_encounter_id and c.deleted_at is null and c.created_by = p_user)
    or exists (select 1 from observation o
               where o.encounter_id = p_encounter_id and o.deleted_at is null and o.code = 'note'
                 and coalesce(o.performer_id, o.created_by) = p_user)
    or exists (select 1 from medication_request m
               where m.encounter_id = p_encounter_id and m.deleted_at is null
                 and coalesce(m.prescriber_id, m.created_by) = p_user)
    or exists (select 1 from service_request r
               where r.encounter_id = p_encounter_id and r.deleted_at is null and r.requester_id = p_user)
    or exists (select 1 from service_request r
               join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
               where r.encounter_id = p_encounter_id and r.category = 'imaging'
                 and (d.created_by = p_user or d.verified_by = p_user))
    or exists (select 1 from procedure pr
               where pr.encounter_id = p_encounter_id and pr.deleted_at is null and pr.performer_id = p_user)
    or exists (select 1 from staff_call c
               where c.encounter_id = p_encounter_id and c.kind = 'help' and c.answered_by = p_user
                 and c.status in ('accepted', 'done'))
  )
$$;

-- The departments in charge of a visit: those of the places where it was treated (a treating desk,
-- the laboratory or ultrasound): the department it was sent to; only when none was named, the
-- departments giving that desk. Reception, triage and the pharmacy see every patient pass and are
-- not "in charge".
create or replace function visit_departments(p_encounter_id uuid)
returns uuid[]
language sql stable security definer set search_path = public
as $$
  -- when no department was named, the department of the person who took (or was given) the
  -- patient there and gives that desk; never every department giving the desk (a head of another
  -- department who never saw the patient is not "in charge")
  select coalesce(array_agg(distinct d.id), '{}')
  from queue_entry q
  join department d on d.active and d.deleted_at is null
    and (d.id = q.department_id
         or (q.department_id is null and station_desks(q.station) && d.services
             and exists (select 1 from staff_department sd
                         where sd.department_id = d.id
                           and sd.profile_id in (q.taken_by, q.assigned_to))))
  where q.encounter_id = p_encounter_id and q.deleted_at is null
    and station_desks(q.station) && (treating_desks() || array['laboratory', 'ultrasound'])
$$;

-- The heads (not the assistants) of the departments in charge of any visit of the patient.
create or replace function heads_in_charge(p_patient_id uuid)
returns uuid[]
language sql stable security definer set search_path = public
as $$
  select coalesce(array_agg(distinct sd.profile_id), '{}')
  from encounter e
  cross join lateral unnest(visit_departments(e.id)) as vd(id)
  join staff_department sd on sd.department_id = vd.id and sd.position = 'head'
  join profiles p on p.id = sd.profile_id and p.active and p.deleted_at is null
  where e.patient_id = p_patient_id and e.deleted_at is null
$$;

-- The approved request (or emergency access) of the signed-in person for this patient, while
-- the visit it was asked in stays open.
create or replace function access_in_force(p_patient_id uuid)
returns record_access_request
language sql stable security definer set search_path = public
as $$
  select r.*
  from record_access_request r
  join encounter e on e.id = r.encounter_id and e.status = 'open' and e.deleted_at is null
  where r.patient_id = p_patient_id and r.requested_by = auth.uid() and r.status = 'approved'
  order by r.answered_at desc nulls last, r.created_at desc
  limit 1
$$;

-- How the signed-in person sees the patient's whole history, or null:
-- 'manager', 'head' (of a department in charge), 'emergency' or 'request' (in force).
create or replace function history_via(p_patient_id uuid)
returns text
language sql stable security definer set search_path = public
as $$
  select case
    when auth.uid() is null then null
    when is_manager() then 'manager'
    when auth.uid() = any (heads_in_charge(p_patient_id)) then 'head'
    else (select a.kind from access_in_force(p_patient_id) a where a.id is not null)
  end
$$;

-- How the signed-in person sees one visit's clinical record, or null:
--   open visit:   'visit' (working on it, the manager), else history_via
--   closed visit: 'manager', 'own' (treated it), else history_via
-- p_via_known: the caller already worked out history_via (p_via) for the patient; the loops over
-- a patient's visits pass it so it is not worked out again for every visit.
create or replace function visit_view_with(p_encounter_id uuid, p_via text, p_via_known boolean)
returns text
language plpgsql stable security definer set search_path = public
as $$
declare
  v_e encounter%rowtype;
begin
  if auth.uid() is null then
    return null;
  end if;
  select * into v_e from encounter where id = p_encounter_id and deleted_at is null;
  if not found then
    return null;
  end if;
  if v_e.status = 'open' then
    if may_work_on(v_e.id) or took_part(v_e.id) then
      return 'visit';
    end if;
    -- the visit waits, not yet taken, at a desk this person uses (they may take the patient)
    if exists (select 1 from queue_entry q
               where q.encounter_id = v_e.id and q.finished_at is null and q.deleted_at is null
                 and q.taken_by is null and (q.assigned_to is null or q.assigned_to = auth.uid())
                 and q.station <> 'reception' and may_use_any_desk(station_desks(q.station))) then
      return 'visit';
    end if;
    -- a test of the visit is open at their laboratory or ultrasound desk
    if exists (select 1 from service_request r
               where r.encounter_id = v_e.id and r.deleted_at is null
                 and r.status not in ('verified', 'cancelled')
                 and may_use_desk(request_desk(r.station, r.category))) then
      return 'visit';
    end if;
    -- a medicine of the visit waits at the pharmacy
    if may_use_desk('pharmacy')
       and exists (select 1 from medication_request m
                   where m.encounter_id = v_e.id and m.deleted_at is null and rx_pending(m)) then
      return 'visit';
    end if;
    return case when p_via_known then p_via else history_via(v_e.patient_id) end;
  end if;
  if is_manager() then
    return 'manager';
  end if;
  if treated(v_e.id) then
    return 'own';
  end if;
  return case when p_via_known then p_via else history_via(v_e.patient_id) end;
end
$$;

create or replace function visit_view(p_encounter_id uuid)
returns text
language sql stable security definer set search_path = public
as $$
  select visit_view_with(p_encounter_id, null, false)
$$;

-- The open visit the signed-in person treats now, or null: someone who reads clinical records and
-- is linked to the visit clinically: the patient is theirs at a desk other than reception or the
-- cashier, a task or an accepted help call of the visit is theirs, or they took part in it.
create or replace function treating_visit(p_patient_id uuid)
returns uuid
language sql stable security definer set search_path = public
as $$
  select e.id
  from encounter e
  where e.patient_id = p_patient_id and e.status = 'open' and e.deleted_at is null
    and auth.uid() is not null and clinical_reader()
    and (exists (select 1 from queue_entry q
                 where q.encounter_id = e.id and q.finished_at is null and q.deleted_at is null
                   and q.station not in ('reception', 'cashier') and queue_entry_for_me(q.id))
         or exists (select 1 from internal_task k
                    where k.encounter_id = e.id and k.done_at is null and k.deleted_at is null
                      and (k.assigned_to = auth.uid() or task_for_me(k.assigned_role)))
         or exists (select 1 from staff_call c
                    where c.encounter_id = e.id and c.kind = 'help' and c.status = 'accepted'
                      and c.answered_by = auth.uid())
         or took_part(e.id))
  order by e.arrived_at desc
  limit 1
$$;

-- The level of the signed-in person for the patient: 'full' (history), 'summary' (treating now)
-- or 'identity'.
create or replace function patient_level(p_patient_id uuid)
returns text
language sql stable security definer set search_path = public
as $$
  select case
    when history_via(p_patient_id) is not null then 'full'
    when treating_visit(p_patient_id) is not null then 'summary'
    else 'identity'
  end
$$;

-- One line in the access log; the same person, patient, visit and way once per half hour.
create or replace function log_record_access(p_patient_id uuid, p_encounter_id uuid, p_via text, p_what text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req uuid;
begin
  if auth.uid() is null or p_via is null or p_patient_id is null then
    return;
  end if;
  if exists (select 1 from record_access_entry a
             where a.actor_id = auth.uid() and a.patient_id = p_patient_id
               and a.encounter_id is not distinct from p_encounter_id and a.via = p_via
               and a.at > now() - interval '30 minutes') then
    return;
  end if;
  if p_via in ('request', 'emergency') then
    select a.id into v_req from access_in_force(p_patient_id) a;
  end if;
  insert into record_access_entry (actor_id, patient_id, encounter_id, via, what, request_id)
  values (auth.uid(), p_patient_id, p_encounter_id, p_via, p_what, v_req);
end
$$;

-- The safety summary (level 2): allergies, blood group, alerts, chronic conditions, the medicines
-- being taken and the last vital signs.
create or replace function patient_safety_summary(p_patient_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'allergies', p.allergies,
    'allergiesNone', coalesce(p.allergies_none, false) and p.allergies is null,
    'bloodGroup', p.blood_group,
    'alerts', p.notes,
    'flags', p.flags,
    -- long-lasting conditions: a chronic ICD-10 group, or the same diagnosis on two visits
    'chronic', coalesce((
      select jsonb_agg(jsonb_build_object('text', x.text, 'icd10', x.icd10_code, 'since', x.first_at, 'lastAt', x.created_at)
                       order by x.created_at desc)
      from (
        select distinct on (lower(c.text)) c.text, c.icd10_code, c.created_at,
               min(c.created_at) over (partition by lower(c.text)) as first_at
        from condition c join encounter e on e.id = c.encounter_id and e.deleted_at is null
        where e.patient_id = p.id and c.deleted_at is null
          and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'))
          and (coalesce(c.icd10_code, '') ~ '^(I1[0-5]|I25|I50|E0[3-5]|E1[0-4]|J4[45]|G40|N18|B18|B2[0-4]|F2[0-9]|F3[1-3])'
               or (select count(distinct c2.encounter_id) from condition c2
                   join encounter e2 on e2.id = c2.encounter_id and e2.deleted_at is null
                   where e2.patient_id = p.id and c2.deleted_at is null and lower(c2.text) = lower(c.text)) >= 2)
        order by lower(c.text), c.created_at desc
      ) x), '[]'::jsonb),
    -- medicines of the open visit, and those still running (prescribed days not over)
    'medications', coalesce((
      select jsonb_agg(jsonb_build_object(
          'item', i.name_generic || coalesce(' ' || i.strength, ''), 'dose', m.dose, 'frequency', m.frequency,
          'days', m.duration_days, 'at', m.created_at,
          'until', case when m.duration_days is not null then m.created_at + make_interval(days => m.duration_days) end,
          'by', (select full_name from profiles where id = coalesce(m.prescriber_id, m.created_by)))
        order by m.created_at desc)
      from medication_request m
      join encounter e on e.id = m.encounter_id and e.deleted_at is null
      join item i on i.id = m.item_id
      where e.patient_id = p.id and m.deleted_at is null and m.cancelled_at is null and m.not_given_at is null
        and m.created_at > now() - interval '180 days'
        and (e.status = 'open' or m.created_at + make_interval(days => coalesce(m.duration_days, 0)) >= now())), '[]'::jsonb),
    'lastVitals', coalesce((
      select jsonb_agg(jsonb_build_object('code', v.code, 'value', v.value_num, 'unit', v.unit, 'at', v.effective_at,
                                          'by', (select full_name from profiles where id = v.performer_id))
                       order by v.code)
      from (
        select distinct on (o.code) o.code, o.value_num, o.unit, o.effective_at, o.performer_id
        from observation o join encounter e on e.id = o.encounter_id and e.deleted_at is null
        where e.patient_id = p.id and o.deleted_at is null and o.code <> 'note' and o.value_num is not null
        order by o.code, o.effective_at desc
      ) v), '[]'::jsonb),
    'lastVisitAt', (select max(e.arrived_at) from encounter e where e.patient_id = p.id and e.deleted_at is null)
  )
  from patient p where p.id = p_patient_id
$$;

-- What the signed-in person may see of the patient, and may ask for (the patient file's banner
-- and its Request / Emergency buttons). patient_access_with: history_via and treating_visit
-- already worked out by the caller (internal).
create or replace function patient_access_with(p_patient_id uuid, p_via text, p_treating uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_via text := p_via;
  v_treating uuid := p_treating;
  v_reader boolean := clinical_reader();
  v_past integer;
  v_own integer;
  v_hidden integer;
  v_req record_access_request%rowtype;
  v_level text;
begin
  if auth.uid() is null or not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  v_level := case when v_via is not null then 'full' when v_treating is not null then 'summary' else 'identity' end;
  select count(*),
         count(*) filter (where treated(e.id)),
         count(*) filter (where not v_reader or visit_view_with(e.id, v_via, true) is null)
  into v_past, v_own, v_hidden
  from encounter e
  where e.patient_id = p_patient_id and e.deleted_at is null and e.status = 'closed';
  -- my latest request for the visit I treat now
  if v_treating is not null then
    select * into v_req from record_access_request r
    where r.patient_id = p_patient_id and r.encounter_id = v_treating and r.requested_by = auth.uid()
    order by r.created_at desc limit 1;
  end if;
  return jsonb_build_object(
    'level', v_level,
    'via', v_via,
    'treatingEncounterId', v_treating,
    'pastVisits', v_past,
    'ownVisits', v_own,
    'hiddenVisits', v_hidden,
    'canRequest', has_perm('clinical.read') and v_treating is not null and v_via is null and v_hidden > 0
                  and (v_req.id is null or v_req.status in ('refused', 'cancelled')),
    'canEmergency', has_perm('clinical.read') and v_treating is not null and v_via is null and v_hidden > 0,
    -- the manager and the heads in charge (history_via says so)
    'canSeeLog', coalesce(v_via in ('manager', 'head'), false),
    'request', case when v_req.id is not null then jsonb_build_object(
        'id', v_req.id, 'kind', v_req.kind, 'status', v_req.status, 'reason', v_req.reason,
        'at', v_req.created_at, 'answeredAt', v_req.answered_at, 'answerNote', v_req.answer_note,
        'answeredBy', (select full_name from profiles where id = v_req.answered_by)) end
  );
end
$$;

create or replace function patient_access(p_patient_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select patient_access_with(p_patient_id, history_via(p_patient_id), treating_visit(p_patient_id))
$$;

-- ---------------------------------------------------------------- A the reading functions
-- The patient file (0084) by level: every visit is listed (date, reference, places, bill), but
-- its diagnosis, triage reason, vital signs and diagnoses only where the record may be seen
-- ('private' otherwise); the safety summary from level 2; the safety fields of the patient row
-- and of the printed details hidden at level 1. Opening past records is logged.
-- The extra fields the manager marked "medical" in Settings → Patient file fields
-- (setting patient.fields: [{key, label, type, private: true}]): private like the safety
-- summary — shown to whoever treats the patient now and to full-history readers only.
create or replace function private_extra_keys()
returns text[]
language sql stable security definer set search_path = public
as $$
  select coalesce(array_agg(f ->> 'key'), '{}'::text[])
  from setting s
  cross join lateral jsonb_array_elements(
    case when jsonb_typeof(s.value) = 'array' then s.value else '[]'::jsonb end) f
  where s.key = 'patient.fields' and jsonb_typeof(f) = 'object' and f ->> 'private' = 'true'
$$;
revoke all on function private_extra_keys() from public, anon, authenticated;

create or replace function patient_file(p_patient_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_patient jsonb;
  v_visits jsonb;
  v_vitals jsonb;
  v_conditions jsonb;
  v_bills jsonb;
  v_doc jsonb;
  v_reader boolean := clinical_reader();
  v_via text;
  v_treating uuid;
  v_level text;
  v_past_seen boolean;
  v_views jsonb;
begin
  if not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select to_jsonb(p) - 'photo_blob_id' - 'merged_into' - 'guardian_patient_id' into v_patient
  from patient p where p.id = p_patient_id and p.deleted_at is null;
  if v_patient is null then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;
  -- worked out once for the whole file (the visits' loop reuses them)
  v_via := history_via(p_patient_id);
  v_treating := treating_visit(p_patient_id);
  v_level := case when v_via is not null then 'full' when v_treating is not null then 'summary' else 'identity' end;

  -- how each visit may be seen (null: private)
  select coalesce(jsonb_object_agg(e.id::text, s.view) filter (where s.view is not null), '{}'::jsonb),
         coalesce(bool_or(s.view is not null and e.status = 'closed'), false)
  into v_views, v_past_seen
  from encounter e
  cross join lateral (select case when v_reader then visit_view_with(e.id, v_via, true) end as view) s
  where e.patient_id = p_patient_id and e.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', e.id, 'reference', e.reference, 'arrivedAt', e.arrived_at, 'status', e.status, 'type', e.type,
      'triage', e.triage_level,
      'triageReason', case when s.view is not null then e.triage_reason end,
      'practitioner', (select names from practitioner where id = e.practitioner_id),
      'stations', (select coalesce(jsonb_agg(distinct q.station::text), '[]'::jsonb) from queue_entry q where q.encounter_id = e.id and q.deleted_at is null),
      'currentStation', (select q.station from queue_entry q where q.encounter_id = e.id and q.finished_at is null and q.deleted_at is null order by q.created_at desc limit 1),
      'diagnosis', case when s.view is not null then
        (select c.text from condition c where c.encounter_id = e.id and c.type = 'primary' and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read')) order by c.created_at desc limit 1) end,
      'total', (select i.total from invoice i where i.encounter_id = e.id),
      'balance', (select invoice_balance(i.id) from invoice i where i.encounter_id = e.id),
      'billStatus', (select i.status from invoice i where i.encounter_id = e.id),
      'closedAt', e.closed_at,
      'private', s.view is null,
      'view', s.view
    ) order by e.arrived_at desc), '[]'::jsonb) into v_visits
  from encounter e cross join lateral (select v_views ->> e.id::text as view) s
  where e.patient_id = p_patient_id and e.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'encounterId', o.encounter_id, 'code', o.code, 'value', o.value_num, 'text', o.value_text,
      'unit', o.unit, 'at', o.effective_at, 'by', (select full_name from profiles where id = o.performer_id)
    ) order by o.effective_at desc), '[]'::jsonb) into v_vitals
  -- the visits one may see; whoever types the nurse's sheet (vitals.write) also sees what is
  -- recorded on the open visit (0019), never a past one
  from observation o
  where o.deleted_at is null and o.code <> 'note'
    and (v_views ? o.encounter_id::text
         or (has_perm('vitals.write')
             and o.encounter_id in (select e.id from encounter e
                                    where e.patient_id = p_patient_id and e.status = 'open' and e.deleted_at is null)));

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'encounterId', c.encounter_id, 'text', c.text, 'icd10', c.icd10_code, 'type', c.type,
      'provisional', c.provisional, 'at', c.created_at, 'by', (select full_name from profiles where id = c.created_by)
    ) order by c.created_at desc), '[]'::jsonb) into v_conditions
  from condition c
  where v_views ? c.encounter_id::text and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'));

  select coalesce(jsonb_agg(jsonb_build_object(
      'invoiceId', i.id, 'encounterId', i.encounter_id, 'number', i.number, 'status', i.status,
      'total', i.total, 'patientShare', i.patient_share, 'insurerShare', i.insurer_share,
      'balance', invoice_balance(i.id), 'payer', (select name from payer where id = i.payer_id),
      'at', i.created_at
    ) order by i.created_at desc), '[]'::jsonb) into v_bills
  from invoice i join encounter e on e.id = i.encounter_id
  where e.patient_id = p_patient_id and i.deleted_at is null;

  v_doc := doc_patient(p_patient_id, null);
  if v_level = 'identity' then
    v_patient := v_patient || jsonb_build_object('allergies', null, 'allergies_none', null,
                                                 'blood_group', null, 'notes', null,
                                                 -- the manager's "medical" extra fields go too
                                                 'extra', coalesce(v_patient -> 'extra', '{}'::jsonb) - private_extra_keys(),
                                                 -- the safety marks go; "VIP" is not one
                                                 'flags', jsonb_strip_nulls(jsonb_build_object('vip', v_patient -> 'flags' -> 'vip')));
    v_doc := v_doc - 'allergies' - 'allergiesNone' - 'bloodGroup' - 'weightKg' - 'weightAt';
  end if;

  if v_past_seen then
    perform log_record_access(p_patient_id, null, coalesce(v_via, 'own'), 'file');
  end if;

  return jsonb_build_object('patient', v_patient, 'visits', v_visits, 'vitals', v_vitals,
                            'conditions', v_conditions, 'bills', v_bills,
                            'document', v_doc,
                            'safetyHidden', v_level = 'identity',
                            'summary', case when v_level <> 'identity' then patient_safety_summary(p_patient_id) end,
                            'access', patient_access_with(p_patient_id, v_via, v_treating));
end
$$;

-- One visit's clinical record (0085) when the person may see it (visit_view); otherwise the
-- same shape, empty, with private = true and what may be asked (access). A past visit opened is
-- logged.
create or replace function visit_clinical(p_encounter_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_view text;
  v_patient uuid;
  v_closed boolean;
  v_safe boolean;
begin
  -- clinicians; the lab and the pharmacy read the record too (their orders and prescriptions)
  if not clinical_reader() then
    return null;
  end if;
  select e.patient_id, e.status = 'closed' into v_patient, v_closed
  from encounter e where e.id = p_encounter_id and e.deleted_at is null;
  if v_patient is null then
    return null;
  end if;
  v_view := visit_view(p_encounter_id);
  if v_view is null then
    v_safe := patient_level(v_patient) <> 'identity';
    return jsonb_build_object(
      'diagnoses', '[]'::jsonb, 'notes', '[]'::jsonb, 'prescriptions', '[]'::jsonb, 'orders', '[]'::jsonb,
      'patient', (select jsonb_build_object('id', p.id,
                    'allergies', case when v_safe then p.allergies end,
                    'bloodGroup', case when v_safe then p.blood_group end,
                    'notes', case when v_safe then p.notes end,
                    'flags', case when v_safe then p.flags else '{}'::jsonb end)
                  || case when v_safe then doc_patient(p.id, p_encounter_id)
                          else doc_patient(p.id, p_encounter_id) - 'allergies' - 'allergiesNone' - 'bloodGroup'
                               - 'weightKg' - 'weightAt' end
                  from patient p where p.id = v_patient),
      'visit', doc_visit(p_encounter_id),
      'private', true,
      'view', null,
      'access', patient_access(v_patient));
  end if;
  if v_closed then
    perform log_record_access(v_patient, p_encounter_id, v_view, 'visit');
  end if;
  return jsonb_build_object(
    'diagnoses', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'text', c.text, 'icd10', c.icd10_code, 'type', c.type, 'provisional', c.provisional, 'at', c.created_at,
        'by', (select full_name from profiles where id = c.created_by)) order by c.created_at)
      from condition c where c.encounter_id = p_encounter_id and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'))), '[]'::jsonb),
    'notes', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'text', o.value_text, 'at', o.effective_at,
        'by', (select full_name from profiles where id = o.performer_id)) order by o.effective_at)
      from observation o where o.encounter_id = p_encounter_id and o.code = 'note' and o.deleted_at is null), '[]'::jsonb),
    'prescriptions', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'by', (select full_name from profiles where id = coalesce(m.prescriber_id, m.created_by)), 'item', i.name_generic || coalesce(' ' || i.strength, ''), 'dose', m.dose, 'route', m.route,
        'frequency', m.frequency, 'days', m.duration_days, 'quantity', m.quantity, 'instructions', m.instructions, 'at', m.created_at,
        'dispensed', m.supply = 'room' or exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null),
        'supply', m.supply, 'givenAt', m.given_at, 'givenBy', (select full_name from profiles where id = m.given_by),
        'notGivenAt', m.not_given_at, 'notGivenReason', m.not_given_reason,
        'prescriberId', coalesce(m.prescriber_id, m.created_by), 'pending', rx_pending(m),
        'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
        'cancelledBy', (select full_name from profiles where id = m.cancelled_by),
        'prescriber', doc_person(coalesce(m.prescriber_id, m.created_by))) order by m.created_at)
      from medication_request m join item i on i.id = m.item_id where m.encounter_id = p_encounter_id and m.deleted_at is null), '[]'::jsonb),
    'orders', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'test', s.name_en, 'category', r.category, 'station', coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end), 'status', r.status, 'reason', r.reason, 'at', r.created_at, 'mine', coalesce(r.requester_id = auth.uid(), false),
        'result', (select jsonb_build_object('findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
          'corrected', d.corrected_at is not null, 'correctionReason', d.correction_reason,
          'at', coalesce(d.verified_at, d.updated_at), 'by', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
          'byPerson', doc_person(coalesce(d.verified_by, d.created_by)))
          from diagnostic_report d where d.service_request_id = r.id and d.deleted_at is null)) order by r.created_at)
      from service_request r join service s on s.id = r.service_id where r.encounter_id = p_encounter_id and r.deleted_at is null), '[]'::jsonb),
    'patient', (select jsonb_build_object('id', p.id, 'allergies', p.allergies, 'bloodGroup', p.blood_group, 'notes', p.notes, 'flags', p.flags)
                       || doc_patient(p.id, e.id)
      from encounter e join patient p on p.id = e.patient_id where e.id = p_encounter_id),
    'visit', doc_visit(p_encounter_id),
    'private', false,
    'view', v_view
  );
end
$$;

-- The tests of every visit of the patient (0063), only of the visits that may be seen.
create or replace function patient_results(p_patient_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_rows jsonb;
  v_past boolean;
  v_via text;
begin
  if not (has_perm('clinical.read') or has_perm('orders.read')) then
    return '[]'::jsonb;
  end if;
  v_via := history_via(p_patient_id);
  with seen as (
    select e.id, e.status, visit_view_with(e.id, v_via, true) as view
    from encounter e where e.patient_id = p_patient_id and e.deleted_at is null
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'encounterId', r.encounter_id, 'test', s.name_en, 'category', r.category,
      'status', r.status, 'reason', r.reason, 'orderedAt', r.created_at,
      'orderedBy', (select full_name from profiles where id = r.requester_id),
      'findings', d.findings, 'impression', d.impression,
      'verified', d.verified_at is not null, 'resultAt', coalesce(d.verified_at, d.updated_at),
      'resultBy', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by))
    ) order by r.created_at desc), '[]'::jsonb),
    coalesce(bool_or(v.status = 'closed'), false)
  into v_rows, v_past
  from service_request r
  join seen v on v.id = r.encounter_id and v.view is not null
  join service s on s.id = r.service_id
  left join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
  where r.deleted_at is null;
  if v_past then
    perform log_record_access(p_patient_id, null, coalesce(v_via, 'own'), 'results');
  end if;
  return v_rows;
end
$$;

-- The track of a visit (0083): the steps, bill and payments for whoever reads patients; its
-- vital signs, diagnoses, medicines and tests only where the record may be seen (private = true
-- otherwise). A past visit opened is logged.
create or replace function visit_journey(p_encounter_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_steps jsonb;
  v_vitals jsonb := '[]'::jsonb;
  v_dx jsonb := '[]'::jsonb;
  v_meds jsonb := '[]'::jsonb;
  v_tests jsonb := '[]'::jsonb;
  v_charges jsonb;
  v_payments jsonb;
  v_bill jsonb;
  v_enc encounter%rowtype;
  v_view text;
  v_handovers jsonb;
begin
  if not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_enc from encounter where id = p_encounter_id and deleted_at is null;
  if not found then
    raise exception 'visit not found' using errcode = 'P0002';
  end if;
  v_view := case when clinical_reader() then visit_view(p_encounter_id) end;

  select coalesce(jsonb_agg(jsonb_build_object(
      'station', q.station, 'queuedAt', q.created_at, 'calledAt', q.called_at, 'startedAt', q.started_at,
      'finishedAt', q.finished_at, 'takenBy', tb.full_name, 'assignedTo', asg.full_name,
      'referredBy', rb.full_name, 'note', case when v_view is not null then q.referral_note end,
      'enteredBy', eb.full_name,
      'service', q.service, 'department', (select d.name from department d where d.id = q.department_id)
    ) order by q.created_at), '[]'::jsonb) into v_steps
  from queue_entry q
  left join profiles tb on tb.id = q.taken_by
  left join profiles asg on asg.id = q.assigned_to
  left join profiles rb on rb.id = q.referred_by
  left join profiles eb on eb.id = q.entered_by
  where q.encounter_id = p_encounter_id and q.deleted_at is null;

  if v_view is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
        'code', o.code, 'value', o.value_num, 'unit', o.unit, 'at', o.effective_at,
        'by', (select full_name from profiles where id = o.performer_id)
      ) order by o.effective_at), '[]'::jsonb) into v_vitals
    from observation o where o.encounter_id = p_encounter_id and o.deleted_at is null and o.code <> 'note';

    select coalesce(jsonb_agg(jsonb_build_object(
        'text', c.text, 'icd10', c.icd10_code, 'type', c.type, 'provisional', c.provisional, 'at', c.created_at,
        'by', (select full_name from profiles where id = c.created_by)
      ) order by c.created_at), '[]'::jsonb) into v_dx
    from condition c where c.encounter_id = p_encounter_id and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'));

    select coalesce(jsonb_agg(jsonb_build_object(
        'item', i.name_generic || coalesce(' ' || i.strength, ''), 'quantity', m.quantity, 'dose', m.dose,
        'frequency', m.frequency, 'days', m.duration_days, 'supply', m.supply, 'givenAt', m.given_at,
        'givenBy', (select full_name from profiles where id = m.given_by), 'at', m.created_at,
        'by', (select full_name from profiles where id = m.created_by),
        'dispensed', exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null),
        'notGivenAt', m.not_given_at, 'notGivenReason', m.not_given_reason,
        'notGivenBy', (select full_name from profiles where id = m.not_given_by),
        'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
        'cancelledBy', (select full_name from profiles where id = m.cancelled_by)
      ) order by m.created_at), '[]'::jsonb) into v_meds
    from medication_request m join item i on i.id = m.item_id
    where m.encounter_id = p_encounter_id and m.deleted_at is null;

    select coalesce(jsonb_agg(jsonb_build_object(
        'test', s.name_en, 'status', r.status, 'priority', r.priority, 'at', r.created_at,
        'by', (select full_name from profiles where id = r.created_by),
        'result', (select coalesce(dr.impression, dr.findings) from diagnostic_report dr where dr.service_request_id = r.id and dr.deleted_at is null order by dr.created_at desc limit 1)
      ) order by r.created_at), '[]'::jsonb) into v_tests
    from service_request r left join service s on s.id = r.service_id
    where r.encounter_id = p_encounter_id and r.deleted_at is null;

    if v_enc.status = 'closed' then
      perform log_record_access(v_enc.patient_id, p_encounter_id, v_view, 'journey');
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'description', l.description, 'quantity', l.quantity, 'unitPrice', l.unit_price,
      'total', round(l.quantity * l.unit_price), 'office', l.office, 'at', l.created_at,
      'by', (select full_name from profiles where id = l.entered_by)
    ) order by l.created_at), '[]'::jsonb) into v_charges
  from invoice_line l join invoice i on i.id = l.invoice_id
  where i.encounter_id = p_encounter_id and l.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'amount', p.amount, 'method', p.method, 'reference', p.reference, 'at', p.paid_at,
      'by', (select full_name from profiles where id = p.cashier_id)
    ) order by p.paid_at), '[]'::jsonb) into v_payments
  from payment p join invoice i on i.id = p.invoice_id
  where i.encounter_id = p_encounter_id and p.deleted_at is null;

  select jsonb_build_object('status', b.status, 'total', b.total, 'balance', b.balance, 'paid', b.paid,
                            'number', b.number, 'settledBy', b.settled_by, 'settledAt', b.settled_at)
  into v_bill from visit_bill b where b.encounter_id = p_encounter_id;

  -- who handed the patient over to whom (20261129090000_handover); the note and the reason are
  -- clinical: for the two colleagues and those who may see this visit's record
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', h.id, 'station', h.station, 'at', h.created_at, 'from', f.full_name, 'to', t.full_name,
      'note', case when v_view is not null or auth.uid() in (h.from_user, h.to_user) then h.note end,
      'status', h.status, 'answeredAt', h.answered_at,
      'answeredBy', (select full_name from profiles where id = h.answered_by),
      'reason', case when v_view is not null or auth.uid() in (h.from_user, h.to_user) then h.reason end
    ) order by h.created_at), '[]'::jsonb) into v_handovers
  from patient_handover h
  join profiles f on f.id = h.from_user
  join profiles t on t.id = h.to_user
  where h.encounter_id = p_encounter_id and h.deleted_at is null;

  return jsonb_build_object(
    'encounterId', v_enc.id, 'arrivedAt', v_enc.arrived_at, 'status', v_enc.status, 'closedAt', v_enc.closed_at,
    'triage', v_enc.triage_level,
    'triageReason', case when v_view is not null then v_enc.triage_reason end,
    'closedBy', (select full_name from profiles where id = v_enc.closed_by),
    -- the track: treatment finished, why the patient left, what they came for
    'treatmentDoneAt', v_enc.clinical_done_at, 'leftReason', v_enc.left_reason, 'service', v_enc.service,
    'steps', v_steps, 'vitals', v_vitals, 'diagnoses', v_dx, 'medicines', v_meds, 'tests', v_tests,
    'charges', v_charges, 'payments', v_payments, 'bill', v_bill, 'handovers', v_handovers,
    'private', v_view is null
  );
end
$$;

-- update_patient (0084), plus E: at level 1 the safety fields the person cannot see are neither
-- cleared nor replaced (the form sends them empty); one may be added where none is recorded.
create or replace function update_patient(p_patient_id uuid, p_fields jsonb)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_birth date := nullif(p_fields ->> 'birth_date', '')::date;
  v_age integer := nullif(p_fields ->> 'age_years', '')::integer;
  v_allergies text;
  v_none boolean;
  v_old patient%rowtype;
begin
  if not has_perm('patient.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_fields ? 'extra' and jsonb_typeof(p_fields -> 'extra') <> 'object' then
    raise exception 'extra must be an object' using errcode = '22023';
  end if;
  if p_fields ? 'allergies_none' and jsonb_typeof(p_fields -> 'allergies_none') not in ('boolean', 'null') then
    raise exception 'allergies_none must be true or false' using errcode = '22023';
  end if;
  if patient_level(p_patient_id) = 'identity' then
    select * into v_old from patient where id = p_patient_id;
    p_fields := p_fields - 'allergies_none';
    if v_old.allergies is not null or v_old.allergies_none
       or nullif(trim(coalesce(p_fields ->> 'allergies', '')), '') is null then
      p_fields := p_fields - 'allergies';
    end if;
    if v_old.blood_group is not null or nullif(trim(coalesce(p_fields ->> 'blood_group', '')), '') is null then
      p_fields := p_fields - 'blood_group';
    end if;
    if v_old.notes is not null or nullif(trim(coalesce(p_fields ->> 'notes', '')), '') is null then
      p_fields := p_fields - 'notes';
    end if;
    -- the manager's "medical" extra fields: never shown at this level, so a value already there
    -- is kept as it is; an empty one may be filled in (like the allergies above)
    if p_fields ? 'extra' then
      p_fields := jsonb_set(p_fields, '{extra}',
        ((p_fields -> 'extra') - private_extra_keys())
        || coalesce((select jsonb_object_agg(k,
                              case when nullif(trim(coalesce(v_old.extra ->> k, '')), '') is not null
                                   then v_old.extra -> k else p_fields -> 'extra' -> k end)
                     from unnest(private_extra_keys()) k
                     where coalesce(v_old.extra, '{}'::jsonb) ? k or (p_fields -> 'extra') ? k), '{}'::jsonb));
    end if;
  end if;
  v_allergies := nullif(trim(coalesce(p_fields ->> 'allergies', '')), '');
  v_none := coalesce((p_fields ->> 'allergies_none')::boolean, false);
  if v_birth is null and v_age is not null then
    v_birth := (current_date - make_interval(years => v_age))::date;
  end if;
  update patient set
    surname = coalesce(nullif(trim(p_fields ->> 'surname'), ''), surname),
    given_names = coalesce(nullif(trim(p_fields ->> 'given_names'), ''), given_names),
    sex = coalesce((p_fields ->> 'sex')::sex, sex),
    birth_date = coalesce(v_birth, birth_date),
    age_estimated = case when v_birth is not null then (v_age is not null and (p_fields ->> 'birth_date') is null) else age_estimated end,
    national_id = case when p_fields ? 'national_id' then nullif(regexp_replace(coalesce(p_fields ->> 'national_id', ''), '[^0-9]', '', 'g'), '') else national_id end,
    phone_1 = case when p_fields ? 'phone_1' then nullif(trim(p_fields ->> 'phone_1'), '') else phone_1 end,
    phone_2 = case when p_fields ? 'phone_2' then nullif(trim(p_fields ->> 'phone_2'), '') else phone_2 end,
    district = case when p_fields ? 'district' then nullif(trim(p_fields ->> 'district'), '') else district end,
    sector = case when p_fields ? 'sector' then nullif(trim(p_fields ->> 'sector'), '') else sector end,
    cell = case when p_fields ? 'cell' then nullif(trim(p_fields ->> 'cell'), '') else cell end,
    village = case when p_fields ? 'village' then nullif(trim(p_fields ->> 'village'), '') else village end,
    occupation = case when p_fields ? 'occupation' then nullif(trim(p_fields ->> 'occupation'), '') else occupation end,
    emergency_name = case when p_fields ? 'emergency_name' then nullif(trim(p_fields ->> 'emergency_name'), '') else emergency_name end,
    emergency_phone = case when p_fields ? 'emergency_phone' then nullif(trim(p_fields ->> 'emergency_phone'), '') else emergency_phone end,
    blood_group = case when p_fields ? 'blood_group' then nullif(trim(p_fields ->> 'blood_group'), '') else blood_group end,
    -- an allergy written wins; "no known allergies" clears the text
    allergies = case when v_allergies is not null then v_allergies
                     when p_fields ? 'allergies' then null
                     when v_none then null
                     else allergies end,
    allergies_none = case when v_allergies is not null then false
                          when p_fields ? 'allergies_none' then v_none
                          else allergies_none end,
    notes = case when p_fields ? 'notes' then nullif(trim(p_fields ->> 'notes'), '') else notes end,
    ubudehe_category = case when p_fields ? 'ubudehe_category' then nullif(p_fields ->> 'ubudehe_category', '')::smallint else ubudehe_category end,
    language = coalesce((p_fields ->> 'language')::lang, language),
    preferred_channel = coalesce((p_fields ->> 'preferred_channel')::contact_channel, preferred_channel),
    -- Replace the whole map; the app always sends the full set of extra values.
    extra = case when p_fields ? 'extra' then p_fields -> 'extra' else extra end
  where id = p_patient_id and deleted_at is null;
  if not found then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;
end
$$;

-- ---------------------------------------------------------------- the table policies
-- Reading a clinical table directly gives the rows of the visits the person may see.
drop policy if exists observation_select on observation;
create policy observation_select on observation for select to authenticated
  using (has_perm('clinical.read') and visit_view(encounter_id) is not null);
drop policy if exists condition_select on condition;
create policy condition_select on condition for select to authenticated
  using (has_perm('clinical.read') and visit_view(encounter_id) is not null);
drop policy if exists procedure_select on procedure;
create policy procedure_select on procedure for select to authenticated
  using (has_perm('clinical.read') and visit_view(encounter_id) is not null);
drop policy if exists service_request_select on service_request;
create policy service_request_select on service_request for select to authenticated
  using (has_perm('orders.read') and visit_view(encounter_id) is not null);
drop policy if exists diagnostic_report_select on diagnostic_report;
create policy diagnostic_report_select on diagnostic_report for select to authenticated
  using (has_perm('orders.read') and exists (
    select 1 from service_request r
    where r.id = diagnostic_report.service_request_id and visit_view(r.encounter_id) is not null));
drop policy if exists medication_request_select on medication_request;
create policy medication_request_select on medication_request for select to authenticated
  using (has_perm('prescription.read') and visit_view(encounter_id) is not null);
drop policy if exists medication_dispense_select on medication_dispense;
create policy medication_dispense_select on medication_dispense for select to authenticated
  using (has_perm('prescription.read') and visit_view(encounter_id) is not null);
drop policy if exists prescription_doc_read on prescription_doc;
create policy prescription_doc_read on prescription_doc for select
  using ((has_perm('prescription.read') or has_perm('clinical.read')) and visit_view(encounter_id) is not null);
drop policy if exists vaccination_select on vaccination;
create policy vaccination_select on vaccination for select to authenticated
  using (has_perm('clinical.read') and case when encounter_id is not null then visit_view(encounter_id) is not null
                                          else history_via(patient_id) is not null end);
drop policy if exists fp_event_select on fp_event;
create policy fp_event_select on fp_event for select to authenticated
  using (has_perm('clinical.read') and case when encounter_id is not null then visit_view(encounter_id) is not null
                                          else history_via(patient_id) is not null end);
drop policy if exists hiv_test_select on hiv_test;
create policy hiv_test_select on hiv_test for select to authenticated
  using (has_perm('sensitive.read') and case when encounter_id is not null then visit_view(encounter_id) is not null
                                            else history_via(patient_id) is not null end);
drop policy if exists document_select on document;
create policy document_select on document for select to authenticated
  using (has_perm('patient.read') and case when encounter_id is not null then visit_view(encounter_id) is not null
                                          else history_via(patient_id) is not null end);

-- ---------------------------------------------------------------- B requests, C emergencies
-- Who answers a request about the patient: the managers and the heads in charge.
create or replace function record_access_approvers(p_patient_id uuid)
returns uuid[]
language sql stable security definer set search_path = public
as $$
  select coalesce(array_agg(distinct x.id), '{}')
  from (
    select p.id from profiles p where p.role = 'manager' and p.active and p.deleted_at is null
    union
    select unnest(heads_in_charge(p_patient_id))
  ) x
$$;

-- May the signed-in person answer requests about the patient?
create or replace function may_answer_access(p_patient_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select is_manager() or coalesce(auth.uid() = any (heads_in_charge(p_patient_id)), false)
$$;

-- The checks shared by a request and an emergency access: signed in, reads clinical records,
-- treats the patient now, has no access already, gave a reason. Returns the visit treated.
create or replace function record_access_check(p_patient_id uuid, p_reason text)
returns uuid
language plpgsql stable security definer set search_path = public
as $$
declare
  v_enc uuid;
begin
  if auth.uid() is null or not has_perm('clinical.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not exists (select 1 from patient where id = p_patient_id and deleted_at is null) then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;
  v_enc := treating_visit(p_patient_id);
  if v_enc is null then
    raise exception 'not allowed: only the people treating the patient now may ask to see the past records'
      using errcode = '42501', hint = 'not_treating';
  end if;
  if history_via(p_patient_id) is not null then
    raise exception 'you already see the past records of this patient'
      using errcode = '22023', hint = 'already_allowed';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why you need the past records' using errcode = '22023', hint = 'reason_needed';
  end if;
  return v_enc;
end
$$;

-- B: ask the manager and the heads in charge to see the patient's past records. A request
-- still waiting for this visit is returned as it is.
create or replace function request_record_access(p_patient_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_enc uuid := record_access_check(p_patient_id, p_reason);
  v_req record_access_request%rowtype;
  v_name text;
  v_file text;
  v_me text;
  v_to uuid[];
begin
  select * into v_req from record_access_request r
  where r.patient_id = p_patient_id and r.encounter_id = v_enc and r.requested_by = auth.uid()
    and r.kind = 'request' and r.status = 'pending'
  order by r.created_at desc limit 1;
  if found then
    return jsonb_build_object('id', v_req.id, 'status', v_req.status, 'existing', true,
                              'approvers', cardinality(record_access_approvers(p_patient_id)));
  end if;
  insert into record_access_request (patient_id, encounter_id, requested_by, kind, reason)
  values (p_patient_id, v_enc, auth.uid(), 'request', trim(p_reason))
  returning * into v_req;
  select p.surname || ' ' || p.given_names, p.file_number into v_name, v_file from patient p where p.id = p_patient_id;
  select full_name into v_me from profiles where id = auth.uid();
  v_to := array(select x from unnest(record_access_approvers(p_patient_id)) x where x <> auth.uid());
  insert into notification (kind, params, title, body, link, urgent, recipient_user, created_by)
  select 'access_request',
         jsonb_build_object('requestId', v_req.id, 'patientId', p_patient_id, 'name', v_name, 'file', v_file,
                            'by', v_me, 'reason', v_req.reason),
         'Access to past records requested',
         v_me || ' asks to see the past records of ' || v_name || ' (' || coalesce(v_file, '') || '): ' || v_req.reason,
         '/app/record-access?request=' || v_req.id, false, x, auth.uid()
  from unnest(v_to) x;
  return jsonb_build_object('id', v_req.id, 'status', v_req.status, 'existing', false,
                            'approvers', cardinality(v_to));
end
$$;

-- C: open the past records at once in an emergency. Urgent notice to the manager and the heads
-- in charge; a red entry in the access log; the manager reviews it later.
create or replace function emergency_record_access(p_patient_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_enc uuid := record_access_check(p_patient_id, p_reason);
  v_req record_access_request%rowtype;
  v_name text;
  v_file text;
  v_me text;
begin
  insert into record_access_request (patient_id, encounter_id, requested_by, kind, reason, status, answered_at)
  values (p_patient_id, v_enc, auth.uid(), 'emergency', trim(p_reason), 'approved', now())
  returning * into v_req;
  -- a request still waiting for this visit is no longer needed
  with c as (
    update record_access_request set status = 'cancelled', answered_at = now(), answer_note = 'emergency access opened'
    where patient_id = p_patient_id and encounter_id = v_enc and requested_by = auth.uid()
      and kind = 'request' and status = 'pending'
    returning id
  )
  delete from notification n using c
  where n.kind = 'access_request' and (n.params ->> 'requestId') = c.id::text;
  insert into record_access_entry (actor_id, patient_id, encounter_id, via, what, request_id)
  values (auth.uid(), p_patient_id, null, 'emergency', 'emergency', v_req.id);
  select p.surname || ' ' || p.given_names, p.file_number into v_name, v_file from patient p where p.id = p_patient_id;
  select full_name into v_me from profiles where id = auth.uid();
  insert into notification (kind, params, title, body, link, urgent, recipient_user, created_by)
  select 'access_emergency',
         jsonb_build_object('requestId', v_req.id, 'patientId', p_patient_id, 'name', v_name, 'file', v_file,
                            'by', v_me, 'reason', v_req.reason),
         'Emergency access to past records',
         v_me || ' opened the past records of ' || v_name || ' (' || coalesce(v_file, '') || ') in an emergency: ' || v_req.reason,
         '/app/record-access?request=' || v_req.id, true, x, auth.uid()
  from unnest(record_access_approvers(p_patient_id)) x
  where x <> auth.uid();
  return jsonb_build_object('id', v_req.id, 'status', v_req.status, 'via', 'emergency');
end
$$;

-- B: the first approver to answer approves or refuses (a refusal says why). The requester is told.
create or replace function answer_record_access(p_request_id uuid, p_approve boolean, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_req record_access_request%rowtype;
  v_name text;
  v_me text;
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if auth.uid() is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_req from record_access_request where id = p_request_id for update;
  if not found or v_req.kind <> 'request' then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  if v_req.requested_by = auth.uid() or not may_answer_access(v_req.patient_id) then
    raise exception 'not allowed: the manager or a head of a department in charge of the patient answers'
      using errcode = '42501', hint = 'not_approver';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'this request was already answered (%)', v_req.status
      using errcode = '22023', hint = 'already_answered',
            detail = coalesce((select full_name from profiles where id = v_req.answered_by), '');
  end if;
  if p_approve is null then
    raise exception 'approve or refuse' using errcode = '22023';
  end if;
  if not p_approve and (v_note is null or length(v_note) < 3) then
    raise exception 'say why the request is refused' using errcode = '22023', hint = 'reason_needed';
  end if;
  if p_approve and not exists (select 1 from encounter e where e.id = v_req.encounter_id and e.status = 'open' and e.deleted_at is null) then
    raise exception 'the visit is closed: the access would end at once' using errcode = '22023', hint = 'visit_closed';
  end if;
  update record_access_request
  set status = case when p_approve then 'approved' else 'refused' end,
      answered_by = auth.uid(), answered_at = now(), answer_note = v_note
  where id = p_request_id
  returning * into v_req;
  -- the other approvers no longer need to answer
  delete from notification where kind = 'access_request' and (params ->> 'requestId') = p_request_id::text;
  select p.surname || ' ' || p.given_names into v_name from patient p where p.id = v_req.patient_id;
  select full_name into v_me from profiles where id = auth.uid();
  insert into notification (kind, params, title, body, link, urgent, recipient_user, created_by)
  values ('access_answer',
          jsonb_build_object('requestId', v_req.id, 'patientId', v_req.patient_id, 'name', v_name,
                             'approved', p_approve, 'by', v_me, 'reason', v_note),
          case when p_approve then 'Access to past records approved' else 'Access to past records refused' end,
          v_me || case when p_approve then ' approved your request to see the past records of '
                       else ' refused your request to see the past records of ' end
            || v_name || coalesce(': ' || v_note, '') || '.',
          '/app/patient?id=' || v_req.patient_id, false, v_req.requested_by, auth.uid());
  return jsonb_build_object('id', v_req.id, 'status', v_req.status);
end
$$;

-- The requester withdraws a request still waiting.
create or replace function cancel_record_access(p_request_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  update record_access_request set status = 'cancelled', answered_at = now()
  where id = p_request_id and requested_by = auth.uid() and kind = 'request' and status = 'pending';
  if not found then
    raise exception 'no request of yours waiting' using errcode = 'P0002', hint = 'not_found';
  end if;
  delete from notification where kind = 'access_request' and (params ->> 'requestId') = p_request_id::text;
end
$$;

-- C: the manager reviews an emergency access (with a comment).
create or replace function review_emergency_access(p_request_id uuid, p_note text default null)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not is_manager() then
    raise exception 'not allowed: the manager reviews emergency accesses' using errcode = '42501', hint = 'not_manager';
  end if;
  update record_access_request
  set reviewed_by = auth.uid(), reviewed_at = now(), review_note = nullif(trim(coalesce(p_note, '')), '')
  where id = p_request_id and kind = 'emergency';
  if not found then
    raise exception 'emergency access not found' using errcode = 'P0002';
  end if;
end
$$;

-- B/C: the requests and emergency accesses the signed-in person may see (the last 90 days):
--   'pending'   waiting for an answer they may give
--   'mine'      their own
--   'emergency' emergency accesses (the manager: those to review first)
--   'all'       every one they may see (as requester, approver or the manager)
create or replace function record_access_requests(p_scope text default 'pending')
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'kind', r.kind, 'status', r.status,
      'patientId', r.patient_id, 'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
      'encounterId', r.encounter_id, 'visitReference', e.reference, 'visitOpen', e.status = 'open',
      'requestedById', r.requested_by, 'requestedBy', rq.full_name, 'requestedByRole', rq.role,
      'reason', r.reason, 'at', r.created_at,
      'answeredBy', (select full_name from profiles where id = r.answered_by),
      'answeredAt', r.answered_at, 'answerNote', r.answer_note,
      'active', r.status = 'approved' and e.status = 'open',
      'mine', r.requested_by = auth.uid(),
      'canAnswer', r.kind = 'request' and r.status = 'pending' and r.requested_by <> auth.uid()
                   and e.status = 'open' and may_answer_access(r.patient_id),
      'canCancel', r.kind = 'request' and r.status = 'pending' and r.requested_by = auth.uid(),
      'reviewedBy', (select full_name from profiles where id = r.reviewed_by),
      'reviewedAt', r.reviewed_at, 'reviewNote', r.review_note,
      'canReview', r.kind = 'emergency' and r.reviewed_at is null and is_manager()
    ) order by (r.kind = 'emergency' and r.reviewed_at is null) desc, (r.status = 'pending') desc, r.created_at desc), '[]'::jsonb)
  from record_access_request r
  join patient p on p.id = r.patient_id
  join encounter e on e.id = r.encounter_id
  join profiles rq on rq.id = r.requested_by
  where auth.uid() is not null
    and r.created_at > now() - interval '90 days'
    and (r.requested_by = auth.uid() or may_answer_access(r.patient_id))
    and case coalesce(p_scope, 'pending')
          when 'pending' then r.kind = 'request' and r.status = 'pending' and r.requested_by <> auth.uid()
                              and e.status = 'open'
          when 'mine' then r.requested_by = auth.uid()
          when 'emergency' then r.kind = 'emergency'
          else true
        end
$$;

-- ---------------------------------------------------------------- D the access log
create or replace function access_entry_json(a record_access_entry)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'id', a.id, 'at', a.at, 'actorId', a.actor_id, 'actor', pr.full_name, 'actorRole', pr.role,
    'patientId', a.patient_id, 'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
    'encounterId', a.encounter_id, 'visitReference', e.reference,
    'via', a.via, 'what', a.what, 'requestId', a.request_id, 'reason', r.reason,
    'emergency', a.via = 'emergency',
    'reviewed', r.reviewed_at is not null, 'reviewedBy', (select full_name from profiles where id = r.reviewed_by),
    'reviewNote', r.review_note)
  from patient p
  left join profiles pr on pr.id = a.actor_id
  left join encounter e on e.id = a.encounter_id
  left join record_access_request r on r.id = a.request_id
  where p.id = a.patient_id
$$;

-- The manager's page "Record access": who opened past records, filtered (default: 30 days).
create or replace function record_access_log(
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_patient_id uuid default null,
  p_actor uuid default null,
  p_via text default null,
  p_limit integer default 100,
  p_offset integer default 0
)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_from timestamptz := coalesce(p_from, now() - interval '30 days');
  v_to timestamptz := coalesce(p_to, now() + interval '1 minute');
  v_total integer;
  v_rows jsonb;
begin
  if not is_manager() then
    raise exception 'not allowed: the manager reads the record access log' using errcode = '42501';
  end if;
  select count(*) into v_total
  from record_access_entry a
  where a.at >= v_from and a.at < v_to
    and (p_patient_id is null or a.patient_id = p_patient_id)
    and (p_actor is null or a.actor_id = p_actor)
    and (p_via is null or a.via = p_via);
  select coalesce(jsonb_agg(access_entry_json(x) order by x.at desc), '[]'::jsonb) into v_rows
  from (
    select a.* from record_access_entry a
    where a.at >= v_from and a.at < v_to
      and (p_patient_id is null or a.patient_id = p_patient_id)
      and (p_actor is null or a.actor_id = p_actor)
      and (p_via is null or a.via = p_via)
    order by a.at desc
    limit greatest(1, least(coalesce(p_limit, 100), 500)) offset greatest(coalesce(p_offset, 0), 0)
  ) x;
  return jsonb_build_object('total', v_total, 'rows', v_rows,
    'unreviewed', (select count(*) from record_access_request r where r.kind = 'emergency' and r.reviewed_at is null));
end
$$;

-- The patient file's "Who looked": the manager and the heads in charge.
create or replace function patient_access_log(p_patient_id uuid, p_limit integer default 50)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
begin
  if not may_answer_access(p_patient_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(access_entry_json(x) order by x.at desc)
    from (select a.* from record_access_entry a where a.patient_id = p_patient_id
          order by a.at desc limit greatest(1, least(coalesce(p_limit, 50), 200))) x), '[]'::jsonb);
end
$$;

-- ---------------------------------------------------------------- grants
-- Internal: written by the reading functions only.
revoke all on function log_record_access(uuid, uuid, text, text) from public, anon, authenticated;
revoke all on function record_access_check(uuid, text) from public, anon, authenticated;
revoke all on function patient_safety_summary(uuid) from public, anon, authenticated;
revoke all on function access_entry_json(record_access_entry) from public, anon, authenticated;
revoke all on function record_access_approvers(uuid) from public, anon, authenticated;
-- The rules. Only visit_view and history_via are called by the table policies (as the reader);
-- the others run inside the security definer functions and are not for asking about colleagues.
revoke all on function clinical_reader(), took_part(uuid, uuid), treated(uuid, uuid), visit_departments(uuid),
  heads_in_charge(uuid), access_in_force(uuid), treating_visit(uuid), patient_level(uuid), may_answer_access(uuid),
  visit_view_with(uuid, text, boolean), patient_access_with(uuid, text, uuid)
  from public, anon, authenticated;
revoke all on function history_via(uuid), visit_view(uuid) from public, anon;
grant execute on function visit_view(uuid), history_via(uuid) to authenticated;
revoke all on function patient_access(uuid), request_record_access(uuid, text), emergency_record_access(uuid, text),
  answer_record_access(uuid, boolean, text), cancel_record_access(uuid), review_emergency_access(uuid, text),
  record_access_requests(text), record_access_log(timestamptz, timestamptz, uuid, uuid, text, integer, integer),
  patient_access_log(uuid, integer) from public, anon;
grant execute on function patient_access(uuid), request_record_access(uuid, text), emergency_record_access(uuid, text),
  answer_record_access(uuid, boolean, text), cancel_record_access(uuid), review_emergency_access(uuid, text),
  record_access_requests(text), record_access_log(timestamptz, timestamptz, uuid, uuid, text, integer, integer),
  patient_access_log(uuid, integer) to authenticated;
revoke all on function patient_file(uuid), visit_clinical(uuid), patient_results(uuid), visit_journey(uuid),
  update_patient(uuid, jsonb) from public, anon;
grant execute on function patient_file(uuid), visit_clinical(uuid), patient_results(uuid), visit_journey(uuid),
  update_patient(uuid, jsonb) to authenticated;

-- ---------------------------------------------------------------- H the other ways in
-- The latest vital signs of a visit (0019): the open visits as before (the queues, triage and the
-- nurse's paper sheet need them); a closed visit only for whoever may see its record.
create or replace view visit_vitals with (security_invoker = false) as
  select distinct on (o.encounter_id, o.code)
         o.encounter_id, o.code, o.value_num, o.unit, o.effective_at,
         pm.full_name as measured_by, pe.full_name as entered_by
  from observation o
  join encounter e on e.id = o.encounter_id and e.deleted_at is null
  left join profiles pm on pm.id = o.performer_id
  left join profiles pe on pe.id = o.created_by
  where o.deleted_at is null
    and o.code in ('bp_sys', 'bp_dia', 'pulse', 'temp', 'resp', 'spo2', 'weight', 'height', 'muac')
    and (has_perm('clinical.read') or has_perm('vitals.write'))
    and (e.status = 'open' or visit_view(o.encounter_id) is not null)
  order by o.encounter_id, o.code, o.effective_at desc;
revoke all on visit_vitals from anon;
grant select on visit_vitals to authenticated;

-- The queue board runs with its owner's rights, because the triage reason and the referral note
-- are no longer readable from the tables (below). It filters as the tables' policies did: queue
-- and patient readers; colleagues' names for staff readers (or oneself). Open visits only.
create or replace view queue_board with (security_invoker = false) as
  select q.id as queue_id, q.encounter_id, q.station, q.ticket_no, q.priority,
         q.created_at as queued_at, q.called_at, q.started_at, q.finished_at,
         e.patient_id, e.triage_level, e.arrived_at, e.type as encounter_type,
         p.file_number, p.surname, p.given_names, p.sex, p.birth_date, p.phone_1,
         q.pool_id, tb.full_name as taken_by_name,
         q.assigned_to, asg.full_name as assigned_name, rb.full_name as referred_by_name,
         -- the referral note is clinical: for clinical readers who may see the visit
         case when has_perm('clinical.read') and visit_view(q.encounter_id) is not null
              then q.referral_note end as referral_note,
         q.return_station,
         v.effective_at as vitals_at, v.measured_by as vitals_by,
         q.department_id, dep.name as department_name, queue_entry_for_me(q.id) as can_work,
         q.taken_by, coalesce(q.service, e.service) as service,
         (q.assigned_to = auth.uid() or q.taken_by = auth.uid()
          or (q.assigned_to is null and q.taken_by is null
              and serves_station(auth.uid(), q.station, q.service))
          or coalesce(ho.status = 'pending' and ho.to_user = auth.uid(), false)) as for_me,
         -- the latest handover of the entry (20261129090000_handover); its note is clinical: for
         -- the two colleagues and those who read clinical records
         ho.id as handover_id, ho.status as handover_status,
         ho.from_user as handover_from, hf.full_name as handover_from_name,
         ho.to_user as handover_to, ht.full_name as handover_to_name,
         case when auth.uid() in (ho.from_user, ho.to_user)
                   or (has_perm('clinical.read') and visit_view(q.encounter_id) is not null)
              then ho.note end as handover_note,
         ho.created_at as handover_at, ho.answered_at as handover_answered_at
  from queue_entry q
  join encounter e on e.id = q.encounter_id
  join patient p on p.id = e.patient_id
  left join profiles tb on tb.id = q.taken_by and (tb.id = auth.uid() or has_perm('staff.read'))
  left join profiles asg on asg.id = q.assigned_to and (asg.id = auth.uid() or has_perm('staff.read'))
  left join profiles rb on rb.id = q.referred_by and (rb.id = auth.uid() or has_perm('staff.read'))
  left join department dep on dep.id = q.department_id and dep.deleted_at is null
  left join lateral last_vitals_stamp(q.encounter_id) v on true
  left join lateral (select h.* from patient_handover h
                     where h.queue_id = q.id and h.status in ('pending', 'taken') and h.deleted_at is null
                     order by h.created_at desc limit 1) ho on true
  left join profiles hf on hf.id = ho.from_user
  left join profiles ht on ht.id = ho.to_user
  where q.deleted_at is null and e.status = 'open'
    and has_perm('queue.read') and has_perm('patient.read');
revoke all on queue_board from anon;
grant select on queue_board to authenticated;

-- Reading the tables directly gives no safety field, triage reason or referral note: those come
-- through the reading functions, by level. Column privileges: a column added to these tables later
-- must be granted here too (a plain "grant select on patient" would open them all again).
revoke select on patient from authenticated;
grant select (id, created_at, created_by, device_id, received_at, updated_at, updated_by, deleted_at, version,
              file_number, surname, given_names, sex, birth_date, age_estimated, national_id, id_verified,
              id_source, phone_1, phone_2, preferred_channel, language, district, sector, cell, village,
              ubudehe_category, occupation, emergency_name, emergency_phone, guardian_patient_id,
              consent_treatment, consent_messages, consent_insurer, merged_into, photo_blob_id, no_national_id)
  on patient to authenticated;
revoke select on encounter from authenticated;
grant select (id, created_at, created_by, device_id, received_at, updated_at, updated_by, deleted_at, version,
              patient_id, type, arrived_at, practitioner_id, triage_level, coverage_id, appointment_id,
              status, closed_at, closed_by, reopen_reason, clinical_done_at, left_reason, service,
              intended_to, reference)
  on encounter to authenticated;
revoke select on queue_entry from authenticated;
grant select (id, created_at, created_by, device_id, received_at, updated_at, updated_by, deleted_at, version,
              encounter_id, station, ticket_no, priority, called_at, started_at, finished_at, entered_by,
              pool_id, taken_by, assigned_to, referred_by, return_station, return_to, department_id, service)
  on queue_entry to authenticated;

-- The patient search (0026): identity for everyone; the allergy and safety marks for the people
-- who read clinical records.
create or replace function patients_list(p_query text default null, p_limit integer default 50, p_offset integer default 0)
returns jsonb
language sql stable security definer set search_path = public
as $$
  with q as (select nullif(trim(coalesce(p_query, '')), '') as text),
  base as (
    select p.*,
           (select max(e.arrived_at) from encounter e where e.patient_id = p.id and e.deleted_at is null) as last_visit_at,
           (select count(*) from encounter e where e.patient_id = p.id and e.deleted_at is null) as visits,
           (select e.id from encounter e where e.patient_id = p.id and e.status = 'open' and e.deleted_at is null order by e.arrived_at desc limit 1) as open_encounter_id,
           (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id where e.patient_id = p.id and i.deleted_at is null and i.status <> 'credited') as balance_due
    from patient p, q
    where has_perm('patient.read') and p.deleted_at is null and p.merged_into is null
      and (q.text is null
        or upper(p.file_number) = upper(q.text)
        or p.national_id = q.text
        or (length(regexp_replace(q.text, '[^0-9]', '', 'g')) >= 4 and regexp_replace(coalesce(p.phone_1, ''), '[^0-9]', '', 'g') like '%' || regexp_replace(q.text, '[^0-9]', '', 'g') || '%')
        or (p.surname || ' ' || p.given_names) ilike '%' || q.text || '%'
        or (p.given_names || ' ' || p.surname) ilike '%' || q.text || '%')
  )
  select jsonb_build_object(
    'total', (select count(*) from base),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id', b.id, 'fileNumber', b.file_number, 'surname', b.surname, 'givenNames', b.given_names,
        'sex', b.sex, 'birthDate', b.birth_date, 'phone', b.phone_1, 'sector', b.sector,
        'registeredAt', b.created_at, 'lastVisitAt', b.last_visit_at, 'visits', b.visits,
        'openEncounterId', b.open_encounter_id, 'balanceDue', b.balance_due,
        -- 0088: the safety marks for the people who read clinical records only ("VIP" for all)
        'flags', case when clinical_reader() then b.flags
                      else jsonb_strip_nulls(jsonb_build_object('vip', b.flags -> 'vip')) end,
        'hasAllergies', case when clinical_reader() then b.allergies is not null else false end
      ) order by coalesce(b.last_visit_at, b.created_at) desc)
      from (select * from base order by coalesce(last_visit_at, created_at) desc limit greatest(1, least(p_limit, 200)) offset greatest(0, p_offset)) b), '[]'::jsonb)
  )
$$;

-- The analytics of one person (0086), for the heads and assistants of their department: what was
-- written in a visit (a diagnosis, a medicine, a result) only where the reader may see that visit.
create or replace function staff_activity_detail(
  p_user uuid,
  p_from date default null,
  p_to date default null,
  p_kind text default null,
  p_limit integer default 500
)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_manager boolean := is_manager();
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_start timestamptz;
  v_end timestamptz;
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 500);
  v_person jsonb;
  v_result jsonb;
begin
  if not v_manager and not exists (
    select 1
    from staff_department mine
    join department d on d.id = mine.department_id and d.deleted_at is null
    join profiles me on me.id = mine.profile_id and me.active
    join staff_department theirs on theirs.department_id = mine.department_id
    where mine.profile_id = auth.uid() and mine.position in ('head', 'assistant') and theirs.profile_id = p_user) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_kind is not null and not (p_kind = any (analytics_kinds(v_manager))) then
    raise exception 'unknown kind of work' using errcode = '22023';
  end if;
  if v_to < v_from then
    select v_to, v_from into v_from, v_to;
  end if;
  v_start := v_from::timestamp at time zone 'Africa/Kigali';
  v_end := (v_to + 1)::timestamp at time zone 'Africa/Kigali';
  select jsonb_build_object('id', p.id, 'name', p.full_name, 'role', p.role, 'staffId', p.staff_id,
                            'active', p.active and p.deleted_at is null, 'lastSignIn', p.last_sign_in_at,
                            'departments', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) order by d.sort_order, d.name), '[]'::jsonb)
                                            from staff_department sd join department d on d.id = sd.department_id and d.deleted_at is null
                                            where sd.profile_id = p.id))
  into v_person
  from profiles p where p.id = p_user;
  if v_person is null then
    raise exception 'person not found' using errcode = 'P0002';
  end if;

  with ev as (
    select * from analytics_staff_events(v_start, v_end, v_manager) where user_id = p_user
  )
  select jsonb_build_object(
    'from', v_from, 'to', v_to, 'person', v_person,
    'counts', (select coalesce(jsonb_object_agg(k, coalesce((select count(*) from ev where ev.kind = k), 0)), '{}'::jsonb)
               from unnest(analytics_kinds(v_manager)) k),
    'days', coalesce((
      select jsonb_agg(jsonb_build_object('day', d.day, 'kind', d.kind, 'n', d.n) order by d.day, d.kind)
      from (select (ev.at at time zone 'Africa/Kigali')::date as day, ev.kind, count(*) as n from ev group by 1, 2) d), '[]'::jsonb),
    'total', (select count(*) from ev where p_kind is null or ev.kind = p_kind),
    'records', coalesce((
      select jsonb_agg(jsonb_build_object(
          'at', r.at, 'kind', r.kind, 'encounterId', r.encounter_id, 'patientId', r.pid,
          'patientName', r.pname, 'fileNumber', r.file_number, 'what', r.what,
          'amount', case when v_manager then r.amount end) order by r.at desc)
      from (
        select ev.at, ev.kind, ev.encounter_id, ev.amount,
               -- 0088: what was written (a diagnosis, a medicine, a result…) only where the reader may
               -- see that visit's record; the manager and the person themselves always
               case when v_manager or ev.user_id = auth.uid()
                         or ev.kind in ('registered', 'patientsSeen', 'admissions',
                                        'payments', 'refunds', 'voided', 'handovers')
                         or (ev.encounter_id is not null and visit_view(ev.encounter_id) is not null)
                    then ev.what end as what,
               -- an HIV test names its patient to the manager only
               case when ev.kind = 'hivTests' and not v_manager then null else ev.patient_id end as pid,
               case when ev.kind = 'hivTests' and not v_manager then null else pt.surname || ' ' || pt.given_names end as pname,
               case when ev.kind = 'hivTests' and not v_manager then null else pt.file_number end as file_number
        from ev left join patient pt on pt.id = ev.patient_id
        where p_kind is null or ev.kind = p_kind
        order by ev.at desc
        limit v_limit) r), '[]'::jsonb),
    'signIns', coalesce((
      select jsonb_agg(jsonb_build_object('at', a.at, 'ok', a.reason is null or a.reason not like 'wrong PIN%', 'reason', a.reason)
                       order by a.at desc)
      from (select at, reason from audit_event
            where actor_id = p_user and action = 'login' and at >= v_start and at < v_end
            order by at desc limit 200) a), '[]'::jsonb),
    'money', case when v_manager then jsonb_build_object(
      'byMethod', coalesce((
        select jsonb_agg(jsonb_build_object('method', m.method, 'count', m.n, 'amount', m.amount) order by m.amount desc)
        from (select method, count(*) as n, sum(amount) as amount from payment
              where cashier_id = p_user and deleted_at is null and paid_at >= v_start and paid_at < v_end
              group by method) m), '[]'::jsonb),
      'refunds', coalesce((
        select jsonb_agg(jsonb_build_object('at', rf.refunded_at, 'amount', rf.amount, 'method', rf.method, 'reason', rf.reason,
                                            'patient', pt.surname || ' ' || pt.given_names, 'fileNumber', pt.file_number,
                                            'encounterId', i.encounter_id) order by rf.refunded_at desc)
        from refund rf
        join invoice i on i.id = rf.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient pt on pt.id = e.patient_id
        where rf.cashier_id = p_user and rf.deleted_at is null and rf.refunded_at >= v_start and rf.refunded_at < v_end), '[]'::jsonb),
      'voided', coalesce((
        select jsonb_agg(jsonb_build_object('at', y.voided_at, 'paidAt', y.paid_at, 'amount', y.amount, 'method', y.method,
                                            'reason', y.void_reason, 'by', vb.full_name,
                                            'patient', coalesce(pt.surname || ' ' || pt.given_names, cs.buyer_name)) order by y.voided_at desc)
        from payment y
        left join profiles vb on vb.id = y.voided_by
        left join invoice i on i.id = y.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient pt on pt.id = e.patient_id
        left join counter_sale cs on cs.id = y.counter_sale_id
        where y.cashier_id = p_user and y.voided_at is not null and y.voided_at >= v_start and y.voided_at < v_end), '[]'::jsonb),
      'closes', coalesce((
        select jsonb_agg(jsonb_build_object('day', c.date, 'expected', c.expected, 'counted', c.counted, 'variance', c.variance)
                         order by c.date desc)
        from day_close c
        where c.cashier_id = p_user and c.deleted_at is null and c.date between v_from and v_to), '[]'::jsonb))
    end
  ) into v_result;
  return v_result;
end
$$;
revoke all on function staff_activity_detail(uuid, date, date, text, integer) from public, anon;
grant execute on function staff_activity_detail(uuid, date, date, text, integer) to authenticated;

-- B: a request still waiting when its visit closes can no longer be answered: it is cancelled and
-- the approvers' notices go.
create or replace function cancel_requests_of_closed_visit()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  -- finish_visit closes and reopens within one transaction: only a visit still closed counts
  if not exists (select 1 from encounter where id = new.id and status = 'closed') then
    return null;
  end if;
  with c as (
    update record_access_request
    set status = 'cancelled', answered_at = now(), answer_note = 'visit closed'
    where encounter_id = new.id and status = 'pending'
    returning id
  )
  delete from notification n using c
  where n.kind = 'access_request' and (n.params ->> 'requestId') = c.id::text;
  return null;
end
$$;
revoke all on function cancel_requests_of_closed_visit() from public, anon, authenticated;
drop trigger if exists encounter_closed_cancels_access on encounter;
create constraint trigger encounter_closed_cancels_access
  after update of status on encounter
  deferrable initially deferred
  for each row when (new.status = 'closed' and old.status is distinct from 'closed')
  execute function cancel_requests_of_closed_visit();

-- The heads of a department are looked up for every visit of a patient.
create index if not exists staff_department_department_position_idx on staff_department (department_id, position);


-- ============================================================ 20261201090000_supporting_files.sql
-- 0089 · Supporting files on the patient file: photos, scans and PDFs (ultrasound images,
-- laboratory printouts, referral letters…), kept private and shown by the privacy levels (0088).
--
-- Frank: "the sonographer must be able to upload any supporting file in the patient file ... and
-- this must be an option in the patient file so that someone who treats or works on the patient
-- may see where he may upload some files".
--
--   * A  THE FILES (patient_file_doc): one row per file, attached to a visit (and to a test of the
--        visit when it is the laboratory or ultrasound's): a type (ultrasound image, laboratory
--        printout, scan, referral letter, photo, other), a title, who added it and when. JPEG, PNG,
--        WebP or PDF, at most 10 MB. The file itself is in the PRIVATE Storage bucket
--        'patient-files' at <patient id>/<visit id>/<file id>.<jpg|png|webp|pdf>.
--   * B  WHO ADDS ONE (may_attach_file): while the visit is open, anyone working on it who writes
--        in the record (clinical.write or orders.write, and visit_view = 'visit': holding the
--        patient, a task or help call, took part, the patient waits at their desk, the manager…),
--        and the laboratory / ultrasound desk on the tests of the visit at their desk. The file is
--        sent to Storage first, then registered (attach_file), which checks the object is there.
--        A test's requester is told when the laboratory or ultrasound adds a file to the test.
--   * C  WHO SEES ONE: the privacy levels of 0088: a file of the open visit is level 3 (the people
--        working on it), a file of a past visit is level 4 (the manager, the heads in charge, the
--        clinician who treated that visit, an approved request or emergency access). The lists
--        (list_patient_files, list_visit_files) give the files one may see and how many are
--        private. The person who added a file also sees it for 24 hours (to check or remove it
--        after the visit closed). file_open checks again, logs the opening of a past visit's file
--        (what = 'attachment'; the log now keeps one line per what was opened) and gives the
--        path; the screen then asks Storage for a link valid 5 minutes, which Storage gives only
--        when its own policy (below) agrees: for a past visit's file, only after that log line.
--   * D  REMOVING ONE (remove_file): the person who added it within 24 hours, or the manager,
--        always with a reason. The row stays (removed_at, by, reason) with an audit line; the
--        file in Storage may then be deleted by that person in the next 15 minutes (the screen
--        does it at once) or by the manager at any time ("storageLeft" says a copy is still there).
--   * E  STORAGE (only where the storage schema exists: Supabase; PGlite has none): the bucket is
--        created private with the size and type limits; its policies on storage.objects ask for
--        an approved session (0081 does not cover Storage) and the rules above: add to a visit one
--        may attach to, read a registered file one may see (or one's upload not registered yet, or
--        a removed file by the person deleting it), delete a removed file (by who removed it, 15
--        minutes, or the manager) or an upload never registered. No update: a file is never
--        replaced, a new one is added.
--
-- Errcodes: 42501 not allowed (hints: not_on_visit, remove_too_late, not_uploader, private),
-- 22023 bad input (hints: file_type, file_too_big, file_path, title_needed, file_kind,
-- reason_needed, file_visit_closed, already_removed, not_uploaded, wrong_test), P0002 not found
-- (hint: not_found).

-- ---------------------------------------------------------------- A the table
create table if not exists patient_file_doc (
  id uuid primary key default gen_random_uuid(),
  patient_id uuid not null references patient (id),
  encounter_id uuid not null references encounter (id),
  -- the test it belongs to (an ultrasound image, a laboratory printout)
  service_request_id uuid references service_request (id),
  kind text not null check (kind in ('ultrasound', 'lab', 'scan', 'referral', 'photo', 'other')),
  title text not null check (length(trim(title)) between 1 and 200),
  note text check (note is null or length(note) <= 1000),
  storage_path text not null unique,
  mime_type text not null check (mime_type in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf')),
  size_bytes integer not null check (size_bytes > 0 and size_bytes <= 10485760),
  uploaded_by uuid not null default auth.uid() references profiles (id),
  uploaded_at timestamptz not null default now(),
  removed_at timestamptz,
  removed_by uuid references profiles (id),
  remove_reason text,
  check ((removed_at is null) = (removed_by is null)),
  check (removed_at is null or length(trim(coalesce(remove_reason, ''))) >= 3)
);
create index if not exists patient_file_doc_patient_idx on patient_file_doc (patient_id, uploaded_at desc);
create index if not exists patient_file_doc_encounter_idx on patient_file_doc (encounter_id);
create index if not exists patient_file_doc_request_idx on patient_file_doc (service_request_id)
  where service_request_id is not null;
comment on table patient_file_doc is
  'Supporting files (photos, scans, PDFs) of a patient''s visit; the file is in the private Storage bucket patient-files (0089).';
alter table patient_file_doc enable row level security;
-- read and written through the functions below only
revoke all on patient_file_doc from anon, authenticated;

-- The access log (0088) also says when a past visit's file was opened.
alter table record_access_entry drop constraint if exists record_access_entry_what_check;
alter table record_access_entry add constraint record_access_entry_what_check
  check (what in ('file', 'visit', 'results', 'journey', 'emergency', 'attachment'));

-- One line in the access log (0088), now once per half hour per person, patient, visit, way AND
-- what was opened: opening a past visit and then one of its files gives two lines ('visit',
-- 'attachment'); before, the file's line was swallowed by the visit's. The Storage rule below
-- relies on a fresh 'attachment' line.
create or replace function log_record_access(p_patient_id uuid, p_encounter_id uuid, p_via text, p_what text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req uuid;
begin
  if auth.uid() is null or p_via is null or p_patient_id is null then
    return;
  end if;
  if exists (select 1 from record_access_entry a
             where a.actor_id = auth.uid() and a.patient_id = p_patient_id
               and a.encounter_id is not distinct from p_encounter_id and a.via = p_via
               and a.what = p_what
               and a.at > now() - interval '30 minutes') then
    return;
  end if;
  if p_via in ('request', 'emergency') then
    select a.id into v_req from access_in_force(p_patient_id) a;
  end if;
  insert into record_access_entry (actor_id, patient_id, encounter_id, via, what, request_id)
  values (auth.uid(), p_patient_id, p_encounter_id, p_via, p_what, v_req);
end
$$;

-- ---------------------------------------------------------------- helpers
-- The limits, in one place (the screens read them from the lists).
create or replace function file_max_bytes()
returns integer
language sql immutable
as $$ select 10485760 $$;

create or replace function file_mime_ok(p_mime text)
returns boolean
language sql immutable
as $$ select coalesce(p_mime in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf'), false) $$;

-- The extension a file of this type is stored under.
create or replace function file_ext_ok(p_mime text, p_ext text)
returns boolean
language sql immutable
as $$
  select case p_mime
    when 'image/jpeg' then p_ext in ('jpg', 'jpeg')
    when 'image/png' then p_ext = 'png'
    when 'image/webp' then p_ext = 'webp'
    when 'application/pdf' then p_ext = 'pdf'
    else false
  end
$$;

-- An approved session (0081), or the code switched off: Storage is not behind check_request.
create or replace function storage_session_ok()
returns boolean
language sql stable security definer set search_path = public
as $$
  select auth.uid() is not null and (session_ok() or not enforce_code_on())
$$;

-- The visit a Storage path belongs to: '<patient id>/<visit id>/<file id>.<ext>', the visit being
-- the patient's. Null for any other name.
create or replace function file_path_encounter(p_name text)
returns uuid
language plpgsql stable security definer set search_path = public
as $$
declare
  m text[];
  v_enc uuid;
begin
  m := regexp_match(coalesce(p_name, ''),
    '^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp|pdf)$');
  if m is null then
    return null;
  end if;
  select e.id into v_enc from encounter e
  where e.id = m[2]::uuid and e.patient_id = m[1]::uuid and e.deleted_at is null;
  return v_enc;
end
$$;

-- May the signed-in person add a file to this visit (to this test of it, when given)?
-- The visit is open, and: they work on it and write in the record (clinical.write or
-- orders.write, visit_view = 'visit'), or a test of the visit is at their laboratory /
-- ultrasound desk (orders.write).
create or replace function may_attach_file(p_encounter_id uuid, p_service_request_id uuid default null)
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce(auth.uid() is not null
    and exists (select 1 from encounter e
                where e.id = p_encounter_id and e.status = 'open' and e.deleted_at is null)
    and (p_service_request_id is null
         or exists (select 1 from service_request r
                    where r.id = p_service_request_id and r.encounter_id = p_encounter_id
                      and r.deleted_at is null and r.status <> 'cancelled'))
    and (
      ((has_perm('clinical.write') or has_perm('orders.write')) and clinical_reader()
       and may_work_on(p_encounter_id))
      or (has_perm('orders.write')
          and exists (select 1 from service_request r
                      where r.encounter_id = p_encounter_id and r.deleted_at is null
                        and r.status <> 'cancelled'
                        and (p_service_request_id is null or r.id = p_service_request_id)
                        and may_use_desk(request_desk(r.station, r.category))))
    ), false)
$$;

-- How the signed-in person sees one file, or null (private): the privacy level of its visit
-- (0088); and the person who added it, for 24 hours, whatever the visit (a laboratory printout
-- stays theirs to check and remove after the visit closes).
create or replace function file_view(d patient_file_doc)
returns text
language sql stable security definer set search_path = public
as $$
  select coalesce(
    case when clinical_reader() or is_manager() then visit_view(d.encounter_id) end,
    case when d.removed_at is null and d.uploaded_by = auth.uid()
              and d.uploaded_at > now() - interval '24 hours' then 'own' end)
$$;

-- Is the file still in the bucket? Null where there is no Storage (PGlite).
create or replace function file_object_exists(p_path text)
returns boolean
language plpgsql stable security definer set search_path = public
as $$
declare
  v boolean;
begin
  if to_regclass('storage.objects') is null then
    return null;
  end if;
  execute 'select exists (select 1 from storage.objects where bucket_id = ''patient-files'' and name = $1)'
    into v using p_path;
  return v;
end
$$;

-- What the screens show of one file.
create or replace function file_doc_json(f patient_file_doc, p_view text)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'id', f.id, 'patientId', f.patient_id, 'encounterId', f.encounter_id,
    'visitReference', e.reference, 'visitOpen', e.status = 'open', 'visitAt', e.arrived_at,
    'serviceRequestId', f.service_request_id,
    'test', (select s.name_en from service_request r join service s on s.id = r.service_id
             where r.id = f.service_request_id),
    'kind', f.kind, 'title', f.title, 'note', f.note,
    'mimeType', f.mime_type, 'sizeBytes', f.size_bytes, 'path', f.storage_path,
    'uploadedById', f.uploaded_by, 'uploadedBy', u.full_name, 'uploadedByRole', u.role,
    'uploadedAt', f.uploaded_at,
    'removed', f.removed_at is not null, 'removedAt', f.removed_at,
    'removedBy', (select full_name from profiles where id = f.removed_by), 'removeReason', f.remove_reason,
    -- a removed file whose copy is still in storage (the delete failed): the manager finishes it
    'storageLeft', case when f.removed_at is not null then file_object_exists(f.storage_path) end,
    'canRemove', f.removed_at is null
                 and (is_manager() or (f.uploaded_by = auth.uid() and f.uploaded_at > now() - interval '24 hours')),
    'view', p_view)
  from encounter e
  left join profiles u on u.id = f.uploaded_by
  where e.id = f.encounter_id
$$;

-- The files of a patient (or of one visit / one test) that the signed-in person may see, how many
-- are private to them, and those removed (the manager only).
create or replace function files_list(p_patient_id uuid, p_encounter_id uuid, p_service_request_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_via text;
  v_reader boolean := clinical_reader();
  v_files jsonb;
  v_hidden integer;
  v_removed integer;
begin
  if auth.uid() is null or not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  v_via := history_via(p_patient_id);
  with f as (
    select d, coalesce(
             case when v_reader or is_manager() then visit_view_with(d.encounter_id, v_via, true) end,
             -- one's own upload, for 24 hours (as file_view)
             case when d.removed_at is null and d.uploaded_by = auth.uid()
                       and d.uploaded_at > now() - interval '24 hours' then 'own' end) as view
    from patient_file_doc d
    where d.patient_id = p_patient_id
      and (p_encounter_id is null or d.encounter_id = p_encounter_id)
      and (p_service_request_id is null or d.service_request_id = p_service_request_id)
  )
  select coalesce(jsonb_agg(file_doc_json(f.d, f.view) order by (f.d).uploaded_at desc)
                    filter (where f.view is not null and ((f.d).removed_at is null or is_manager())), '[]'::jsonb),
         count(*) filter (where f.view is null and (f.d).removed_at is null),
         count(*) filter (where f.view is not null and (f.d).removed_at is not null)
  into v_files, v_hidden, v_removed
  from f;
  return jsonb_build_object(
    'files', v_files,
    'hidden', v_hidden,
    'removed', v_removed,
    'maxBytes', file_max_bytes(),
    'types', jsonb_build_array('image/jpeg', 'image/png', 'image/webp', 'application/pdf'));
end
$$;

-- The patient file's "Files": every visit's, and the open visit the person may add to.
create or replace function list_patient_files(p_patient_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_list jsonb := files_list(p_patient_id, null, null);
begin
  return v_list || jsonb_build_object(
    'attachTo', (select e.id from encounter e
                 where e.patient_id = p_patient_id and e.status = 'open' and e.deleted_at is null
                   and may_attach_file(e.id)
                 order by e.arrived_at desc limit 1));
end
$$;

-- One visit's files (the visit page), or one test's (the result entry); may the person add one.
create or replace function list_visit_files(p_encounter_id uuid, p_service_request_id uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_patient uuid;
begin
  select patient_id into v_patient from encounter where id = p_encounter_id and deleted_at is null;
  if v_patient is null then
    raise exception 'visit not found' using errcode = 'P0002', hint = 'not_found';
  end if;
  return files_list(v_patient, p_encounter_id, p_service_request_id)
    || jsonb_build_object('canAttach', may_attach_file(p_encounter_id, p_service_request_id),
                          'encounterId', p_encounter_id, 'patientId', v_patient);
end
$$;

-- ---------------------------------------------------------------- B adding a file
-- Registers a file already sent to Storage at p_path. Checks the rules again (the type, the
-- size, the path of this visit, the person may add to it) and, on Supabase, that the file is in
-- the bucket with that size and type.
create or replace function attach_file(
  p_encounter_id uuid,
  p_path text,
  p_kind text,
  p_title text,
  p_mime text,
  p_size integer,
  p_service_request_id uuid default null,
  p_note text default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_e encounter%rowtype;
  v_ext text := lower(substring(coalesce(p_path, '') from '\.([a-zA-Z]+)$'));
  v_obj_found boolean := false;
  v_obj_size bigint;
  v_obj_mime text;
  v_f patient_file_doc%rowtype;
  v_req service_request%rowtype;
  v_name text;
  v_file text;
  v_me text;
  v_test text;
begin
  if auth.uid() is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_e from encounter where id = p_encounter_id and deleted_at is null;
  if not found then
    raise exception 'visit not found' using errcode = 'P0002', hint = 'not_found';
  end if;
  if v_e.status <> 'open' then
    raise exception 'files are added while the visit is open' using errcode = '22023', hint = 'file_visit_closed';
  end if;
  if coalesce(p_kind, '') not in ('ultrasound', 'lab', 'scan', 'referral', 'photo', 'other') then
    raise exception 'unknown kind of file' using errcode = '22023', hint = 'file_kind';
  end if;
  if length(trim(coalesce(p_title, ''))) = 0 or length(trim(p_title)) > 200 then
    raise exception 'give the file a title' using errcode = '22023', hint = 'title_needed';
  end if;
  if not file_mime_ok(p_mime) then
    raise exception 'only photos (JPEG, PNG, WebP) and PDF files' using errcode = '22023', hint = 'file_type';
  end if;
  if p_size is null or p_size <= 0 or p_size > file_max_bytes() then
    raise exception 'the file is larger than 10 MB' using errcode = '22023', hint = 'file_too_big';
  end if;
  if file_path_encounter(p_path) is distinct from p_encounter_id
     or split_part(p_path, '/', 1) <> v_e.patient_id::text
     or not file_ext_ok(p_mime, v_ext) then
    raise exception 'the file is not stored where this visit''s files go' using errcode = '22023', hint = 'file_path';
  end if;
  if p_service_request_id is not null then
    select * into v_req from service_request
    where id = p_service_request_id and encounter_id = p_encounter_id and deleted_at is null;
    if not found or v_req.status = 'cancelled' then
      raise exception 'this test is not one of the visit' using errcode = '22023', hint = 'wrong_test';
    end if;
  end if;
  if not may_attach_file(p_encounter_id, p_service_request_id) then
    raise exception 'not allowed: only the people working on the visit add files'
      using errcode = '42501', hint = 'not_on_visit';
  end if;
  -- On Supabase: the file must be in the bucket, with the size and type said.
  if to_regclass('storage.objects') is not null then
    execute 'select true, (metadata ->> ''size'')::bigint, metadata ->> ''mimetype''
             from storage.objects where bucket_id = ''patient-files'' and name = $1'
      into v_obj_found, v_obj_size, v_obj_mime using p_path;
    if not coalesce(v_obj_found, false) then
      raise exception 'the file did not arrive: send it again' using errcode = '22023', hint = 'not_uploaded';
    end if;
    if v_obj_size is not null and v_obj_size > file_max_bytes() then
      raise exception 'the file is larger than 10 MB' using errcode = '22023', hint = 'file_too_big';
    end if;
    if v_obj_mime is not null and not file_mime_ok(v_obj_mime) then
      raise exception 'only photos (JPEG, PNG, WebP) and PDF files' using errcode = '22023', hint = 'file_type';
    end if;
  end if;
  insert into patient_file_doc (patient_id, encounter_id, service_request_id, kind, title, note,
                                storage_path, mime_type, size_bytes, uploaded_by)
  values (v_e.patient_id, p_encounter_id, p_service_request_id, p_kind, trim(p_title),
          nullif(trim(coalesce(p_note, '')), ''), p_path, p_mime,
          coalesce(v_obj_size::integer, p_size), auth.uid())
  returning * into v_f;
  insert into audit_event (actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'create', 'patient_file_doc', v_f.id,
          jsonb_build_object('patient', v_f.patient_id, 'encounter', v_f.encounter_id, 'kind', v_f.kind,
                             'title', v_f.title, 'mime', v_f.mime_type, 'size', v_f.size_bytes));
  -- the laboratory or ultrasound added a file to a test: its requester is told
  if v_req.id is not null and v_req.requester_id is not null and v_req.requester_id <> auth.uid() then
    select p.surname || ' ' || p.given_names, p.file_number into v_name, v_file
    from patient p where p.id = v_e.patient_id;
    select full_name into v_me from profiles where id = auth.uid();
    select s.name_en into v_test from service s where s.id = v_req.service_id;
    insert into notification (kind, params, title, body, link, urgent, recipient_user, created_by)
    values ('file_attached',
            jsonb_build_object('fileId', v_f.id, 'patientId', v_e.patient_id, 'encounterId', v_e.id,
                               'name', v_name, 'file', v_file, 'by', v_me, 'title', v_f.title,
                               'kind', v_f.kind, 'test', v_test),
            'File added to a test',
            coalesce(v_me, '') || ' added "' || v_f.title || '" to ' || coalesce(v_test, 'a test') || ' of ' || coalesce(v_name, ''),
            '/app/visit?encounter=' || v_e.id, false, v_req.requester_id, auth.uid());
  end if;
  return file_doc_json(v_f, 'visit');
end
$$;

-- ---------------------------------------------------------------- C opening a file
-- Checks the person may see the file, logs the opening of a past visit's file, and gives its
-- path; the screen then asks Storage for a link valid 5 minutes (createSignedUrl), which the
-- bucket's own policy checks again.
create or replace function file_open(p_file_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_f patient_file_doc%rowtype;
  v_view text;
begin
  if auth.uid() is null or not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_f from patient_file_doc where id = p_file_id;
  if not found or (v_f.removed_at is not null and not is_manager()) then
    raise exception 'file not found' using errcode = 'P0002', hint = 'not_found';
  end if;
  if v_f.removed_at is not null then
    raise exception 'this file was removed' using errcode = '22023', hint = 'already_removed';
  end if;
  v_view := file_view(v_f);
  if v_view is null then
    raise exception 'not allowed: this file belongs to records you may not see'
      using errcode = '42501', hint = 'private';
  end if;
  if v_view <> 'visit' then
    perform log_record_access(v_f.patient_id, v_f.encounter_id, v_view, 'attachment');
  end if;
  return jsonb_build_object('id', v_f.id, 'bucket', 'patient-files', 'path', v_f.storage_path,
                            'mimeType', v_f.mime_type, 'title', v_f.title, 'expiresIn', 300);
end
$$;

-- ---------------------------------------------------------------- D removing a file
-- The person who added it within 24 hours, or the manager; always with a reason. The row stays
-- (removed); the screen then deletes the file from Storage (only that person may: policy below).
create or replace function remove_file(p_file_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_f patient_file_doc%rowtype;
begin
  if auth.uid() is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the file is removed' using errcode = '22023', hint = 'reason_needed';
  end if;
  select * into v_f from patient_file_doc where id = p_file_id for update;
  if not found then
    raise exception 'file not found' using errcode = 'P0002', hint = 'not_found';
  end if;
  if v_f.removed_at is not null then
    raise exception 'this file was already removed' using errcode = '22023', hint = 'already_removed';
  end if;
  if not is_manager() then
    if v_f.uploaded_by <> auth.uid() then
      raise exception 'not allowed: the person who added the file or the manager removes it'
        using errcode = '42501', hint = 'not_uploader';
    end if;
    if v_f.uploaded_at <= now() - interval '24 hours' then
      raise exception 'not allowed: after 24 hours only the manager removes a file'
        using errcode = '42501', hint = 'remove_too_late';
    end if;
  end if;
  update patient_file_doc
  set removed_at = now(), removed_by = auth.uid(), remove_reason = trim(p_reason)
  where id = v_f.id
  returning * into v_f;
  insert into audit_event (actor_id, action, entity, entity_id, before, reason)
  values (auth.uid(), 'delete', 'patient_file_doc', v_f.id,
          jsonb_build_object('patient', v_f.patient_id, 'encounter', v_f.encounter_id, 'kind', v_f.kind,
                             'title', v_f.title, 'path', v_f.storage_path, 'uploadedBy', v_f.uploaded_by),
          v_f.remove_reason);
  return jsonb_build_object('id', v_f.id, 'bucket', 'patient-files', 'path', v_f.storage_path,
                            'removedAt', v_f.removed_at);
end
$$;

-- ---------------------------------------------------------------- E the Storage rules
-- Used by the policies on storage.objects for the bucket (and checked by db:check directly).
-- Send a file: an approved session, a path of a visit one may add to, not a registered file.
create or replace function file_object_insert_ok(p_name text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce(storage_session_ok()
    and file_path_encounter(p_name) is not null
    and not exists (select 1 from patient_file_doc d where d.storage_path = p_name)
    and may_attach_file(file_path_encounter(p_name)), false)
$$;

-- Delete a file from Storage: a removed file, by the manager, or by the person who removed it in
-- the 15 minutes after (the screen deletes it at once; a failed delete is finished by the
-- manager); or an upload never registered (the screen cleans up when registering failed).
create or replace function file_object_delete_ok(p_name text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce(storage_session_ok()
    and case
      when exists (select 1 from patient_file_doc d where d.storage_path = p_name) then
        exists (select 1 from patient_file_doc d
                where d.storage_path = p_name and d.removed_at is not null
                  and (is_manager()
                       or (d.removed_by = auth.uid() and d.removed_at > now() - interval '15 minutes')))
      else file_object_insert_ok(p_name)
    end, false)
$$;

-- Read a file (the 5-minute link): a registered file, not removed, that one may see (file_view):
-- of today's visit at once; of a past visit only after file_open wrote its 'attachment' line in
-- the access log, so that a link asked of Storage directly is never an unlogged look (35 minutes:
-- longer than the half hour in which file_open does not write the line again); one's own upload
-- not registered yet (Storage reads back what it has just written); a removed file, by the
-- person who may delete it.
create or replace function file_object_read_ok(p_name text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce(storage_session_ok() and has_perm('patient.read')
    and case
      when exists (select 1 from patient_file_doc d where d.storage_path = p_name) then
        exists (select 1 from patient_file_doc d
                cross join lateral (select file_view(d) as v) x
                where d.storage_path = p_name and d.removed_at is null and x.v is not null
                  and (x.v = 'visit'
                       or exists (select 1 from record_access_entry a
                                  where a.actor_id = auth.uid() and a.patient_id = d.patient_id
                                    and a.encounter_id = d.encounter_id and a.what = 'attachment'
                                    and a.at > now() - interval '35 minutes')))
        -- Postgres deletes only the rows it may read: the person deleting a removed file
        or file_object_delete_ok(p_name)
      else file_object_insert_ok(p_name)
    end, false)
$$;

-- The bucket and its policies, where Storage exists (Supabase). Nothing to do by hand.
do $$
begin
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    raise notice 'no storage schema here: the bucket patient-files is not created';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('patient-files', 'patient-files', false, 10485760,
          array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
  on conflict (id) do update
    set public = false, file_size_limit = excluded.file_size_limit,
        allowed_mime_types = excluded.allowed_mime_types;
  execute 'drop policy if exists patient_files_insert on storage.objects';
  execute 'drop policy if exists patient_files_select on storage.objects';
  execute 'drop policy if exists patient_files_delete on storage.objects';
  execute $p$create policy patient_files_insert on storage.objects for insert to authenticated
    with check (bucket_id = 'patient-files' and public.file_object_insert_ok(name))$p$;
  execute $p$create policy patient_files_select on storage.objects for select to authenticated
    using (bucket_id = 'patient-files' and public.file_object_read_ok(name))$p$;
  execute $p$create policy patient_files_delete on storage.objects for delete to authenticated
    using (bucket_id = 'patient-files' and public.file_object_delete_ok(name))$p$;
end
$$;

-- ---------------------------------------------------------------- grants
revoke all on function file_doc_json(patient_file_doc, text), files_list(uuid, uuid, uuid),
  file_path_encounter(text), file_view(patient_file_doc), file_object_exists(text),
  log_record_access(uuid, uuid, text, text) from public, anon, authenticated;
revoke all on function storage_session_ok(), may_attach_file(uuid, uuid), list_patient_files(uuid),
  list_visit_files(uuid, uuid), attach_file(uuid, text, text, text, text, integer, uuid, text),
  file_open(uuid), remove_file(uuid, text), file_object_insert_ok(text), file_object_read_ok(text),
  file_object_delete_ok(text) from public, anon;
grant execute on function storage_session_ok(), may_attach_file(uuid, uuid), list_patient_files(uuid),
  list_visit_files(uuid, uuid), attach_file(uuid, text, text, text, text, integer, uuid, text),
  file_open(uuid), remove_file(uuid, text), file_object_insert_ok(text), file_object_read_ok(text),
  file_object_delete_ok(text) to authenticated;


-- ============================================================ 20261202090000_security_hardening.sql
-- Security hardening after the full audit of 26 October 2026 (independent review of every
-- table, view, policy and function; each finding reproduced before fixing).
--
--  1. The audit log's monthly partitions had no row-level security and the default table rights:
--     any signed-in staff member could read (whole patient rows are copied into before/after),
--     change, delete or forge audit rows. Partitions: no rights, RLS on (reading goes through the
--     parent table's policy); new partitions the same; no direct writes to audit_event at all;
--     log_access() is no longer callable from the API.
--  2. Views: no write rights for anyone through the API. public_payers and public_service_lines
--     could be written by visitors (the website key) and public_practitioners/public_booked_slots
--     by any staff member, because a simple view is updatable as its owner (skipping RLS).
--  3. Tables: the app writes only through the checked functions, so the API roles lose insert,
--     update, delete and truncate on every table (and on tables created later). This closes direct
--     edits that skipped the functions' rules (allergies cleared, a cash count's variance hidden,
--     a past prescription changed to gain access to the visit).
--  4. home_summary's results list: only what the reader may see (a doctor: the tests they asked
--     for; the manager; others: open orders they may read and visits they may see), HIV tests only
--     with sensitive.read. Before, every non-doctor role saw every recent result.
--  5. Read policies that ignored the privacy levels: bill lines and bills for the clinical roles,
--     nurse tasks, handover notes now follow visit_view().
--  6. visit_routing: the referral note only for clinical readers who may see the visit.
--  7. desk_orders: only for people who use that desk.
--  8. A prescription's author cannot be changed; "treated this visit" counts the prescriber.
--  9. A deactivated account, or one given a new PIN by the manager, loses its approved sign-ins at
--     once (the 0081 gate then refuses every request of the old sign-in).

-- 1. The audit log --------------------------------------------------------------------------------
do $$
declare
  r record;
begin
  for r in
    select c.oid::regclass as t
    from pg_inherits i
    join pg_class c on c.oid = i.inhrelid
    join pg_class p on p.oid = i.inhparent
    where p.relname = 'audit_event' and p.relnamespace = 'public'::regnamespace
  loop
    execute format('revoke all on %s from anon, authenticated', r.t);
    execute format('alter table %s enable row level security', r.t);
  end loop;
end
$$;
revoke insert, update, delete, truncate on audit_event from anon, authenticated;

create or replace function ensure_audit_partitions(p_months integer default 12)
returns void
language plpgsql
as $$
declare
  m date := date_trunc('month', now())::date;
  i integer;
  v_name text;
begin
  for i in 0 .. p_months - 1 loop
    v_name := 'audit_event_' || to_char(m + make_interval(months => i), 'YYYY_MM');
    execute format(
      'create table if not exists %I partition of audit_event for values from (%L) to (%L)',
      v_name,
      m + make_interval(months => i),
      m + make_interval(months => i + 1)
    );
    -- read only through the parent table's policy; never written from the API (security hardening)
    execute format('revoke all on %I from anon, authenticated', v_name);
    execute format('alter table %I enable row level security', v_name);
  end loop;
end
$$;

do $$
begin
  if to_regprocedure('log_access(text,uuid,audit_action,text)') is not null then
    execute 'revoke execute on function log_access(text, uuid, audit_action, text) from public, anon, authenticated';
  end if;
end
$$;

-- 2. Views: read only from the API -----------------------------------------------------------------
do $$
declare
  r record;
begin
  for r in
    select c.relname from pg_class c
    where c.relnamespace = 'public'::regnamespace and c.relkind in ('v', 'm')
  loop
    execute format('revoke insert, update, delete, truncate, references, trigger on public.%I from anon, authenticated', r.relname);
  end loop;
end
$$;

-- 3. Tables: written only through the checked functions -------------------------------------------
revoke insert, update, delete, truncate on all tables in schema public from anon, authenticated;
alter default privileges in schema public revoke insert, update, delete, truncate on tables from anon, authenticated;

-- 4. home_summary (from 20261126090000_departments_decide_desks): the results list follows the
--    privacy levels.
create or replace function home_summary(p_from date default null, p_to date default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_role role_key := current_role_key();
  v_practitioner uuid := (select id from practitioner where user_id = auth.uid() and active limit 1);
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_appts jsonb;
  v_inquiries jsonb;
  v_mine jsonb;
  v_to_accept jsonb;
  v_bills jsonb;
  v_paid jsonb;
  v_beds jsonb;
  v_tasks jsonb;
  v_results jsonb;
begin
  if v_role is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;

  -- today's booked patients (reception, doctors)
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'time', to_char(a.starts_at at time zone 'Africa/Kigali', 'HH24:MI'),
      'name', coalesce(p.surname || ' ' || p.given_names, a.contact_name),
      'doctor', coalesce(pr.names, ''), 'station', coalesce(a.category, ''),
      'status', case when a.status in ('arrived', 'in_progress', 'completed') then 'arrived'
                     when a.starts_at < now() then 'late' else 'due' end,
      'mine', (a.practitioner_id = v_practitioner),
      'encounterId', (select e.id from encounter e where e.appointment_id = a.id order by e.arrived_at desc limit 1)
    ) order by a.starts_at), '[]'::jsonb) into v_appts
  from appointment a
  left join patient p on p.id = a.patient_id
  left join practitioner pr on pr.id = a.practitioner_id
  where a.deleted_at is null and a.status in ('approved', 'confirmed', 'arrived', 'in_progress', 'completed')
    and (a.starts_at at time zone 'Africa/Kigali')::date between v_from and v_to;

  -- public inquiries waiting for reception
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', a.contact_name, 'phone', a.contact_phone, 'reference', a.reference,
      'category', a.category, 'doctor', pr.names, 'channel', a.contact_channel,
      'when', case when a.starts_at is null then null else to_char(a.starts_at at time zone 'Africa/Kigali', 'DD/MM HH24:MI') end,
      'note', a.reason
    ) order by a.created_at), '[]'::jsonb) into v_inquiries
  from appointment a
  left join practitioner pr on pr.id = a.practitioner_id
  where a.deleted_at is null and a.status = 'inquiry';

  -- approved bookings this practitioner still has to accept
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', coalesce(p.surname || ' ' || p.given_names, a.contact_name),
      'when', to_char(a.starts_at at time zone 'Africa/Kigali', 'DD/MM HH24:MI'), 'note', a.reason,
      'category', a.category, 'startsAt', a.starts_at
    ) order by a.starts_at), '[]'::jsonb) into v_to_accept
  from appointment a
  left join patient p on p.id = a.patient_id
  where a.deleted_at is null and a.status = 'approved' and a.practitioner_id = v_practitioner
    and a.starts_at > now() - interval '1 day';

  -- open bills: visits with something charged and a patient balance (cashier)
  select coalesce(jsonb_agg(jsonb_build_object(
      'encounterId', i.encounter_id, 'name', p.surname || ' ' || p.given_names, 'file', p.file_number,
      'ticket', (select ticket_no from queue_entry q where q.encounter_id = i.encounter_id order by q.created_at limit 1),
      'station', (select station from queue_entry q where q.encounter_id = i.encounter_id and q.finished_at is null order by q.created_at desc limit 1),
      'amount', i.patient_share, 'balance', invoice_balance(i.id), 'status', i.status
    ) order by i.updated_at desc), '[]'::jsonb) into v_bills
  from invoice i
  join encounter e on e.id = i.encounter_id
  join patient p on p.id = e.patient_id
  where i.deleted_at is null and i.total > 0 and e.status = 'open' and invoice_balance(i.id) > 0;

  select jsonb_build_object('count', count(*), 'amount', coalesce(sum(amount), 0)) into v_paid
  from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to;

  -- beds
  select coalesce(jsonb_agg(jsonb_build_object(
      'n', b.sort_order, 'name', b.name, 'state', b.status,
      'who', (select p.surname || ' ' || left(p.given_names, 1) || '.' from bed_stay s join encounter e on e.id = s.encounter_id join patient p on p.id = e.patient_id
              where s.bed_id = b.id and s.discharged_at is null limit 1)
    ) order by b.sort_order, b.name), '[]'::jsonb) into v_beds
  from bed b where b.deleted_at is null;

  -- tasks for my role or me
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', k.id, 'time', to_char(k.due_at at time zone 'Africa/Kigali', 'HH24:MI'), 'title', k.title,
      'detail', coalesce(k.detail, ''), 'overdue', (k.due_at < now()),
      'patient', (select p.surname || ' ' || p.given_names from patient p where p.id = k.patient_id)
    ) order by k.due_at), '[]'::jsonb) into v_tasks
  from internal_task k
  where k.deleted_at is null and k.done_at is null and (k.assigned_to = auth.uid() or task_for_me(k.assigned_role));

  -- lab / imaging results of the last two days: a doctor's own requests; the manager; others only
  -- results of visits they may see (privacy levels); HIV tests only with sensitive.read
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'encounterId', sr.encounter_id, 'test', s.name_en,
      'name', p.surname || ' ' || p.given_names, 'impression', coalesce(r.impression, r.findings, ''),
      'verified', (r.verified_at is not null), 'at', to_char(r.updated_at at time zone 'Africa/Kigali', 'HH24:MI'),
      'reviewed', (r.reviewed_at is not null), 'corrected', (r.corrected_at is not null)
    ) order by (r.reviewed_at is null) desc, r.updated_at desc), '[]'::jsonb) into v_results
  from diagnostic_report r
  join service_request sr on sr.id = r.service_request_id
  join service s on s.id = sr.service_id
  join encounter e on e.id = sr.encounter_id
  join patient p on p.id = e.patient_id
  where r.deleted_at is null
    and (r.updated_at > now() - interval '2 days' or (r.reviewed_at is null and r.updated_at > now() - interval '7 days'))
    and (
      -- after a handover the results follow the patient to the colleague who took them
      (v_role = 'doctor' and result_recipient(sr.encounter_id, sr.requester_id) = auth.uid())
      or is_manager()
      or (v_role is distinct from 'doctor' and has_perm('orders.read')
          and visit_view(sr.encounter_id) is not null)
    )
    and (has_perm('sensitive.read')
         or not (coalesce(s.name_en, '') ilike '%hiv%' or coalesce(s.code, '') ilike '%hiv%'));

  return jsonb_build_object(
    'role', v_role,
    -- the patients this person took and finished today (a doctor's "Seen")
    'seenToday', (select count(distinct q.encounter_id) from queue_entry q
                  where q.taken_by = auth.uid() and q.deleted_at is null and q.finished_at is not null
                    and (q.finished_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'appointments', v_appts,
    'inquiries', v_inquiries,
    'toAccept', v_to_accept,
    'openBills', v_bills,
    'paidToday', v_paid,
    'beds', v_beds,
    'tasks', v_tasks,
    'results', v_results
  );
end
$$;

-- 5. Read policies that follow the privacy levels ---------------------------------------------------
drop policy if exists invoice_line_select_clinical on invoice_line;
create policy invoice_line_select_clinical on invoice_line for select to authenticated
  using (has_perm('charge.write')
         and exists (select 1 from invoice i where i.id = invoice_line.invoice_id
                     and visit_view(i.encounter_id) is not null));
drop policy if exists invoice_select_clinical on invoice;
create policy invoice_select_clinical on invoice for select to authenticated
  using (has_perm('charge.write') and visit_view(encounter_id) is not null);

drop policy if exists internal_task_select on internal_task;
create policy internal_task_select on internal_task for select to authenticated
  using (has_perm('queue.read')
         and (encounter_id is null or assigned_to = auth.uid() or task_for_me(assigned_role)
              or visit_view(encounter_id) is not null));

drop policy if exists patient_handover_read on patient_handover;
create policy patient_handover_read on patient_handover for select to authenticated
  using (from_user = auth.uid() or to_user = auth.uid() or is_manager()
         or visit_view(encounter_id) is not null);

-- 6. visit_routing (from 20261102120000_desks_connected): the referral note is clinical
create or replace function visit_routing(p_encounter_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'queueId', q.id, 'station', q.station, 'since', q.created_at,
      'assignedTo', q.assigned_to, 'assignedName', a.full_name,
      'referredBy', q.referred_by, 'referredName', r.full_name,
      'note', case when has_perm('clinical.read') and visit_view(q.encounter_id) is not null
                   then q.referral_note end,
      'returnStation', q.return_station, 'returnTo', q.return_to, 'returnName', b.full_name,
      'takenBy', q.taken_by, 'takenName', t.full_name, 'canWork', queue_entry_for_me(q.id)
    ) order by q.created_at), '[]'::jsonb)
  from queue_entry q
  left join profiles a on a.id = q.assigned_to
  left join profiles r on r.id = q.referred_by
  left join profiles b on b.id = q.return_to
  left join profiles t on t.id = q.taken_by
  where q.encounter_id = p_encounter_id and q.finished_at is null and q.deleted_at is null
    and has_perm('queue.read')
$$;

-- 7. desk_orders (from 20261125090000_document_details): only for people who use that desk
create or replace function desk_orders(p_station station)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(x.j order by x.prio, x.at), '[]'::jsonb)
  from (
    select r.priority as prio, r.created_at as at, doc_patient(p.id, e.id) || jsonb_build_object(
      'id', r.id, 'encounterId', r.encounter_id, 'patientId', p.id,
      'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
      'sex', p.sex, 'birthDate', p.birth_date,
      'ticket', (select q.ticket_no from queue_entry q where q.encounter_id = r.encounter_id order by q.created_at limit 1),
      'triage', e.triage_level,
      'test', s.name_en, 'category', r.category, 'status', r.status, 'priority', r.priority,
      'reason', r.reason, 'orderedAt', r.created_at,
      'orderedBy', (select full_name from profiles where id = r.requester_id),
      'findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
      'resultAt', coalesce(d.verified_at, d.updated_at),
      'resultBy', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
      'resultByPerson', doc_person(coalesce(d.verified_by, d.created_by)),
      'visitReference', e.reference, 'visitAt', e.arrived_at
    ) as j
    from service_request r
    join encounter e on e.id = r.encounter_id and e.status = 'open'
    join patient p on p.id = e.patient_id
    join service s on s.id = r.service_id
    left join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
    where r.deleted_at is null and r.station = p_station and p_station not in ('laboratory', 'ultrasound')
      and r.status not in ('verified', 'cancelled')
      and (has_perm('clinical.read') or has_perm('orders.read'))
      and (is_manager() or may_use_any_desk(station_desks(p_station)))
  ) x
$$;

-- 8. A prescription's author stays; "treated this visit" counts the prescriber -----------------------
create or replace function guard_medication_request()
returns trigger
language plpgsql
as $$
begin
  -- the checked (security definer) functions run as their owner, not as the API roles
  if current_user::text not in ('authenticated', 'anon') then
    return coalesce(new, old);
  end if;
  if tg_op = 'INSERT' then
    raise exception 'prescriptions are written with the prescription form only' using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'a prescription is not deleted: the doctor cancels it' using errcode = '42501';
  end if;
  if new.given_at is distinct from old.given_at or new.given_by is distinct from old.given_by
     or new.not_given_at is distinct from old.not_given_at or new.not_given_by is distinct from old.not_given_by
     or new.not_given_reason is distinct from old.not_given_reason
     or new.cancelled_at is distinct from old.cancelled_at or new.cancelled_by is distinct from old.cancelled_by
     or new.cancel_reason is distinct from old.cancel_reason
     or new.supply is distinct from old.supply or new.quantity is distinct from old.quantity
     or new.item_id is distinct from old.item_id or new.encounter_id is distinct from old.encounter_id
     or new.prescriber_id is distinct from old.prescriber_id or new.deleted_at is distinct from old.deleted_at
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'handing over, not given, cancelling and the medicine or quantity change only through the pharmacy and prescription screens'
      using errcode = '42501';
  end if;
  return new;
end
$$;

create or replace function treated(p_encounter_id uuid, p_user uuid default auth.uid())
returns boolean
language sql stable security definer set search_path = public
as $$
  select p_user is not null and (
    exists (select 1 from queue_entry q
            where q.encounter_id = p_encounter_id and q.deleted_at is null and q.taken_by = p_user
              and station_desks(q.station) && treating_desks())
    or exists (select 1 from condition c
               where c.encounter_id = p_encounter_id and c.deleted_at is null and c.created_by = p_user)
    or exists (select 1 from observation o
               where o.encounter_id = p_encounter_id and o.deleted_at is null and o.code = 'note'
                 and coalesce(o.performer_id, o.created_by) = p_user)
    or exists (select 1 from medication_request m
               where m.encounter_id = p_encounter_id and m.deleted_at is null
                 and (m.prescriber_id = p_user or (m.prescriber_id is null and m.created_by = p_user)))
    or exists (select 1 from service_request r
               where r.encounter_id = p_encounter_id and r.deleted_at is null and r.requester_id = p_user)
    or exists (select 1 from service_request r
               join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
               where r.encounter_id = p_encounter_id and r.category = 'imaging'
                 and (d.created_by = p_user or d.verified_by = p_user))
    or exists (select 1 from procedure pr
               where pr.encounter_id = p_encounter_id and pr.deleted_at is null and pr.performer_id = p_user)
    or exists (select 1 from staff_call c
               where c.encounter_id = p_encounter_id and c.kind = 'help' and c.answered_by = p_user
                 and c.status in ('accepted', 'done'))
  )
$$;

-- 9. Deactivated, or given a new PIN: the approved sign-ins end at once -----------------------------
create or replace function end_sign_ins_on_account_change()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if (old.active and not new.active)
     or (new.must_change_pin and not coalesce(old.must_change_pin, false)) then
    update approved_session
       set ended_at = now(),
           ended_reason = case when not new.active then 'deactivated' else 'new PIN' end
     where user_id = new.id and ended_at is null;
  end if;
  return new;
end
$$;
revoke all on function end_sign_ins_on_account_change() from public, anon, authenticated;
drop trigger if exists end_sign_ins_on_account_change on profiles;
create trigger end_sign_ins_on_account_change
  after update of active, must_change_pin on profiles
  for each row execute function end_sign_ins_on_account_change();

-- 10. A visit that ends without the cashier's settle step still posts its bill (number, and the
--     insurer's claim). Before, finish_visit with nothing left to pay and end_visit ("left without
--     paying") closed the visit with the bill still a draft: no invoice number, no claim.
create or replace function post_drafts_of_visit(p_encounter_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
begin
  for v_id in
    select i.id from invoice i
    where i.encounter_id = p_encounter_id and i.status = 'draft' and i.deleted_at is null
      and exists (select 1 from invoice_line l where l.invoice_id = i.id and l.deleted_at is null)
  loop
    perform post_invoice_now(v_id);
  end loop;
end
$$;
revoke all on function post_drafts_of_visit(uuid) from public, anon, authenticated;

-- finish_visit (from 20261115090000_medicines_list_pharmacy) + the bill posted when the visit closes
create or replace function finish_visit(p_encounter_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_rx boolean;
  v_due boolean;
  v_ticket text;
  v_next station;
  v_keep queue_entry%rowtype;
begin
  perform assert_may_work_on(p_encounter_id);
  v_rx := exists (select 1 from medication_request m where m.encounter_id = p_encounter_id and rx_pending(m));
  v_next := case when v_rx then 'pharmacy' else 'cashier' end;
  -- the patient already waits there (the doctor sent them on before finishing): keep that place
  select * into v_keep from queue_entry
  where encounter_id = p_encounter_id and station = v_next and finished_at is null and deleted_at is null
  order by created_at desc limit 1;
  perform close_encounter(p_encounter_id);
  v_due := exists (select 1 from invoice i where i.encounter_id = p_encounter_id and invoice_balance(i.id) > 0);
  if v_rx or v_due then
    -- Treatment is over; the visit stays open until the medicines are handed over and the bill is paid.
    update encounter set status = 'open', closed_at = null, closed_by = null, clinical_done_at = now()
    where id = p_encounter_id;
    if v_keep.id is not null then
      update queue_entry set finished_at = null,
             referral_note = coalesce(referral_note, case when v_rx then 'Medicines to hand over' end)
      where id = v_keep.id
      returning * into v_keep;
      perform notify_queue_entry_row(v_keep);
      return;
    end if;
    select ticket_no into v_ticket from queue_entry where encounter_id = p_encounter_id order by created_at limit 1;
    -- medicines first (their price joins the bill), then the cashier
    if v_rx then
      insert into queue_entry (encounter_id, station, ticket_no, referred_by, referral_note)
      values (p_encounter_id, 'pharmacy', coalesce(v_ticket, 'A-000'), auth.uid(), 'Medicines to hand over');
    else
      insert into queue_entry (encounter_id, station, ticket_no)
      values (p_encounter_id, 'cashier', coalesce(v_ticket, 'A-000'));
    end if;
  else
    -- nothing left to hand over or to pay: the visit is closed, its bill posted (insurer's claim)
    perform post_drafts_of_visit(p_encounter_id);
  end if;
end
$$;

-- end_visit (from 20261106090000_desks_wave8) + the bill posted when the visit closes
create or replace function end_visit(p_encounter_id uuid, p_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_due numeric;
begin
  if not has_perm('queue.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  select coalesce(sum(invoice_balance(i.id)), 0) into v_due from invoice i
  where i.encounter_id = p_encounter_id and i.status <> 'credited';
  if v_due > 0 then
    if current_role_key() <> 'manager' then
      raise exception 'money is still due (% RWF): take the payment first, or ask the manager', round(v_due)
        using errcode = '23514';
    end if;
    if nullif(trim(coalesce(p_reason, '')), '') is null then
      raise exception 'money is still due (% RWF): say why the patient left without paying', round(v_due)
        using errcode = '22023';
    end if;
  end if;
  update queue_entry set finished_at = now()
  where encounter_id = p_encounter_id and finished_at is null;
  update encounter
  set status = 'closed', closed_at = now(), closed_by = auth.uid(),
      left_reason = nullif(trim(coalesce(p_reason, '')), '')
  where id = p_encounter_id;
  -- the bill gets its number and the insurer's claim; what the patient owes stays on the unpaid list
  perform post_drafts_of_visit(p_encounter_id);
  return jsonb_build_object('due', v_due);
end
$$;

-- 11. visit_access (from 20261129090000_handover): the handover note only for the two colleagues
--     and clinicians who may see this visit
create or replace function visit_access(p_encounter_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'canWork', may_work_on(p_encounter_id),
    'canRoute', may_route(p_encounter_id),
    'holder', patient_holder(p_encounter_id),
    'helping', exists (select 1 from staff_call c
                       where c.encounter_id = p_encounter_id and c.kind = 'help'
                         and c.status = 'accepted' and c.answered_by = auth.uid()),
    'help', coalesce((
      select jsonb_agg(jsonb_build_object(
               'callId', c.id, 'status', c.status, 'asker', a.full_name,
               'helper', coalesce(h.full_name, t.full_name), 'mine', c.from_user = auth.uid(),
               'helperIsMe', c.answered_by = auth.uid(),
               'note', c.note) order by c.created_at)
      from staff_call c
      join profiles a on a.id = c.from_user
      left join profiles h on h.id = c.answered_by
      left join profiles t on t.id = c.to_user
      where c.encounter_id = p_encounter_id and c.kind = 'help' and c.status in ('open', 'accepted')), '[]'::jsonb),
    -- 0088: I have the patient at a treating desk and may hand them over
    'canHandOver', handover_held_queue(p_encounter_id, auth.uid()) is not null and has_perm('clinical.write'),
    -- 0088: the handover waiting for an answer on this visit (to me, from me, or clinicians who
    -- may see this visit: the note is clinical)
    'handover', (
      select handover_json(h) || jsonb_build_object('mine', h.from_user = auth.uid(), 'forMe', h.to_user = auth.uid())
      from patient_handover h
      where h.encounter_id = p_encounter_id and h.status = 'pending' and h.deleted_at is null
        and (h.from_user = auth.uid() or h.to_user = auth.uid()
             or (has_perm('clinical.read') and visit_view(p_encounter_id) is not null))
      order by h.created_at desc limit 1)
  )
  where exists (select 1 from profiles where id = auth.uid() and active)
$$;

-- 12. A medicine returned on a bill not yet posted but already paid: the cashier is told there is money to give back.
-- (from 20261126090000_departments_decide_desks)
create or replace function return_medicine(p_medication_request_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_d medication_dispense%rowtype;
  v_inv invoice%rowtype;
  v_mv record;
  v_back integer := 0;
  v_patient numeric := 0;
  v_insurer numeric := 0;
  v_total numeric := 0;
  v_lines jsonb;
  v_cn uuid;
  v_year integer := extract(year from now())::integer;
  v_balance numeric;
  v_name text;
  v_item text;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the medicine comes back' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_medication_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  select * into v_d from medication_dispense
  where medication_request_id = v_m.id and deleted_at is null order by created_at desc limit 1;
  if not found then
    raise exception 'this medicine was not handed over by the pharmacy' using errcode = 'P0002';
  end if;
  if not is_manager()
     and (v_d.created_at at time zone 'Africa/Kigali')::date <> (now() at time zone 'Africa/Kigali')::date then
    raise exception 'a hand-over of another day is undone by the manager' using errcode = '42501';
  end if;
  select * into v_inv from invoice where encounter_id = v_m.encounter_id;
  -- On a posted bill the return is money (a credit note, a smaller insurer claim): the person's
  -- own right, which a department or cover never gives.
  if v_inv.id is not null and v_inv.status <> 'draft'
     and not (is_manager() or staff_perm(auth.uid(), 'stock.dispense') or has_perm('billing.write')) then
    raise exception 'a medicine on a posted bill is taken back by the pharmacist or the manager'
      using errcode = '42501';
  end if;
  -- the units go back where they came from
  for v_mv in
    select item_id, batch_id, from_location_id, quantity from stock_movement
    where dispense_id = v_d.id and type = 'dispense' and deleted_at is null
  loop
    insert into stock_movement (item_id, batch_id, to_location_id, quantity, type, reason, dispense_id, medication_request_id)
    values (v_mv.item_id, v_mv.batch_id, v_mv.from_location_id, v_mv.quantity, 'return', trim(p_reason), v_d.id, v_m.id);
    v_back := v_back + v_mv.quantity;
  end loop;
  update medication_dispense set deleted_at = now() where id = v_d.id;

  if v_inv.id is null or v_inv.status = 'draft' then
    -- the bill is still open: the line leaves it, and the medicine waits at the pharmacy again
    update invoice_line set deleted_at = now(),
           manual_reason = coalesce(manual_reason || ' · ', '') || 'returned: ' || trim(p_reason)
    where source_type = 'medication_dispense' and source_id = v_d.id and deleted_at is null;
    if v_inv.id is not null then
      perform recompute_invoice(v_inv.id);
    end if;
    update medication_request set given_at = null, given_by = null where id = v_m.id;
    if exists (select 1 from encounter where id = v_m.encounter_id and status = 'open')
       and not exists (select 1 from queue_entry where encounter_id = v_m.encounter_id and station = 'pharmacy'
                       and finished_at is null and deleted_at is null) then
      insert into queue_entry (encounter_id, station, ticket_no)
      values (v_m.encounter_id, 'pharmacy',
              (select ticket_no from queue_entry where encounter_id = v_m.encounter_id order by created_at limit 1));
    end if;
    v_balance := case when v_inv.id is not null then invoice_balance(v_inv.id) else 0 end;
    if v_balance < 0 then
      -- the bill was already paid: money to give back, the cashier is told
      select p.surname || ' ' || p.given_names into v_name
      from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
      select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
      insert into notification (kind, params, link, recipient_stations, created_by)
      values ('refund_due', jsonb_build_object('name', v_name, 'item', v_item, 'amount', -v_balance,
                                               'reason', trim(p_reason)),
              '/app/visit?encounter=' || v_m.encounter_id, array['cashier'::station], auth.uid());
    end if;
    return jsonb_build_object('units', v_back, 'mode', 'bill', 'creditNoteId', null, 'credit', 0,
                              'balance', v_balance);
  end if;

  -- The bill is posted: its lines never change. A credit note gives the line back: the patient's
  -- share lowers what they owe (or is money to give back at the cashier); the insurer's share
  -- leaves an open claim.
  select coalesce(sum(l.patient_share), 0), coalesce(sum(l.insurer_share), 0),
         coalesce(sum(round(l.unit_price * l.quantity)), 0),
         coalesce(jsonb_agg(jsonb_build_object('lineId', l.id, 'description', l.description, 'quantity', l.quantity,
                                               'unitPrice', l.unit_price, 'patientShare', l.patient_share,
                                               'insurerShare', l.insurer_share)), '[]'::jsonb)
  into v_patient, v_insurer, v_total, v_lines
  from invoice_line l
  where l.invoice_id = v_inv.id and l.source_type = 'medication_dispense' and l.source_id = v_d.id
    and l.deleted_at is null;
  if v_total > 0 then
    insert into credit_note (invoice_id, number, lines, total, reason, approver_id, patient_amount, insurer_amount,
                             source_type, source_id)
    values (v_inv.id, 'CN-' || v_year || '-' || lpad(next_number('credit_note', v_year)::text, 6, '0'),
            v_lines, v_total, 'returned: ' || trim(p_reason), auth.uid(), v_patient, v_insurer,
            'medication_dispense', v_d.id)
    returning id into v_cn;
    if v_insurer > 0 then
      update claim set amount = greatest(0, amount - v_insurer)
      where invoice_id = v_inv.id and status = 'open' and batch_id is null;
    end if;
  end if;
  -- the line is done: returned (it does not wait at the pharmacy again)
  update medication_request
  set given_at = null, given_by = null, not_given_at = now(), not_given_by = auth.uid(),
      not_given_reason = 'returned: ' || trim(p_reason)
  where id = v_m.id;
  v_balance := invoice_balance(v_inv.id);
  if v_balance < 0 then
    -- money to give back: the cashier is told
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
    select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
    insert into notification (kind, params, link, recipient_stations, created_by)
    values ('refund_due', jsonb_build_object('name', v_name, 'item', v_item, 'amount', -v_balance,
                                             'reason', trim(p_reason)),
            '/app/visit?encounter=' || v_m.encounter_id, array['cashier'::station], auth.uid());
  end if;
  return jsonb_build_object('units', v_back, 'mode', 'credit', 'creditNoteId', v_cn, 'credit', v_patient,
                            'balance', v_balance);
end
$$;

-- 13. Putting back a medicine given here on a paid, not yet posted bill: the cashier is told too.
-- (from 20261124090000_stores_and_stock)
create or replace function undo_given_here(p_request_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_inv invoice%rowtype;
  v_mv record;
  v_back integer := 0;
  v_patient numeric := 0;
  v_insurer numeric := 0;
  v_total numeric := 0;
  v_lines jsonb;
  v_cn uuid;
  v_year integer := extract(year from now())::integer;
  v_balance numeric;
  v_mode text := 'bill';
  v_name text;
begin
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the medicine is put back' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  if v_m.not_given_at is not null or v_m.cancelled_at is not null then
    raise exception 'this medicine was already put back' using errcode = '23505';
  end if;
  if v_m.supply <> 'room' or v_m.given_at is null then
    raise exception 'only a medicine given here is put back here' using errcode = '22023';
  end if;
  if not is_manager() then
    if v_m.given_by is distinct from auth.uid() then
      raise exception 'only the person who gave it (or the manager) puts it back' using errcode = '42501';
    end if;
    if (v_m.given_at at time zone 'Africa/Kigali')::date <> (now() at time zone 'Africa/Kigali')::date then
      raise exception 'a medicine given on another day is put back by the manager' using errcode = '42501';
    end if;
  end if;
  -- the units go back into the store they came from
  for v_mv in
    select item_id, batch_id, from_location_id, sum(quantity)::integer as quantity from stock_movement
    where medication_request_id = v_m.id and type = 'consumption' and from_location_id is not null and deleted_at is null
    group by item_id, batch_id, from_location_id
  loop
    insert into stock_movement (item_id, batch_id, to_location_id, quantity, type, reason, medication_request_id)
    values (v_mv.item_id, v_mv.batch_id, v_mv.from_location_id, v_mv.quantity, 'return',
            'put back: ' || trim(p_reason), v_m.id);
    v_back := v_back + v_mv.quantity;
  end loop;
  select * into v_inv from invoice where encounter_id = v_m.encounter_id;
  if v_inv.id is null or v_inv.status = 'draft' then
    update invoice_line set deleted_at = now(),
           manual_reason = coalesce(manual_reason || ' · ', '') || 'returned: ' || trim(p_reason)
    where source_type = 'medication_request' and source_id = v_m.id and deleted_at is null;
    if v_inv.id is not null then
      perform recompute_invoice(v_inv.id);
    end if;
  else
    v_mode := 'credit';
    select coalesce(sum(l.patient_share), 0), coalesce(sum(l.insurer_share), 0),
           coalesce(sum(round(l.unit_price * l.quantity)), 0),
           coalesce(jsonb_agg(jsonb_build_object('lineId', l.id, 'description', l.description, 'quantity', l.quantity,
                                                 'unitPrice', l.unit_price, 'patientShare', l.patient_share,
                                                 'insurerShare', l.insurer_share)), '[]'::jsonb)
    into v_patient, v_insurer, v_total, v_lines
    from invoice_line l
    where l.invoice_id = v_inv.id and l.source_type = 'medication_request' and l.source_id = v_m.id
      and l.deleted_at is null;
    if v_total > 0 then
      insert into credit_note (invoice_id, number, lines, total, reason, approver_id, patient_amount, insurer_amount,
                               source_type, source_id)
      values (v_inv.id, 'CN-' || v_year || '-' || lpad(next_number('credit_note', v_year)::text, 6, '0'),
              v_lines, v_total, 'returned: ' || trim(p_reason), auth.uid(), v_patient, v_insurer,
              'medication_request', v_m.id)
      returning id into v_cn;
      if v_insurer > 0 then
        update claim set amount = greatest(0, amount - v_insurer)
        where invoice_id = v_inv.id and status = 'open' and batch_id is null;
      end if;
    end if;
  end if;
  update medication_request
  set given_at = null, given_by = null, not_given_at = now(), not_given_by = auth.uid(),
      not_given_reason = 'returned: ' || trim(p_reason)
  where id = v_m.id;
  v_balance := case when v_inv.id is not null then invoice_balance(v_inv.id) else 0 end;
  if v_balance < 0 then
    -- money to give back: the cashier is told
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
    insert into notification (kind, params, link, recipient_stations, created_by)
    values ('refund_due', jsonb_build_object('name', v_name, 'item', item_label(v_m.item_id), 'amount', -v_balance,
                                             'reason', trim(p_reason)),
            '/app/visit?encounter=' || v_m.encounter_id, array['cashier'::station], auth.uid());
  end if;
  return jsonb_build_object('units', v_back, 'mode', v_mode, 'creditNoteId', v_cn,
                            'credit', case when v_mode = 'credit' then v_patient else 0 end, 'balance', v_balance);
end
$$;

-- 14. After a handover the colleague who took the patient may cancel a medicine still waiting at the pharmacy.
-- (from 20261126090000_departments_decide_desks)
create or replace function cancel_prescription(p_request_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_item text;
  v_name text;
  v_left integer;
begin
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the medicine is cancelled' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  if not (is_manager()
          or (has_perm('clinical.write')
              and (coalesce(v_m.prescriber_id, v_m.created_by) = auth.uid()
                   -- the patient was handed over: the colleague who took them now decides
                   or (may_work_on(v_m.encounter_id)
                       and result_recipient(v_m.encounter_id, coalesce(v_m.prescriber_id, v_m.created_by)) = auth.uid())))) then
    raise exception 'only the doctor treating the patient (or the manager) can cancel it' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  if not rx_pending(v_m) then
    raise exception 'this medicine is no longer waiting at the pharmacy (handed over, not given or cancelled)'
      using errcode = 'P0002';
  end if;
  update medication_request
  set cancelled_at = now(), cancelled_by = auth.uid(), cancel_reason = trim(p_reason)
  where id = v_m.id;
  -- the pharmacy is told the line left its list
  select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
  insert into notification (kind, params, link, recipient_stations, created_by)
  values ('rx_cancelled',
          jsonb_build_object('item', v_item, 'name', v_name, 'reason', trim(p_reason),
                             'by', (select full_name from profiles where id = auth.uid())),
          '/app/visit?encounter=' || v_m.encounter_id, array['pharmacy'::station], auth.uid());
  -- nothing left at the pharmacy: the patient goes on (back, cashier, or the visit closes)
  perform after_pharmacy(v_m.encounter_id);
  select count(*)::integer into v_left from medication_request m
  where m.encounter_id = v_m.encounter_id and rx_pending(m);
  return jsonb_build_object('id', v_m.id, 'pending', v_left,
                            'balance', invoice_balance((select id from invoice where encounter_id = v_m.encounter_id)));
end
$$;

-- 15. "My orders" follows a handed-over patient to the colleague who took them.
-- (from 20261119090000_audit_fixes)
create or replace function my_orders(p_days integer default 7, p_from date default null, p_to date default null)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(x.j order by x.at desc), '[]'::jsonb)
  from (
    select r.created_at as at, jsonb_build_object(
      'id', r.id, 'encounterId', r.encounter_id, 'patientId', p.id,
      'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
      'test', s.name_en,
      'station', coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end),
      'status', r.status, 'priority', r.priority, 'reason', r.reason, 'orderedAt', r.created_at,
      'findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
      'resultAt', coalesce(d.verified_at, d.updated_at),
      'resultBy', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
      'visitOpen', e.status = 'open') as j
    from service_request r
    join encounter e on e.id = r.encounter_id
    join patient p on p.id = e.patient_id
    join service s on s.id = r.service_id
    left join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
    where r.deleted_at is null and result_recipient(r.encounter_id, r.requester_id) = auth.uid()
      and case when p_from is not null
            then (r.created_at at time zone 'Africa/Kigali')::date between p_from and coalesce(p_to, p_from)
            else r.created_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 90))) end
    order by r.created_at desc
    limit 500
  ) x
$$;

-- 16. The head's department dashboard: the desks come from the department's services (as everywhere since 0085), by role only for a department without services.
-- (from 20261127090000_analytics)
create or replace function department_summary(p_department_id uuid, p_from date, p_to date)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_dept department%rowtype;
  v_days integer := greatest(1, p_to - p_from + 1);
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_midnight timestamptz := ((now() at time zone 'Africa/Kigali')::date)::timestamp at time zone 'Africa/Kigali';
  v_stations station[];
  v_members jsonb;
  v_queue jsonb;
  v_tiles jsonb;
  v_services jsonb;
begin
  if not (is_manager() or exists (
    select 1 from staff_department sd join profiles p on p.id = sd.profile_id
    where sd.profile_id = auth.uid() and sd.department_id = p_department_id
      and sd.position in ('head', 'assistant') and p.active)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_dept from department where id = p_department_id and deleted_at is null;
  if not found then
    raise exception 'department not found' using errcode = 'P0002';
  end if;
  select coalesce(array_agg(s), '{}') into v_stations
  from unnest(enum_range(null::station)) s
  where (cardinality(coalesce(v_dept.services, '{}')) > 0 and station_desks(s) && v_dept.services)
     or (cardinality(coalesce(v_dept.services, '{}')) = 0 and station_role(s) = any (v_dept.roles));

  -- the people of the department and what each did in the period
  with ev as (
    select ev.user_id, ev.kind
    from analytics_staff_events(p_from::timestamp at time zone 'Africa/Kigali',
                                (p_to + 1)::timestamp at time zone 'Africa/Kigali', false) ev
    where ev.user_id in (select sd.profile_id from staff_department sd where sd.department_id = p_department_id)
      and ev.kind in ('patientsSeen', 'registered', 'vitals', 'results', 'medicinesGiven', 'tasksDone')
  ),
  a as (
    select ev.user_id,
           count(*) filter (where kind = 'patientsSeen') as patients,
           count(*) filter (where kind = 'registered') as registrations,
           count(*) filter (where kind = 'vitals') as vitals,
           count(*) filter (where kind = 'results') as results,
           count(*) filter (where kind = 'medicinesGiven') as dispensed,
           count(*) filter (where kind = 'tasksDone') as tasks_done
    from ev group by ev.user_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.full_name, 'role', p.role, 'position', sd.position, 'station', p.station,
      'lastSignIn', p.last_sign_in_at, 'active', p.active,
      'patients', coalesce(a.patients, 0),
      'registrations', coalesce(a.registrations, 0),
      'vitals', coalesce(a.vitals, 0),
      'results', coalesce(a.results, 0),
      'dispensed', coalesce(a.dispensed, 0),
      'payments', (select count(*) from payment y where y.deleted_at is null and y.cashier_id = p.id
                   and (y.paid_at at time zone 'Africa/Kigali')::date between p_from and p_to),
      'tasksDone', coalesce(a.tasks_done, 0),
      'busyNow', (select count(*) from queue_entry q join encounter e on e.id = q.encounter_id
                  where q.taken_by = p.id and q.deleted_at is null and q.finished_at is null and e.status = 'open')
    ) order by case sd.position when 'head' then 0 when 'assistant' then 1 else 2 end, p.full_name), '[]'::jsonb)
  into v_members
  from staff_department sd join profiles p on p.id = sd.profile_id
  left join a on a.user_id = p.id
  where sd.department_id = p_department_id;

  -- the department's desks right now
  select coalesce(jsonb_agg(jsonb_build_object('station', w.station, 'waiting', w.waiting, 'busy', w.busy,
                                               'longest', w.longest, 'forgotten', w.forgotten) order by w.station), '[]'::jsonb)
  into v_queue
  from queue_now(v_stations) w;

  select jsonb_build_object(
    'patients', (select count(distinct q.encounter_id) from queue_entry q
                 where q.deleted_at is null and q.station = any (v_stations) and q.finished_at is not null
                   and (q.finished_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'patientsPrev', (select count(distinct q.encounter_id) from queue_entry q
                     where q.deleted_at is null and q.station = any (v_stations) and q.finished_at is not null
                       and (q.finished_at at time zone 'Africa/Kigali')::date between p_from - v_days and p_from - 1),
    'waitingNow', (select count(*) from queue_entry q join encounter e on e.id = q.encounter_id
                   where q.deleted_at is null and q.station = any (v_stations) and q.finished_at is null
                     and q.started_at is null and e.status = 'open' and q.created_at >= v_midnight),
    'forgottenNow', (select count(*) from queue_entry q join encounter e on e.id = q.encounter_id
                     where q.deleted_at is null and q.station = any (v_stations) and q.finished_at is null
                       and q.started_at is null and e.status = 'open' and q.created_at < v_midnight),
    'ordersOpen', (select count(*) from service_request r join encounter e on e.id = r.encounter_id
                   where r.deleted_at is null and e.status = 'open'
                     and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) = any (v_stations)
                     and r.status not in ('resulted', 'verified', 'cancelled')),
    'ordersNotDone', (select count(*) from service_request r
                      where r.deleted_at is null and r.status = 'cancelled'
                        and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) = any (v_stations)
                        and (r.updated_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'tasksOpen', (select count(*) from internal_task k join encounter e on e.id = k.encounter_id
                  where k.deleted_at is null and k.done_at is null and e.status = 'open'
                    and k.assigned_role = any (v_dept.roles)),
    'members', jsonb_array_length(v_members),
    'signedInToday', (select count(*) from staff_department sd join profiles p on p.id = sd.profile_id
                      where sd.department_id = p_department_id
                        and (p.last_sign_in_at at time zone 'Africa/Kigali')::date = v_today)
  ) into v_tiles;

  -- the department's treatments done in the period (count only)
  select coalesce(jsonb_agg(jsonb_build_object('name', x.name, 'count', x.n) order by x.n desc), '[]'::jsonb) into v_services
  from (
    select l.description as name, count(*) as n
    from invoice_line l
    join service_department sv on sv.service_id = l.service_id and sv.department_id = p_department_id
    where l.deleted_at is null and (l.created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by l.description order by count(*) desc limit 10
  ) x;

  return jsonb_build_object('department', jsonb_build_object('id', v_dept.id, 'name', v_dept.name, 'roles', v_dept.roles),
                            'stations', to_jsonb(v_stations), 'tiles', v_tiles, 'members', v_members,
                            'queue', v_queue, 'services', v_services);
end
$$;

-- 17. Sending a patient to a department: the department must give that desk (its services), by role only for a department without services.
-- (from 20261126090000_departments_decide_desks)
create or replace function begin_visit(
  p_patient_id uuid,
  p_station station default 'consultation',
  p_department_id uuid default null,
  p_note text default null,
  p_myself boolean default false,
  p_emergency boolean default false,
  p_service text default null,
  p_assigned_to uuid default null,
  p_triage_to uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_role role_key := current_role_key();
  v_desk station := coalesce(case when not p_myself then service_station(p_service) end, p_station);
  v_station station;
  v_enc uuid;
  v_q queue_entry%rowtype;
begin
  if not has_perm('queue.write') or not has_perm('visit.start') then
    raise exception 'you may not start visits (the manager has not allowed it)' using errcode = '42501';
  end if;
  -- A visit is started at reception. "I take the patient myself" is decided below (the person's
  -- own desk); an emergency by the people who treat, wherever reception is given.
  if not (p_myself or p_emergency) then
    perform assert_desk(array['reception'], 'starting visits');
  elsif p_emergency and not p_myself then
    perform assert_desk(array['reception', 'triage'] || treating_desks(), 'emergency visits');
  end if;
  if p_emergency and v_role in ('receptionist', 'cashier') then
    raise exception 'only treating staff can register an emergency' using errcode = '42501';
  end if;
  if p_service is not null and service_station(p_service) is null then
    raise exception 'unknown service' using errcode = '22023';
  end if;
  if p_myself and not (
       v_role = 'manager'
       or (v_role = 'doctor' and v_desk in ('consultation', 'dental', 'theatre', 'ultrasound'))
       or (v_role = 'nurse' and v_desk in ('triage', 'nursing', 'beds'))
       or (v_role = 'lab_tech' and v_desk = 'laboratory')
       or (v_role = 'sonographer' and v_desk = 'ultrasound')
       or (v_role = 'pharmacist' and v_desk = 'pharmacy')
       -- or a department of theirs gives that desk (a nurse of the Laboratory …)
       or exists (select 1 from unnest(station_desks(v_desk)) as d(desk)
                  where in_desk_department(auth.uid(), d.desk) and may_use_desk(d.desk))) then
    raise exception 'you do not work at % : send the patient there instead', initcap(v_desk::text)
      using errcode = '42501';
  end if;
  if p_assigned_to is not null and (p_service is null or not staff_serves(p_assigned_to, p_service)) then
    raise exception 'that person does not give this service' using errcode = '22023';
  end if;
  if p_triage_to is not null and not staff_serves(p_triage_to, 'triage') then
    raise exception 'that person does not work at triage' using errcode = '22023';
  end if;
  if p_department_id is not null and not exists (
       select 1 from department d where d.id = p_department_id and d.deleted_at is null
         and ((cardinality(coalesce(d.services, '{}')) > 0 and station_desks(v_desk) && d.services)
              or (cardinality(coalesce(d.services, '{}')) = 0 and station_role(v_desk) = any (d.roles)))) then
    raise exception 'that department does not work at %', initcap(v_desk::text) using errcode = '22023';
  end if;
  if exists (select 1 from encounter where patient_id = p_patient_id and status = 'open') then
    raise exception 'this patient already has an open visit' using errcode = '23505';
  end if;

  v_station := case
    when p_myself or p_emergency then v_desk
    when triage_first() then 'triage'::station
    else v_desk end;
  perform set_config('mmc.visit_open', 'on', true);
  v_enc := open_encounter(p_patient_id, 'opd', v_station);
  perform set_config('mmc.visit_open', '', true);
  -- the service and the person chosen stay with the visit (used after triage)
  update encounter
  set service = p_service, intended_to = case when p_myself then auth.uid() else p_assigned_to end,
      practitioner_id = case
        when p_assigned_to is not null and exists (select 1 from profiles where id = p_assigned_to and role = 'doctor')
        then ensure_practitioner(p_assigned_to) else practitioner_id end
  where id = v_enc;

  if p_emergency then
    update encounter
    set triage_level = 'red', triage_reason = 'Emergency: registered directly at ' || v_station::text
    where id = v_enc;
    update queue_entry set priority = 1 where encounter_id = v_enc;
  end if;

  select * into v_q from queue_entry
  where encounter_id = v_enc and station = v_station and finished_at is null and deleted_at is null
  order by created_at limit 1;
  update queue_entry
  set referral_note = coalesce(nullif(trim(coalesce(p_note, '')), ''), referral_note),
      service = p_service,
      department_id = case when v_station = v_desk and p_assigned_to is null then coalesce(p_department_id, department_id) else department_id end,
      assigned_to = case
        when v_station = 'triage' and not p_myself then coalesce(p_triage_to, assigned_to)
        when v_station = v_desk and not p_myself then coalesce(p_assigned_to, assigned_to)
        else assigned_to end,
      referred_by = auth.uid()
  where id = v_q.id
  returning * into v_q;
  if p_myself then
    perform take_patient(v_q.id);
    delete from notification where kind = 'queue' and params ->> 'queue' = v_q.id::text;
  elsif v_q.assigned_to is not null then
    -- the person chosen is told (instead of everyone at the desk)
    perform notify_queue_entry_row(v_q);
  end if;

  return jsonb_build_object(
    'encounter_id', v_enc,
    'ticket_no', v_q.ticket_no,
    'station', v_station,
    'myself', p_myself,
    'assigned', (select full_name from profiles where id = v_q.assigned_to),
    'department', (select name from department where id = p_department_id));
end
$$;


-- ============================================================ 20261203090000_guide_fixes.sql
-- Fixes found while writing the system guide (26 October 2026): the rules the screens relied on
-- but the database did not enforce, and a few leaks.
--
--  1. staff_login_email gave anyone the e-mail of a staff member from the staff ID and username
--     alone (the lookup was callable by visitors). It now needs the PIN too, checked against the
--     Auth password hash, with the same limit as staff-otp (5 wrong PINs in 15 minutes).
--  2. home_summary listed the open bills (names, balances) to every role: now only for the people
--     who take payments, and the manager.
--  3. HIV tests were hidden only in the home results inbox: now also in visit_clinical's test list
--     for readers without sensitive.read, and in the laboratory worklist for anyone who has neither
--     that right nor the desk that runs the test (the laboratory and ultrasound staff keep their
--     work); add_diagnosis refuses an HIV code (ICD-10 B20–B24) to people without the right.
--  4. dashboard_summary showed a head of department "Who did what" and the sign-ins of the whole
--     clinic: now their own department's people only (the manager still sees everyone).
--  5. A second PIN reset while the first was still pending left the old sign-ins alive: every new
--     temporary PIN ends them; a manager cannot give themself a temporary PIN.
--  6. decline_appointment did not check the calendar's owner (accept_appointment did).
--  7. mark_result_reviewed let any clinician mark any result seen: now the requester, the colleague
--     who took the patient over, or the manager.
--  8. record_vitals accepts the same limits as the form (an impossible value is a typing mistake).
--  9. merge_patients also moves the duplicate's files and record-access rows; the two patient
--     searches find a patient by a file number recorded at a merge.
-- 10. The "file added to a test" notice follows the patient to the colleague who took them over.
-- 11. patient_file tells the edit form which private extra fields already have a value
--     (`extra_filled`), so an empty one can be filled and a filled one locked.
-- (The beds limit stays at 200; set_bed_count already refuses with errcode 22023.)

-- 1. The sign-in e-mail lookup needs the PIN ------------------------------------------------------
-- The PIN is the Supabase Auth password; its bcrypt hash is compared here (pgcrypto's crypt, which
-- lives in the extensions schema on Supabase). A wrong PIN is written to the audit log like the
-- ones staff-otp and the lock screen record, so the three share one limit.
drop function if exists staff_login_email(text, text);
create or replace function staff_login_email(p_staff_id text, p_username text, p_pin text)
returns text
language plpgsql security definer set search_path = public, extensions
as $$
declare
  v_id uuid;
  v_email text;
  v_hash text;
begin
  select p.id, p.email into v_id, v_email
  from profiles p
  where p.staff_id = upper(trim(p_staff_id)) and p.username = lower(trim(p_username)) and p.active;
  if not found or coalesce(p_pin, '') !~ '^[0-9]{6}$' then
    return null;
  end if;
  -- too many wrong PINs lately: no answer, so the PIN cannot be guessed here either
  if (select count(*) from audit_event a
      where a.actor_id = v_id and a.action = 'login' and a.reason like 'wrong PIN%'
        and a.at > now() - interval '15 minutes') >= 5 then
    return null;
  end if;
  select u.encrypted_password into v_hash from auth.users u where u.id = v_id;
  if v_hash is null or v_hash not like '$2%' or crypt(p_pin, v_hash) <> v_hash then
    insert into audit_event (actor_id, action, entity, entity_id, reason)
    values (v_id, 'login', 'profiles', v_id, 'wrong PIN (lookup)');
    return null;
  end if;
  return v_email;
end
$$;
revoke all on function staff_login_email(text, text, text) from public;
grant execute on function staff_login_email(text, text, text) to anon, authenticated;

-- 2. Open bills only for the people who take payments ---------------------------------------------
create or replace function home_summary(p_from date default null, p_to date default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_role role_key := current_role_key();
  v_practitioner uuid := (select id from practitioner where user_id = auth.uid() and active limit 1);
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today);
  v_to date := coalesce(p_to, p_from, v_today);
  v_appts jsonb;
  v_inquiries jsonb;
  v_mine jsonb;
  v_to_accept jsonb;
  v_bills jsonb := '[]'::jsonb;
  v_paid jsonb;
  v_beds jsonb;
  v_tasks jsonb;
  v_results jsonb;
begin
  if v_role is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;

  -- today's booked patients (reception, doctors)
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'time', to_char(a.starts_at at time zone 'Africa/Kigali', 'HH24:MI'),
      'name', coalesce(p.surname || ' ' || p.given_names, a.contact_name),
      'doctor', coalesce(pr.names, ''), 'station', coalesce(a.category, ''),
      'status', case when a.status in ('arrived', 'in_progress', 'completed') then 'arrived'
                     when a.starts_at < now() then 'late' else 'due' end,
      'mine', (a.practitioner_id = v_practitioner),
      'encounterId', (select e.id from encounter e where e.appointment_id = a.id order by e.arrived_at desc limit 1)
    ) order by a.starts_at), '[]'::jsonb) into v_appts
  from appointment a
  left join patient p on p.id = a.patient_id
  left join practitioner pr on pr.id = a.practitioner_id
  where a.deleted_at is null and a.status in ('approved', 'confirmed', 'arrived', 'in_progress', 'completed')
    and (a.starts_at at time zone 'Africa/Kigali')::date between v_from and v_to;

  -- public inquiries waiting for reception
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', a.contact_name, 'phone', a.contact_phone, 'reference', a.reference,
      'category', a.category, 'doctor', pr.names, 'channel', a.contact_channel,
      'when', case when a.starts_at is null then null else to_char(a.starts_at at time zone 'Africa/Kigali', 'DD/MM HH24:MI') end,
      'note', a.reason
    ) order by a.created_at), '[]'::jsonb) into v_inquiries
  from appointment a
  left join practitioner pr on pr.id = a.practitioner_id
  where a.deleted_at is null and a.status = 'inquiry';

  -- approved bookings this practitioner still has to accept
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'name', coalesce(p.surname || ' ' || p.given_names, a.contact_name),
      'when', to_char(a.starts_at at time zone 'Africa/Kigali', 'DD/MM HH24:MI'), 'note', a.reason,
      'category', a.category, 'startsAt', a.starts_at
    ) order by a.starts_at), '[]'::jsonb) into v_to_accept
  from appointment a
  left join patient p on p.id = a.patient_id
  where a.deleted_at is null and a.status = 'approved' and a.practitioner_id = v_practitioner
    and a.starts_at > now() - interval '1 day';

  -- open bills: visits with something charged and a patient balance, for the people who take
  -- payments and the manager (the other roles have no business with names and balances)
  if has_perm('payment.take') or is_manager() then
    select coalesce(jsonb_agg(jsonb_build_object(
        'encounterId', i.encounter_id, 'name', p.surname || ' ' || p.given_names, 'file', p.file_number,
        'ticket', (select ticket_no from queue_entry q where q.encounter_id = i.encounter_id order by q.created_at limit 1),
        'station', (select station from queue_entry q where q.encounter_id = i.encounter_id and q.finished_at is null order by q.created_at desc limit 1),
        'amount', i.patient_share, 'balance', invoice_balance(i.id), 'status', i.status
      ) order by i.updated_at desc), '[]'::jsonb) into v_bills
    from invoice i
    join encounter e on e.id = i.encounter_id
    join patient p on p.id = e.patient_id
    where i.deleted_at is null and i.total > 0 and e.status = 'open' and invoice_balance(i.id) > 0;
  end if;

  select jsonb_build_object('count', count(*), 'amount', coalesce(sum(amount), 0)) into v_paid
  from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to;

  -- beds
  select coalesce(jsonb_agg(jsonb_build_object(
      'n', b.sort_order, 'name', b.name, 'state', b.status,
      'who', (select p.surname || ' ' || left(p.given_names, 1) || '.' from bed_stay s join encounter e on e.id = s.encounter_id join patient p on p.id = e.patient_id
              where s.bed_id = b.id and s.discharged_at is null limit 1)
    ) order by b.sort_order, b.name), '[]'::jsonb) into v_beds
  from bed b where b.deleted_at is null;

  -- tasks for my role or me
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', k.id, 'time', to_char(k.due_at at time zone 'Africa/Kigali', 'HH24:MI'), 'title', k.title,
      'detail', coalesce(k.detail, ''), 'overdue', (k.due_at < now()),
      'patient', (select p.surname || ' ' || p.given_names from patient p where p.id = k.patient_id)
    ) order by k.due_at), '[]'::jsonb) into v_tasks
  from internal_task k
  where k.deleted_at is null and k.done_at is null and (k.assigned_to = auth.uid() or task_for_me(k.assigned_role));

  -- lab / imaging results of the last two days: a doctor's own requests; the manager; others only
  -- results of visits they may see (privacy levels); HIV tests only with sensitive.read
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'encounterId', sr.encounter_id, 'test', s.name_en,
      'name', p.surname || ' ' || p.given_names, 'impression', coalesce(r.impression, r.findings, ''),
      'verified', (r.verified_at is not null), 'at', to_char(r.updated_at at time zone 'Africa/Kigali', 'HH24:MI'),
      'reviewed', (r.reviewed_at is not null), 'corrected', (r.corrected_at is not null)
    ) order by (r.reviewed_at is null) desc, r.updated_at desc), '[]'::jsonb) into v_results
  from diagnostic_report r
  join service_request sr on sr.id = r.service_request_id
  join service s on s.id = sr.service_id
  join encounter e on e.id = sr.encounter_id
  join patient p on p.id = e.patient_id
  where r.deleted_at is null
    and (r.updated_at > now() - interval '2 days' or (r.reviewed_at is null and r.updated_at > now() - interval '7 days'))
    and (
      -- after a handover the results follow the patient to the colleague who took them
      (v_role = 'doctor' and result_recipient(sr.encounter_id, sr.requester_id) = auth.uid())
      or is_manager()
      or (v_role is distinct from 'doctor' and has_perm('orders.read')
          and visit_view(sr.encounter_id) is not null)
    )
    and (has_perm('sensitive.read') or not sensitive_service(s.id));

  return jsonb_build_object(
    'role', v_role,
    -- the patients this person took and finished today (a doctor's "Seen")
    'seenToday', (select count(distinct q.encounter_id) from queue_entry q
                  where q.taken_by = auth.uid() and q.deleted_at is null and q.finished_at is not null
                    and (q.finished_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'appointments', v_appts,
    'inquiries', v_inquiries,
    'toAccept', v_to_accept,
    'openBills', v_bills,
    'paidToday', v_paid,
    'beds', v_beds,
    'tasks', v_tasks,
    'results', v_results
  );
end
$$;

-- 3. HIV tests and diagnoses only for the people allowed to see them ------------------------------
-- The one rule the home inbox used (name or code says HIV), for every list.
create or replace function sensitive_service(p_service_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from service s
    where s.id = p_service_id
      and (coalesce(s.name_en, '') ilike '%hiv%' or coalesce(s.code, '') ilike '%hiv%')
  )
$$;
revoke all on function sensitive_service(uuid) from public, anon, authenticated;

create or replace function visit_clinical(p_encounter_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_view text;
  v_patient uuid;
  v_closed boolean;
  v_safe boolean;
begin
  -- clinicians; the lab and the pharmacy read the record too (their orders and prescriptions)
  if not clinical_reader() then
    return null;
  end if;
  select e.patient_id, e.status = 'closed' into v_patient, v_closed
  from encounter e where e.id = p_encounter_id and e.deleted_at is null;
  if v_patient is null then
    return null;
  end if;
  v_view := visit_view(p_encounter_id);
  if v_view is null then
    v_safe := patient_level(v_patient) <> 'identity';
    return jsonb_build_object(
      'diagnoses', '[]'::jsonb, 'notes', '[]'::jsonb, 'prescriptions', '[]'::jsonb, 'orders', '[]'::jsonb,
      'patient', (select jsonb_build_object('id', p.id,
                    'allergies', case when v_safe then p.allergies end,
                    'bloodGroup', case when v_safe then p.blood_group end,
                    'notes', case when v_safe then p.notes end,
                    'flags', case when v_safe then p.flags else '{}'::jsonb end)
                  || case when v_safe then doc_patient(p.id, p_encounter_id)
                          else doc_patient(p.id, p_encounter_id) - 'allergies' - 'allergiesNone' - 'bloodGroup'
                               - 'weightKg' - 'weightAt' end
                  from patient p where p.id = v_patient),
      'visit', doc_visit(p_encounter_id),
      'private', true,
      'view', null,
      'access', patient_access(v_patient));
  end if;
  if v_closed then
    perform log_record_access(v_patient, p_encounter_id, v_view, 'visit');
  end if;
  return jsonb_build_object(
    'diagnoses', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'text', c.text, 'icd10', c.icd10_code, 'type', c.type, 'provisional', c.provisional, 'at', c.created_at,
        'by', (select full_name from profiles where id = c.created_by)) order by c.created_at)
      from condition c where c.encounter_id = p_encounter_id and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'))), '[]'::jsonb),
    'notes', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'text', o.value_text, 'at', o.effective_at,
        'by', (select full_name from profiles where id = o.performer_id)) order by o.effective_at)
      from observation o where o.encounter_id = p_encounter_id and o.code = 'note' and o.deleted_at is null), '[]'::jsonb),
    'prescriptions', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'by', (select full_name from profiles where id = coalesce(m.prescriber_id, m.created_by)), 'item', i.name_generic || coalesce(' ' || i.strength, ''), 'dose', m.dose, 'route', m.route,
        'frequency', m.frequency, 'days', m.duration_days, 'quantity', m.quantity, 'instructions', m.instructions, 'at', m.created_at,
        'dispensed', m.supply = 'room' or exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null),
        'supply', m.supply, 'givenAt', m.given_at, 'givenBy', (select full_name from profiles where id = m.given_by),
        'notGivenAt', m.not_given_at, 'notGivenReason', m.not_given_reason,
        'prescriberId', coalesce(m.prescriber_id, m.created_by), 'pending', rx_pending(m),
        'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
        'cancelledBy', (select full_name from profiles where id = m.cancelled_by),
        'prescriber', doc_person(coalesce(m.prescriber_id, m.created_by))) order by m.created_at)
      from medication_request m join item i on i.id = m.item_id where m.encounter_id = p_encounter_id and m.deleted_at is null), '[]'::jsonb),
    -- HIV tests (like the diagnoses above) only for the people allowed to see them
    'orders', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'test', s.name_en, 'category', r.category, 'station', coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end), 'status', r.status, 'reason', r.reason, 'at', r.created_at, 'mine', coalesce(r.requester_id = auth.uid(), false),
        'result', (select jsonb_build_object('findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
          'corrected', d.corrected_at is not null, 'correctionReason', d.correction_reason,
          'at', coalesce(d.verified_at, d.updated_at), 'by', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
          'byPerson', doc_person(coalesce(d.verified_by, d.created_by)))
          from diagnostic_report d where d.service_request_id = r.id and d.deleted_at is null)) order by r.created_at)
      from service_request r join service s on s.id = r.service_id
      where r.encounter_id = p_encounter_id and r.deleted_at is null
        and (has_perm('sensitive.read') or not sensitive_service(s.id))), '[]'::jsonb),
    'patient', (select jsonb_build_object('id', p.id, 'allergies', p.allergies, 'bloodGroup', p.blood_group, 'notes', p.notes, 'flags', p.flags)
                       || doc_patient(p.id, e.id)
      from encounter e join patient p on p.id = e.patient_id where e.id = p_encounter_id),
    'visit', doc_visit(p_encounter_id),
    'private', false,
    'view', v_view
  );
end
$$;

create or replace function lab_worklist(p_scope text default 'open')
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(x.j order by x.prio, x.at), '[]'::jsonb)
  from (
    select r.priority as prio, r.created_at as at, doc_patient(p.id, e.id) || jsonb_build_object(
      'id', r.id, 'encounterId', r.encounter_id, 'patientId', p.id,
      'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
      'sex', p.sex, 'birthDate', p.birth_date,
      'ticket', (select q.ticket_no from queue_entry q where q.encounter_id = r.encounter_id order by q.created_at limit 1),
      'triage', e.triage_level,
      'test', s.name_en, 'category', r.category, 'status', r.status, 'priority', r.priority,
      'reason', r.reason, 'orderedAt', r.created_at,
      'orderedBy', (select full_name from profiles where id = r.requester_id),
      'findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
      'corrected', d.corrected_at is not null,
      'resultAt', coalesce(d.verified_at, d.updated_at),
      'resultBy', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
      'resultByPerson', doc_person(coalesce(d.verified_by, d.created_by)),
      'visitReference', e.reference, 'visitAt', e.arrived_at
    ) as j
    from service_request r
    join encounter e on e.id = r.encounter_id and (p_scope = 'done' or e.status = 'open')
    join patient p on p.id = e.patient_id
    join service s on s.id = r.service_id
    left join diagnostic_report d on d.service_request_id = r.id and d.deleted_at is null
    where r.deleted_at is null and has_perm('orders.read')
      and r.category in (select unnest(my_test_categories())) and coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end) in ('laboratory', 'ultrasound')
      -- HIV tests: the people allowed to see them, and the desk that runs them (the laboratory and
      -- ultrasound staff do their work whatever their rights)
      and (has_perm('sensitive.read') or may_use_desk(request_desk(r.station, r.category))
           or not sensitive_service(s.id))
      and case when p_scope = 'done'
            then r.status in ('resulted', 'verified')
                 and (coalesce(d.verified_at, d.updated_at) at time zone 'Africa/Kigali')::date
                     = (now() at time zone 'Africa/Kigali')::date
            else r.status not in ('verified', 'cancelled') end
  ) x
$$;

create or replace function add_diagnosis(p_encounter_id uuid, p_text text, p_icd10 text default null, p_type condition_type default 'primary', p_provisional boolean default false)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare v_id uuid;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  perform assert_may_work_on(p_encounter_id);
  if length(trim(coalesce(p_text, ''))) < 2 then
    raise exception 'the diagnosis needs a description' using errcode = '22023';
  end if;
  -- an HIV diagnosis (ICD-10 B20–B24) is written by the people allowed to see HIV results
  if upper(trim(coalesce(p_icd10, ''))) ~ '^B2[0-4]' and not has_perm('sensitive.read') then
    raise exception 'an HIV diagnosis is recorded by the people allowed to see HIV results'
      using errcode = '42501', hint = 'not_permitted';
  end if;
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  insert into condition (encounter_id, text, icd10_code, type, provisional)
  values (p_encounter_id, trim(p_text), nullif(upper(trim(coalesce(p_icd10, ''))), ''), p_type, p_provisional)
  returning id into v_id;
  return v_id;
end
$$;

-- 4. A head's dashboard: their own department's people --------------------------------------------
create or replace function dashboard_summary(p_from date, p_to date)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_manager boolean := is_manager();
  -- a head or assistant: the people of the departments they lead (null: the manager, everyone)
  v_members uuid[];
  v_days integer := greatest(1, p_to - p_from + 1);
  v_prev_from date := p_from - v_days;
  v_prev_to date := p_from - 1;
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_midnight timestamptz := ((now() at time zone 'Africa/Kigali')::date)::timestamp at time zone 'Africa/Kigali';
  v_tiles jsonb;
  v_rev30 jsonb;
  v_rev_period jsonb;
  v_collections jsonb;
  v_receivables jsonb;
  v_visits jsonb;
  v_wait jsonb;
  v_top jsonb;
  v_staff jsonb;
  v_reorder jsonb;
  v_expiring jsonb;
  v_noshow jsonb;
  v_messages jsonb;
  v_claims jsonb;
  v_logins jsonb;
  v_services jsonb;
begin
  if not (v_manager or exists (select 1 from profiles where id = auth.uid() and active and dashboard is not null)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not v_manager then
    select coalesce(array_agg(distinct m.profile_id), '{}') into v_members
    from staff_department m
    join staff_department h on h.department_id = m.department_id
    join department d on d.id = m.department_id and d.deleted_at is null
    where h.profile_id = auth.uid() and h.position in ('head', 'assistant');
  end if;

  -- headline tiles
  select jsonb_build_object(
    'registered', (select count(*) from patient where deleted_at is null and (created_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'registeredPrev', (select count(*) from patient where deleted_at is null and (created_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to),
    'visits', (select count(*) from encounter where deleted_at is null and (arrived_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'visitsPrev', (select count(*) from encounter where deleted_at is null and (arrived_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to),
    -- patients who joined a queue today and are not taken yet (one patient sent to several desks counts once)
    'waitingNow', (select count(distinct q.encounter_id) from queue_entry q join encounter e on e.id = q.encounter_id
                   where q.deleted_at is null and q.finished_at is null and q.started_at is null and e.status = 'open'
                     and q.created_at >= v_midnight),
    -- still open from an earlier day: forgotten in a queue (please close)
    'forgottenNow', (select count(distinct q.encounter_id) from queue_entry q join encounter e on e.id = q.encounter_id
                     where q.deleted_at is null and q.finished_at is null and q.started_at is null and e.status = 'open'
                       and q.created_at < v_midnight),
    'revenue', case when v_manager then (select coalesce(sum(amount), 0) from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between p_from and p_to) end,
    'revenuePrev', case when v_manager then (select coalesce(sum(amount), 0) from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between v_prev_from and v_prev_to) end,
    'refunded', case when v_manager then (select coalesce(sum(amount), 0) from refund where deleted_at is null and (refunded_at at time zone 'Africa/Kigali')::date between p_from and p_to) end,
    'openBills', case when v_manager then (select count(*) from invoice i join encounter e on e.id = i.encounter_id where i.deleted_at is null and i.total > 0 and e.status = 'open' and invoice_balance(i.id) > 0) end,
    'openBillsDue', case when v_manager then (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id where i.deleted_at is null and i.total > 0 and e.status = 'open' and invoice_balance(i.id) > 0) end,
    'debts', case when v_manager then (select count(*) from invoice i join encounter e on e.id = i.encounter_id
                                       where i.deleted_at is null and e.status <> 'open' and invoice_balance(i.id) > 0) end,
    'debtsDue', case when v_manager then (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id
                                          where i.deleted_at is null and e.status <> 'open' and invoice_balance(i.id) > 0) end,
    'bedsOccupied', (select count(*) from bed where deleted_at is null and status = 'occupied'),
    'bedsTotal', (select count(*) from bed where deleted_at is null and status <> 'out_of_service')
  ) into v_tiles;

  -- revenue per day, last 30 days ending today: collected, refunded and net
  select coalesce(jsonb_agg(jsonb_build_object('day', d::date, 'amount', coalesce(s.amount, 0),
                                               'refunds', coalesce(r.amount, 0),
                                               'net', coalesce(s.amount, 0) - coalesce(r.amount, 0)) order by d), '[]'::jsonb) into v_rev30
  from generate_series(v_today - 29, v_today, interval '1 day') d
  left join (
    select (paid_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount
    from payment where deleted_at is null and paid_at >= (v_today - 29)::timestamp at time zone 'Africa/Kigali'
    group by 1
  ) s on s.day = d::date
  left join (
    select (refunded_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount
    from refund where deleted_at is null and refunded_at >= (v_today - 29)::timestamp at time zone 'Africa/Kigali'
    group by 1
  ) r on r.day = d::date;

  -- the same for the chosen period (up to 92 days; longer: see Analytics)
  if v_days <= 92 then
    select coalesce(jsonb_agg(jsonb_build_object('day', d::date, 'amount', coalesce(s.amount, 0),
                                                 'refunds', coalesce(r.amount, 0),
                                                 'net', coalesce(s.amount, 0) - coalesce(r.amount, 0)) order by d), '[]'::jsonb)
    into v_rev_period
    from generate_series(p_from, p_to, interval '1 day') d
    left join (
      select (paid_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount
      from payment where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between p_from and p_to
      group by 1
    ) s on s.day = d::date
    left join (
      select (refunded_at at time zone 'Africa/Kigali')::date as day, sum(amount) as amount
      from refund where deleted_at is null and (refunded_at at time zone 'Africa/Kigali')::date between p_from and p_to
      group by 1
    ) r on r.day = d::date;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('method', m, 'amount', coalesce(s.amount, 0)) order by s.amount desc nulls last), '[]'::jsonb) into v_collections
  from unnest(array['cash', 'momo', 'airtel', 'card', 'bank']::payment_method[]) m
  left join (
    select method, sum(amount) as amount from payment
    where deleted_at is null and (paid_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by method
  ) s on s.method = m;

  select coalesce(jsonb_agg(jsonb_build_object('payer', py.name, 'count', c.n, 'amount', c.amount) order by c.amount desc), '[]'::jsonb) into v_receivables
  from (
    select payer_id, count(*) as n, sum(amount) as amount from claim
    where deleted_at is null and status in ('open', 'batched', 'submitted', 'rejected', 'resubmitted')
    group by payer_id
  ) c join payer py on py.id = c.payer_id;

  -- visits by service group (charged lines in the range)
  select coalesce(jsonb_agg(jsonb_build_object('group', g.grp, 'categoryId', g.cat_id, 'name', g.name, 'nameKin', g.kin,
                                                'nameFr', g.fr, 'count', g.n) order by g.n desc), '[]'::jsonb) into v_visits
  from (
    -- by the clinic's own categories; medicines (no service) count as pharmacy
    select coalesce(c.base_group::text, case when s.id is null then 'pharmacy' else 'other' end) as grp,
           c.id as cat_id, c.name_en as name, c.name_kin as kin, c.name_fr as fr, count(distinct i.encounter_id) as n
    from invoice_line l
    join invoice i on i.id = l.invoice_id
    left join service s on s.id = l.service_id
    left join service_category c on c.id = s.category_id
    where l.deleted_at is null and (l.created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by c.id, 1, 3, 4, 5
  ) g;

  -- the queues right now (no average: see Analytics → Waiting times)
  select coalesce(jsonb_agg(jsonb_build_object('station', w.station, 'waiting', w.waiting, 'busy', w.busy,
                                               'longest', w.longest, 'forgotten', w.forgotten) order by w.station), '[]'::jsonb)
  into v_wait
  from queue_now(null) w;

  -- top treatments in the range
  select coalesce(jsonb_agg(jsonb_build_object('name', x.name, 'count', x.n, 'amount', case when v_manager then x.amount end) order by x.n desc), '[]'::jsonb) into v_top
  from (
    select l.description as name, count(*) as n, sum(round(l.unit_price * l.quantity)) as amount
    from invoice_line l
    where l.deleted_at is null and (l.created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by l.description
    order by count(*) desc
    limit 10
  ) x;

  -- who did what (accountability): the same counts as Analytics → Who did what; a head sees the
  -- people of their own department only
  with ev as (
    select * from analytics_staff_events(p_from::timestamp at time zone 'Africa/Kigali',
                                         (p_to + 1)::timestamp at time zone 'Africa/Kigali', v_manager)
  ),
  a as (
    select ev.user_id,
           count(*) filter (where kind = 'registered') as registrations,
           count(*) filter (where kind = 'vitals') as vitals,
           count(*) filter (where kind = 'charges') as charges,
           count(*) filter (where kind = 'patientsSeen') as patients,
           count(*) filter (where kind = 'results') as results,
           count(*) filter (where kind = 'medicinesGiven') as dispensed,
           count(*) filter (where kind = 'payments') as payments,
           coalesce(sum(amount) filter (where kind = 'payments'), 0) as collected
    from ev group by ev.user_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id, 'name', p.full_name, 'role', p.role, 'staffId', p.staff_id,
      'active', p.active and p.deleted_at is null,
      'registrations', coalesce(a.registrations, 0), 'vitals', coalesce(a.vitals, 0), 'charges', coalesce(a.charges, 0),
      'patients', coalesce(a.patients, 0), 'results', coalesce(a.results, 0), 'dispensed', coalesce(a.dispensed, 0),
      'payments', case when v_manager then coalesce(a.payments, 0) end,
      'collected', case when v_manager then coalesce(a.collected, 0) end,
      'lastSignIn', p.last_sign_in_at
    ) order by (coalesce(a.registrations, 0) + coalesce(a.vitals, 0) + coalesce(a.charges, 0) + coalesce(a.payments, 0)
                + coalesce(a.patients, 0) + coalesce(a.results, 0) + coalesce(a.dispensed, 0)) desc, p.full_name), '[]'::jsonb) into v_staff
  from profiles p
  left join a on a.user_id = p.id
  where (v_members is null or p.id = any (v_members))
    and ((p.active and p.deleted_at is null)
         or (a.user_id is not null and (a.registrations + a.vitals + a.charges + a.patients + a.results + a.dispensed + a.payments) > 0));

  -- stock: the item's id and full name (with strength)
  select coalesce(jsonb_agg(jsonb_build_object('id', r.item_id, 'name', item_label(r.item_id), 'onHand', r.on_hand, 'min', r.reorder_level)
                            order by (r.on_hand::numeric / greatest(r.reorder_level, 1)), item_label(r.item_id)), '[]'::jsonb) into v_reorder
  from items_below_reorder r;

  select jsonb_build_object(
    'expired', count(distinct s.item_id) filter (where s.expiry < v_today),
    'd30', count(distinct s.item_id) filter (where s.expiry >= v_today and s.expiry <= v_today + 30),
    'd60', count(distinct s.item_id) filter (where s.expiry > v_today + 30 and s.expiry <= v_today + 60),
    'd90', count(distinct s.item_id) filter (where s.expiry > v_today + 60 and s.expiry <= v_today + 90)
  ) into v_expiring
  from (select item_id, batch_id, expiry, sum(quantity) as q from stock_on_hand where expiry is not null
        group by item_id, batch_id, expiry) s
  where s.q > 0;

  -- bookings
  select jsonb_build_object(
    'booked', count(*) filter (where status in ('confirmed', 'arrived', 'in_progress', 'completed', 'no_show')),
    'missed', count(*) filter (where status = 'no_show'),
    'pending', (select count(*) from appointment where deleted_at is null and status = 'inquiry')
  ) into v_noshow
  from appointment where deleted_at is null and (coalesce(starts_at, created_at) at time zone 'Africa/Kigali')::date between p_from and p_to;

  select coalesce(jsonb_agg(jsonb_build_object('channel', ch, 'sent', coalesce(s.sent, 0), 'failed', coalesce(s.failed, 0)) order by ch), '[]'::jsonb) into v_messages
  from unnest(array['whatsapp', 'sms', 'email']::message_channel[]) ch
  left join (
    select channel, count(*) filter (where status in ('sent', 'delivered')) as sent, count(*) filter (where status = 'failed') as failed
    from message where deleted_at is null and (created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    group by channel
  ) s on s.channel = ch;

  select coalesce(jsonb_agg(jsonb_build_object('payer', py.name, 'count', c.n, 'amount', case when v_manager then c.amount end) order by c.amount desc), '[]'::jsonb) into v_claims
  from (select payer_id, count(*) as n, sum(amount) as amount from claim where deleted_at is null and status = 'open' group by payer_id) c
  join payer py on py.id = c.payer_id;

  -- sign-ins of the last 24 hours (a head: their department's people)
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name, 'role', p.role, 'at', a.at, 'reason', a.reason) order by a.at desc), '[]'::jsonb) into v_logins
  from (select actor_id, at, reason from audit_event
        where action = 'login' and at > now() - interval '1 day'
          and (v_members is null or actor_id = any (v_members))
        order by at desc limit 12) a
  join profiles p on p.id = a.actor_id;

  select jsonb_build_object('active', count(*) filter (where active), 'total', count(*)) into v_services from service where deleted_at is null;

  return jsonb_build_object(
    'from', p_from, 'to', p_to, 'manager', v_manager, 'generatedAt', now(),
    -- money for the manager only (heads of department see the activity, not the money)
    'tiles', v_tiles,
    'revenue30d', case when v_manager then v_rev30 else '[]'::jsonb end,
    'revenuePeriod', case when v_manager then v_rev_period end,
    'collections', case when v_manager then v_collections else '[]'::jsonb end,
    'receivables', case when v_manager then v_receivables else '[]'::jsonb end,
    'visitsByGroup', v_visits, 'waitByStation', v_wait, 'topTreatments', v_top, 'staff', v_staff,
    'reorder', v_reorder, 'expiring', v_expiring, 'bookings', v_noshow, 'messages', v_messages,
    'claims', v_claims, 'logins', v_logins, 'services', v_services
  );
end
$$;

-- 5. Every temporary PIN ends the open sign-ins; nobody resets their own -------------------------
-- The profiles trigger (0091) fires only when "PIN change pending" turns on; a second reset while
-- it is still on changes only the temporary PIN row, so that row ends the sign-ins too.
create or replace function temp_pin_set()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if new.set_by is not null and new.set_by = new.user_id then
    raise exception 'a manager does not reset their own PIN' using errcode = '42501', hint = 'not_permitted';
  end if;
  if tg_op = 'INSERT' or new.pin is distinct from old.pin then
    update approved_session
       set ended_at = now(), ended_reason = 'new PIN'
     where user_id = new.user_id and ended_at is null;
  end if;
  return new;
end
$$;
revoke all on function temp_pin_set() from public, anon, authenticated;
drop trigger if exists temp_pin_set on staff_temp_pin;
create trigger temp_pin_set
  before insert or update on staff_temp_pin
  for each row execute function temp_pin_set();

-- 6. Declining a booking: the calendar's owner (or the manager), as for accepting ------------------
create or replace function decline_appointment(p_appointment_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_a appointment%rowtype;
begin
  if not (has_perm('appointment.accept') or is_manager()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_a from appointment where id = p_appointment_id and deleted_at is null for update;
  if not found or v_a.status <> 'approved' then
    raise exception 'appointment not found or not approved' using errcode = 'P0002';
  end if;
  if not is_manager()
     and not exists (select 1 from practitioner where id = v_a.practitioner_id and user_id = auth.uid()) then
    raise exception 'only the doctor of this calendar declines the booking' using errcode = '42501';
  end if;
  update appointment set status = 'declined', cancel_reason = p_reason
  where id = p_appointment_id;
end
$$;

-- 7. "Seen": the requester, the colleague who took the patient over, or the manager ---------------
create or replace function mark_result_reviewed(p_report_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req service_request%rowtype;
begin
  if not (has_perm('clinical.write') or is_manager()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  select r.* into v_req
  from diagnostic_report d
  join service_request r on r.id = d.service_request_id
  where d.id = p_report_id and d.deleted_at is null;
  if not found then
    raise exception 'result not found' using errcode = 'P0002', hint = 'not_found';
  end if;
  if not is_manager()
     and auth.uid() not in (v_req.requester_id, result_recipient(v_req.encounter_id, v_req.requester_id)) then
    raise exception 'only the doctor who asked for the test, or who took the patient over, marks the result seen'
      using errcode = '42501';
  end if;
  update diagnostic_report set reviewed_at = now(), reviewed_by = auth.uid()
  where id = p_report_id and deleted_at is null and reviewed_at is null;
end
$$;

-- 8. Vital signs: the form's limits, in the database too -----------------------------------------
create or replace function record_vitals(
  p_encounter_id uuid,
  p_vitals jsonb,
  p_triage triage_level default null,
  p_next_station station default null,
  p_reason text default null,
  p_measured_by uuid default null,
  p_measured_at timestamptz default null
)
returns text
language plpgsql security definer set search_path = public
as $$
declare
  v_ticket text;
  v_key text;
  v_val numeric;
  v_count integer := 0;
  v_by uuid := coalesce(p_measured_by, auth.uid());
  v_at timestamptz := coalesce(p_measured_at, now());
  v_arrived timestamptz;
  v_at_triage boolean;
  v_units jsonb := '{"bp_sys":"mmHg","bp_dia":"mmHg","pulse":"bpm","temp":"°C","resp":"/min","spo2":"%","weight":"kg","height":"cm","muac":"cm"}'::jsonb;
begin
  if not has_perm('vitals.write') then
    raise exception 'you may not record vital signs (the manager has not allowed it)' using errcode = '42501', hint = 'not_permitted';
  end if;
  select arrived_at into v_arrived from encounter where id = p_encounter_id and status = 'open';
  if not found then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  select exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = 'triage'
                 and finished_at is null and deleted_at is null) into v_at_triage;
  -- At triage: the people of a department that does triage (when none does, as before).
  if v_at_triage then
    perform assert_desk(array['triage'], 'triage');
  end if;
  -- Sending on from triage is for whoever may work on the patient (as with "Send on"): reception
  -- that sent the patient to triage, or a nurse other than the one named, records only.
  if v_at_triage and p_next_station is not null and not may_route(p_encounter_id) then
    if current_role_key() = 'receptionist' then
      raise exception 'this patient is with %: record the measurements without choosing where they go next; the nurse there sends them on',
        coalesce(patient_holder(p_encounter_id), 'triage') using errcode = '42501';
    end if;
    perform assert_may_work_on(p_encounter_id, true);
  end if;
  -- Without clinical rights the person typing must name who measured.
  if not has_perm('clinical.write') and (p_measured_by is null or p_measured_by = auth.uid()) then
    raise exception 'choose the nurse who took the measurements' using errcode = '22023';
  end if;
  if not exists (select 1 from profiles where id = v_by and active) then
    raise exception 'unknown staff member for "measured by"' using errcode = '22023';
  end if;
  -- the person named as having measured must be allowed to record vital signs themselves
  if v_by <> auth.uid() and not staff_perm(v_by, 'vitals.write') then
    raise exception 'the person named as "measured by" is not allowed to take vital signs'
      using errcode = '42501', hint = 'not_permitted';
  end if;
  if v_at > now() + interval '5 minutes' then
    raise exception 'the measurement time is in the future' using errcode = '22023';
  end if;
  if v_at < v_arrived - interval '1 hour' then
    raise exception 'the measurement time is before the patient arrived' using errcode = '22023';
  end if;

  for v_key, v_val in
    select key, nullif(value, '')::numeric from jsonb_each_text(coalesce(p_vitals, '{}'::jsonb))
  loop
    if v_val is not null and v_units ? v_key then
      -- the same limits as the form (newborn to adult, critically ill included): outside them it
      -- is a typing mistake
      case v_key
        when 'bp_sys' then
          if v_val not between 40 and 300 then
            raise exception 'the systolic blood pressure must be between 40 and 300 mmHg' using errcode = '22023';
          end if;
        when 'bp_dia' then
          if v_val not between 20 and 200 then
            raise exception 'the diastolic blood pressure must be between 20 and 200 mmHg' using errcode = '22023';
          end if;
        when 'pulse' then
          if v_val not between 20 and 250 then
            raise exception 'the pulse must be between 20 and 250 per minute' using errcode = '22023';
          end if;
        when 'temp' then
          if v_val not between 30 and 44 then
            raise exception 'the temperature must be between 30 and 44 °C' using errcode = '22023';
          end if;
        when 'resp' then
          if v_val not between 4 and 100 then
            raise exception 'the breathing rate must be between 4 and 100 per minute' using errcode = '22023';
          end if;
        when 'spo2' then
          if v_val not between 40 and 100 then
            raise exception 'the oxygen saturation must be between 40 and 100 %%' using errcode = '22023';
          end if;
        when 'weight' then
          if v_val not between 0.3 and 350 then
            raise exception 'the weight must be between 0.3 and 350 kg' using errcode = '22023';
          end if;
        when 'height' then
          if v_val not between 20 and 250 then
            raise exception 'the height must be between 20 and 250 cm' using errcode = '22023';
          end if;
        when 'muac' then
          if v_val not between 5 and 60 then
            raise exception 'the arm circumference must be between 5 and 60 cm' using errcode = '22023';
          end if;
        else null;
      end case;
      insert into observation (encounter_id, code, value_num, unit, performer_id, effective_at)
      values (p_encounter_id, v_key, v_val, v_units ->> v_key, v_by, v_at);
      v_count := v_count + 1;
    end if;
  end loop;
  if v_count = 0 then
    raise exception 'enter at least one measurement' using errcode = '22023';
  end if;

  if v_by <> auth.uid() then
    insert into audit_event (actor_id, action, entity, entity_id, after, reason)
    values (auth.uid(), 'create', 'observation', p_encounter_id,
            jsonb_build_object('measured_by', v_by, 'measured_at', v_at, 'count', v_count),
            'vitals entered on behalf of the person who measured');
  end if;

  if p_triage is not null then
    update encounter set triage_level = p_triage, triage_reason = coalesce(p_reason, triage_reason)
    where id = p_encounter_id;
    -- the colour reorders the places where the patient waits (red first)
    update queue_entry set priority = case p_triage when 'red' then 1 when 'yellow' then 2 else 3 end
    where encounter_id = p_encounter_id and finished_at is null and started_at is null and deleted_at is null;
  end if;

  select ticket_no into v_ticket from queue_entry where encounter_id = p_encounter_id order by created_at limit 1;

  -- At triage: close the triage turn and send the patient on. Later (e.g. the doctor typing
  -- the nurse's paper sheet): measurements only, the patient stays where they are.
  if v_at_triage and p_next_station is not null then
    update queue_entry set finished_at = now()
    where encounter_id = p_encounter_id and station = 'triage' and finished_at is null;
    insert into queue_entry (encounter_id, station, ticket_no, priority)
    values (p_encounter_id, p_next_station, v_ticket,
            case coalesce(p_triage, 'green') when 'red' then 1 when 'yellow' then 2 else 3 end);
  end if;
  return v_ticket;
end
$$;

-- 9. Merging: files and record-access rows move too; the old number finds the patient -------------
create or replace function merge_patients(p_keep uuid, p_merge uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_old_number text;
  v_table text;
  v_moved integer := 0;
  v_n integer;
begin
  if not is_manager() then
    raise exception 'only the manager can merge patient files' using errcode = '42501';
  end if;
  if p_keep is null or p_merge is null or p_keep = p_merge then
    raise exception 'choose two different files' using errcode = '22023';
  end if;
  if not exists (select 1 from patient where id = p_keep and deleted_at is null and merged_into is null) then
    raise exception 'the file to keep was not found' using errcode = 'P0002';
  end if;
  select file_number into v_old_number from patient where id = p_merge and deleted_at is null and merged_into is null;
  if not found then
    raise exception 'the duplicate file was not found or is already merged' using errcode = 'P0002';
  end if;
  if exists (select 1 from encounter where patient_id = p_keep and status = 'open')
     and exists (select 1 from encounter where patient_id = p_merge and status = 'open') then
    raise exception 'both files have a visit open: close one first' using errcode = '23514';
  end if;
  foreach v_table in array array['appointment', 'encounter', 'vaccination', 'fp_event', 'hiv_test',
                                  'document', 'message', 'internal_task', 'coverage',
                                  'patient_file_doc', 'record_access_request', 'record_access_entry'] loop
    if exists (select 1 from information_schema.columns
               where table_schema = 'public' and table_name = v_table and column_name = 'patient_id') then
      execute format('update %I set patient_id = $1 where patient_id = $2', v_table) using p_keep, p_merge;
      get diagnostics v_n = row_count;
      v_moved := v_moved + v_n;
    end if;
  end loop;
  update patient set guardian_patient_id = p_keep where guardian_patient_id = p_merge;
  update coverage set principal_patient_id = p_keep where principal_patient_id = p_merge;
  insert into patient_alias (file_number, patient_id) values (v_old_number, p_keep)
  on conflict (file_number) do update set patient_id = p_keep;
  update patient_alias set patient_id = p_keep where patient_id = p_merge;
  update patient set merged_into = p_keep, updated_at = now() where id = p_merge;
  insert into audit_event (actor_id, action, entity, entity_id, after, reason)
  values (auth.uid(), 'update', 'patient', p_keep,
          jsonb_build_object('merged', p_merge, 'fileNumber', v_old_number, 'moved', v_moved), 'files merged');
  return jsonb_build_object('moved', v_moved, 'oldNumber', v_old_number);
end
$$;

create or replace function find_patients(p_query text, p_limit integer default 10)
returns table (
  id uuid, file_number text, surname text, given_names text, sex sex, birth_date date,
  phone_1 text, has_open_visit boolean
)
language sql stable security definer set search_path = public
as $$
  with q as (select trim(coalesce(p_query, '')) as text)
  select p.id, p.file_number, p.surname, p.given_names, p.sex, p.birth_date, p.phone_1,
         exists (select 1 from encounter e where e.patient_id = p.id and e.status = 'open') as has_open_visit
  from patient p, q
  where has_perm('patient.read')
    and p.deleted_at is null and p.merged_into is null and length(q.text) >= 2
    and (
      upper(p.file_number) = upper(q.text)
      -- a file number of a duplicate merged into this one
      or exists (select 1 from patient_alias a where a.patient_id = p.id and upper(a.file_number) = upper(q.text))
      or p.national_id = q.text
      or regexp_replace(coalesce(p.phone_1, ''), '[^0-9]', '', 'g') like '%' || regexp_replace(q.text, '[^0-9]', '', 'g') || '%'
         and length(regexp_replace(q.text, '[^0-9]', '', 'g')) >= 4
      or (p.surname || ' ' || p.given_names) ilike '%' || q.text || '%'
      or (p.given_names || ' ' || p.surname) ilike '%' || q.text || '%'
    )
  order by p.surname, p.given_names
  limit greatest(1, least(p_limit, 50))
$$;

create or replace function patients_list(p_query text default null, p_limit integer default 50, p_offset integer default 0)
returns jsonb
language sql stable security definer set search_path = public
as $$
  with q as (select nullif(trim(coalesce(p_query, '')), '') as text),
  base as (
    select p.*,
           (select max(e.arrived_at) from encounter e where e.patient_id = p.id and e.deleted_at is null) as last_visit_at,
           (select count(*) from encounter e where e.patient_id = p.id and e.deleted_at is null) as visits,
           (select e.id from encounter e where e.patient_id = p.id and e.status = 'open' and e.deleted_at is null order by e.arrived_at desc limit 1) as open_encounter_id,
           (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id where e.patient_id = p.id and i.deleted_at is null and i.status <> 'credited') as balance_due
    from patient p, q
    where has_perm('patient.read') and p.deleted_at is null and p.merged_into is null
      and (q.text is null
        or upper(p.file_number) = upper(q.text)
        -- a file number of a duplicate merged into this one
        or exists (select 1 from patient_alias a where a.patient_id = p.id and upper(a.file_number) = upper(q.text))
        or p.national_id = q.text
        or (length(regexp_replace(q.text, '[^0-9]', '', 'g')) >= 4 and regexp_replace(coalesce(p.phone_1, ''), '[^0-9]', '', 'g') like '%' || regexp_replace(q.text, '[^0-9]', '', 'g') || '%')
        or (p.surname || ' ' || p.given_names) ilike '%' || q.text || '%'
        or (p.given_names || ' ' || p.surname) ilike '%' || q.text || '%')
  )
  select jsonb_build_object(
    'total', (select count(*) from base),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id', b.id, 'fileNumber', b.file_number, 'surname', b.surname, 'givenNames', b.given_names,
        'sex', b.sex, 'birthDate', b.birth_date, 'phone', b.phone_1, 'sector', b.sector,
        'registeredAt', b.created_at, 'lastVisitAt', b.last_visit_at, 'visits', b.visits,
        'openEncounterId', b.open_encounter_id, 'balanceDue', b.balance_due,
        -- 0088: the safety marks for the people who read clinical records only ("VIP" for all)
        'flags', case when clinical_reader() then b.flags
                      else jsonb_strip_nulls(jsonb_build_object('vip', b.flags -> 'vip')) end,
        'hasAllergies', case when clinical_reader() then b.allergies is not null else false end
      ) order by coalesce(b.last_visit_at, b.created_at) desc)
      from (select * from base order by coalesce(last_visit_at, created_at) desc limit greatest(1, least(p_limit, 200)) offset greatest(0, p_offset)) b), '[]'::jsonb)
  )
$$;

-- 10. "File added to a test": told to whoever has the patient now ---------------------------------
create or replace function attach_file(
  p_encounter_id uuid,
  p_path text,
  p_kind text,
  p_title text,
  p_mime text,
  p_size integer,
  p_service_request_id uuid default null,
  p_note text default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_e encounter%rowtype;
  v_ext text := lower(substring(coalesce(p_path, '') from '\.([a-zA-Z]+)$'));
  v_obj_found boolean := false;
  v_obj_size bigint;
  v_obj_mime text;
  v_f patient_file_doc%rowtype;
  v_req service_request%rowtype;
  v_to uuid;
  v_name text;
  v_file text;
  v_me text;
  v_test text;
begin
  if auth.uid() is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_e from encounter where id = p_encounter_id and deleted_at is null;
  if not found then
    raise exception 'visit not found' using errcode = 'P0002', hint = 'not_found';
  end if;
  if v_e.status <> 'open' then
    raise exception 'files are added while the visit is open' using errcode = '22023', hint = 'file_visit_closed';
  end if;
  if coalesce(p_kind, '') not in ('ultrasound', 'lab', 'scan', 'referral', 'photo', 'other') then
    raise exception 'unknown kind of file' using errcode = '22023', hint = 'file_kind';
  end if;
  if length(trim(coalesce(p_title, ''))) = 0 or length(trim(p_title)) > 200 then
    raise exception 'give the file a title' using errcode = '22023', hint = 'title_needed';
  end if;
  if not file_mime_ok(p_mime) then
    raise exception 'only photos (JPEG, PNG, WebP) and PDF files' using errcode = '22023', hint = 'file_type';
  end if;
  if p_size is null or p_size <= 0 or p_size > file_max_bytes() then
    raise exception 'the file is larger than 10 MB' using errcode = '22023', hint = 'file_too_big';
  end if;
  if file_path_encounter(p_path) is distinct from p_encounter_id
     or split_part(p_path, '/', 1) <> v_e.patient_id::text
     or not file_ext_ok(p_mime, v_ext) then
    raise exception 'the file is not stored where this visit''s files go' using errcode = '22023', hint = 'file_path';
  end if;
  if p_service_request_id is not null then
    select * into v_req from service_request
    where id = p_service_request_id and encounter_id = p_encounter_id and deleted_at is null;
    if not found or v_req.status = 'cancelled' then
      raise exception 'this test is not one of the visit' using errcode = '22023', hint = 'wrong_test';
    end if;
  end if;
  if not may_attach_file(p_encounter_id, p_service_request_id) then
    raise exception 'not allowed: only the people working on the visit add files'
      using errcode = '42501', hint = 'not_on_visit';
  end if;
  -- On Supabase: the file must be in the bucket, with the size and type said.
  if to_regclass('storage.objects') is not null then
    execute 'select true, (metadata ->> ''size'')::bigint, metadata ->> ''mimetype''
             from storage.objects where bucket_id = ''patient-files'' and name = $1'
      into v_obj_found, v_obj_size, v_obj_mime using p_path;
    if not coalesce(v_obj_found, false) then
      raise exception 'the file did not arrive: send it again' using errcode = '22023', hint = 'not_uploaded';
    end if;
    if v_obj_size is not null and v_obj_size > file_max_bytes() then
      raise exception 'the file is larger than 10 MB' using errcode = '22023', hint = 'file_too_big';
    end if;
    if v_obj_mime is not null and not file_mime_ok(v_obj_mime) then
      raise exception 'only photos (JPEG, PNG, WebP) and PDF files' using errcode = '22023', hint = 'file_type';
    end if;
  end if;
  insert into patient_file_doc (patient_id, encounter_id, service_request_id, kind, title, note,
                                storage_path, mime_type, size_bytes, uploaded_by)
  values (v_e.patient_id, p_encounter_id, p_service_request_id, p_kind, trim(p_title),
          nullif(trim(coalesce(p_note, '')), ''), p_path, p_mime,
          coalesce(v_obj_size::integer, p_size), auth.uid())
  returning * into v_f;
  insert into audit_event (actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'create', 'patient_file_doc', v_f.id,
          jsonb_build_object('patient', v_f.patient_id, 'encounter', v_f.encounter_id, 'kind', v_f.kind,
                             'title', v_f.title, 'mime', v_f.mime_type, 'size', v_f.size_bytes));
  -- the laboratory or ultrasound added a file to a test: its requester is told, or the colleague
  -- who took the patient over since (as the result notices do)
  if v_req.id is not null and v_req.requester_id is not null then
    v_to := result_recipient(v_req.encounter_id, v_req.requester_id);
  end if;
  if v_to is not null and v_to <> auth.uid() then
    select p.surname || ' ' || p.given_names, p.file_number into v_name, v_file
    from patient p where p.id = v_e.patient_id;
    select full_name into v_me from profiles where id = auth.uid();
    select s.name_en into v_test from service s where s.id = v_req.service_id;
    insert into notification (kind, params, title, body, link, urgent, recipient_user, created_by)
    values ('file_attached',
            jsonb_build_object('fileId', v_f.id, 'patientId', v_e.patient_id, 'encounterId', v_e.id,
                               'name', v_name, 'file', v_file, 'by', v_me, 'title', v_f.title,
                               'kind', v_f.kind, 'test', v_test),
            'File added to a test',
            coalesce(v_me, '') || ' added "' || v_f.title || '" to ' || coalesce(v_test, 'a test') || ' of ' || coalesce(v_name, ''),
            '/app/visit?encounter=' || v_e.id, false, v_to, auth.uid());
  end if;
  return file_doc_json(v_f, 'visit');
end
$$;

-- 11. patient_file says which private extra fields are filled -------------------------------------
-- At the identity level the "medical" extra fields leave the file (0088), so the edit form could
-- not tell an empty one (reception may fill it) from a filled one (locked): `extra_filled` lists
-- the private keys that have a value, without the values.
create or replace function patient_file(p_patient_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_patient jsonb;
  v_visits jsonb;
  v_vitals jsonb;
  v_conditions jsonb;
  v_bills jsonb;
  v_doc jsonb;
  v_reader boolean := clinical_reader();
  v_via text;
  v_treating uuid;
  v_level text;
  v_past_seen boolean;
  v_views jsonb;
  v_extra_filled jsonb;
begin
  if not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select to_jsonb(p) - 'photo_blob_id' - 'merged_into' - 'guardian_patient_id' into v_patient
  from patient p where p.id = p_patient_id and p.deleted_at is null;
  if v_patient is null then
    raise exception 'patient not found' using errcode = 'P0002';
  end if;
  -- worked out once for the whole file (the visits' loop reuses them)
  v_via := history_via(p_patient_id);
  v_treating := treating_visit(p_patient_id);
  v_level := case when v_via is not null then 'full' when v_treating is not null then 'summary' else 'identity' end;

  -- how each visit may be seen (null: private)
  select coalesce(jsonb_object_agg(e.id::text, s.view) filter (where s.view is not null), '{}'::jsonb),
         coalesce(bool_or(s.view is not null and e.status = 'closed'), false)
  into v_views, v_past_seen
  from encounter e
  cross join lateral (select case when v_reader then visit_view_with(e.id, v_via, true) end as view) s
  where e.patient_id = p_patient_id and e.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', e.id, 'reference', e.reference, 'arrivedAt', e.arrived_at, 'status', e.status, 'type', e.type,
      'triage', e.triage_level,
      'triageReason', case when s.view is not null then e.triage_reason end,
      'practitioner', (select names from practitioner where id = e.practitioner_id),
      'stations', (select coalesce(jsonb_agg(distinct q.station::text), '[]'::jsonb) from queue_entry q where q.encounter_id = e.id and q.deleted_at is null),
      'currentStation', (select q.station from queue_entry q where q.encounter_id = e.id and q.finished_at is null and q.deleted_at is null order by q.created_at desc limit 1),
      'diagnosis', case when s.view is not null then
        (select c.text from condition c where c.encounter_id = e.id and c.type = 'primary' and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read')) order by c.created_at desc limit 1) end,
      'total', (select i.total from invoice i where i.encounter_id = e.id),
      'balance', (select invoice_balance(i.id) from invoice i where i.encounter_id = e.id),
      'billStatus', (select i.status from invoice i where i.encounter_id = e.id),
      'closedAt', e.closed_at,
      'private', s.view is null,
      'view', s.view
    ) order by e.arrived_at desc), '[]'::jsonb) into v_visits
  from encounter e cross join lateral (select v_views ->> e.id::text as view) s
  where e.patient_id = p_patient_id and e.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'encounterId', o.encounter_id, 'code', o.code, 'value', o.value_num, 'text', o.value_text,
      'unit', o.unit, 'at', o.effective_at, 'by', (select full_name from profiles where id = o.performer_id)
    ) order by o.effective_at desc), '[]'::jsonb) into v_vitals
  -- the visits one may see; whoever types the nurse's sheet (vitals.write) also sees what is
  -- recorded on the open visit (0019), never a past one
  from observation o
  where o.deleted_at is null and o.code <> 'note'
    and (v_views ? o.encounter_id::text
         or (has_perm('vitals.write')
             and o.encounter_id in (select e.id from encounter e
                                    where e.patient_id = p_patient_id and e.status = 'open' and e.deleted_at is null)));

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'encounterId', c.encounter_id, 'text', c.text, 'icd10', c.icd10_code, 'type', c.type,
      'provisional', c.provisional, 'at', c.created_at, 'by', (select full_name from profiles where id = c.created_by)
    ) order by c.created_at desc), '[]'::jsonb) into v_conditions
  from condition c
  where v_views ? c.encounter_id::text and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'));

  select coalesce(jsonb_agg(jsonb_build_object(
      'invoiceId', i.id, 'encounterId', i.encounter_id, 'number', i.number, 'status', i.status,
      'total', i.total, 'patientShare', i.patient_share, 'insurerShare', i.insurer_share,
      'balance', invoice_balance(i.id), 'payer', (select name from payer where id = i.payer_id),
      'at', i.created_at
    ) order by i.created_at desc), '[]'::jsonb) into v_bills
  from invoice i join encounter e on e.id = i.encounter_id
  where e.patient_id = p_patient_id and i.deleted_at is null;

  -- the private extra fields that have a value (the keys only; the form locks them)
  select coalesce(jsonb_agg(k order by k), '[]'::jsonb) into v_extra_filled
  from unnest(private_extra_keys()) k
  where nullif(trim(coalesce(v_patient -> 'extra' ->> k, '')), '') is not null;

  v_doc := doc_patient(p_patient_id, null);
  if v_level = 'identity' then
    v_patient := v_patient || jsonb_build_object('allergies', null, 'allergies_none', null,
                                                 'blood_group', null, 'notes', null,
                                                 -- the manager's "medical" extra fields go too
                                                 'extra', coalesce(v_patient -> 'extra', '{}'::jsonb) - private_extra_keys(),
                                                 -- the safety marks go; "VIP" is not one
                                                 'flags', jsonb_strip_nulls(jsonb_build_object('vip', v_patient -> 'flags' -> 'vip')));
    v_doc := v_doc - 'allergies' - 'allergiesNone' - 'bloodGroup' - 'weightKg' - 'weightAt';
  end if;

  if v_past_seen then
    perform log_record_access(p_patient_id, null, coalesce(v_via, 'own'), 'file');
  end if;

  return jsonb_build_object('patient', v_patient, 'visits', v_visits, 'vitals', v_vitals,
                            'conditions', v_conditions, 'bills', v_bills,
                            'document', v_doc,
                            'safetyHidden', v_level = 'identity',
                            'extra_filled', v_extra_filled,
                            'summary', case when v_level <> 'identity' then patient_safety_summary(p_patient_id) end,
                            'access', patient_access_with(p_patient_id, v_via, v_treating));
end
$$;


-- ============================================================ 20261204090000_calendars_for_nurses_and_managers.sql
-- 0094 · Calendars for nurses and the manager.
--
-- Frank: a manager may be a doctor and wants their own calendar, chosen in "Calendar of" like
-- anyone else's; a nurse keeps a calendar and is booked, on the website and at reception, like
-- a doctor.
--
-- Who keeps a calendar (and can be booked): doctors, sonographers, nurses and managers.
--  - calendar_role_ok, calendar_people (the manager sees themself), save_calendar,
--    ensure_practitioner and bookable_doctors accept the four roles.
--  - public_practitioners says the role of each public calendar, so the website labels a nurse
--    as a nurse (the column is added at the end of the view; everything else is unchanged).
--  - appointment_arrived: a nurse's booked patient waits at the Nursing desk; a doctor's or a
--    manager's at the desk their specialty implies (Dental for a dentist, else Consultation).
--  - Nurses and the manager answer the bookings made with them (appointment.accept), as the
--    sonographer does since 0056.

insert into role_permissions (role, permission) values
  ('nurse', 'appointment.accept'),
  ('manager', 'appointment.read'), ('manager', 'appointment.accept')
on conflict do nothing;

-- ---------------------------------------------------------------- who keeps a calendar
create or replace function calendar_role_ok(p_user uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from profiles where id = p_user and active
                   and role in ('doctor', 'sonographer', 'nurse', 'manager'))
$$;

-- Manager: everyone who may keep a calendar (the manager included), with whether one is saved.
create or replace function calendar_people()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'userId', p.id, 'name', p.full_name, 'role', p.role, 'staffId', p.staff_id,
    'visibility', pr.calendar_visibility, 'saved', pr.id is not null
  ) order by (p.id = auth.uid()) desc, p.full_name), '[]'::jsonb)
  from profiles p
  left join practitioner pr on pr.user_id = p.id and pr.deleted_at is null
  where is_manager() and p.active and p.role in ('doctor', 'sonographer', 'nurse', 'manager')
$$;

create or replace function save_calendar(
  p_user uuid,
  p_hours jsonb,
  p_slot_minutes integer,
  p_visibility text,
  p_days_off date[] default '{}',
  p_note text default null,
  p_title text default null,
  p_categories text[] default '{}',
  p_languages text default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_user uuid := coalesce(p_user, auth.uid());
  v_id uuid;
  v_name text;
  v_staff text;
  v_key text;
  v_span jsonb;
  v_hours jsonb := coalesce(p_hours, '{}'::jsonb);
begin
  if auth.uid() is null or (v_user <> auth.uid() and not is_manager()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not calendar_role_ok(v_user) then
    raise exception 'only doctors, sonographers, nurses and managers keep a calendar' using errcode = '22023';
  end if;
  if coalesce(p_visibility, '') not in ('private', 'staff', 'public') then
    raise exception 'choose who may see the calendar' using errcode = '22023';
  end if;
  if p_slot_minutes is null or p_slot_minutes not between 5 and 240 then
    raise exception 'the booking slot must be between 5 and 240 minutes' using errcode = '22023';
  end if;
  if jsonb_typeof(v_hours) <> 'object' then
    raise exception 'working hours are not valid' using errcode = '22023';
  end if;
  for v_key in select jsonb_object_keys(v_hours) loop
    if v_key not in ('0', '1', '2', '3', '4', '5', '6') or jsonb_typeof(v_hours -> v_key) <> 'array' then
      raise exception 'working hours are not valid' using errcode = '22023';
    end if;
    for v_span in select * from jsonb_array_elements(v_hours -> v_key) loop
      if (v_span ->> 0) !~ '^[0-2][0-9]:[0-5][0-9]$' or (v_span ->> 1) !~ '^[0-2][0-9]:[0-5][0-9]$'
         or (v_span ->> 0)::time >= (v_span ->> 1)::time then
        raise exception 'each working period must start before it ends' using errcode = '22023';
      end if;
    end loop;
  end loop;

  select full_name, staff_id into v_name, v_staff from profiles where id = v_user;
  select id into v_id from practitioner where user_id = v_user and deleted_at is null limit 1;
  if v_id is null then
    insert into practitioner (code, user_id, names, title, slot_minutes, working_hours, categories,
                              languages, calendar_visibility, days_off, calendar_note, active)
    values (lower(coalesce(v_staff, 'dr-' || left(v_user::text, 8))), v_user, v_name,
            nullif(trim(coalesce(p_title, '')), ''), p_slot_minutes, v_hours, coalesce(p_categories, '{}'),
            nullif(trim(coalesce(p_languages, '')), ''), p_visibility, coalesce(p_days_off, '{}'),
            nullif(trim(coalesce(p_note, '')), ''), true)
    returning id into v_id;
  else
    update practitioner
    set names = coalesce(v_name, names), title = nullif(trim(coalesce(p_title, '')), ''),
        slot_minutes = p_slot_minutes, working_hours = v_hours, categories = coalesce(p_categories, '{}'),
        languages = nullif(trim(coalesce(p_languages, '')), ''), calendar_visibility = p_visibility,
        days_off = coalesce(p_days_off, '{}'), calendar_note = nullif(trim(coalesce(p_note, '')), ''),
        active = true
    where id = v_id;
  end if;
  return v_id;
end
$$;

revoke all on function calendar_role_ok(uuid), calendar_people(),
  save_calendar(uuid, jsonb, integer, text, date[], text, text, text[], text) from public, anon;
grant execute on function calendar_people(),
  save_calendar(uuid, jsonb, integer, text, date[], text, text, text[], text) to authenticated;

-- ---------------------------------------------------------------- who can be booked
-- The calendar row of a person, created the first time they are booked (private, no hours yet).
create or replace function ensure_practitioner(p_user uuid)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_name text;
  v_staff text;
begin
  if not (has_perm('appointment.approve') or is_manager() or p_user = auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select id into v_id from practitioner where user_id = p_user and deleted_at is null limit 1;
  if v_id is not null then
    update practitioner set active = true where id = v_id;
    return v_id;
  end if;
  select full_name, staff_id into v_name, v_staff from profiles
  where id = p_user and active and role in ('doctor', 'sonographer', 'nurse', 'manager');
  if v_name is null then
    raise exception 'only doctors, sonographers, nurses and managers can be booked' using errcode = '22023';
  end if;
  insert into practitioner (code, user_id, names, slot_minutes, working_hours, calendar_visibility, active)
  values (lower(coalesce(v_staff, 'dr-' || left(p_user::text, 8))), p_user, v_name, 30, '{}'::jsonb, 'private', true)
  returning id into v_id;
  return v_id;
end
$$;

-- Reception's list: everyone who can be booked, with their role (the form labels a nurse).
create or replace function bookable_doctors()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'userId', p.id, 'name', p.full_name, 'role', p.role, 'staffId', p.staff_id,
    'hasHours', coalesce(pr.working_hours, '{}'::jsonb) <> '{}'::jsonb,
    'slotMinutes', coalesce(pr.slot_minutes, 30),
    'title', pr.title
  ) order by p.full_name), '[]'::jsonb)
  from profiles p
  left join practitioner pr on pr.user_id = p.id and pr.deleted_at is null
  where has_perm('appointment.read') and p.active and p.role in ('doctor', 'sonographer', 'nurse', 'manager')
$$;

revoke all on function ensure_practitioner(uuid), bookable_doctors() from public, anon;
grant execute on function ensure_practitioner(uuid), bookable_doctors() to authenticated;

-- ---------------------------------------------------------------- the website: the role of each public calendar
create or replace view public_practitioners as
  select pr.id, pr.code, pr.names, pr.title, pr.specialty, pr.categories, pr.languages,
         pr.working_hours, pr.slot_minutes, pr.days_off, pr.calendar_note,
         (select p.role::text from profiles p where p.id = pr.user_id) as role
  from practitioner pr
  where pr.active and pr.deleted_at is null and pr.calendar_visibility = 'public'
    and pr.user_id is not null
    and exists (select 1 from profiles p where p.id = pr.user_id and p.active);
revoke insert, update, delete, truncate, references, trigger on public_practitioners from anon, authenticated;
grant select on public_practitioners to anon, authenticated;

-- ---------------------------------------------------------------- arrival: the booked person's desk
-- A nurse's booked patient waits at Nursing; a doctor's (or a manager's) at Dental when their
-- desk is the dental one, else at Consultation. A patient already in the clinic keeps their
-- place; only a visit started by the arrival goes to the booked person.
create or replace function appointment_arrived(p_appointment_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_appt appointment%rowtype;
  v_visit jsonb;
  v_enc uuid;
  v_doctor uuid;
  v_desk station;
  v_name text;
begin
  if not has_perm('appointment.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_appt from appointment where id = p_appointment_id and deleted_at is null for update;
  if not found or v_appt.status not in ('approved', 'confirmed') then
    raise exception 'this appointment is not waiting for the patient' using errcode = 'P0002';
  end if;
  if v_appt.patient_id is null then
    raise exception 'register the patient first, then mark the arrival' using errcode = 'P0002';
  end if;
  select user_id into v_doctor from practitioner where id = v_appt.practitioner_id;
  -- the booked person's desk: a nurse at Nursing, a dentist at Dental, anyone else at Consultation
  select case
           when p.role = 'nurse' then 'nursing'::station
           when lower(coalesce(p.station, '')) like '%dent%' then 'dental'::station
           else 'consultation'::station end
  into v_desk
  from profiles p where p.id = v_doctor;
  v_desk := coalesce(v_desk, 'consultation'::station);

  select jsonb_build_object(
           'encounter_id', e.id,
           'ticket_no', (select q.ticket_no from queue_entry q where q.encounter_id = e.id order by q.created_at limit 1),
           'station', (select q.station from queue_entry q where q.encounter_id = e.id and q.finished_at is null
                       order by q.created_at desc limit 1),
           'existing', true)
  into v_visit
  from encounter e where e.patient_id = v_appt.patient_id and e.status = 'open' and e.deleted_at is null
  order by e.arrived_at desc limit 1;

  if v_visit is null then
    v_visit := start_visit(v_appt.patient_id, false, v_desk);
  end if;
  v_enc := (v_visit ->> 'encounter_id')::uuid;

  -- The visit belongs to the booking: the booked person has the patient, and the booking
  -- completes when the visit ends.
  update encounter
  set appointment_id = coalesce(appointment_id, v_appt.id),
      practitioner_id = coalesce(practitioner_id, v_appt.practitioner_id)
  where id = v_enc;

  -- already in the clinic but waiting nowhere: back in line (triage or the booked person's desk)
  if not exists (select 1 from queue_entry where encounter_id = v_enc and finished_at is null and deleted_at is null) then
    insert into queue_entry (encounter_id, station, ticket_no)
    values (v_enc, case when triage_first() then 'triage'::station else v_desk end,
            (select ticket_no from queue_entry where encounter_id = v_enc order by created_at limit 1));
  end if;
  -- waiting at the booked person's desk, nobody has them yet: given to that person
  if v_doctor is not null then
    if not coalesce((v_visit ->> 'existing')::boolean, false) then
    update queue_entry set assigned_to = v_doctor
    where encounter_id = v_enc and finished_at is null and deleted_at is null and taken_by is null
      and assigned_to is null and station in ('consultation', 'dental', 'nursing');
    end if;
    select p.surname || ' ' || p.given_names into v_name from patient p where p.id = v_appt.patient_id;
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('booked_arrived',
            jsonb_build_object('name', v_name, 'when', v_appt.starts_at, 'triage', triage_first()),
            '/app/visit?encounter=' || v_enc, v_doctor, auth.uid());
  end if;

  update appointment set status = 'arrived' where id = p_appointment_id;
  return v_visit || jsonb_build_object('station',
    (select q.station from queue_entry q where q.encounter_id = v_enc and q.finished_at is null order by q.created_at desc limit 1));
end
$$;
revoke all on function appointment_arrived(uuid) from public, anon;
grant execute on function appointment_arrived(uuid) to authenticated;


-- ============================================================ 20261205090000_record_access_manager_only.sql
-- 0095 · Record-access requests: by default only the manager answers.
--
-- Frank: the manager (the owner) answers the requests to see a patient's past records. A head of
-- department does not answer them by position any more. The manager can give that right in
-- Settings → Who may do what: the new feature "Answer record-access requests" (records.approve),
-- switched on for a role or given to one person as an exception (0054 mechanism). It has no
-- default role; the manager keeps it, as every feature.
--
-- What follows the rule: who answers (answer_record_access, hint 'not_approver' kept), who is
-- told of a new request and of an emergency access (record_access_approvers), the "pending"
-- list and canAnswer (record_access_requests → may_answer_access), the 'approvers' count a
-- requester is shown (patient_access). The heads keep what they had otherwise: the full history
-- of their department's patients (history_via 'head') and "who looked" on the patient file.

-- ---------------------------------------------------------------- the feature
create or replace function managed_permission(p text)
returns boolean
language sql immutable
as $$
  select p in ('payment.take', 'visit.start', 'vitals.write', 'charge.write', 'clinical.write',
               'orders.write', 'appointment.approve', 'stock.write', 'records.approve')
$$;

-- The manager has it (my_permissions lists it for the manager); no other role by default.
insert into role_permissions (role, permission) values ('manager', 'records.approve')
on conflict do nothing;

create or replace function my_permissions()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(p), '[]'::jsonb)
  from unnest(array['payment.take', 'visit.start', 'vitals.write', 'charge.write', 'clinical.write',
                    'orders.write', 'appointment.approve', 'stock.write', 'records.approve']) as p
  where has_perm(p)
$$;

-- ---------------------------------------------------------------- who answers
-- Who answers a request about the patient (and is told of a new request or an emergency access):
-- the managers and everyone the manager allowed to answer (the role's switch or an exception).
-- The patient no longer matters; the argument stays for the callers.
create or replace function record_access_approvers(p_patient_id uuid)
returns uuid[]
language sql stable security definer set search_path = public
as $$
  select coalesce(array_agg(distinct p.id), '{}')
  from profiles p
  where p.active and p.deleted_at is null
    and (p.role = 'manager' or staff_perm(p.id, 'records.approve'))
$$;

-- May the signed-in person answer requests about the patient?
create or replace function may_answer_access(p_patient_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select is_manager() or has_perm('records.approve')
$$;

-- B: the first approver to answer approves or refuses (a refusal says why). The requester is told.
create or replace function answer_record_access(p_request_id uuid, p_approve boolean, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_req record_access_request%rowtype;
  v_name text;
  v_me text;
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if auth.uid() is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_req from record_access_request where id = p_request_id for update;
  if not found or v_req.kind <> 'request' then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  if v_req.requested_by = auth.uid() or not may_answer_access(v_req.patient_id) then
    raise exception 'not allowed: the manager answers, or whoever the manager allowed to answer record-access requests'
      using errcode = '42501', hint = 'not_approver';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'this request was already answered (%)', v_req.status
      using errcode = '22023', hint = 'already_answered',
            detail = coalesce((select full_name from profiles where id = v_req.answered_by), '');
  end if;
  if p_approve is null then
    raise exception 'approve or refuse' using errcode = '22023';
  end if;
  if not p_approve and (v_note is null or length(v_note) < 3) then
    raise exception 'say why the request is refused' using errcode = '22023', hint = 'reason_needed';
  end if;
  if p_approve and not exists (select 1 from encounter e where e.id = v_req.encounter_id and e.status = 'open' and e.deleted_at is null) then
    raise exception 'the visit is closed: the access would end at once' using errcode = '22023', hint = 'visit_closed';
  end if;
  update record_access_request
  set status = case when p_approve then 'approved' else 'refused' end,
      answered_by = auth.uid(), answered_at = now(), answer_note = v_note
  where id = p_request_id
  returning * into v_req;
  -- the other approvers no longer need to answer
  delete from notification where kind = 'access_request' and (params ->> 'requestId') = p_request_id::text;
  select p.surname || ' ' || p.given_names into v_name from patient p where p.id = v_req.patient_id;
  select full_name into v_me from profiles where id = auth.uid();
  insert into notification (kind, params, title, body, link, urgent, recipient_user, created_by)
  values ('access_answer',
          jsonb_build_object('requestId', v_req.id, 'patientId', v_req.patient_id, 'name', v_name,
                             'approved', p_approve, 'by', v_me, 'reason', v_note),
          case when p_approve then 'Access to past records approved' else 'Access to past records refused' end,
          v_me || case when p_approve then ' approved your request to see the past records of '
                       else ' refused your request to see the past records of ' end
            || v_name || coalesce(': ' || v_note, '') || '.',
          '/app/patient?id=' || v_req.patient_id, false, v_req.requested_by, auth.uid());
  return jsonb_build_object('id', v_req.id, 'status', v_req.status);
end
$$;

-- The patient file's "Who looked" stays with the manager and the heads in charge (it followed
-- may_answer_access before; a head keeps it although they no longer answer requests).
create or replace function patient_access_log(p_patient_id uuid, p_limit integer default 50)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
begin
  if not (is_manager() or coalesce(auth.uid() = any (heads_in_charge(p_patient_id)), false)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(access_entry_json(x) order by x.at desc)
    from (select a.* from record_access_entry a where a.patient_id = p_patient_id
          order by a.at desc limit greatest(1, least(coalesce(p_limit, 50), 200))) x), '[]'::jsonb);
end
$$;

comment on table record_access_request is
  'Requests to see a patient''s past records (and emergency accesses), answered by the manager or whoever the manager allowed to (records.approve, 0095).';

-- ---------------------------------------------------------------- grants
revoke all on function record_access_approvers(uuid), may_answer_access(uuid) from public, anon, authenticated;
revoke all on function answer_record_access(uuid, boolean, text), patient_access_log(uuid, integer), my_permissions()
  from public, anon;
grant execute on function answer_record_access(uuid, boolean, text), patient_access_log(uuid, integer), my_permissions()
  to authenticated;


-- ============================================================ 20261206090000_notice_targets.sql
-- 0096 · Notices open the exact thing they are about.
--
-- Frank: a doctor clicked "Booking to accept" and landed at the top of Home with the booking far
-- below. The app now works out each notice's destination from its kind and params
-- (lib/notice-target.ts) and points Home items with `?focus=<kind>:<id>` (scrolled into view and
-- outlined). Every kind already carries the id it needs except 'task': a task given without a
-- visit had no link at all and no task id. It now carries the task id ('task') and, without a
-- visit, the link to the Tasks panel of Home (`/app?focus=task:<id>`); a task on a visit still
-- opens the visit.

-- notify_task (last in 20261126090000_departments_decide_desks): the same recipients as before.
create or replace function notify_task()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_name text;
  v_link text := case when new.encounter_id is not null then '/app/visit?encounter=' || new.encounter_id
                      else '/app?focus=task:' || new.id end;
  v_params jsonb;
begin
  select p.surname || ' ' || p.given_names into v_name from patient p where p.id = new.patient_id;
  v_params := jsonb_build_object('title', new.title, 'name', v_name, 'due', new.due_at, 'task', new.id);
  if new.assigned_to is null and new.assigned_role = 'nurse' and desk_offered('nursing') then
    insert into notification (kind, params, link, recipient_user, created_by)
    select 'task', v_params, v_link, p.id, auth.uid()
    from profiles p
    where p.active and p.deleted_at is null and p.role <> 'manager' and desk_via(p.id, 'nursing') is not null;
  else
    insert into notification (kind, params, link, recipient_role, recipient_user, created_by)
    values ('task', v_params, v_link,
            case when new.assigned_to is null then new.assigned_role end,
            new.assigned_to,
            auth.uid());
  end if;
  return new;
end
$$;


-- ============================================================ 20261207090000_pharmacy_simplified.sql
-- 0097 · The pharmacy, simplified (the owner's design, 27 October).
--
-- Frank: the clinic's pharmacy is a small pharmacy and the main store. It records stock, hands over
-- prescribed medicines, sells to walk-in buyers, supplies the room stores and alerts the manager.
--
--   * A  ADD STOCK. add_stock(lines, store?, note?): the item (one of the list, or a new one: a
--        medicine or a supply), batch number, expiry, quantity, cost per unit, selling price. No
--        supplier, no delivery note, no date (today). Into the main pharmacy (another store: the
--        manager). A new item takes the selling price; an existing one whose price differs takes it
--        when the person may set prices (item_price.write / catalogue.write), else the line says
--        price_ignored. The same batch number with another expiry, and an expiry already past, are
--        refused (hints batch_expiry, expired_date). Kept as a goods received note (GRN-…) without a
--        supplier, so the history and the movements read as before. receive_delivery keeps working;
--        its supplier is now optional.
--   * B  PART OF A PRESCRIPTION. dispense_prescription(request, store?, quantity?): null = what
--        remains (as before); less = part given (medication_request.quantity_given). The bill charges
--        what was given; the line stays at the pharmacy while something remains; the prescriber is
--        told (rx_part_given: given / remaining). rx_not_given closes what remains (its notice says
--        how much was given). pharmacy_queue lines carry quantity, given, remaining and price what
--        remains. A return (return_medicine) gives back the last hand-over and its quantity.
--   * C  THE PHARMACIST TAKES THE PAYMENT OF A WALK-IN SALE. take_counter_payment: also the
--        pharmacist (role) or the pharmacy desk, for counter sales only (take_payment on visits' bills
--        is unchanged). The payment records the pharmacist as the receiver; their cash count
--        (cashier_summary, scope 'mine'; close_cash_day) counts their own payments.
--   * D  ROOM STORES: unchanged (confirm_receipt without lines = everything arrived).
--   * E  ALERTS. stock_alert_check(): below the reorder level (stock_low, once per medicine per day),
--        expiring within stock.expiry_days (stock_expiring, once per batch), expired and still on a
--        shelf (stock_expired, urgent, once per batch per day) and one summary a day (stock_summary),
--        to the manager and the pharmacy. Run by add_stock, dispense_prescription and adjust_stock,
--        and by the web once a day. message_manager(text): a staff_message to the managers.
--   * F  TOTALS. stock_totals(store?): inventory cost, selling value, items, low, expiring, expired.
--        stock_sales gains revenue, cost and margin for the period.
--   * G  THE EXPIRY WINDOW. Setting stock.expiry_days (default 30) for every "expiring soon"
--        (stock_overview, stock_alerts, store_stock, my_stores, the alerts and the totals).
--
-- Errcodes: 42501 not allowed, 22023 bad input (hints batch_expiry, expired_date, store_closed,
-- more_than_remaining), 23505 already done, P0002 not found.

-- ---------------------------------------------------------------- columns and the setting
alter table item add column if not exists kind text not null default 'medicine';
alter table item drop constraint if exists item_kind_ck;
alter table item add constraint item_kind_ck check (kind in ('medicine', 'supply'));

alter table medication_request add column if not exists quantity_given integer not null default 0;
-- what was handed over before this migration: all of it
update medication_request set quantity_given = ceil(quantity)::integer
where given_at is not null and quantity_given = 0;

insert into setting (key, value) values ('stock.expiry_days', '30'::jsonb) on conflict (key) do nothing;

create index if not exists notification_kind_key_idx on notification (kind, (params ->> 'key')) where params ? 'key';

-- ---------------------------------------------------------------- helpers
-- The "expiring soon" window in days (setting stock.expiry_days, default 30).
create or replace function stock_expiry_days()
returns integer
language sql stable security definer set search_path = public
as $$
  select coalesce((
    select case jsonb_typeof(s.value)
             when 'number' then (s.value #>> '{}')::numeric
             when 'object' then nullif(s.value ->> 'days', '')::numeric
           end
    from setting s where s.key = 'stock.expiry_days')::integer, 30)
$$;

-- The pharmacist (role) or the pharmacy desk: takes the money of a walk-in (counter) sale.
create or replace function pharmacy_takes_money()
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce(may_use_desk('pharmacy'), false)
      or exists (select 1 from profiles p where p.id = auth.uid() and p.active and p.deleted_at is null
                 and p.role = 'pharmacist')
$$;

-- Internal: the cash price of an item (the current cash price list).
create or replace function set_cash_price(p_item_id uuid, p_price numeric)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_list uuid;
begin
  select id into v_list from price_list
  where payer_id is null and deleted_at is null and effective_from <= current_date
    and (effective_to is null or effective_to >= current_date)
  order by effective_from desc limit 1;
  if v_list is null then
    insert into price_list (payer_id, name, effective_from) values (null, 'Cash prices', current_date) returning id into v_list;
  end if;
  insert into price_list_item (price_list_id, item_id, price) values (v_list, p_item_id, round(p_price))
  on conflict (price_list_id, item_id) where item_id is not null
  do update set price = excluded.price, deleted_at = null;
end
$$;

-- Internal: a stock notice to the manager and to the pharmacy, once per key (a key carrying the day
-- makes it once a day). Returns how many notices were written.
create or replace function stock_notice(p_kind text, p_key text, p_params jsonb, p_link text, p_urgent boolean default false)
returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_n integer := 0;
  r record;
begin
  for r in select * from (values ('manager'::role_key, null::station[]), (null::role_key, array['pharmacy'::station]))
           as x(role, stations) loop
    if not exists (select 1 from notification n
                   where n.kind = p_kind and n.params ->> 'key' = p_key
                     and n.recipient_role is not distinct from r.role
                     and n.recipient_stations is not distinct from r.stations) then
      insert into notification (kind, params, link, urgent, recipient_role, recipient_stations, created_by)
      values (p_kind, coalesce(p_params, '{}'::jsonb) || jsonb_build_object('key', p_key), p_link,
              coalesce(p_urgent, false), r.role, r.stations, auth.uid());
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end
$$;

-- ---------------------------------------------------------------- E  alerts
-- Internal: the stock alerts (idempotent). Low: unexpired pharmacy units at or below the reorder
-- level; expiring: a batch on a shelf expiring within the window; expired: a batch past its expiry
-- still on a shelf (every store but "In transit").
create or replace function stock_alert_run()
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_days integer := stock_expiry_days();
  v_day text := to_char((now() at time zone 'Africa/Kigali')::date, 'YYYY-MM-DD');
  v_low integer := 0;
  v_expiring integer := 0;
  v_expired integer := 0;
  v_expired_units integer := 0;
  v_created integer := 0;
  r record;
begin
  perform pg_advisory_xact_lock(hashtext('mmc.stock_alert_check'));
  for r in select b.item_id, b.on_hand, b.reorder_level from items_below_reorder b order by b.name_generic loop
    v_low := v_low + 1;
    v_created := v_created + stock_notice('stock_low', 'low:' || r.item_id || ':' || v_day,
      jsonb_build_object('item', item_label(r.item_id), 'itemId', r.item_id, 'onHand', r.on_hand,
                         'level', r.reorder_level),
      '/app/stock?tab=stock&item=' || r.item_id);
  end loop;
  for r in
    select s.batch_id, s.item_id, b.batch_no, s.expiry, sum(s.quantity)::integer as quantity,
           sum(s.quantity * coalesce(b.unit_cost, 0)) as cost
    from stock_on_hand s
    join stock_location l on l.id = s.location_id and l.deleted_at is null and l.type::text <> 'transit'
    join batch b on b.id = s.batch_id
    where s.quantity > 0 and s.expiry is not null and s.expiry <= current_date + v_days
    group by s.batch_id, s.item_id, b.batch_no, s.expiry
    order by s.expiry
  loop
    if r.expiry < current_date then
      v_expired := v_expired + 1;
      v_expired_units := v_expired_units + r.quantity;
      v_created := v_created + stock_notice('stock_expired', 'expired:' || r.batch_id || ':' || v_day,
        jsonb_build_object('item', item_label(r.item_id), 'itemId', r.item_id, 'batchId', r.batch_id,
                           'batchNo', r.batch_no, 'expiry', r.expiry, 'quantity', r.quantity,
                           'value', round(r.cost, 2)),
        '/app/stock?tab=stock&item=' || r.item_id, true);
    else
      v_expiring := v_expiring + 1;
      v_created := v_created + stock_notice('stock_expiring', 'expiring:' || r.batch_id,
        jsonb_build_object('item', item_label(r.item_id), 'itemId', r.item_id, 'batchId', r.batch_id,
                           'batchNo', r.batch_no, 'expiry', r.expiry, 'quantity', r.quantity,
                           'days', r.expiry - current_date),
        '/app/stock?tab=stock&item=' || r.item_id);
    end if;
  end loop;
  if v_low + v_expiring + v_expired > 0 then
    v_created := v_created + stock_notice('stock_summary', 'summary:' || v_day,
      jsonb_build_object('low', v_low, 'expiring', v_expiring, 'expired', v_expired,
                         'expiredUnits', v_expired_units, 'days', v_days, 'day', v_day),
      '/app/stock?tab=stock', v_expired > 0);
  end if;
  return jsonb_build_object('low', v_low, 'expiring', v_expiring, 'expired', v_expired,
                            'expiredUnits', v_expired_units, 'expiryDays', v_days, 'created', v_created);
end
$$;

-- The web runs it once a day (pharmacy home, manager dashboard). Someone who does not see the stock
-- gets zeros (nothing written).
create or replace function stock_alert_check()
returns jsonb
language plpgsql security definer set search_path = public
as $$
begin
  if not (stock_admin() or has_perm('stock.read')) then
    return jsonb_build_object('low', 0, 'expiring', 0, 'expired', 0, 'expiredUnits', 0,
                              'expiryDays', stock_expiry_days(), 'created', 0, 'skipped', true);
  end if;
  return stock_alert_run();
end
$$;

-- A message to the managers (any staff member: 3 to 500 characters, 20 an hour at most).
create or replace function message_manager(p_text text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_me profiles%rowtype;
  v_text text := trim(coalesce(p_text, ''));
begin
  select * into v_me from profiles where id = auth.uid() and active and deleted_at is null;
  if not found then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if length(v_text) < 3 or length(v_text) > 500 then
    raise exception 'write a message of 3 to 500 characters' using errcode = '22023';
  end if;
  if (select count(*) from notification where kind = 'staff_message' and created_by = v_me.id
        and created_at > now() - interval '1 hour') >= 20 then
    raise exception 'too many messages in the last hour: try again later' using errcode = '22023';
  end if;
  insert into notification (kind, params, body, link, recipient_role, created_by)
  values ('staff_message',
          jsonb_build_object('text', v_text, 'from', v_me.full_name, 'fromId', v_me.id, 'role', v_me.role),
          v_text, null, 'manager', v_me.id);
end
$$;

-- ---------------------------------------------------------------- F  totals
-- One store (whoever sees it), else every pharmacy store (the pharmacy) or every store (the
-- manager). Costs only for the pharmacy and the manager. inventory_cost and selling_value count
-- unexpired units; expired units apart.
create or replace function stock_totals(p_location_id uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_days integer := stock_expiry_days();
  v_admin boolean := stock_admin();
  v_stores uuid[];
  v_room boolean := false;
  v_low integer;
  v_r record;
begin
  if p_location_id is not null then
    if not exists (select 1 from stock_location where id = p_location_id and deleted_at is null
                   and type::text <> 'transit') then
      raise exception 'store not found' using errcode = 'P0002';
    end if;
    if not may_see_store(p_location_id) then
      raise exception 'not allowed' using errcode = '42501';
    end if;
    v_stores := array[p_location_id];
    v_room := is_room_type((select type from stock_location where id = p_location_id));
  elsif is_manager() then
    select coalesce(array_agg(id), '{}'::uuid[]) into v_stores
    from stock_location where deleted_at is null and type::text <> 'transit';
  elsif v_admin then
    select coalesce(array_agg(id), '{}'::uuid[]) into v_stores
    from stock_location where deleted_at is null and type = 'pharmacy';
  else
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_room then
    select count(*)::integer into v_low from store_item_level m
    where m.location_id = p_location_id and usable_stock(m.item_id, p_location_id) < m.min_level;
  else
    select count(*)::integer into v_low from items_below_reorder;
  end if;
  select
    round(coalesce(sum(x.quantity * x.cost) filter (where x.usable), 0), 2) as inventory_cost,
    coalesce(sum(x.quantity * coalesce(x.price, 0)) filter (where x.usable), 0) as selling_value,
    count(distinct x.item_id) filter (where x.usable)::integer as items,
    count(distinct x.batch_id) filter (where x.usable and x.expiry <= current_date + v_days)::integer as expiring,
    coalesce(sum(x.quantity) filter (where x.usable and x.expiry <= current_date + v_days), 0)::integer as expiring_units,
    coalesce(sum(x.quantity) filter (where not x.usable), 0)::integer as expired_units,
    round(coalesce(sum(x.quantity * x.cost) filter (where not x.usable), 0), 2) as expired_cost
  into v_r
  from (
    select s.item_id, s.batch_id, s.quantity, s.expiry, coalesce(b.unit_cost, 0) as cost,
           (s.expiry is null or s.expiry >= current_date) as usable,
           (select pf.price from price_for(null, s.item_id, null) pf) as price
    from stock_on_hand s left join batch b on b.id = s.batch_id
    where s.location_id = any (v_stores) and s.quantity > 0
  ) x;
  return jsonb_build_object(
    'inventory_cost', case when v_admin then v_r.inventory_cost end,
    'selling_value', v_r.selling_value,
    'items', v_r.items,
    'low', v_low,
    'expiring_30', v_r.expiring,
    'expiring_units', v_r.expiring_units,
    'expired_units', v_r.expired_units,
    'expired_cost', case when v_admin then v_r.expired_cost end,
    'expiry_days', v_days,
    'location_id', p_location_id
  );
end
$$;

-- stock_sales (from 20261124090000_stores_and_stock): the same, with the period's revenue, cost of
-- what was sold and margin.
create or replace function stock_sales(p_from date, p_to date)
returns jsonb
language sql stable security definer set search_path = public
as $$
  with sold as (
    select l.item_id, l.quantity::numeric as units, round(l.quantity * l.unit_price) as revenue
    from invoice_line l
    join invoice inv on inv.id = l.invoice_id and inv.status <> 'credited'
    where l.deleted_at is null and l.item_id is not null
      and (l.created_at at time zone 'Africa/Kigali')::date between p_from and p_to
    union all
    select x.item_id, x.quantity, x.line_total
    from counter_sale_line x join counter_sale s on s.id = x.sale_id
    where x.deleted_at is null and s.deleted_at is null and s.status = 'handed_over'
      and (s.handed_over_at at time zone 'Africa/Kigali')::date between p_from and p_to
  ), per_item as (
    select i.name_generic || coalesce(' ' || i.strength, '') as name,
           sum(s.units) as units,
           sum(s.revenue) as revenue,
           round(sum(s.units) * coalesce((
             select sum(coalesce(m.unit_cost, b.unit_cost) * m.quantity) / nullif(sum(m.quantity), 0)
             from stock_movement m join batch b on b.id = m.batch_id
             where m.item_id = i.id and m.type = 'receipt' and m.deleted_at is null and b.deleted_at is null), 0), 2) as cost
    from sold s join item i on i.id = s.item_id
    group by i.id, i.name_generic, i.strength
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'item', x.name, 'units', x.units, 'revenue', x.revenue, 'cost', x.cost, 'margin', x.revenue - x.cost
      ) order by x.revenue desc) from per_item x), '[]'::jsonb),
    'revenue', (select coalesce(sum(revenue), 0) from per_item),
    'cost', (select coalesce(sum(cost), 0) from per_item),
    'margin', (select coalesce(sum(revenue - cost), 0) from per_item),
    'counterRevenue', (select coalesce(sum(s.total), 0) from counter_sale s
                       where s.deleted_at is null and s.status = 'handed_over'
                         and (s.handed_over_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'received', (select coalesce(sum(m.quantity * coalesce(m.unit_cost, b.unit_cost, 0)), 0)
                 from stock_movement m left join batch b on b.id = m.batch_id
                 where m.deleted_at is null and m.type = 'receipt' and (m.moved_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    'consumed', (select coalesce(sum(m.quantity * coalesce(b.unit_cost, 0)), 0) from stock_movement m left join batch b on b.id = m.batch_id
                 where m.deleted_at is null and m.type = 'consumption' and (m.moved_at at time zone 'Africa/Kigali')::date between p_from and p_to),
    -- everything held, in every store and on the way
    'stockValue', (select coalesce(sum(s.quantity * coalesce(b.unit_cost, 0)), 0) from stock_on_hand s
                   left join batch b on b.id = s.batch_id where s.quantity > 0)
  )
  where has_perm('stock.read') and stock_admin()
$$;

-- ---------------------------------------------------------------- A  add stock
create or replace function add_stock(p_lines jsonb, p_location_id uuid default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_main uuid := main_pharmacy();
  v_loc uuid;
  v_id uuid;
  v_number text;
  v_line jsonb;
  v_n integer;
  v_item uuid;
  v_new jsonb;
  v_kind text;
  v_name text;
  v_strength text;
  v_created boolean;
  v_qty numeric;
  v_units integer;
  v_cost numeric;
  v_sell numeric;
  v_price numeric;
  v_expiry date;
  v_batch uuid;
  v_line_cost numeric;
  v_updated boolean;
  v_ignored boolean;
  v_price_right boolean := has_perm('item_price.write') or has_perm('catalogue.write');
  v_out jsonb := '[]'::jsonb;
  v_total numeric := 0;
  v_state text;
  v_msg text;
  v_hint text;
begin
  if not stock_manager() then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  v_loc := coalesce(p_location_id, v_main);
  if v_loc is null then
    raise exception 'no pharmacy store yet: create one under Stock' using errcode = 'P0002';
  end if;
  if v_loc is distinct from v_main and not is_manager() then
    raise exception 'stock is added into the main pharmacy (another store: the manager)' using errcode = '42501';
  end if;
  if not exists (select 1 from stock_location where id = v_loc and deleted_at is null and type::text <> 'transit') then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'add at least one medicine' using errcode = '22023';
  end if;
  v_number := day_number('GRN', 'goods-receipt');
  insert into goods_receipt (supplier_id, received_on, note, number, reference, delivered_on, location_id, supplier_name)
  values (null, now(), nullif(trim(coalesce(p_note, '')), ''), v_number, null,
          (now() at time zone 'Africa/Kigali')::date, v_loc, null)
  returning id into v_id;

  for v_line, v_n in select x.value, x.ordinality from jsonb_array_elements(p_lines) with ordinality as x loop
    begin
      v_created := false;
      v_updated := false;
      v_ignored := false;
      v_item := nullif(v_line ->> 'item_id', '')::uuid;
      v_new := case when jsonb_typeof(v_line -> 'new_item') = 'object' then v_line -> 'new_item' end;
      v_sell := nullif(v_line ->> 'sell_price', '')::numeric;
      if v_sell is not null and v_sell < 0 then
        raise exception 'the price must be zero or more' using errcode = '22023';
      end if;
      if v_item is null and v_new is not null then
        v_kind := coalesce(nullif(v_new ->> 'kind', ''), 'medicine');
        if v_kind not in ('medicine', 'supply') then
          raise exception 'a new item is a medicine or a supply' using errcode = '22023';
        end if;
        v_name := trim(coalesce(v_new ->> 'name', ''));
        v_strength := nullif(trim(coalesce(v_new ->> 'strength', '')), '');
        if length(v_name) < 2 then
          raise exception 'the medicine needs a name' using errcode = '22023';
        end if;
        -- the same name (and strength) already on the list: that item
        select id into v_item from item
        where deleted_at is null and lower(name_generic) = lower(v_name)
          and lower(coalesce(strength, '')) = lower(coalesce(v_strength, ''))
        order by active desc, created_at
        limit 1;
        if v_item is null then
          insert into item (code, name_generic, strength, form, unit, selling_unit, active, kind)
          values (case when v_kind = 'supply' then 'SUP-' else 'MED-' end
                    || lpad(next_number('item_code', 0)::text, 4, '0'),
                  v_name, v_strength, nullif(trim(coalesce(v_new ->> 'form', '')), ''),
                  nullif(trim(coalesce(v_new ->> 'unit', '')), ''), nullif(trim(coalesce(v_new ->> 'unit', '')), ''),
                  true, v_kind)
          returning id into v_item;
          v_created := true;
        end if;
      end if;
      if v_item is null then
        raise exception 'choose the medicine' using errcode = '22023';
      end if;
      if not exists (select 1 from item where id = v_item and deleted_at is null) then
        raise exception 'medicine not found' using errcode = 'P0002';
      end if;
      v_qty := nullif(v_line ->> 'quantity', '')::numeric;
      if v_qty is null or v_qty <= 0 then
        raise exception 'quantity must be more than zero' using errcode = '22023';
      end if;
      if v_qty <> round(v_qty) then
        raise exception 'the quantity must come to whole units' using errcode = '22023';
      end if;
      v_units := v_qty::integer;
      v_cost := nullif(v_line ->> 'unit_cost', '')::numeric;
      if v_cost is null or v_cost < 0 then
        raise exception 'the cost per unit must be zero or more' using errcode = '22023';
      end if;
      v_expiry := nullif(v_line ->> 'expiry', '')::date;
      -- the selling price: a new item (or one without a price) takes it; a different price needs the right
      if v_sell is not null then
        select pf.price into v_price from price_for(null, v_item, null) pf;
        if v_price is null or v_created then
          perform set_cash_price(v_item, v_sell);
          v_updated := true;
        elsif round(v_sell) <> v_price then
          if v_price_right then
            perform set_cash_price(v_item, v_sell);
            v_updated := true;
          else
            v_ignored := true;
          end if;
        end if;
      end if;
      v_batch := receive_batch(v_item, v_loc, v_units, v_cost, v_line ->> 'batch_no', v_expiry, null, null, v_id);
      v_line_cost := round(round(v_cost, 2) * v_units, 2);
      insert into goods_receipt_line (receipt_id, item_id, batch_id, batch_no, expiry, unit, packs, pack_size, units,
                                      unit_cost, pack_cost, line_cost)
      select v_id, v_item, b.id, b.batch_no, b.expiry, 'unit', v_units, 1, v_units, round(v_cost, 2), null, v_line_cost
      from batch b where b.id = v_batch;
      v_total := v_total + v_line_cost;
      v_out := v_out || jsonb_build_array(jsonb_build_object(
        'item_id', v_item, 'batch_id', v_batch, 'quantity', v_units, 'line_cost', v_line_cost,
        'created', v_created, 'price_updated', v_updated, 'price_ignored', v_ignored));
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text, v_hint = pg_exception_hint;
      raise exception 'line %: %', v_n, v_msg using errcode = v_state, hint = coalesce(nullif(v_hint, ''), 'line');
    end;
  end loop;
  update goods_receipt set total_cost = v_total where id = v_id;
  perform stock_alert_run();
  return jsonb_build_object('lines', v_out, 'total_cost', v_total, 'id', v_id, 'number', v_number, 'location_id', v_loc);
end
$$;

-- receive_delivery (from 20261128090000_switches_enforced): the supplier is optional.
create or replace function receive_delivery(
  p_supplier text, p_reference text, p_lines jsonb, p_delivered_on date default null,
  p_location_id uuid default null, p_note text default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_loc uuid;
  v_sup uuid;
  v_ref text := nullif(trim(coalesce(p_reference, '')), '');
  v_on date := coalesce(p_delivered_on, (now() at time zone 'Africa/Kigali')::date);
  v_id uuid;
  v_number text;
  v_line jsonb;
  v_n integer;
  v_item uuid;
  v_code text;
  v_r medicine_reference%rowtype;
  v_unit text;
  v_qty numeric;
  v_pack integer;
  v_units integer;
  v_cost numeric;
  v_unit_cost numeric;
  v_line_cost numeric;
  v_expiry date;
  v_batch uuid;
  v_total numeric := 0;
  v_all_units integer := 0;
  v_state text;
  v_msg text;
  v_hint text;
begin
  if not stock_manager() then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  v_loc := coalesce(p_location_id, main_pharmacy());
  if v_loc is null or not exists (select 1 from stock_location where id = v_loc and type = 'pharmacy' and active
                                  and deleted_at is null) then
    raise exception 'deliveries are received into an open pharmacy store' using errcode = '22023', hint = 'receive_into_pharmacy';
  end if;
  if v_on > (now() at time zone 'Africa/Kigali')::date then
    raise exception 'the delivery date is in the future' using errcode = '22023';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'add at least one medicine' using errcode = '22023';
  end if;
  v_sup := supplier_for(p_supplier);
  if v_ref is not null and exists (select 1 from goods_receipt g where g.supplier_id = v_sup and lower(g.reference) = lower(v_ref)
                                   and g.deleted_at is null) then
    raise exception 'delivery note % of this supplier was already received', v_ref using errcode = '23505', hint = 'duplicate_delivery';
  end if;
  v_number := day_number('GRN', 'goods-receipt');
  insert into goods_receipt (supplier_id, received_on, note, number, reference, delivered_on, location_id, supplier_name)
  values (v_sup, now(), nullif(trim(coalesce(p_note, '')), ''), v_number, v_ref, v_on, v_loc,
          nullif(trim(coalesce(p_supplier, '')), ''))
  returning id into v_id;

  for v_line, v_n in select x.value, x.ordinality from jsonb_array_elements(p_lines) with ordinality as x loop
    begin
      v_item := nullif(v_line ->> 'itemId', '')::uuid;
      v_code := nullif(upper(trim(coalesce(v_line ->> 'refCode', ''))), '');
      if v_item is null and v_code is not null then
        select id into v_item from item where code = v_code and deleted_at is null;
        if v_item is null then
          -- a medicine new at the clinic, from the reference list (RHIA): added with its selling price
          select * into v_r from medicine_reference where code = v_code;
          if not found then
            raise exception 'this medicine is not on the reference list' using errcode = 'P0002';
          end if;
          v_item := upsert_item(null, v_r.generic,
                                coalesce(nullif(v_line ->> 'sellingPrice', '')::numeric, v_r.price),
                                v_r.presentation, null, v_r.unit, true, v_r.code);
        end if;
      end if;
      if v_item is null or not exists (select 1 from item where id = v_item and deleted_at is null) then
        raise exception 'choose the medicine' using errcode = '22023';
      end if;
      v_unit := coalesce(nullif(v_line ->> 'unit', ''), 'unit');
      if v_unit not in ('box', 'unit') then
        raise exception 'count in boxes or in units' using errcode = '22023';
      end if;
      v_qty := nullif(v_line ->> 'quantity', '')::numeric;
      if v_qty is null or v_qty <= 0 then
        raise exception 'quantity must be more than zero' using errcode = '22023';
      end if;
      if v_unit = 'box' then
        v_pack := coalesce(nullif(v_line ->> 'packSize', '')::integer, (select pack_size from item where id = v_item));
        if v_pack is null or v_pack < 1 then
          raise exception 'say how many units are in one box' using errcode = '22023', hint = 'pack_size';
        end if;
        update item set pack_size = v_pack where id = v_item and pack_size is null;
      else
        v_pack := 1;
      end if;
      v_units := round(v_qty * v_pack)::integer;
      if v_units <> v_qty * v_pack or v_units <= 0 then
        raise exception 'the quantity must come to whole units' using errcode = '22023';
      end if;
      v_cost := nullif(v_line ->> 'cost', '')::numeric;
      if v_cost is null or v_cost < 0 then
        raise exception 'the cost must be zero or more' using errcode = '22023';
      end if;
      v_unit_cost := round(v_cost / v_pack, 2);
      v_line_cost := round(v_cost * v_qty, 2);
      v_expiry := nullif(v_line ->> 'expiry', '')::date;
      perform set_cash_price_if_none(v_item, nullif(v_line ->> 'sellingPrice', '')::numeric);
      v_batch := receive_batch(v_item, v_loc, v_units, v_unit_cost, v_line ->> 'batchNo', v_expiry, v_sup,
                               concat_ws(' · ', nullif(trim(coalesce(p_supplier, '')), ''), v_ref, v_number), v_id);
      insert into goods_receipt_line (receipt_id, item_id, batch_id, batch_no, expiry, unit, packs, pack_size, units,
                                      unit_cost, pack_cost, line_cost)
      values (v_id, v_item, v_batch, (select batch_no from batch where id = v_batch), v_expiry, v_unit, v_qty, v_pack,
              v_units, v_unit_cost, case when v_unit = 'box' then v_cost end, v_line_cost);
      v_total := v_total + v_line_cost;
      v_all_units := v_all_units + v_units;
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text, v_hint = pg_exception_hint;
      raise exception 'line %: %', v_n, v_msg using errcode = v_state, hint = coalesce(nullif(v_hint, ''), 'line');
    end;
  end loop;
  update goods_receipt set total_cost = v_total where id = v_id;
  return jsonb_build_object('id', v_id, 'number', v_number, 'locationId', v_loc,
                            'lines', jsonb_array_length(p_lines), 'units', v_all_units, 'totalCost', v_total);
end
$$;

-- ---------------------------------------------------------------- B  part of a prescription
-- rx_pending (from 20261123090000_dispensing_fixes): waiting while something remains to give.
create or replace function rx_pending(m medication_request)
returns boolean
language sql stable security definer set search_path = public
as $$
  select m.deleted_at is null and m.supply = 'pharmacy' and m.given_at is null and m.not_given_at is null
    and m.cancelled_at is null
    and coalesce(m.quantity_given, 0) < ceil(m.quantity)
    and (coalesce(m.quantity_given, 0) > 0
         or not exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null))
$$;

-- guard_medication_request (from 20261202090000_security_hardening): the quantity given too.
create or replace function guard_medication_request()
returns trigger
language plpgsql
as $$
begin
  -- the checked (security definer) functions run as their owner, not as the API roles
  if current_user::text not in ('authenticated', 'anon') then
    return coalesce(new, old);
  end if;
  if tg_op = 'INSERT' then
    raise exception 'prescriptions are written with the prescription form only' using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'a prescription is not deleted: the doctor cancels it' using errcode = '42501';
  end if;
  if new.given_at is distinct from old.given_at or new.given_by is distinct from old.given_by
     or new.not_given_at is distinct from old.not_given_at or new.not_given_by is distinct from old.not_given_by
     or new.not_given_reason is distinct from old.not_given_reason
     or new.cancelled_at is distinct from old.cancelled_at or new.cancelled_by is distinct from old.cancelled_by
     or new.cancel_reason is distinct from old.cancel_reason
     or new.supply is distinct from old.supply or new.quantity is distinct from old.quantity
     or new.item_id is distinct from old.item_id or new.encounter_id is distinct from old.encounter_id
     or new.prescriber_id is distinct from old.prescriber_id or new.deleted_at is distinct from old.deleted_at
     or new.quantity_given is distinct from old.quantity_given
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'handing over, not given, cancelling and the medicine or quantity change only through the pharmacy and prescription screens'
      using errcode = '42501';
  end if;
  return new;
end
$$;

-- dispense_prescription (from 20261126090000_departments_decide_desks): a quantity (part given).
drop function if exists dispense_prescription(uuid, uuid);
create or replace function dispense_prescription(
  p_medication_request_id uuid, p_location_id uuid default null, p_quantity integer default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_loc uuid;
  v_dispense uuid;
  v_charged boolean := false;
  v_whole integer;
  v_left integer;
  v_give integer;
  v_charge numeric;
  v_done boolean;
  v_to uuid;
  v_name text;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  select * into v_m from medication_request where id = p_medication_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  if v_m.cancelled_at is not null then
    raise exception 'the doctor cancelled this medicine' using errcode = '23505';
  end if;
  v_whole := ceil(v_m.quantity)::integer;
  v_left := v_whole - coalesce(v_m.quantity_given, 0);
  if v_m.given_at is not null or v_left <= 0
     or (coalesce(v_m.quantity_given, 0) = 0 and exists (
           select 1 from medication_dispense d where d.medication_request_id = v_m.id and d.deleted_at is null)) then
    raise exception 'already dispensed' using errcode = '23505';
  end if;
  if v_m.not_given_at is not null then
    raise exception 'this medicine was marked as not given' using errcode = '23505';
  end if;
  if p_quantity is not null and p_quantity <= 0 then
    raise exception 'quantity must be more than zero' using errcode = '22023';
  end if;
  if p_quantity is not null and p_quantity > v_left then
    raise exception 'only % left to give of this medicine', v_left using errcode = '22023', hint = 'more_than_remaining';
  end if;
  -- The prescription is final once the doctor has finished (or sent the patient on). A sale written
  -- by the pharmacist themself is not held.
  if coalesce(v_m.prescriber_id, v_m.created_by) is distinct from auth.uid() and doctor_holds(v_m.encounter_id) then
    raise exception 'the doctor is still seeing this patient: hand the medicines over when the doctor has finished'
      using errcode = 'MS002', hint = 'doctor_holds';
  end if;
  if p_location_id is not null then
    if not exists (select 1 from stock_location where id = p_location_id and type = 'pharmacy'
                   and active and deleted_at is null) then
      raise exception 'choose an open pharmacy store' using errcode = '22023';
    end if;
    v_loc := p_location_id;
  else
    v_loc := main_pharmacy();
  end if;
  if v_loc is null then
    raise exception 'no pharmacy store yet: create one under Stock' using errcode = 'P0002';
  end if;
  v_give := coalesce(p_quantity, v_left);
  v_done := v_give = v_left;
  v_dispense := dispense_fefo(v_m.encounter_id, v_m.item_id, v_give, v_loc, v_m.id, null);
  -- the bill charges what is given; the last part charges what remains of the prescribed quantity
  v_charge := case when v_done then v_m.quantity - coalesce(v_m.quantity_given, 0) else v_give end;
  -- no price: handed over free (charged = false); no open bill: refused (MS001)
  begin
    perform add_charge_internal(v_m.encounter_id, 'pharmacy'::station, null, v_m.item_id, v_charge,
                       null, null, null, null, 'medication_dispense', v_dispense);
    v_charged := true;
  exception when sqlstate 'P0002' then
    v_charged := false;
  end;
  update medication_request
  set quantity_given = coalesce(quantity_given, 0) + v_give,
      given_at = case when v_done then now() end,
      given_by = case when v_done then auth.uid() end
  where id = v_m.id;
  -- part given: the prescriber is told what was given and what remains
  if not v_done then
    v_to := coalesce(v_m.prescriber_id, v_m.created_by);
    if v_to is not null and v_to is distinct from auth.uid() then
      select p.surname || ' ' || p.given_names into v_name
      from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
      insert into notification (kind, params, link, recipient_user, created_by)
      values ('rx_part_given',
              jsonb_build_object('item', item_label(v_m.item_id), 'name', v_name,
                                 'given', coalesce(v_m.quantity_given, 0) + v_give, 'remaining', v_left - v_give,
                                 'quantity', v_whole, 'requestId', v_m.id),
              '/app/visit?encounter=' || v_m.encounter_id, v_to, auth.uid());
    end if;
  end if;
  -- the last line handed over: on to the cashier (money due) or the visit closes
  perform after_pharmacy(v_m.encounter_id);
  perform stock_alert_run();
  return jsonb_build_object('dispenseId', v_dispense, 'charged', v_charged, 'locationId', v_loc,
                            'given', v_give, 'givenTotal', coalesce(v_m.quantity_given, 0) + v_give,
                            'remaining', v_left - v_give, 'quantity', v_whole);
end
$$;

-- rx_not_given (from 20261126090000_departments_decide_desks): closes what remains; the notice says what was given.
create or replace function rx_not_given(p_medication_request_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_item text;
  v_name text;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  if length(trim(coalesce(p_reason, ''))) < 2 then
    raise exception 'say why the medicine is not given' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_medication_request_id for update;
  if not found or not rx_pending(v_m) then
    raise exception 'this medicine is no longer waiting at the pharmacy' using errcode = 'P0002';
  end if;
  update medication_request
  set not_given_at = now(), not_given_by = auth.uid(), not_given_reason = trim(p_reason)
  where id = v_m.id;
  select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
  if coalesce(v_m.prescriber_id, v_m.created_by) is not null
     and coalesce(v_m.prescriber_id, v_m.created_by) is distinct from auth.uid() then
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('rx_not_given', jsonb_build_object('item', v_item, 'name', v_name, 'reason', trim(p_reason),
                                               'given', coalesce(v_m.quantity_given, 0),
                                               'remaining', ceil(v_m.quantity)::integer - coalesce(v_m.quantity_given, 0),
                                               'requestId', v_m.id),
            '/app/visit?encounter=' || v_m.encounter_id, coalesce(v_m.prescriber_id, v_m.created_by), auth.uid());
  end if;
  perform after_pharmacy(v_m.encounter_id);
end
$$;

-- return_medicine (from 20261202090000_security_hardening): the quantity of the hand-over taken back.
create or replace function return_medicine(p_medication_request_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_d medication_dispense%rowtype;
  v_inv invoice%rowtype;
  v_mv record;
  v_back integer := 0;
  v_patient numeric := 0;
  v_insurer numeric := 0;
  v_total numeric := 0;
  v_lines jsonb;
  v_cn uuid;
  v_year integer := extract(year from now())::integer;
  v_balance numeric;
  v_name text;
  v_item text;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the medicine comes back' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_medication_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  select * into v_d from medication_dispense
  where medication_request_id = v_m.id and deleted_at is null order by created_at desc limit 1;
  if not found then
    raise exception 'this medicine was not handed over by the pharmacy' using errcode = 'P0002';
  end if;
  if not is_manager()
     and (v_d.created_at at time zone 'Africa/Kigali')::date <> (now() at time zone 'Africa/Kigali')::date then
    raise exception 'a hand-over of another day is undone by the manager' using errcode = '42501';
  end if;
  select * into v_inv from invoice where encounter_id = v_m.encounter_id;
  -- On a posted bill the return is money (a credit note, a smaller insurer claim): the person's
  -- own right, which a department or cover never gives.
  if v_inv.id is not null and v_inv.status <> 'draft'
     and not (is_manager() or staff_perm(auth.uid(), 'stock.dispense') or has_perm('billing.write')) then
    raise exception 'a medicine on a posted bill is taken back by the pharmacist or the manager'
      using errcode = '42501';
  end if;
  -- the units go back where they came from
  for v_mv in
    select item_id, batch_id, from_location_id, quantity from stock_movement
    where dispense_id = v_d.id and type = 'dispense' and deleted_at is null
  loop
    insert into stock_movement (item_id, batch_id, to_location_id, quantity, type, reason, dispense_id, medication_request_id)
    values (v_mv.item_id, v_mv.batch_id, v_mv.from_location_id, v_mv.quantity, 'return', trim(p_reason), v_d.id, v_m.id);
    v_back := v_back + v_mv.quantity;
  end loop;
  update medication_dispense set deleted_at = now() where id = v_d.id;

  if v_inv.id is null or v_inv.status = 'draft' then
    -- the bill is still open: the line leaves it, and the medicine waits at the pharmacy again
    update invoice_line set deleted_at = now(),
           manual_reason = coalesce(manual_reason || ' · ', '') || 'returned: ' || trim(p_reason)
    where source_type = 'medication_dispense' and source_id = v_d.id and deleted_at is null;
    if v_inv.id is not null then
      perform recompute_invoice(v_inv.id);
    end if;
    update medication_request
    set given_at = null, given_by = null, quantity_given = greatest(0, coalesce(quantity_given, 0) - v_d.quantity)
    where id = v_m.id;
    if exists (select 1 from encounter where id = v_m.encounter_id and status = 'open')
       and not exists (select 1 from queue_entry where encounter_id = v_m.encounter_id and station = 'pharmacy'
                       and finished_at is null and deleted_at is null) then
      insert into queue_entry (encounter_id, station, ticket_no)
      values (v_m.encounter_id, 'pharmacy',
              (select ticket_no from queue_entry where encounter_id = v_m.encounter_id order by created_at limit 1));
    end if;
    v_balance := case when v_inv.id is not null then invoice_balance(v_inv.id) else 0 end;
    if v_balance < 0 then
      -- the bill was already paid: money to give back, the cashier is told
      select p.surname || ' ' || p.given_names into v_name
      from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
      select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
      insert into notification (kind, params, link, recipient_stations, created_by)
      values ('refund_due', jsonb_build_object('name', v_name, 'item', v_item, 'amount', -v_balance,
                                               'reason', trim(p_reason)),
              '/app/visit?encounter=' || v_m.encounter_id, array['cashier'::station], auth.uid());
    end if;
    return jsonb_build_object('units', v_back, 'mode', 'bill', 'creditNoteId', null, 'credit', 0,
                              'balance', v_balance);
  end if;

  -- The bill is posted: its lines never change. A credit note gives the line back: the patient's
  -- share lowers what they owe (or is money to give back at the cashier); the insurer's share
  -- leaves an open claim.
  select coalesce(sum(l.patient_share), 0), coalesce(sum(l.insurer_share), 0),
         coalesce(sum(round(l.unit_price * l.quantity)), 0),
         coalesce(jsonb_agg(jsonb_build_object('lineId', l.id, 'description', l.description, 'quantity', l.quantity,
                                               'unitPrice', l.unit_price, 'patientShare', l.patient_share,
                                               'insurerShare', l.insurer_share)), '[]'::jsonb)
  into v_patient, v_insurer, v_total, v_lines
  from invoice_line l
  where l.invoice_id = v_inv.id and l.source_type = 'medication_dispense' and l.source_id = v_d.id
    and l.deleted_at is null;
  if v_total > 0 then
    insert into credit_note (invoice_id, number, lines, total, reason, approver_id, patient_amount, insurer_amount,
                             source_type, source_id)
    values (v_inv.id, 'CN-' || v_year || '-' || lpad(next_number('credit_note', v_year)::text, 6, '0'),
            v_lines, v_total, 'returned: ' || trim(p_reason), auth.uid(), v_patient, v_insurer,
            'medication_dispense', v_d.id)
    returning id into v_cn;
    if v_insurer > 0 then
      update claim set amount = greatest(0, amount - v_insurer)
      where invoice_id = v_inv.id and status = 'open' and batch_id is null;
    end if;
  end if;
  -- the line is done: returned (it does not wait at the pharmacy again)
  update medication_request
  set given_at = null, given_by = null, quantity_given = greatest(0, coalesce(quantity_given, 0) - v_d.quantity),
      not_given_at = now(), not_given_by = auth.uid(),
      not_given_reason = 'returned: ' || trim(p_reason)
  where id = v_m.id;
  v_balance := invoice_balance(v_inv.id);
  if v_balance < 0 then
    -- money to give back: the cashier is told
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
    select i.name_generic || coalesce(' ' || i.strength, '') into v_item from item i where i.id = v_m.item_id;
    insert into notification (kind, params, link, recipient_stations, created_by)
    values ('refund_due', jsonb_build_object('name', v_name, 'item', v_item, 'amount', -v_balance,
                                             'reason', trim(p_reason)),
            '/app/visit?encounter=' || v_m.encounter_id, array['cashier'::station], auth.uid());
  end if;
  return jsonb_build_object('units', v_back, 'mode', 'credit', 'creditNoteId', v_cn, 'credit', v_patient,
                            'balance', v_balance);
end
$$;

-- pharmacy_queue (from 20261126090000_departments_decide_desks): quantity, given, remaining; priced on what remains.
create or replace function pharmacy_queue(p_location_id uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_loc uuid;
  v_stores jsonb;
  v_lines jsonb;
  v_patients jsonb;
begin
  -- the pharmacy and the manager only: the list carries allergies, prescriptions and bill amounts
  if not (may_use_desk('pharmacy') or is_manager()) then
    return jsonb_build_object('locationId', null, 'stores', '[]'::jsonb, 'lines', '[]'::jsonb, 'patients', '[]'::jsonb);
  end if;
  if p_location_id is not null then
    if not exists (select 1 from stock_location where id = p_location_id and type = 'pharmacy'
                   and active and deleted_at is null) then
      raise exception 'choose an open pharmacy store' using errcode = '22023';
    end if;
    v_loc := p_location_id;
  else
    v_loc := main_pharmacy();
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'isMain', l.id = main_pharmacy())
                            order by (l.id = main_pharmacy()) desc, l.created_at), '[]'::jsonb)
  into v_stores
  from stock_location l where l.type = 'pharmacy' and l.active and l.deleted_at is null;

  with lines as (
    select m.id, m.encounter_id, m.created_at, p.id as patient_id,
           p.surname || ' ' || p.given_names as patient, p.file_number, p.sex, p.birth_date, p.allergies,
           (select q.ticket_no from queue_entry q where q.encounter_id = m.encounter_id order by q.created_at limit 1) as ticket,
           m.item_id, i.name_generic || coalesce(' ' || i.strength, '') as item, i.selling_unit,
           i.prescribing_rule, m.quantity, m.quantity_given, m.dose, m.frequency, m.duration_days, m.instructions,
           pr.id as prescriber_id, pr.full_name as prescriber, pr.specialty,
           py.name as payer, cp.price as cash_price, pp.price as payer_price, pp.fallback,
           cov.pct,
           round(round(pp.price) * greatest(m.quantity - m.quantity_given, 0)) as line_total,
           doctor_holds(m.encounter_id) as holds
    from medication_request m
    join encounter e on e.id = m.encounter_id and e.status = 'open'
    join patient p on p.id = e.patient_id
    join item i on i.id = m.item_id
    left join invoice inv on inv.encounter_id = e.id
    left join payer py on py.id = inv.payer_id
    left join profiles pr on pr.id = coalesce(m.prescriber_id, m.created_by)
    left join lateral (select pf.price from price_for(null, m.item_id, null) pf) cp on true
    left join lateral (select pf.price, pf.fallback from price_for(null, m.item_id, inv.payer_id) pf) pp on true
    left join lateral (select coalesce(coverage_pct_for((select c.plan_id from coverage c where c.id = inv.coverage_id),
                                                        'pharmacy'::service_group), 0) as pct) cov on true
    where rx_pending(m)
  ), priced as (
    select l.*, round(coalesce(l.line_total, 0) * l.pct / 100) as insurer_share
    from lines l
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'requestId', x.id, 'encounterId', x.encounter_id, 'patientId', x.patient_id, 'patient', x.patient,
      'file', x.file_number, 'ticket', x.ticket,
      'itemId', x.item_id, 'item', x.item, 'unit', x.selling_unit,
      'quantity', x.quantity, 'given', x.quantity_given,
      'remaining', ceil(x.quantity)::integer - x.quantity_given, 'dose', x.dose, 'frequency', x.frequency, 'days', x.duration_days,
      'instructions', x.instructions, 'prescriber', x.prescriber, 'prescriberId', x.prescriber_id, 'at', x.created_at,
      -- the cash price (as before) and what the bill will say
      'price', x.cash_price, 'cashPrice', x.cash_price, 'payerPrice', x.payer_price,
      'priced', x.payer_price is not null, 'payer', x.payer, 'coveragePct', x.pct,
      'lineTotal', coalesce(x.line_total, 0), 'insurerShare', x.insurer_share,
      'patientShare', coalesce(x.line_total, 0) - x.insurer_share,
      -- the stock of the store chosen at the desk
      'locationId', v_loc, 'pharmacyLocationId', v_loc,
      'onHandPharmacy', case when v_loc is null then 0 else usable_stock(x.item_id, v_loc) end,
      'expiredInPharmacy', (select coalesce(sum(s.quantity), 0)::integer from stock_on_hand s
                            where s.item_id = x.item_id and s.location_id = v_loc and s.quantity > 0
                              and s.expiry < current_date),
      'onHandElsewhere', (select coalesce(sum(s.quantity), 0)::integer from stock_on_hand s
                          join stock_location l on l.id = s.location_id
                          where s.item_id = x.item_id and l.id is distinct from v_loc and l.active and l.deleted_at is null
                            and s.quantity > 0 and (s.expiry is null or s.expiry >= current_date)),
      'doctorHolds', x.holds,
      -- the pharmacist's check
      'sex', x.sex, 'birthDate', x.birth_date,
      'ageYears', case when x.birth_date is not null then extract(year from age(current_date, x.birth_date))::integer end,
      'allergies', x.allergies,
      'prescribingRule', x.prescribing_rule, 'prescriberSpecialty', x.specialty,
      'ruleOk', rx_rule_ok(x.prescribing_rule, x.specialty)
    ) order by x.created_at), '[]'::jsonb)
  into v_lines
  from priced x;

  with lines as (
    select m.encounter_id, min(m.created_at) as first_at, count(*)::integer as n,
           sum(round(round(coalesce(pp.price, 0)) * greatest(m.quantity - m.quantity_given, 0))) as total,
           sum(round(round(round(coalesce(pp.price, 0)) * greatest(m.quantity - m.quantity_given, 0)) * cov.pct / 100)) as insurer
    from medication_request m
    join encounter e on e.id = m.encounter_id and e.status = 'open'
    left join invoice inv on inv.encounter_id = e.id
    left join lateral (select pf.price from price_for(null, m.item_id, inv.payer_id) pf) pp on true
    left join lateral (select coalesce(coverage_pct_for((select c.plan_id from coverage c where c.id = inv.coverage_id),
                                                        'pharmacy'::service_group), 0) as pct) cov on true
    where rx_pending(m)
    group by m.encounter_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'encounterId', l.encounter_id, 'patientId', p.id, 'patient', p.surname || ' ' || p.given_names,
      'file', p.file_number,
      'ticket', (select q.ticket_no from queue_entry q where q.encounter_id = l.encounter_id order by q.created_at limit 1),
      'sex', p.sex, 'birthDate', p.birth_date,
      'ageYears', case when p.birth_date is not null then extract(year from age(current_date, p.birth_date))::integer end,
      'ageMonths', case when p.birth_date is not null
                        then (extract(year from age(current_date, p.birth_date)) * 12
                              + extract(month from age(current_date, p.birth_date)))::integer end,
      'allergies', p.allergies, 'payer', py.name,
      'lines', l.n, 'total', l.total, 'insurerShare', l.insurer, 'patientShare', l.total - l.insurer,
      'balance', invoice_balance(inv.id),
      'doctorHolds', doctor_holds(l.encounter_id)
    ) order by l.first_at), '[]'::jsonb)
  into v_patients
  from lines l
  join encounter e on e.id = l.encounter_id
  join patient p on p.id = e.patient_id
  left join invoice inv on inv.encounter_id = e.id
  left join payer py on py.id = inv.payer_id;

  return jsonb_build_object('locationId', v_loc, 'stores', v_stores, 'lines', v_lines, 'patients', v_patients);
end
$$;

-- ---------------------------------------------------------------- C  the pharmacist takes walk-in payments
-- take_counter_payment (from 20261124090000_stores_and_stock): also the pharmacist (role) or the pharmacy desk, for counter sales; taken at the pharmacy, no notice to it.
create or replace function take_counter_payment(
  p_sale_id uuid, p_method payment_method, p_reference text default null, p_payer_phone text default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_s counter_sale%rowtype;
  v_year integer := extract(year from now())::integer;
  v_pay uuid;
  v_receipt text;
  v_short text;
begin
  if not (has_perm('payment.take') or pharmacy_takes_money()) then
    raise exception 'you may not take payments (the manager has not allowed it)' using errcode = '42501';
  end if;
  select * into v_s from counter_sale where id = p_sale_id and deleted_at is null for update;
  if not found then
    raise exception 'sale not found' using errcode = 'P0002';
  end if;
  if v_s.status = 'cancelled' then
    raise exception 'this sale was cancelled' using errcode = 'P0002';
  end if;
  if v_s.status <> 'open' then
    raise exception 'this sale is already paid' using errcode = '23505';
  end if;
  if p_method not in ('cash', 'momo', 'airtel', 'card', 'bank') then
    raise exception 'a counter sale is paid in cash, mobile money, card or bank' using errcode = '22023';
  end if;
  if p_method in ('momo', 'airtel', 'card', 'bank') and nullif(trim(coalesce(p_reference, '')), '') is null then
    raise exception 'a transaction reference is required for %', p_method using errcode = '22023';
  end if;
  -- no money for medicines no longer on the shelf
  select string_agg(item_label(l.item_id), ', ') into v_short
  from counter_sale_line l
  where l.sale_id = v_s.id and l.deleted_at is null and usable_stock(l.item_id, v_s.location_id) < l.quantity;
  if v_short is not null then
    raise exception 'no longer enough in the pharmacy: %', v_short using errcode = '23514', hint = 'short';
  end if;
  if v_s.total > 0 then
    insert into payment (invoice_id, counter_sale_id, method, amount, reference, payer_phone, receipt_no)
    values (null, v_s.id, p_method, v_s.total, nullif(trim(coalesce(p_reference, '')), ''),
            nullif(trim(coalesce(p_payer_phone, '')), ''),
            'RCT-' || v_year || '-' || lpad(next_number('receipt', v_year)::text, 6, '0'))
    returning id, receipt_no into v_pay, v_receipt;
  end if;
  -- the units are the buyer's from now on: they leave the shelf's balance at once, so a hand-over,
  -- another sale or a transfer note cannot take them before the buyer collects
  perform counter_sale_take(v_s.id);
  update counter_sale set status = 'paid', paid_at = now(), payment_id = v_pay where id = v_s.id;
  if not pharmacy_takes_money() then
  insert into notification (kind, params, link, recipient_stations, created_by)
  values ('counter_sale_paid', jsonb_build_object('number', v_s.number, 'amount', v_s.total, 'buyer', v_s.buyer_name,
                                                  'saleId', v_s.id),
          '/app/stock?tab=pharmacy&sale=' || v_s.id, array['pharmacy'::station], auth.uid());
  end if;
  return jsonb_build_object('id', v_s.id, 'number', v_s.number, 'status', 'paid', 'amount', v_s.total,
                            'receipt', v_receipt, 'paymentId', v_pay);
end
$$;

-- close_cash_day (from 20261128090000_switches_enforced): the pharmacist counts the walk-in payments they took.
create or replace function close_cash_day(p_day date, p_counted jsonb, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_day date := coalesce(p_day, (now() at time zone 'Africa/Kigali')::date);
  v_expected jsonb;
  v_counted jsonb := '{}'::jsonb;
  v_variance numeric;
  v_id uuid;
  v_key text;
  v_val text;
begin
  if not (is_manager() or has_perm('payment.take') or pharmacy_takes_money()
          or exists (select 1 from payment where cashier_id = auth.uid() and deleted_at is null
                     and (paid_at at time zone 'Africa/Kigali')::date = v_day)
          or exists (select 1 from refund where cashier_id = auth.uid() and deleted_at is null
                     and (refunded_at at time zone 'Africa/Kigali')::date = v_day)) then
    raise exception 'you may not take payments (the manager has not allowed it)' using errcode = '42501', hint = 'not_permitted';
  end if;
  select coalesce(jsonb_object_agg(n.method, n.amount), '{}'::jsonb) into v_expected
  from (select m.method, sum(m.amount) as amount from (
          select method::text as method, amount from payment
          where deleted_at is null and cashier_id = auth.uid() and (paid_at at time zone 'Africa/Kigali')::date = v_day
          union all
          select method::text, -amount from refund
          where deleted_at is null and cashier_id = auth.uid() and (refunded_at at time zone 'Africa/Kigali')::date = v_day
        ) m group by m.method) n;
  for v_key, v_val in select key, value from jsonb_each_text(coalesce(p_counted, '{}'::jsonb)) loop
    if v_key in ('cash', 'momo', 'airtel', 'card', 'bank') and v_val ~ '^[0-9]+$' then
      v_counted := v_counted || jsonb_build_object(v_key, v_val::numeric);
    end if;
  end loop;
  v_variance := coalesce((select sum(value::numeric) from jsonb_each_text(v_counted)), 0)
              - coalesce((select sum(value::numeric) from jsonb_each_text(v_expected)), 0);
  insert into day_close (date, cashier_id, expected, counted, variance, note)
  values (v_day, auth.uid(), v_expected, v_counted, v_variance, nullif(trim(coalesce(p_note, '')), ''))
  on conflict (date, cashier_id) do update
  set expected = excluded.expected, counted = excluded.counted, variance = excluded.variance,
      note = excluded.note, updated_at = now()
  returning id into v_id;
  update payment set day_close_id = v_id
  where deleted_at is null and cashier_id = auth.uid() and (paid_at at time zone 'Africa/Kigali')::date = v_day;
  return jsonb_build_object('id', v_id, 'expected', v_expected, 'counted', v_counted, 'variance', v_variance);
end
$$;

-- cashier_summary (from 20261128090000_switches_enforced): the pharmacist sees their own payments and cash count, and the walk-in sales waiting to be paid.
create or replace function cashier_summary(p_day date default null, p_from date default null, p_to date default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, p_day, v_today);
  v_to date := coalesce(p_to, p_day, p_from, v_today);
  v_day date;
  v_len integer;
  v_me uuid := auth.uid();
  v_all boolean := has_perm('billing.read');
  v_take boolean := has_perm('payment.take');
  v_pharm boolean := pharmacy_takes_money();
begin
  if not (v_all or v_take or v_pharm
          or exists (select 1 from payment where cashier_id = v_me and deleted_at is null and day_close_id is null)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_to < v_from then
    select v_to, v_from into v_from, v_to;
  end if;
  v_day := coalesce(p_day, v_to);
  v_len := v_to - v_from + 1;
  return jsonb_build_object(
    'day', v_day,
    'from', v_from,
    'to', v_to,
    'scope', case when v_all then 'desk' else 'mine' end,
    'total', (select coalesce(sum(amount), 0) from payment
              where deleted_at is null and (v_all or cashier_id = v_me)
                and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'count', (select count(*) from payment
              where deleted_at is null and (v_all or cashier_id = v_me)
                and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'previousTotal', (select coalesce(sum(amount), 0) from payment
                      where deleted_at is null and (v_all or cashier_id = v_me)
                        and (paid_at at time zone 'Africa/Kigali')::date between v_from - v_len and v_from - 1
                        and (v_to <> v_today or paid_at <= now() - make_interval(days => v_len))),
    'served', case when v_all then
                (select count(distinct q.encounter_id) from queue_entry q
                 where q.deleted_at is null and q.station = 'cashier' and q.finished_at is not null
                   and (q.finished_at at time zone 'Africa/Kigali')::date between v_from and v_to)
              else
                (select count(distinct coalesce(i.encounter_id, pa.counter_sale_id)) from payment pa
                 left join invoice i on i.id = pa.invoice_id
                 where pa.deleted_at is null and pa.cashier_id = v_me
                   and (pa.paid_at at time zone 'Africa/Kigali')::date between v_from and v_to)
              end,
    'refunded', (select coalesce(sum(amount), 0) from refund
                 where deleted_at is null and (v_all or cashier_id = v_me)
                   and (refunded_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'refunds', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select r.refunded_at as at, jsonb_build_object(
            'id', r.id, 'at', r.refunded_at, 'method', r.method, 'amount', r.amount, 'reference', r.reference,
            'reason', r.reason, 'patient', p.surname || ' ' || p.given_names,
            'cashier', (select full_name from profiles where id = r.cashier_id), 'mine', r.cashier_id = v_me
          ) as j
        from refund r
        join invoice i on i.id = r.invoice_id
        join encounter e on e.id = i.encounter_id
        join patient p on p.id = e.patient_id
        where r.deleted_at is null and (v_all or r.cashier_id = v_me)
          and (r.refunded_at at time zone 'Africa/Kigali')::date between v_from and v_to
        order by r.refunded_at desc limit 500) x
    ), '[]'::jsonb),
    'debts', case when v_all or v_take then
               (select count(*) from invoice i join encounter e on e.id = i.encounter_id
                where i.deleted_at is null and e.status <> 'open' and invoice_balance(i.id) > 0)
             else 0 end,
    'debtsDue', case when v_all or v_take then
                  (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id
                   where i.deleted_at is null and e.status <> 'open' and invoice_balance(i.id) > 0)
                else 0 end,
    'mine', (select coalesce(sum(amount), 0) from payment
             where deleted_at is null and cashier_id = v_me
               and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to),
    'byMethod', coalesce((
      select jsonb_agg(jsonb_build_object('method', m.method, 'amount', m.amount, 'count', m.n) order by m.amount desc)
      from (select method::text as method, sum(amount) as amount, count(*) as n from payment
            where deleted_at is null and (v_all or cashier_id = v_me)
              and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to
            group by method) m
    ), '[]'::jsonb),
    'byCashier', coalesce((
      select jsonb_agg(jsonb_build_object('name', c.name, 'amount', c.amount, 'count', c.n) order by c.amount desc)
      from (select coalesce(pr.full_name, '—') as name, sum(pa.amount) as amount, count(*) as n
            from payment pa left join profiles pr on pr.id = pa.cashier_id
            where pa.deleted_at is null and (v_all or pa.cashier_id = v_me)
              and (pa.paid_at at time zone 'Africa/Kigali')::date between v_from and v_to
            group by pr.full_name) c
    ), '[]'::jsonb),
    -- the payments of the period: visits' bills and counter sales
    'payments', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select pa.paid_at as at, jsonb_build_object(
            'id', pa.id, 'at', pa.paid_at, 'method', pa.method, 'amount', pa.amount, 'reference', pa.reference,
            'invoice', i.number, 'encounterId', i.encounter_id,
            'patient', coalesce(p.surname || ' ' || p.given_names, cs.buyer_name),
            'fileNumber', p.file_number,
            'counterSaleId', cs.id, 'counterSale', cs.number,
            'cashier', pr.full_name, 'receipt', pa.receipt_no,
            'mine', pa.cashier_id = v_me, 'counted', pa.day_close_id is not null
          ) as j
        from payment pa
        left join invoice i on i.id = pa.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient p on p.id = e.patient_id
        left join counter_sale cs on cs.id = pa.counter_sale_id
        left join profiles pr on pr.id = pa.cashier_id
        where pa.deleted_at is null and (v_all or pa.cashier_id = v_me)
          and (pa.paid_at at time zone 'Africa/Kigali')::date between v_from and v_to
        order by pa.paid_at desc limit 500) x
    ), '[]'::jsonb),
    'voided', coalesce((
      select jsonb_agg(x.j order by x.at desc) from (
        select pa.voided_at as at, jsonb_build_object(
            'id', pa.id, 'at', pa.paid_at, 'method', pa.method, 'amount', pa.amount, 'receipt', pa.receipt_no,
            'patient', coalesce(p.surname || ' ' || p.given_names, cs.buyer_name),
            'counterSale', cs.number, 'reason', pa.void_reason,
            'by', (select full_name from profiles where id = pa.voided_by), 'voidedAt', pa.voided_at
          ) as j
        from payment pa
        left join invoice i on i.id = pa.invoice_id
        left join encounter e on e.id = i.encounter_id
        left join patient p on p.id = e.patient_id
        left join counter_sale cs on cs.id = pa.counter_sale_id
        where pa.deleted_at is not null and pa.voided_at is not null and (v_all or pa.cashier_id = v_me)
          and (pa.paid_at at time zone 'Africa/Kigali')::date between v_from and v_to
        order by pa.voided_at desc limit 500) x
    ), '[]'::jsonb),
    'closes', coalesce((
      select jsonb_agg(jsonb_build_object(
          'cashier', pr.full_name, 'mine', d.cashier_id = v_me, 'expected', d.expected,
          'counted', d.counted, 'variance', d.variance, 'note', d.note, 'at', d.updated_at
        ) order by pr.full_name)
      from day_close d left join profiles pr on pr.id = d.cashier_id
      where d.deleted_at is null and d.date = v_day and (v_all or d.cashier_id = v_me)
    ), '[]'::jsonb),
    'myExpected', coalesce((
      select jsonb_object_agg(n.method, n.amount) from (select m.method, sum(m.amount) as amount from (
          select method::text as method, amount from payment
          where deleted_at is null and cashier_id = v_me and (paid_at at time zone 'Africa/Kigali')::date = v_day
          union all
          select method::text, -amount from refund
          where deleted_at is null and cashier_id = v_me and (refunded_at at time zone 'Africa/Kigali')::date = v_day
        ) m group by m.method) n
    ), '{}'::jsonb),
    'openBills', case when v_all or v_take then
                   (select count(*) from invoice i join encounter e on e.id = i.encounter_id
                    where i.deleted_at is null and i.status = 'draft' and e.status = 'open' and invoice_balance(i.id) > 0)
                 else 0 end,
    'openDue', case when v_all or v_take then
                 (select coalesce(sum(invoice_balance(i.id)), 0) from invoice i join encounter e on e.id = i.encounter_id
                  where i.deleted_at is null and i.status = 'draft' and e.status = 'open' and invoice_balance(i.id) > 0)
               else 0 end,
    -- counter sales (walk-in buyers): paid in the period, and those waiting to pay now
    'counterSales', jsonb_build_object(
      'count', (select count(*) from payment where deleted_at is null and counter_sale_id is not null
                and (v_all or cashier_id = v_me)
                and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to),
      'total', (select coalesce(sum(amount), 0) from payment where deleted_at is null and counter_sale_id is not null
                and (v_all or cashier_id = v_me)
                and (paid_at at time zone 'Africa/Kigali')::date between v_from and v_to)),
    'counterToPay', case when v_all or v_take or v_pharm then coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', s.id, 'number', s.number, 'buyer', s.buyer_name, 'phone', s.buyer_phone, 'total', s.total,
          'at', s.created_at, 'by', (select full_name from profiles where id = s.created_by),
          'lines', (select count(*) from counter_sale_line x where x.sale_id = s.id and x.deleted_at is null)
        ) order by s.created_at)
      from counter_sale s where s.deleted_at is null and s.status = 'open'
    ), '[]'::jsonb) else '[]'::jsonb end
  );
end
$$;

-- ---------------------------------------------------------------- E  write-offs run the alerts
-- adjust_stock (from 20261128090000_switches_enforced): a count or a write-off runs the stock alerts.
create or replace function adjust_stock(p_item_id uuid, p_location_id uuid, p_counted integer, p_reason text)
returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_on_hand integer;
  v_diff integer;
  v_remaining integer;
  v_row record;
  v_take integer;
  v_batch uuid;
  v_l stock_location%rowtype;
begin
  v_l := assert_store_work(p_location_id);
  if p_counted is null or p_counted < 0 then
    raise exception 'the count must be zero or more' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the count changes' using errcode = '22023';
  end if;
  perform lock_stock(p_item_id, p_location_id);
  select coalesce(sum(quantity), 0)::integer into v_on_hand
  from stock_on_hand where item_id = p_item_id and location_id = p_location_id;
  v_diff := p_counted - v_on_hand;
  -- a room store is supplied only by the pharmacy's transfer notes: its holders do not count it up
  if is_room_type(v_l.type) and v_diff > 0 and not stock_manager() then
    raise exception 'more on the shelf than the system says: ask the pharmacy to send it with a transfer note'
      using errcode = '22023', hint = 'use_transfer_note';
  end if;
  if v_diff < 0 then
    v_remaining := -v_diff;
    for v_row in
      select s.batch_id, s.quantity from stock_on_hand s
      where s.item_id = p_item_id and s.location_id = p_location_id and s.quantity > 0
      order by s.expiry asc nulls last
    loop
      exit when v_remaining <= 0;
      v_take := least(v_row.quantity, v_remaining);
      insert into stock_movement (item_id, batch_id, from_location_id, quantity, type, reason)
      values (p_item_id, v_row.batch_id, p_location_id, v_take, 'adjustment', 'count: ' || trim(p_reason));
      v_remaining := v_remaining - v_take;
    end loop;
    if is_room_type(v_l.type) then
      perform notify_room_loss(p_item_id, v_l, -v_diff, 'count: ' || trim(p_reason));
    end if;
  elsif v_diff > 0 then
    -- more on the shelf: the latest batch this store has held, else the medicine's latest batch
    select b.id into v_batch from batch b
    where b.item_id = p_item_id and b.deleted_at is null
    order by exists (select 1 from stock_movement m where m.batch_id = b.id and m.to_location_id = p_location_id
                     and m.deleted_at is null) desc,
             b.received_on desc
    limit 1;
    if v_batch is null then
      raise exception 'no batch of this item yet: receive it instead' using errcode = 'P0002';
    end if;
    insert into stock_movement (item_id, batch_id, to_location_id, quantity, type, reason)
    values (p_item_id, v_batch, p_location_id, v_diff, 'adjustment', 'count: ' || trim(p_reason));
  end if;
  perform stock_alert_run();
  return v_diff;
end
$$;

-- ---------------------------------------------------------------- G  the expiry window
-- stock_overview (from 20261124090000_stores_and_stock): expiring within stock.expiry_days; the item kind.
create or replace function stock_overview()
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_admin boolean := stock_admin();
  v_vis uuid[] := visible_stores();
  v_main uuid := main_pharmacy();
  v_transit uuid := (select id from stock_location where type::text = 'transit' and deleted_at is null limit 1);
  v_locations jsonb;
  v_days integer := stock_expiry_days();
  v_items jsonb;
begin
  if not (v_admin or has_perm('stock.read') or cardinality(v_vis) > 0) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', l.id, 'name', l.name, 'type', l.type, 'department', d.name, 'active', l.active,
      'isMain', l.id = v_main, 'isRoom', is_room_type(l.type), 'held', holds_store(auth.uid(), l.id),
      'holders', store_holders(l.id)
    ) order by l.active desc, l.type, l.name), '[]'::jsonb)
  into v_locations
  from stock_location l left join department d on d.id = l.department_id
  where l.deleted_at is null and l.type::text <> 'transit' and (v_vis is null or l.id = any (v_vis));

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', i.id, 'code', i.code, 'name', i.name_generic, 'strength', i.strength, 'unit', i.selling_unit,
      'packSize', i.pack_size,
      'sellingPrice', (select pf.price from price_for(null, i.id, null) pf),
      'reorderLevel', i.reorder_level, 'maxLevel', i.max_level,
      'onHand', coalesce(t.on_hand, 0),
      'usable', coalesce(t.usable, 0),
      'costValue', case when v_admin then coalesce(t.cost_value, 0) end,
      'avgCost', case when v_admin and coalesce(t.on_hand, 0) > 0 then round(t.cost_value / t.on_hand, 2) end,
      'byLocation', coalesce(t.by_location, '{}'::jsonb),
      'byLocationUsable', coalesce(t.by_location_usable, '{}'::jsonb),
      'earliestExpiry', t.earliest_expiry,
      'nextExpiry', t.next_expiry,
      'expiredUnits', coalesce(t.expired, 0),
      'expiringUnits', coalesce(t.expiring, 0),
      'inTransit', case when v_admin then coalesce(t.in_transit, 0) end,
      'pharmacyUsable', case when v_admin then coalesce(t.pharmacy_usable, 0) end,
      'low', i.reorder_level > 0 and coalesce(t.pharmacy_usable, 0) <= i.reorder_level,
      'active', i.active, 'kind', i.kind
    ) order by i.name_generic), '[]'::jsonb)
  into v_items
  from item i
  left join lateral (
    select sum(s.quantity)::integer as on_hand,
           sum(s.quantity) filter (where s.expiry is null or s.expiry >= current_date)::integer as usable,
           sum(s.quantity * coalesce(b.unit_cost, 0)) as cost_value,
           min(s.expiry) filter (where s.quantity > 0) as earliest_expiry,
           min(s.expiry) filter (where s.quantity > 0 and s.expiry >= current_date) as next_expiry,
           sum(s.quantity) filter (where s.quantity > 0 and s.expiry < current_date)::integer as expired,
           sum(s.quantity) filter (where s.quantity > 0 and s.expiry between current_date and current_date + v_days)::integer as expiring,
           (select jsonb_object_agg(x.location_id::text, x.q) from (
              select s2.location_id, sum(s2.quantity)::integer as q from stock_on_hand s2
              where s2.item_id = i.id and s2.location_id is distinct from v_transit
                and (v_vis is null or s2.location_id = any (v_vis))
              group by s2.location_id having sum(s2.quantity) <> 0) x) as by_location,
           (select jsonb_object_agg(x.location_id::text, x.q) from (
              select s2.location_id, sum(s2.quantity)::integer as q from stock_on_hand s2
              where s2.item_id = i.id and s2.location_id is distinct from v_transit
                and (v_vis is null or s2.location_id = any (v_vis))
                and (s2.expiry is null or s2.expiry >= current_date)
              group by s2.location_id having sum(s2.quantity) <> 0) x) as by_location_usable,
           (select coalesce(sum(s3.quantity), 0)::integer from stock_on_hand s3
             where s3.item_id = i.id and s3.location_id = v_transit) as in_transit,
           (select coalesce(sum(s4.quantity), 0)::integer from stock_on_hand s4
              join stock_location l4 on l4.id = s4.location_id
             where s4.item_id = i.id and l4.type = 'pharmacy' and l4.active and l4.deleted_at is null
               and s4.quantity > 0 and (s4.expiry is null or s4.expiry >= current_date)) as pharmacy_usable
    from stock_on_hand s left join batch b on b.id = s.batch_id
    where s.item_id = i.id and s.location_id is distinct from v_transit
      and (v_vis is null or s.location_id = any (v_vis))
  ) t on true
  where i.deleted_at is null;

  return jsonb_build_object('locations', v_locations, 'items', v_items, 'admin', v_admin, 'mainPharmacyId', v_main, 'expiryDays', v_days,
                            'transit', case when v_admin then jsonb_build_object(
                              'units', (select coalesce(sum(s.quantity), 0) from stock_on_hand s where s.location_id = v_transit),
                              'value', (select coalesce(sum(s.quantity * coalesce(b.unit_cost, 0)), 0) from stock_on_hand s
                                        left join batch b on b.id = s.batch_id where s.location_id = v_transit),
                              'notes', (select count(*) from stock_transfer where status = 'in_transit')) end);
end
$$;

-- stock_alerts (from 20261124090000_stores_and_stock): expiring within stock.expiry_days.
create or replace function stock_alerts()
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_admin boolean := stock_admin();
  v_vis uuid[] := visible_stores();
  v_days integer := stock_expiry_days();
begin
  return jsonb_build_object(
    'expiryDays', v_days,
    -- the pharmacy: unexpired units at or below the reorder level
    'low', case when v_admin then coalesce((
      select jsonb_agg(jsonb_build_object('itemId', r.item_id, 'item', item_label(r.item_id), 'code', r.code,
                                          'onHand', r.on_hand, 'level', r.reorder_level,
                                          'maxLevel', (select max_level from item where id = r.item_id))
                       order by r.on_hand::numeric / greatest(r.reorder_level, 1), r.name_generic)
      from items_below_reorder r), '[]'::jsonb) else '[]'::jsonb end,
    -- a room store below the minimum set for it
    'roomLow', coalesce((
      select jsonb_agg(jsonb_build_object('storeId', l.id, 'store', l.name, 'itemId', m.item_id, 'item', item_label(m.item_id),
                                          'onHand', usable_stock(m.item_id, l.id), 'min', m.min_level)
                       order by l.name)
      from store_item_level m join stock_location l on l.id = m.location_id and l.active and l.deleted_at is null
      where (v_vis is null or l.id = any (v_vis)) and usable_stock(m.item_id, l.id) < m.min_level), '[]'::jsonb),
    -- expiring within the window (stock.expiry_days) (not expired yet), batch by batch
    'expiring', coalesce((
      select jsonb_agg(jsonb_build_object('storeId', l.id, 'store', l.name, 'itemId', s.item_id, 'item', item_label(s.item_id),
                                          'batchNo', b.batch_no, 'expiry', s.expiry, 'quantity', s.quantity,
                                          'days', s.expiry - current_date)
                       order by s.expiry, l.name)
      from stock_on_hand s join stock_location l on l.id = s.location_id and l.deleted_at is null and l.type::text <> 'transit'
      left join batch b on b.id = s.batch_id
      where s.quantity > 0 and s.expiry between current_date and current_date + v_days
        and (v_vis is null or l.id = any (v_vis))), '[]'::jsonb),
    -- already expired: to write off (or send back to the pharmacy)
    'expired', coalesce((
      select jsonb_agg(jsonb_build_object('storeId', l.id, 'store', l.name, 'itemId', s.item_id, 'item', item_label(s.item_id),
                                          'batchNo', b.batch_no, 'expiry', s.expiry, 'quantity', s.quantity)
                       order by s.expiry, l.name)
      from stock_on_hand s join stock_location l on l.id = s.location_id and l.deleted_at is null and l.type::text <> 'transit'
      left join batch b on b.id = s.batch_id
      where s.quantity > 0 and s.expiry < current_date
        and (v_vis is null or l.id = any (v_vis))), '[]'::jsonb)
  );
end
$$;

-- my_stores (from 20261124090000_stores_and_stock): expiring within stock.expiry_days.
create or replace function my_stores()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', l.id, 'name', l.name, 'type', l.type, 'active', l.active,
      'personal', exists (select 1 from stock_location_holder h where h.location_id = l.id and h.deleted_at is null
                          and h.profile_id = auth.uid()),
      'departments', coalesce((select jsonb_agg(d.name order by d.name) from stock_location_holder h
                               join department d on d.id = h.department_id
                               join staff_department sd on sd.department_id = h.department_id and sd.profile_id = auth.uid()
                               where h.location_id = l.id and h.deleted_at is null), '[]'::jsonb),
      'items', (select count(distinct s.item_id) from stock_on_hand s where s.location_id = l.id and s.quantity > 0)::integer,
      'units', (select coalesce(sum(s.quantity), 0) from stock_on_hand s where s.location_id = l.id and s.quantity > 0)::integer,
      'expiredUnits', (select coalesce(sum(s.quantity), 0) from stock_on_hand s where s.location_id = l.id
                       and s.quantity > 0 and s.expiry < current_date)::integer,
      'expiringUnits', (select coalesce(sum(s.quantity), 0) from stock_on_hand s where s.location_id = l.id
                        and s.quantity > 0 and s.expiry between current_date and current_date + stock_expiry_days())::integer,
      'low', (select count(*) from store_item_level m where m.location_id = l.id
              and usable_stock(m.item_id, l.id) < m.min_level)::integer,
      'incoming', (select count(*) from stock_transfer t where t.to_location_id = l.id and t.status = 'in_transit')::integer,
      'returnsOnTheWay', (select count(*) from stock_transfer t where t.from_location_id = l.id
                          and t.direction = 'to_pharmacy' and t.status = 'in_transit')::integer,
      'openRequests', (select count(*) from store_request r where r.location_id = l.id and r.status = 'open')::integer
    ) order by l.name), '[]'::jsonb)
  from stock_location l
  where l.deleted_at is null and l.active and is_room_type(l.type) and holds_store(auth.uid(), l.id)
$$;

-- store_stock (from 20261128090000_switches_enforced): expiring within stock.expiry_days.
create or replace function store_stock(p_location_id uuid)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_l stock_location%rowtype;
  v_admin boolean := stock_admin();
  v_items jsonb;
  v_incoming jsonb;
begin
  select * into v_l from stock_location where id = p_location_id and deleted_at is null;
  if not found or v_l.type::text = 'transit' then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if not may_see_store(p_location_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'itemId', i.id, 'item', i.name_generic || coalesce(' ' || i.strength, ''), 'code', i.code,
      'unit', i.selling_unit, 'packSize', i.pack_size,
      'onHand', coalesce(t.on_hand, 0), 'usable', coalesce(t.usable, 0), 'expired', coalesce(t.expired, 0),
      'expiringSoon', coalesce(t.expiring, 0), 'earliestExpiry', t.next_expiry,
      'minLevel', m.min_level, 'low', m.min_level is not null and coalesce(t.usable, 0) < m.min_level,
      'price', (select pf.price from price_for(null, i.id, null) pf),
      'value', case when v_admin then coalesce(t.value, 0) end,
      'batches', coalesce(t.batches, '[]'::jsonb)
    ) order by i.name_generic), '[]'::jsonb)
  into v_items
  from item i
  left join store_item_level m on m.location_id = p_location_id and m.item_id = i.id
  left join lateral (
    select sum(s.quantity)::integer as on_hand,
           sum(s.quantity) filter (where s.expiry is null or s.expiry >= current_date)::integer as usable,
           sum(s.quantity) filter (where s.expiry < current_date)::integer as expired,
           sum(s.quantity) filter (where s.expiry between current_date and current_date + stock_expiry_days())::integer as expiring,
           min(s.expiry) filter (where s.expiry >= current_date) as next_expiry,
           sum(s.quantity * coalesce(b.unit_cost, 0)) as value,
           jsonb_agg(jsonb_build_object('batchId', s.batch_id, 'batchNo', b.batch_no, 'expiry', s.expiry,
                                        'quantity', s.quantity, 'expired', s.expiry < current_date,
                                        'unitCost', case when v_admin then b.unit_cost end)
                     order by s.expiry nulls last) as batches
    from stock_on_hand s left join batch b on b.id = s.batch_id
    where s.item_id = i.id and s.location_id = p_location_id and s.quantity > 0
  ) t on true
  where i.deleted_at is null and (t.on_hand is not null or m.min_level is not null);

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', t.id, 'number', t.number, 'direction', t.direction, 'sentAt', t.sent_at,
      'from', lf.name, 'to', lt.name,
      'lines', (select count(*) from stock_transfer_line x where x.transfer_id = t.id)::integer,
      'units', (select coalesce(sum(x.quantity), 0) from stock_transfer_line x where x.transfer_id = t.id)::integer
    ) order by t.sent_at), '[]'::jsonb)
  into v_incoming
  from stock_transfer t
  join stock_location lf on lf.id = t.from_location_id
  join stock_location lt on lt.id = t.to_location_id
  where t.status = 'in_transit' and (t.to_location_id = p_location_id or t.from_location_id = p_location_id);

  return jsonb_build_object(
    'store', jsonb_build_object('id', v_l.id, 'name', v_l.name, 'type', v_l.type, 'active', v_l.active,
                                'isMain', v_l.is_main, 'isRoom', is_room_type(v_l.type),
                                'holders', store_holders(v_l.id)),
    'held', holds_store(auth.uid(), v_l.id),
    -- count and write off: the holders (room store) or the pharmacy (pharmacy and main stores); the manager
    'canManage', is_manager() or case when is_room_type(v_l.type) then holds_store(auth.uid(), v_l.id)
                                       else stock_manager() end,
    'items', v_items,
    'onTheWay', v_incoming,
    'value', case when v_admin then (select coalesce(sum(s.quantity * coalesce(b.unit_cost, 0)), 0)
                                     from stock_on_hand s left join batch b on b.id = s.batch_id
                                     where s.location_id = p_location_id and s.quantity > 0) end
  );
end
$$;

-- save_setting (from 20261120090000_session_hours): the expiry window (stock.expiry_days, 1 to 365 days).
create or replace function save_setting(p_key text, p_value jsonb)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_hours numeric;
begin
  if not has_perm('settings.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_key not in ('clinic.profile', 'clinic.hours', 'clinic.features', 'patient.fields', 'security.lock', 'security.otp', 'security.session', 'flow', 'stock.expiry_days') then
    raise exception 'unknown setting %', p_key using errcode = '22023';
  end if;
  if p_key = 'security.session' then
    if not is_manager() then
      raise exception 'not allowed' using errcode = '42501';
    end if;
    if jsonb_typeof(p_value -> 'hours') is distinct from 'number' then
      raise exception 'hours must be a whole number between 1 and 12' using errcode = '22023';
    end if;
    v_hours := (p_value ->> 'hours')::numeric;
    if v_hours <> trunc(v_hours) or v_hours < 1 or v_hours > 12 then
      raise exception 'hours must be a whole number between 1 and 12' using errcode = '22023';
    end if;
  end if;
  if p_key = 'security.lock' then
    if jsonb_typeof(p_value -> 'idle_minutes') <> 'number'
       or (p_value ->> 'idle_minutes')::numeric < 1
       or (p_value ->> 'idle_minutes')::numeric > 480 then
      raise exception 'idle_minutes must be between 1 and 480' using errcode = '22023';
    end if;
  end if;
  if p_key = 'security.otp' then
    if jsonb_typeof(p_value -> 'trust_days') <> 'number'
       or (p_value ->> 'trust_days')::numeric < 0
       or (p_value ->> 'trust_days')::numeric > 90 then
      raise exception 'trust_days must be between 0 and 90' using errcode = '22023';
    end if;
  end if;
  if p_key = 'flow' and jsonb_typeof(p_value -> 'triage_first') <> 'boolean' then
    raise exception 'flow.triage_first must be true or false' using errcode = '22023';
  end if;
  if p_key = 'patient.fields' and jsonb_typeof(p_value) <> 'array' then
    raise exception 'patient.fields must be a list' using errcode = '22023';
  end if;
  if p_key = 'stock.expiry_days' then
    if jsonb_typeof(p_value) is distinct from 'number' then
      raise exception 'the expiry window is a whole number of days between 1 and 365' using errcode = '22023';
    end if;
    if (p_value #>> '{}')::numeric <> trunc((p_value #>> '{}')::numeric)
       or (p_value #>> '{}')::numeric < 1 or (p_value #>> '{}')::numeric > 365 then
      raise exception 'the expiry window is a whole number of days between 1 and 365' using errcode = '22023';
    end if;
  end if;
  insert into setting (key, value, changed_by, changed_at)
  values (p_key, p_value, auth.uid(), now())
  on conflict (key) do update set value = excluded.value, changed_by = auth.uid(), changed_at = now();
  insert into audit_event (actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'settings', 'setting', null, jsonb_build_object('key', p_key));
end
$$;

-- ---------------------------------------------------------------- grants
-- (functions replaced with the same arguments keep their grants)
revoke all on function add_stock(jsonb, uuid, text), dispense_prescription(uuid, uuid, integer), stock_alert_check(),
  stock_totals(uuid), message_manager(text), stock_expiry_days()
  from public, anon;
grant execute on function add_stock(jsonb, uuid, text), dispense_prescription(uuid, uuid, integer), stock_alert_check(),
  stock_totals(uuid), message_manager(text), stock_expiry_days()
  to authenticated;
-- internal: only the checked functions call them
revoke all on function pharmacy_takes_money(), set_cash_price(uuid, numeric),
  stock_notice(text, text, jsonb, text, boolean), stock_alert_run()
  from public, anon, authenticated;


-- ============================================================ 20261208090000_reference_list_versions.sql
-- 0098 · The official medicine list, versioned; the insurers that follow it price from it.
--
-- The body in charge (RHIA / RSSB) publishes every six months the list of reimbursable medicines:
-- code, generic name, presentation, prescribing rule, selling unit, price and group. Frank (owner):
--   * the manager uploads each new list (Prices → Official medicine list); the old ones are kept;
--   * the list's price is the INSURERS' TARIFF; the clinic's cash price stays its own (Prices);
--   * an insurer that follows the official list (RSSB RAMA, MMI, Mutuelle de Santé) prices the
--     medicines from it with no data entry, the day the clinic starts working with it.
--
--   * reference_list: one row per uploaded list (name, effective_from, uploaded_by / _at, rows,
--     status current | past). medicine_reference_entry: the rows, keyed (list_id, code). The 0077
--     rows become the list 'RHIA June 2026' (effective 2026-06-01, current).
--   * medicine_reference is now a VIEW of the list in effect today (same columns as the 0077
--     table, plus list_id): Add stock, upsert_item, receive_delivery and every reader keep working.
--   * reference_list_at(date): the list in effect on that date (the latest effective_from not after
--     it; the same date: the last uploaded).
--   * import_reference_list(name, effective, rows, dry_run default true): the manager (or whoever
--     holds catalogue.write). Validates every row (code and generic name required, price a number
--     zero or more or empty, a code once); the preview compares with the current list: new,
--     changed prices [{code, generic, old, new}], removed [{code, generic}], unchanged, errors
--     [{row, code, message}]. dry_run false keeps the valid rows as the new current list from
--     the date (the previous one becomes past, kept), and flags the clinic's medicines whose code
--     left the list (item.reference_removed_at; cleared when a code comes back).
--   * reference_lists(): the lists for the Prices page (current first).
--   * payer.follows_reference_list (true for rssb_rama, mmi, cbhi, also when such an insurer is
--     added). price_for(service, item, payer, at): for such a payer without its own price for the
--     ITEM, the price of the item's code on the list in effect on that date, before the cash price.
--     Services unchanged; coverage % applies on that price as before.
--   * add_stock: a medicine picked from the list (new_item.code) is created with the list's code,
--     prescribing rule and group (it was given a MED- code before, which lost the link).
--
-- Errcodes: 42501 not allowed, 22023 bad input, P0002 not found.

-- ---------------------------------------------------------------- the lists
create table if not exists reference_list (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  effective_from date not null,
  uploaded_by uuid references profiles (id),
  uploaded_at timestamptz not null default now(),
  rows integer not null default 0,
  status text not null default 'current' check (status in ('current', 'past'))
);
create unique index if not exists reference_list_one_current on reference_list (status) where status = 'current';
alter table reference_list enable row level security;
drop policy if exists reference_list_read on reference_list;
create policy reference_list_read on reference_list for select to authenticated using (true);
revoke all on reference_list from anon, authenticated;
grant select on reference_list to authenticated;

-- the 0077 table becomes the rows of the lists
alter table medicine_reference rename to medicine_reference_entry;
alter table medicine_reference_entry add column if not exists list_id uuid references reference_list (id);
insert into reference_list (name, effective_from, uploaded_at, rows, status)
select 'RHIA June 2026', date '2026-06-01', coalesce(min(created_at), now()), count(*)::int, 'current'
from medicine_reference_entry;
update medicine_reference_entry set list_id = (select id from reference_list where name = 'RHIA June 2026')
where list_id is null;
alter table medicine_reference_entry alter column list_id set not null;
alter table medicine_reference_entry drop constraint if exists medicine_reference_pkey;
alter table medicine_reference_entry add primary key (list_id, code);
create index if not exists medicine_reference_entry_code_idx on medicine_reference_entry (code);
revoke all on medicine_reference_entry from anon, authenticated;
grant select on medicine_reference_entry to authenticated;

-- The list in effect on a date: the latest effective_from not after it (same date: last uploaded).
create or replace function reference_list_at(p_at date default current_date)
returns uuid
language sql stable security definer set search_path = public
as $$
  select id from reference_list
  where effective_from <= coalesce(p_at, current_date)
  order by effective_from desc, uploaded_at desc
  limit 1
$$;

-- What every reader called medicine_reference: the list in effect today (before its first date:
-- the current one).
create or replace view medicine_reference with (security_invoker = true) as
  select e.code, e.generic, e.presentation, e.prescribing_rule, e.unit, e.price, e.atc_group, e.source,
         e.created_at, e.list_id
  from medicine_reference_entry e
  join (select coalesce(reference_list_at(current_date),
                        (select r.id from reference_list r where r.status = 'current')) as id) cur
    on cur.id = e.list_id;
revoke all on medicine_reference from anon;
grant select on medicine_reference to authenticated;

-- ---------------------------------------------------------------- items and insurers
alter table item add column if not exists reference_removed_at timestamptz;
comment on column item.reference_removed_at is
  'Set when an uploaded official list no longer has this code (no insurer list price); cleared when it returns.';

alter table payer add column if not exists follows_reference_list boolean not null default false;
comment on column payer.follows_reference_list is
  'The insurer prices medicines from the official list (RHIA) when it has no own price for the item.';
update payer set follows_reference_list = true
where type in ('rssb_rama', 'mmi', 'cbhi') and not follows_reference_list;

-- an insurer of these kinds added later follows the list from the start (switched off on the insurer)
create or replace function payer_follows_reference_default()
returns trigger
language plpgsql
as $$
begin
  if new.type in ('rssb_rama', 'mmi', 'cbhi') then
    new.follows_reference_list := true;
  end if;
  return new;
end
$$;
drop trigger if exists trg_payer_follows_reference on payer;
create trigger trg_payer_follows_reference before insert on payer
  for each row execute function payer_follows_reference_default();

-- guard_item (from 20261124090000_stores_and_stock): the list flag changes only with an upload.
create or replace function guard_item()
returns trigger
language plpgsql
as $$
begin
  -- the checked (security definer) functions run as their owner, not as the API roles
  if current_user::text not in ('authenticated', 'anon') then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' then
    raise exception 'a medicine is deleted with the Delete button (the manager)' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and (
       new.deleted_at is distinct from old.deleted_at or new.active is distinct from old.active
       or new.reorder_level is distinct from old.reorder_level or new.max_level is distinct from old.max_level
       or new.code is distinct from old.code or new.pack_size is distinct from old.pack_size
       or new.reference_removed_at is distinct from old.reference_removed_at) then
    raise exception 'deleting, switching off, the code, the box size and the stock levels change only through their screens'
      using errcode = '42501';
  end if;
  return new;
end
$$;

-- ---------------------------------------------------------------- price_for
-- price_for (from 20261015180200_catalogue): an insurer that follows the official list and has no
-- own price for the ITEM takes the price of the item's code on the list in effect on p_at.
create or replace function price_for(
  p_service_id uuid,
  p_item_id uuid,
  p_payer_id uuid,
  p_at date default current_date
)
returns table (price numeric, list_payer_id uuid, fallback boolean)
language plpgsql stable
as $$
begin
  if p_payer_id is not null then
    return query
      select pli.price, pl.payer_id, false
      from price_list pl
      join price_list_item pli on pli.price_list_id = pl.id
      where pl.payer_id = p_payer_id
        and pl.deleted_at is null and pli.deleted_at is null
        and pl.effective_from <= p_at and (pl.effective_to is null or pl.effective_to >= p_at)
        and ((p_service_id is not null and pli.service_id = p_service_id)
          or (p_item_id is not null and pli.item_id = p_item_id))
      order by pl.effective_from desc
      limit 1;
    if found then
      return;
    end if;
    if p_item_id is not null and exists (select 1 from payer py where py.id = p_payer_id and py.follows_reference_list) then
      return query
        select e.price, p_payer_id, false
        from item i
        join medicine_reference_entry e on e.code = i.code and e.list_id = reference_list_at(p_at)
        where i.id = p_item_id and e.price is not null
        limit 1;
      if found then
        return;
      end if;
    end if;
  end if;
  return query
    select pli.price, null::uuid, (p_payer_id is not null)
    from price_list pl
    join price_list_item pli on pli.price_list_id = pl.id
    where pl.payer_id is null
      and pl.deleted_at is null and pli.deleted_at is null
      and pl.effective_from <= p_at and (pl.effective_to is null or pl.effective_to >= p_at)
      and ((p_service_id is not null and pli.service_id = p_service_id)
        or (p_item_id is not null and pli.item_id = p_item_id))
    order by pl.effective_from desc
    limit 1;
end
$$;

-- ---------------------------------------------------------------- the lists for the Prices page
create or replace function reference_lists()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', r.id, 'name', r.name, 'effectiveFrom', r.effective_from, 'rows', r.rows,
    'uploadedAt', r.uploaded_at, 'uploadedBy', p.full_name, 'status', r.status,
    'inEffect', r.id = reference_list_at(current_date))
    order by (r.status = 'current') desc, r.effective_from desc, r.uploaded_at desc), '[]'::jsonb)
  from reference_list r
  left join profiles p on p.id = r.uploaded_by
  where has_perm('catalogue.read')
$$;

-- ---------------------------------------------------------------- the upload
create or replace function import_reference_list(
  p_name text,
  p_effective date,
  p_rows jsonb,
  p_dry_run boolean default true
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_name text := nullif(regexp_replace(trim(coalesce(p_name, '')), '\s+', ' ', 'g'), '');
  v_cur reference_list%rowtype;
  v_r jsonb;
  v_n integer;
  v_row integer;
  v_code text;
  v_generic text;
  v_price_txt text;
  v_err text;
  v_errors jsonb := '[]'::jsonb;
  v_valid integer;
  v_new integer;
  v_unchanged integer;
  v_changed jsonb;
  v_removed jsonb;
  v_list uuid;
  v_flagged integer := 0;
  v_back integer := 0;
begin
  if not (is_manager() or has_perm('catalogue.write')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'the list has no rows' using errcode = '22023';
  end if;
  if jsonb_array_length(p_rows) > 20000 then
    raise exception 'the list has too many rows' using errcode = '22023';
  end if;
  if v_name is null or length(v_name) > 120 then
    raise exception 'give the list a name' using errcode = '22023';
  end if;
  if p_effective is null then
    raise exception 'give the date the list starts' using errcode = '22023';
  end if;
  select * into v_cur from reference_list where status = 'current';
  if found and p_effective < v_cur.effective_from then
    raise exception 'the new list cannot start before the current one' using errcode = '22023';
  end if;

  create temp table if not exists _ref_import (
    code text primary key,
    generic text not null,
    presentation text,
    prescribing_rule text,
    unit text,
    price numeric(12, 0),
    atc_group text
  ) on commit drop;
  truncate _ref_import;

  for v_r, v_n in select x.value, x.ordinality from jsonb_array_elements(p_rows) with ordinality as x loop
    v_err := null;
    v_row := v_n;
    if jsonb_typeof(v_r) <> 'object' then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('row', v_row, 'code', 'not_a_row',
        'message', 'not a row of the list'));
      continue;
    end if;
    if coalesce(v_r ->> 'row', '') ~ '^\d{1,7}$' then
      v_row := (v_r ->> 'row')::integer;
    end if;
    v_code := upper(regexp_replace(coalesce(v_r ->> 'code', ''), '\s+', '', 'g'));
    v_generic := nullif(regexp_replace(trim(coalesce(v_r ->> 'generic', '')), '\s+', ' ', 'g'), '');
    v_price_txt := nullif(replace(trim(coalesce(v_r ->> 'price', '')), ',', ''), '');
    if v_code = '' then
      v_err := 'no_code';
    elsif length(v_code) > 40 then
      v_err := 'bad_code';
    elsif v_generic is null then
      v_err := 'no_generic';
    elsif v_price_txt is not null and v_price_txt !~ '^\d{1,10}(\.\d+)?$' then
      v_err := 'bad_price';
    elsif exists (select 1 from _ref_import where code = v_code) then
      v_err := 'duplicate';
    end if;
    if v_err is not null then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object('row', v_row, 'code', v_err,
        'value', case when v_err in ('bad_price') then v_r ->> 'price' when v_err = 'no_generic' then v_code
                      else v_r ->> 'code' end,
        'message', case v_err
          when 'no_code' then 'the code is missing'
          when 'bad_code' then 'the code is too long'
          when 'no_generic' then 'the generic name is missing'
          when 'bad_price' then 'the price is not a number zero or more'
          else 'this code is already on an earlier row' end));
      continue;
    end if;
    insert into _ref_import (code, generic, presentation, prescribing_rule, unit, price, atc_group)
    values (v_code, left(v_generic, 300),
            left(nullif(regexp_replace(trim(coalesce(v_r ->> 'presentation', '')), '\s+', ' ', 'g'), ''), 300),
            left(nullif(regexp_replace(trim(coalesce(v_r ->> 'prescribing_rule', v_r ->> 'rule', '')), '\s+', ' ', 'g'), ''), 120),
            left(nullif(regexp_replace(trim(coalesce(v_r ->> 'unit', '')), '\s+', ' ', 'g'), ''), 60),
            round(v_price_txt::numeric),
            left(nullif(regexp_replace(trim(coalesce(v_r ->> 'atc_group', v_r ->> 'group', '')), '\s+', ' ', 'g'), ''), 200));
  end loop;

  select count(*)::int into v_valid from _ref_import;
  select count(*)::int into v_new from _ref_import n
  where not exists (select 1 from medicine_reference_entry e where e.list_id = v_cur.id and e.code = n.code);
  select count(*)::int into v_unchanged from _ref_import n
  join medicine_reference_entry e on e.list_id = v_cur.id and e.code = n.code
  where e.price is not distinct from n.price;
  select coalesce(jsonb_agg(jsonb_build_object('code', n.code, 'generic', n.generic, 'presentation', n.presentation,
           'old', e.price, 'new', n.price,
           'inClinic', exists (select 1 from item i where i.code = n.code and i.deleted_at is null))
           order by n.generic, n.code), '[]'::jsonb)
  into v_changed
  from _ref_import n
  join medicine_reference_entry e on e.list_id = v_cur.id and e.code = n.code
  where e.price is distinct from n.price;
  select coalesce(jsonb_agg(jsonb_build_object('code', e.code, 'generic', e.generic, 'presentation', e.presentation,
           'inClinic', exists (select 1 from item i where i.code = e.code and i.deleted_at is null))
           order by e.generic, e.code), '[]'::jsonb)
  into v_removed
  from medicine_reference_entry e
  where e.list_id = v_cur.id and not exists (select 1 from _ref_import n where n.code = e.code);

  if not p_dry_run then
    if v_valid = 0 then
      raise exception 'no row of the list can be used' using errcode = '22023';
    end if;
    update reference_list set status = 'past' where status = 'current';
    insert into reference_list (name, effective_from, uploaded_by, rows, status)
    values (v_name, p_effective, auth.uid(), v_valid, 'current')
    returning id into v_list;
    insert into medicine_reference_entry (list_id, code, generic, presentation, prescribing_rule, unit, price, atc_group, source)
    select v_list, code, generic, presentation, prescribing_rule, unit, price, atc_group, v_name from _ref_import;
    -- the clinic's medicines: back on the list, or left it
    update item i set reference_removed_at = null
    where i.reference_removed_at is not null and exists (select 1 from _ref_import n where n.code = i.code);
    get diagnostics v_back = row_count;
    update item i set reference_removed_at = now()
    where i.deleted_at is null and i.reference_removed_at is null
      and exists (select 1 from medicine_reference_entry e where e.list_id = v_cur.id and e.code = i.code)
      and not exists (select 1 from _ref_import n where n.code = i.code);
    get diagnostics v_flagged = row_count;
    insert into audit_event (actor_id, action, entity, entity_id, after)
    values (auth.uid(), 'create', 'reference_list', v_list,
            jsonb_build_object('name', v_name, 'effectiveFrom', p_effective, 'rows', v_valid,
                               'replaced', v_cur.name, 'changed', jsonb_array_length(v_changed),
                               'removed', jsonb_array_length(v_removed), 'itemsFlagged', v_flagged));
  end if;
  truncate _ref_import;

  return jsonb_build_object(
    'dryRun', p_dry_run, 'id', v_list, 'name', v_name, 'effectiveFrom', p_effective,
    'total', jsonb_array_length(p_rows), 'rows', v_valid,
    'new', v_new, 'changed', v_changed, 'removed', v_removed, 'unchanged', v_unchanged, 'errors', v_errors,
    'current', case when v_cur.id is null then null
                    else jsonb_build_object('name', v_cur.name, 'effectiveFrom', v_cur.effective_from, 'rows', v_cur.rows) end,
    'itemsFlagged', v_flagged, 'itemsBack', v_back);
end
$$;

-- ---------------------------------------------------------------- add stock
-- add_stock (from 20261207090000_pharmacy_simplified): a medicine of the list keeps the list's code.
create or replace function add_stock(p_lines jsonb, p_location_id uuid default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_main uuid := main_pharmacy();
  v_loc uuid;
  v_id uuid;
  v_number text;
  v_line jsonb;
  v_n integer;
  v_item uuid;
  v_new jsonb;
  v_kind text;
  v_name text;
  v_strength text;
  v_code text;
  v_ref medicine_reference%rowtype;
  v_created boolean;
  v_qty numeric;
  v_units integer;
  v_cost numeric;
  v_sell numeric;
  v_price numeric;
  v_expiry date;
  v_batch uuid;
  v_line_cost numeric;
  v_updated boolean;
  v_ignored boolean;
  v_price_right boolean := has_perm('item_price.write') or has_perm('catalogue.write');
  v_out jsonb := '[]'::jsonb;
  v_total numeric := 0;
  v_state text;
  v_msg text;
  v_hint text;
begin
  if not stock_manager() then
    perform assert_stock_write();
    raise exception 'not allowed' using errcode = '42501';
  end if;
  v_loc := coalesce(p_location_id, v_main);
  if v_loc is null then
    raise exception 'no pharmacy store yet: create one under Stock' using errcode = 'P0002';
  end if;
  if v_loc is distinct from v_main and not is_manager() then
    raise exception 'stock is added into the main pharmacy (another store: the manager)' using errcode = '42501';
  end if;
  if not exists (select 1 from stock_location where id = v_loc and deleted_at is null and type::text <> 'transit') then
    raise exception 'store not found' using errcode = 'P0002';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'add at least one medicine' using errcode = '22023';
  end if;
  v_number := day_number('GRN', 'goods-receipt');
  insert into goods_receipt (supplier_id, received_on, note, number, reference, delivered_on, location_id, supplier_name)
  values (null, now(), nullif(trim(coalesce(p_note, '')), ''), v_number, null,
          (now() at time zone 'Africa/Kigali')::date, v_loc, null)
  returning id into v_id;

  for v_line, v_n in select x.value, x.ordinality from jsonb_array_elements(p_lines) with ordinality as x loop
    begin
      v_created := false;
      v_updated := false;
      v_ignored := false;
      v_item := nullif(v_line ->> 'item_id', '')::uuid;
      v_new := case when jsonb_typeof(v_line -> 'new_item') = 'object' then v_line -> 'new_item' end;
      v_sell := nullif(v_line ->> 'sell_price', '')::numeric;
      if v_sell is not null and v_sell < 0 then
        raise exception 'the price must be zero or more' using errcode = '22023';
      end if;
      if v_item is null and v_new is not null then
        v_kind := coalesce(nullif(v_new ->> 'kind', ''), 'medicine');
        if v_kind not in ('medicine', 'supply') then
          raise exception 'a new item is a medicine or a supply' using errcode = '22023';
        end if;
        v_name := trim(coalesce(v_new ->> 'name', ''));
        v_strength := nullif(trim(coalesce(v_new ->> 'strength', '')), '');
        if length(v_name) < 2 then
          raise exception 'the medicine needs a name' using errcode = '22023';
        end if;
        -- 0098: picked from the official list: the item carries the list's code (its insurer
        -- price and its prescribing rule follow the list)
        v_code := nullif(upper(trim(coalesce(v_new ->> 'code', ''))), '');
        if v_code is not null then
          select * into v_ref from medicine_reference where code = v_code;
          if not found then
            raise exception 'this medicine is not on the reference list' using errcode = 'P0002';
          end if;
          select id into v_item from item where code = v_code;
          if v_item is not null then
            update item set deleted_at = null, active = true where id = v_item and (deleted_at is not null or not active);
          end if;
        end if;
        -- the same name (and strength) already on the list: that item
        if v_item is null then
          select id into v_item from item
          where deleted_at is null and lower(name_generic) = lower(v_name)
            and lower(coalesce(strength, '')) = lower(coalesce(v_strength, ''))
          order by active desc, created_at
          limit 1;
        end if;
        if v_item is null then
          insert into item (code, name_generic, strength, form, unit, selling_unit, active, kind)
          values (coalesce(v_code, case when v_kind = 'supply' then 'SUP-' else 'MED-' end
                    || lpad(next_number('item_code', 0)::text, 4, '0')),
                  v_name, v_strength, nullif(trim(coalesce(v_new ->> 'form', '')), ''),
                  nullif(trim(coalesce(v_new ->> 'unit', '')), ''), nullif(trim(coalesce(v_new ->> 'unit', '')), ''),
                  true, v_kind)
          returning id into v_item;
          if v_code is not null then
            update item set prescribing_rule = v_ref.prescribing_rule, atc_group = v_ref.atc_group,
                            name_brand = v_ref.presentation, source = v_ref.source
            where id = v_item;
          end if;
          v_created := true;
        end if;
      end if;
      if v_item is null then
        raise exception 'choose the medicine' using errcode = '22023';
      end if;
      if not exists (select 1 from item where id = v_item and deleted_at is null) then
        raise exception 'medicine not found' using errcode = 'P0002';
      end if;
      v_qty := nullif(v_line ->> 'quantity', '')::numeric;
      if v_qty is null or v_qty <= 0 then
        raise exception 'quantity must be more than zero' using errcode = '22023';
      end if;
      if v_qty <> round(v_qty) then
        raise exception 'the quantity must come to whole units' using errcode = '22023';
      end if;
      v_units := v_qty::integer;
      v_cost := nullif(v_line ->> 'unit_cost', '')::numeric;
      if v_cost is null or v_cost < 0 then
        raise exception 'the cost per unit must be zero or more' using errcode = '22023';
      end if;
      v_expiry := nullif(v_line ->> 'expiry', '')::date;
      -- the selling price: a new item (or one without a price) takes it; a different price needs the right
      if v_sell is not null then
        select pf.price into v_price from price_for(null, v_item, null) pf;
        if v_price is null or v_created then
          perform set_cash_price(v_item, v_sell);
          v_updated := true;
        elsif round(v_sell) <> v_price then
          if v_price_right then
            perform set_cash_price(v_item, v_sell);
            v_updated := true;
          else
            v_ignored := true;
          end if;
        end if;
      end if;
      v_batch := receive_batch(v_item, v_loc, v_units, v_cost, v_line ->> 'batch_no', v_expiry, null, null, v_id);
      v_line_cost := round(round(v_cost, 2) * v_units, 2);
      insert into goods_receipt_line (receipt_id, item_id, batch_id, batch_no, expiry, unit, packs, pack_size, units,
                                      unit_cost, pack_cost, line_cost)
      select v_id, v_item, b.id, b.batch_no, b.expiry, 'unit', v_units, 1, v_units, round(v_cost, 2), null, v_line_cost
      from batch b where b.id = v_batch;
      v_total := v_total + v_line_cost;
      v_out := v_out || jsonb_build_array(jsonb_build_object(
        'item_id', v_item, 'batch_id', v_batch, 'quantity', v_units, 'line_cost', v_line_cost,
        'created', v_created, 'price_updated', v_updated, 'price_ignored', v_ignored));
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text, v_hint = pg_exception_hint;
      raise exception 'line %: %', v_n, v_msg using errcode = v_state, hint = coalesce(nullif(v_hint, ''), 'line');
    end;
  end loop;
  update goods_receipt set total_cost = v_total where id = v_id;
  perform stock_alert_run();
  return jsonb_build_object('lines', v_out, 'total_cost', v_total, 'id', v_id, 'number', v_number, 'location_id', v_loc);
end
$$;

-- ---------------------------------------------------------------- grants
-- (functions replaced with the same arguments keep their grants)
revoke all on function reference_list_at(date), reference_lists(), import_reference_list(text, date, jsonb, boolean)
  from public, anon;
grant execute on function reference_list_at(date), reference_lists(), import_reference_list(text, date, jsonb, boolean)
  to authenticated;
revoke all on function payer_follows_reference_default() from public, anon, authenticated;


-- ============================================================ 20261209090000_my_bookings.sql
-- 0099 · My bookings: the bookings made with a person who keeps a calendar.
--
-- Frank (owner): a booking made with a doctor, sonographer, nurse or the manager is accepted,
-- moved or declined by that person. They could only do it from the notice or from "Bookings to
-- accept" on Home; nothing listed THEIR OWN bookings over the coming weeks (the Bookings page is
-- reception's desk page, for booking other people).
--
--   * my_bookings(p_from, p_to, p_user default null): the caller's bookings (practitioner rows of
--     the caller) whose time falls on a day from p_from to p_to (Kigali days; default the last 30
--     days to 3 weeks ahead, at most 120 days), plus every booking still waiting for their answer
--     (approved, not more than a day past) whatever its day. The manager may pass p_user to see
--     another practitioner's. Each row carries the patient (or the contact of a website request),
--     the phone, the reason, who booked it and who accepted it, the visit opened on arrival and
--     the history of the booking (created, each change of state or of time, from audit_event).
--     Returns { userId, name, slotMinutes, rows: [...] }; no calendar yet: rows is empty.
--   * Who may: whoever answers bookings (appointment.accept: doctors, sonographers, nurses, the
--     manager) or the manager.

create or replace function my_bookings(p_from date default null, p_to date default null, p_user uuid default null)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_today date := (now() at time zone 'Africa/Kigali')::date;
  v_from date := coalesce(p_from, v_today - 30);
  v_to date := coalesce(p_to, v_today + 21);
  v_user uuid := coalesce(p_user, auth.uid());
  v_rows jsonb;
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if not (has_perm('appointment.accept') or is_manager()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_user <> auth.uid() and not is_manager() then
    raise exception 'only the manager sees the bookings of a colleague' using errcode = '42501';
  end if;
  if v_to < v_from then
    raise exception 'the end of the period is before its start' using errcode = '22023';
  end if;
  if v_to - v_from > 120 then
    v_to := v_from + 120;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'status', a.status, 'startsAt', a.starts_at, 'endsAt', a.ends_at,
      'reason', a.reason, 'category', a.category, 'source', a.source, 'reference', a.reference,
      'channel', a.contact_channel, 'cancelReason', a.cancel_reason, 'createdAt', a.created_at,
      'patientId', p.id, 'fileNumber', p.file_number,
      'name', coalesce(p.surname || ' ' || p.given_names, a.contact_name, ''),
      'phone', coalesce(p.phone_1, a.contact_phone),
      'bookedBy', ap.full_name, 'bookedAt', a.approved_at,
      'acceptedBy', ac.full_name, 'acceptedAt', a.accepted_at,
      'encounterId', (select e.id from encounter e where e.appointment_id = a.id
                      order by e.created_at desc limit 1),
      'late', a.status in ('approved', 'confirmed') and a.starts_at < now() - interval '15 minutes',
      'history', coalesce((
        select jsonb_agg(jsonb_build_object(
            'at', h.at, 'by', who.full_name,
            'status', h.after ->> 'status',
            'startsAt', h.after ->> 'starts_at',
            'moved', h.action = 'update'
                     and (h.before ->> 'starts_at') is distinct from (h.after ->> 'starts_at')
          ) order by h.at)
        from audit_event h
        left join profiles who on who.id = h.actor_id
        where h.entity = 'appointment' and h.entity_id = a.id
          and (h.action = 'create'
               or (h.action = 'update'
                   and ((h.before ->> 'status') is distinct from (h.after ->> 'status')
                        or (h.before ->> 'starts_at') is distinct from (h.after ->> 'starts_at'))))
      ), '[]'::jsonb)
    ) order by a.starts_at), '[]'::jsonb)
  into v_rows
  from appointment a
  join practitioner pr on pr.id = a.practitioner_id and pr.user_id = v_user
  left join patient p on p.id = a.patient_id
  left join profiles ap on ap.id = a.approved_by
  left join profiles ac on ac.id = a.accepted_by
  where a.deleted_at is null
    and a.status not in ('inquiry', 'rejected')
    and a.starts_at is not null
    and (((a.starts_at at time zone 'Africa/Kigali')::date between v_from and v_to)
         or (a.status = 'approved' and a.starts_at > now() - interval '1 day'));

  return jsonb_build_object(
    'userId', v_user,
    'name', (select full_name from profiles where id = v_user),
    'slotMinutes', coalesce((select slot_minutes from practitioner
                             where user_id = v_user and deleted_at is null limit 1), 30),
    'from', v_from, 'to', v_to,
    'rows', v_rows
  );
end
$$;

revoke all on function my_bookings(date, date, uuid) from public, anon;
grant execute on function my_bookings(date, date, uuid) to authenticated;


-- ============================================================ 20261210090000_outside_prescriptions.sql
-- 0100 · Medicines bought at an outside pharmacy.
--
-- Frank (owner): the clinic pharmacy does not always hold every medicine. The doctor printed the
-- prescription and the patient bought the missing ones elsewhere, but the system still sent every
-- line to the pharmacy. Now the prescriber decides, medicine by medicine, who gives it:
--
--   * medication_request.supply gains 'outside': the patient buys it at an outside pharmacy. Such a
--     line is never charged, never waits at the pharmacy (rx_pending is supply = 'pharmacy' only),
--     never moves stock, and is printed on "the prescription for an outside pharmacy".
--   * An outside line may name a medicine the clinic does not hold: item_id is null only for
--     'outside', and medicine_name (always filled for outside lines, so the print never depends on
--     the catalogue) says it; reference_code keeps the official (RHIA) list code when picked there.
--   * supply_set_at / supply_set_by / supply_reason: who decided where it is given, and when.
--   * prescribe(..., p_medicine_name, p_reference_code): 'outside' accepted (a clinic medicine, or
--     one of the official list, or a name typed); same right, desk and visit checks as before, the
--     prescribing-rule warnings too (from the list's rule for a list medicine).
--   * rx_set_supply(request, 'pharmacy' | 'outside', reason?): the prescriber (the doctor treating
--     the patient, or the manager) changes the decision of a line not given and not cancelled;
--     e.g. after the pharmacy marked it "not given: out of stock". Back to the pharmacy only for a
--     clinic medicine on an open visit. The pharmacy is told when a waiting line leaves its list;
--     the patient moves on when nothing is left there (after_pharmacy). Pharmacists without the
--     prescribing right are refused.
--   * rx_not_given tells the prescriber whether the pharmacy had none (noStock) and whether the
--     line can go to an outside pharmacy (outside).
--   * cancel_prescription also cancels an outside line (wrong medicine written).
--   * rx_stock(): the usable (unexpired) units of each medicine at the main pharmacy, for the
--     prescription form.
--   * rx_bought_outside(from, to): "Prescribed but bought outside": each medicine sent outside in
--     the period, how many times and the total quantity (manager and pharmacy, to order).
--   * The readers of prescriptions (visit_clinical, visit_journey, my_prescriptions,
--     patient_safety_summary) read a line without a clinic medicine too (rx_label).

-- ---------------------------------------------------------------- the table
do $$
declare
  r record;
begin
  for r in select conname from pg_constraint
           where conrelid = 'medication_request'::regclass and contype = 'c'
             and pg_get_constraintdef(oid) ilike '%supply%' loop
    execute format('alter table medication_request drop constraint %I', r.conname);
  end loop;
end $$;
alter table medication_request add constraint medication_request_supply_check
  check (supply in ('pharmacy', 'room', 'outside'));
alter table medication_request alter column item_id drop not null;
alter table medication_request add column if not exists medicine_name text;
alter table medication_request add column if not exists reference_code text;
alter table medication_request add column if not exists supply_set_at timestamptz;
alter table medication_request add column if not exists supply_set_by uuid references profiles (id) on delete set null;
alter table medication_request add column if not exists supply_reason text;
alter table medication_request drop constraint if exists medication_request_item_ck;
alter table medication_request add constraint medication_request_item_ck
  check (item_id is not null or (supply = 'outside' and nullif(trim(coalesce(medicine_name, '')), '') is not null));
create index if not exists medication_request_outside_idx on medication_request (created_at) where supply = 'outside';

-- The name a prescription line prints: the name kept on the line (outside), else the medicine's.
create or replace function rx_label(m medication_request)
returns text
language sql stable security definer set search_path = public
as $$
  select coalesce(nullif(trim(coalesce(m.medicine_name, '')), ''), item_label(m.item_id))
$$;

-- The official list's prescribing rule as warnings (rx_warnings reads the clinic's medicine).
create or replace function rx_rule_warnings(p_rule text, p_staff uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select case
    when p_rule is null or trim(p_rule) = '' then '[]'::jsonb
    when upper(trim(p_rule)) = 'HU' then
      jsonb_build_array(jsonb_build_object('kind', 'hospitalOnly', 'rule', p_rule))
    when upper(trim(p_rule)) = 'M' then
      jsonb_build_array(jsonb_build_object('kind', 'needsNote', 'rule', p_rule))
    when rx_rule_ok(p_rule, (select specialty from profiles where id = p_staff)) is false then
      jsonb_build_array(jsonb_build_object('kind', 'prescribingRule', 'rule', p_rule,
                                           'specialty', (select specialty from profiles where id = p_staff)))
    else '[]'::jsonb
  end
$$;

-- guard_medication_request (from 20261207090000_pharmacy_simplified): the new columns change only
-- through prescribe and rx_set_supply.
create or replace function guard_medication_request()
returns trigger
language plpgsql
as $$
begin
  -- the checked (security definer) functions run as their owner, not as the API roles
  if current_user::text not in ('authenticated', 'anon') then
    return coalesce(new, old);
  end if;
  if tg_op = 'INSERT' then
    raise exception 'prescriptions are written with the prescription form only' using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'a prescription is not deleted: the doctor cancels it' using errcode = '42501';
  end if;
  if new.given_at is distinct from old.given_at or new.given_by is distinct from old.given_by
     or new.not_given_at is distinct from old.not_given_at or new.not_given_by is distinct from old.not_given_by
     or new.not_given_reason is distinct from old.not_given_reason
     or new.cancelled_at is distinct from old.cancelled_at or new.cancelled_by is distinct from old.cancelled_by
     or new.cancel_reason is distinct from old.cancel_reason
     or new.supply is distinct from old.supply or new.quantity is distinct from old.quantity
     or new.item_id is distinct from old.item_id or new.encounter_id is distinct from old.encounter_id
     or new.prescriber_id is distinct from old.prescriber_id or new.deleted_at is distinct from old.deleted_at
     or new.quantity_given is distinct from old.quantity_given
     or new.medicine_name is distinct from old.medicine_name or new.reference_code is distinct from old.reference_code
     or new.supply_set_at is distinct from old.supply_set_at or new.supply_set_by is distinct from old.supply_set_by
     or new.supply_reason is distinct from old.supply_reason
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'handing over, not given, cancelling and the medicine or quantity change only through the pharmacy and prescription screens'
      using errcode = '42501';
  end if;
  return new;
end
$$;

-- ---------------------------------------------------------------- prescribe
-- From 20261126090000_departments_decide_desks: 'outside', and a medicine the clinic does not hold.
drop function if exists prescribe(uuid, uuid, numeric, text, text, text, integer, text, text, station, uuid);
create or replace function prescribe(
  p_encounter_id uuid, p_item_id uuid, p_quantity numeric, p_dose text default null, p_route text default null,
  p_frequency text default null, p_duration_days integer default null, p_instructions text default null,
  p_supply text default 'pharmacy', p_station station default null, p_location_id uuid default null,
  p_medicine_name text default null, p_reference_code text default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_charged boolean := false;
  v_loc uuid;
  v_taken boolean := false;
  v_qty integer;
  v_supply text := coalesce(p_supply, 'pharmacy');
  v_code text := nullif(trim(coalesce(p_reference_code, '')), '');
  v_name text;
  v_generic text;
  v_rule text;
  v_warn jsonb := '[]'::jsonb;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  perform assert_may_work_on(p_encounter_id);
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'quantity must be more than zero' using errcode = '22023';
  end if;
  if v_supply not in ('pharmacy', 'room', 'outside') then
    raise exception 'unknown supply' using errcode = '22023';
  end if;
  if not exists (select 1 from encounter where id = p_encounter_id and status = 'open') then
    raise exception 'visit not found or already closed' using errcode = 'P0002';
  end if;
  if p_item_id is null then
    -- not a clinic medicine: only for an outside pharmacy, named (or taken from the official list)
    if v_supply <> 'outside' then
      raise exception 'this medicine is not sold at the clinic: it can only be bought outside' using errcode = '22023';
    end if;
    if v_code is not null then
      select r.generic, r.prescribing_rule into v_generic, v_rule from medicine_reference r where r.code = v_code;
      if not found then
        raise exception 'medicine not found' using errcode = 'P0002';
      end if;
      v_warn := coalesce(rx_rule_warnings(v_rule, auth.uid()), '[]'::jsonb);
    end if;
    v_name := coalesce(nullif(trim(coalesce(p_medicine_name, '')), ''), v_generic);
    if v_name is null then
      raise exception 'write the name of the medicine to buy outside' using errcode = '22023';
    end if;
  else
    if not exists (select 1 from item where id = p_item_id and deleted_at is null) then
      raise exception 'medicine not found' using errcode = 'P0002';
    end if;
    v_warn := coalesce(rx_warnings(p_item_id, auth.uid()), '[]'::jsonb);
    if v_supply = 'outside' then
      -- the print keeps its name even if the catalogue changes
      v_name := item_label(p_item_id);
      v_code := coalesce(v_code, (select i.code from item i where i.id = p_item_id
                                    and exists (select 1 from medicine_reference r where r.code = i.code)));
    else
      v_code := null;
    end if;
  end if;
  if v_supply = 'room' then
    -- Given here: only from a store that holds enough unexpired units; never given without stock.
    v_qty := ceil(p_quantity)::integer;
    v_loc := room_store_for(auth.uid(), p_item_id, v_qty, p_location_id, p_station);
    if v_loc is null then
      raise exception 'not enough of this medicine (not expired) in %: prescribe it for the pharmacy instead',
        case when p_location_id is null then 'a store you may give from' else 'that store' end
        using errcode = 'MS003', hint = 'room_short';
    end if;
  end if;
  insert into medication_request (encounter_id, item_id, dose, route, frequency, duration_days, quantity,
                                  instructions, supply, given_at, given_by, medicine_name, reference_code,
                                  supply_set_at, supply_set_by)
  values (p_encounter_id, p_item_id, nullif(trim(coalesce(p_dose, '')), ''), nullif(trim(coalesce(p_route, '')), ''),
          nullif(trim(coalesce(p_frequency, '')), ''), p_duration_days, p_quantity,
          nullif(trim(coalesce(p_instructions, '')), ''), v_supply,
          case when v_supply = 'room' then now() end, case when v_supply = 'room' then auth.uid() end,
          v_name, v_code, now(), auth.uid())
  returning id into v_id;
  if v_supply = 'room' then
    perform give_from_store(p_item_id, v_loc, v_qty, v_id, 'given in the room');
    v_taken := true;
    -- on the bill at the medicine's price (no price: given free); a closed bill refuses (MS001)
    begin
      perform add_charge_internal(p_encounter_id, coalesce(p_station, 'consultation'::station), null, p_item_id, p_quantity,
                         null, null, null, null, 'medication_request', v_id);
      v_charged := true;
    exception when sqlstate 'P0002' then
      v_charged := false;
    end;
  elsif v_supply = 'pharmacy'
        and not exists (select 1 from queue_entry where encounter_id = p_encounter_id and station = 'pharmacy'
                        and finished_at is null and deleted_at is null) then
    insert into queue_entry (encounter_id, station, ticket_no)
    values (p_encounter_id, 'pharmacy', (select ticket_no from queue_entry where encounter_id = p_encounter_id order by created_at limit 1));
  end if;
  -- 'outside': nothing charged, nothing taken, nothing queued
  return jsonb_build_object('id', v_id, 'supply', v_supply, 'charged', v_charged,
                            'stockTaken', v_taken, 'locationId', v_loc, 'medicineName', v_name,
                            'warnings', v_warn);
end
$$;

-- ---------------------------------------------------------------- the prescriber changes the decision
create or replace function rx_set_supply(p_request_id uuid, p_supply text, p_reason text default null)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_open boolean;
  v_was_waiting boolean;
  v_name text;
  v_left integer;
begin
  if not has_perm('clinical.write') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  if p_supply is null or p_supply not in ('pharmacy', 'outside') then
    raise exception 'unknown supply' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  select e.status = 'open' into v_open from encounter e where e.id = v_m.encounter_id;
  -- as prescribing: the doctor treating the patient (or the prescriber, or the manager)
  if not (is_manager() or coalesce(v_m.prescriber_id, v_m.created_by) = auth.uid()
          or (v_open and may_work_on(v_m.encounter_id))) then
    if v_open then
      perform assert_may_work_on(v_m.encounter_id);
    end if;
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_m.cancelled_at is not null or v_m.given_at is not null or v_m.supply = 'room' then
    raise exception 'this medicine was already given or cancelled: it stays as it is' using errcode = 'P0002';
  end if;
  if coalesce(v_m.quantity_given, 0) > 0
     or (coalesce(v_m.quantity_given, 0) = 0 and v_m.not_given_at is null and exists (
           select 1 from medication_dispense d where d.medication_request_id = v_m.id and d.deleted_at is null)) then
    raise exception 'part of this medicine was already given: prescribe what remains as a new medicine'
      using errcode = '22023';
  end if;
  if v_m.supply = p_supply then
    return jsonb_build_object('id', v_m.id, 'supply', v_m.supply, 'changed', false,
                              'pending', (select count(*)::integer from medication_request m
                                          where m.encounter_id = v_m.encounter_id and rx_pending(m)));
  end if;
  v_was_waiting := rx_pending(v_m);
  if p_supply = 'pharmacy' then
    if v_m.item_id is null then
      raise exception 'this medicine is not sold at the clinic: it can only be bought outside' using errcode = '22023';
    end if;
    if not v_open then
      raise exception 'visit not found or already closed' using errcode = 'P0002';
    end if;
    -- back to the pharmacy's list (a "not given" of before is cleared: the pharmacy tries again)
    update medication_request
    set supply = 'pharmacy', not_given_at = null, not_given_by = null, not_given_reason = null,
        supply_set_at = now(), supply_set_by = auth.uid(),
        supply_reason = nullif(trim(coalesce(p_reason, '')), '')
    where id = v_m.id;
    if not exists (select 1 from queue_entry where encounter_id = v_m.encounter_id and station = 'pharmacy'
                   and finished_at is null and deleted_at is null) then
      insert into queue_entry (encounter_id, station, ticket_no)
      values (v_m.encounter_id, 'pharmacy',
              (select ticket_no from queue_entry where encounter_id = v_m.encounter_id order by created_at limit 1));
    end if;
  else
    update medication_request
    set supply = 'outside', medicine_name = coalesce(nullif(trim(coalesce(medicine_name, '')), ''), item_label(item_id)),
        reference_code = coalesce(reference_code, (select i.code from item i where i.id = v_m.item_id
                                                     and exists (select 1 from medicine_reference r where r.code = i.code))),
        supply_set_at = now(), supply_set_by = auth.uid(),
        supply_reason = nullif(trim(coalesce(p_reason, '')), '')
    where id = v_m.id;
    -- it was on the pharmacy's list: the pharmacy is told it left
    if v_was_waiting then
      select p.surname || ' ' || p.given_names into v_name
      from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
      insert into notification (kind, params, link, recipient_stations, created_by)
      values ('rx_outside',
              jsonb_build_object('item', rx_label(v_m), 'name', v_name,
                                 'by', (select full_name from profiles where id = auth.uid()),
                                 'reason', nullif(trim(coalesce(p_reason, '')), ''), 'requestId', v_m.id),
              '/app/visit?encounter=' || v_m.encounter_id, array['pharmacy'::station], auth.uid());
    end if;
    -- nothing left at the pharmacy: the patient goes on (back, cashier, or the visit closes)
    if v_open then
      perform after_pharmacy(v_m.encounter_id);
    end if;
  end if;
  select count(*)::integer into v_left from medication_request m
  where m.encounter_id = v_m.encounter_id and rx_pending(m);
  return jsonb_build_object('id', v_m.id, 'supply', p_supply, 'changed', true, 'pending', v_left);
end
$$;

-- ---------------------------------------------------------------- the pharmacy says "not given"
-- From 20261207090000_pharmacy_simplified: the prescriber is told whether the pharmacy had none and
-- whether the line may go to an outside pharmacy.
create or replace function rx_not_given(p_medication_request_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_item text;
  v_name text;
  v_left integer;
  v_main uuid := main_pharmacy();
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  if length(trim(coalesce(p_reason, ''))) < 2 then
    raise exception 'say why the medicine is not given' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_medication_request_id for update;
  if not found or not rx_pending(v_m) then
    raise exception 'this medicine is no longer waiting at the pharmacy' using errcode = 'P0002';
  end if;
  update medication_request
  set not_given_at = now(), not_given_by = auth.uid(), not_given_reason = trim(p_reason)
  where id = v_m.id;
  v_item := rx_label(v_m);
  v_left := ceil(v_m.quantity)::integer - coalesce(v_m.quantity_given, 0);
  select p.surname || ' ' || p.given_names into v_name
  from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
  if coalesce(v_m.prescriber_id, v_m.created_by) is not null
     and coalesce(v_m.prescriber_id, v_m.created_by) is distinct from auth.uid() then
    insert into notification (kind, params, link, recipient_user, created_by)
    values ('rx_not_given', jsonb_build_object('item', v_item, 'name', v_name, 'reason', trim(p_reason),
                                               'given', coalesce(v_m.quantity_given, 0),
                                               'remaining', v_left,
                                               'requestId', v_m.id,
                                               -- the pharmacy has not enough (unexpired) for what remains
                                               'noStock', v_main is null or usable_stock(v_m.item_id, v_main) < v_left,
                                               -- nothing given yet: the prescriber may send it outside
                                               'outside', coalesce(v_m.quantity_given, 0) = 0),
            '/app/visit?encounter=' || v_m.encounter_id, coalesce(v_m.prescriber_id, v_m.created_by), auth.uid());
  end if;
  perform after_pharmacy(v_m.encounter_id);
end
$$;

-- dispense_prescription (from 20261207090000_pharmacy_simplified): never a line bought outside.
create or replace function dispense_prescription(
  p_medication_request_id uuid, p_location_id uuid default null, p_quantity integer default null
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_loc uuid;
  v_dispense uuid;
  v_charged boolean := false;
  v_whole integer;
  v_left integer;
  v_give integer;
  v_charge numeric;
  v_done boolean;
  v_to uuid;
  v_name text;
begin
  perform assert_desk(array['pharmacy'], 'the pharmacy');
  select * into v_m from medication_request where id = p_medication_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  if v_m.supply = 'outside' then
    raise exception 'this medicine is bought at an outside pharmacy: the clinic does not give it' using errcode = '23505';
  end if;
  if v_m.cancelled_at is not null then
    raise exception 'the doctor cancelled this medicine' using errcode = '23505';
  end if;
  v_whole := ceil(v_m.quantity)::integer;
  v_left := v_whole - coalesce(v_m.quantity_given, 0);
  if v_m.given_at is not null or v_left <= 0
     or (coalesce(v_m.quantity_given, 0) = 0 and exists (
           select 1 from medication_dispense d where d.medication_request_id = v_m.id and d.deleted_at is null)) then
    raise exception 'already dispensed' using errcode = '23505';
  end if;
  if v_m.not_given_at is not null then
    raise exception 'this medicine was marked as not given' using errcode = '23505';
  end if;
  if p_quantity is not null and p_quantity <= 0 then
    raise exception 'quantity must be more than zero' using errcode = '22023';
  end if;
  if p_quantity is not null and p_quantity > v_left then
    raise exception 'only % left to give of this medicine', v_left using errcode = '22023', hint = 'more_than_remaining';
  end if;
  -- The prescription is final once the doctor has finished (or sent the patient on). A sale written
  -- by the pharmacist themself is not held.
  if coalesce(v_m.prescriber_id, v_m.created_by) is distinct from auth.uid() and doctor_holds(v_m.encounter_id) then
    raise exception 'the doctor is still seeing this patient: hand the medicines over when the doctor has finished'
      using errcode = 'MS002', hint = 'doctor_holds';
  end if;
  if p_location_id is not null then
    if not exists (select 1 from stock_location where id = p_location_id and type = 'pharmacy'
                   and active and deleted_at is null) then
      raise exception 'choose an open pharmacy store' using errcode = '22023';
    end if;
    v_loc := p_location_id;
  else
    v_loc := main_pharmacy();
  end if;
  if v_loc is null then
    raise exception 'no pharmacy store yet: create one under Stock' using errcode = 'P0002';
  end if;
  v_give := coalesce(p_quantity, v_left);
  v_done := v_give = v_left;
  v_dispense := dispense_fefo(v_m.encounter_id, v_m.item_id, v_give, v_loc, v_m.id, null);
  -- the bill charges what is given; the last part charges what remains of the prescribed quantity
  v_charge := case when v_done then v_m.quantity - coalesce(v_m.quantity_given, 0) else v_give end;
  -- no price: handed over free (charged = false); no open bill: refused (MS001)
  begin
    perform add_charge_internal(v_m.encounter_id, 'pharmacy'::station, null, v_m.item_id, v_charge,
                       null, null, null, null, 'medication_dispense', v_dispense);
    v_charged := true;
  exception when sqlstate 'P0002' then
    v_charged := false;
  end;
  update medication_request
  set quantity_given = coalesce(quantity_given, 0) + v_give,
      given_at = case when v_done then now() end,
      given_by = case when v_done then auth.uid() end
  where id = v_m.id;
  -- part given: the prescriber is told what was given and what remains
  if not v_done then
    v_to := coalesce(v_m.prescriber_id, v_m.created_by);
    if v_to is not null and v_to is distinct from auth.uid() then
      select p.surname || ' ' || p.given_names into v_name
      from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
      insert into notification (kind, params, link, recipient_user, created_by)
      values ('rx_part_given',
              jsonb_build_object('item', item_label(v_m.item_id), 'name', v_name,
                                 'given', coalesce(v_m.quantity_given, 0) + v_give, 'remaining', v_left - v_give,
                                 'quantity', v_whole, 'requestId', v_m.id),
              '/app/visit?encounter=' || v_m.encounter_id, v_to, auth.uid());
    end if;
  end if;
  -- the last line handed over: on to the cashier (money due) or the visit closes
  perform after_pharmacy(v_m.encounter_id);
  perform stock_alert_run();
  return jsonb_build_object('dispenseId', v_dispense, 'charged', v_charged, 'locationId', v_loc,
                            'given', v_give, 'givenTotal', coalesce(v_m.quantity_given, 0) + v_give,
                            'remaining', v_left - v_give, 'quantity', v_whole);
end
$$;

-- ---------------------------------------------------------------- cancel
-- From 20261202090000_security_hardening: an outside line may be cancelled too (wrong medicine).
create or replace function cancel_prescription(p_request_id uuid, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_m medication_request%rowtype;
  v_item text;
  v_name text;
  v_left integer;
  v_waiting boolean;
begin
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'say why the medicine is cancelled' using errcode = '22023';
  end if;
  select * into v_m from medication_request where id = p_request_id and deleted_at is null for update;
  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;
  if not (is_manager()
          or (has_perm('clinical.write')
              and (coalesce(v_m.prescriber_id, v_m.created_by) = auth.uid()
                   -- the patient was handed over: the colleague who took them now decides
                   or (may_work_on(v_m.encounter_id)
                       and result_recipient(v_m.encounter_id, coalesce(v_m.prescriber_id, v_m.created_by)) = auth.uid())))) then
    raise exception 'only the doctor treating the patient (or the manager) can cancel it' using errcode = '42501';
  end if;
  perform assert_desk(treating_desks(), 'treatment');
  v_waiting := rx_pending(v_m);
  if not (v_waiting or (v_m.supply = 'outside' and v_m.cancelled_at is null)) then
    raise exception 'this medicine is no longer waiting at the pharmacy (handed over, not given or cancelled)'
      using errcode = 'P0002';
  end if;
  update medication_request
  set cancelled_at = now(), cancelled_by = auth.uid(), cancel_reason = trim(p_reason)
  where id = v_m.id;
  if v_waiting then
    -- the pharmacy is told the line left its list
    v_item := rx_label(v_m);
    select p.surname || ' ' || p.given_names into v_name
    from encounter e join patient p on p.id = e.patient_id where e.id = v_m.encounter_id;
    insert into notification (kind, params, link, recipient_stations, created_by)
    values ('rx_cancelled',
            jsonb_build_object('item', v_item, 'name', v_name, 'reason', trim(p_reason),
                               'by', (select full_name from profiles where id = auth.uid())),
            '/app/visit?encounter=' || v_m.encounter_id, array['pharmacy'::station], auth.uid());
    -- nothing left at the pharmacy: the patient goes on (back, cashier, or the visit closes)
    perform after_pharmacy(v_m.encounter_id);
  end if;
  select count(*)::integer into v_left from medication_request m
  where m.encounter_id = v_m.encounter_id and rx_pending(m);
  return jsonb_build_object('id', v_m.id, 'pending', v_left,
                            'balance', invoice_balance((select id from invoice where encounter_id = v_m.encounter_id)));
end
$$;

-- ---------------------------------------------------------------- the stock the prescriber sees
-- { locationId, items: { itemId: usable units } } at the main pharmacy (not expired); an item
-- missing from `items` has none.
create or replace function rx_stock()
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_loc uuid := main_pharmacy();
begin
  if not (has_perm('clinical.write') or has_perm('stock.read') or is_manager()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'locationId', v_loc,
    'items', coalesce((
      select jsonb_object_agg(x.item_id, x.n)
      from (select s.item_id, sum(s.quantity)::integer as n from stock_on_hand s
            where s.location_id = v_loc and s.quantity > 0 and (s.expiry is null or s.expiry >= current_date)
            group by s.item_id) x), '{}'::jsonb));
end
$$;

-- ---------------------------------------------------------------- "Prescribed but bought outside"
create or replace function rx_bought_outside(p_from date, p_to date)
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
begin
  if not (has_perm('stock.read') and stock_admin()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_to < p_from then
    raise exception 'the end of the period is before its start' using errcode = '22023';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
        'name', x.name, 'itemId', x.item_id, 'referenceCode', x.code, 'inClinic', x.item_id is not null,
        'times', x.times, 'quantity', x.quantity, 'patients', x.patients, 'lastAt', x.last_at,
        'notGiven', x.not_given)
      order by x.times desc, x.quantity desc, x.name)
    from (
      select min(rx_label(m)) as name, m.item_id, min(m.reference_code) as code,
             count(*)::integer as times, sum(m.quantity) as quantity,
             count(distinct e.patient_id)::integer as patients, max(m.created_at) as last_at,
             -- sent outside after the pharmacy had none
             count(*) filter (where m.not_given_at is not null)::integer as not_given
      from medication_request m join encounter e on e.id = m.encounter_id
      where m.deleted_at is null and m.supply = 'outside' and m.cancelled_at is null
        and (m.created_at at time zone 'Africa/Kigali')::date between p_from and p_to
      group by m.item_id, case when m.item_id is null then lower(coalesce(m.reference_code, rx_label(m))) end
    ) x), '[]'::jsonb);
end
$$;

-- ---------------------------------------------------------------- readers of prescriptions
-- visit_clinical (from 20261203090000_guide_fixes): a line without a clinic medicine, and the
-- decision (who, when, why).
create or replace function visit_clinical(p_encounter_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_view text;
  v_patient uuid;
  v_closed boolean;
  v_safe boolean;
begin
  -- clinicians; the lab and the pharmacy read the record too (their orders and prescriptions)
  if not clinical_reader() then
    return null;
  end if;
  select e.patient_id, e.status = 'closed' into v_patient, v_closed
  from encounter e where e.id = p_encounter_id and e.deleted_at is null;
  if v_patient is null then
    return null;
  end if;
  v_view := visit_view(p_encounter_id);
  if v_view is null then
    v_safe := patient_level(v_patient) <> 'identity';
    return jsonb_build_object(
      'diagnoses', '[]'::jsonb, 'notes', '[]'::jsonb, 'prescriptions', '[]'::jsonb, 'orders', '[]'::jsonb,
      'patient', (select jsonb_build_object('id', p.id,
                    'allergies', case when v_safe then p.allergies end,
                    'bloodGroup', case when v_safe then p.blood_group end,
                    'notes', case when v_safe then p.notes end,
                    'flags', case when v_safe then p.flags else '{}'::jsonb end)
                  || case when v_safe then doc_patient(p.id, p_encounter_id)
                          else doc_patient(p.id, p_encounter_id) - 'allergies' - 'allergiesNone' - 'bloodGroup'
                               - 'weightKg' - 'weightAt' end
                  from patient p where p.id = v_patient),
      'visit', doc_visit(p_encounter_id),
      'private', true,
      'view', null,
      'access', patient_access(v_patient));
  end if;
  if v_closed then
    perform log_record_access(v_patient, p_encounter_id, v_view, 'visit');
  end if;
  return jsonb_build_object(
    'diagnoses', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'text', c.text, 'icd10', c.icd10_code, 'type', c.type, 'provisional', c.provisional, 'at', c.created_at,
        'by', (select full_name from profiles where id = c.created_by)) order by c.created_at)
      from condition c where c.encounter_id = p_encounter_id and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'))), '[]'::jsonb),
    'notes', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'text', o.value_text, 'at', o.effective_at,
        'by', (select full_name from profiles where id = o.performer_id)) order by o.effective_at)
      from observation o where o.encounter_id = p_encounter_id and o.code = 'note' and o.deleted_at is null), '[]'::jsonb),
    'prescriptions', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'by', (select full_name from profiles where id = coalesce(m.prescriber_id, m.created_by)), 'item', rx_label(m), 'dose', m.dose, 'route', m.route,
        'frequency', m.frequency, 'days', m.duration_days, 'quantity', m.quantity, 'instructions', m.instructions, 'at', m.created_at,
        'dispensed', m.supply = 'room' or exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null),
        'supply', m.supply, 'givenAt', m.given_at, 'givenBy', (select full_name from profiles where id = m.given_by),
        'notGivenAt', m.not_given_at, 'notGivenReason', m.not_given_reason,
        'prescriberId', coalesce(m.prescriber_id, m.created_by), 'pending', rx_pending(m),
        'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
        'cancelledBy', (select full_name from profiles where id = m.cancelled_by),
        'itemId', m.item_id, 'referenceCode', m.reference_code, 'quantityGiven', coalesce(m.quantity_given, 0),
        'supplySetAt', m.supply_set_at, 'supplySetBy', (select full_name from profiles where id = m.supply_set_by),
        'supplyReason', m.supply_reason,
        'prescriber', doc_person(coalesce(m.prescriber_id, m.created_by))) order by m.created_at)
      from medication_request m where m.encounter_id = p_encounter_id and m.deleted_at is null), '[]'::jsonb),
    -- HIV tests (like the diagnoses above) only for the people allowed to see them
    'orders', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'test', s.name_en, 'category', r.category, 'station', coalesce(r.station, case when r.category = 'imaging' then 'ultrasound'::station else 'laboratory'::station end), 'status', r.status, 'reason', r.reason, 'at', r.created_at, 'mine', coalesce(r.requester_id = auth.uid(), false),
        'result', (select jsonb_build_object('findings', d.findings, 'impression', d.impression, 'verified', d.verified_at is not null,
          'corrected', d.corrected_at is not null, 'correctionReason', d.correction_reason,
          'at', coalesce(d.verified_at, d.updated_at), 'by', (select full_name from profiles where id = coalesce(d.verified_by, d.created_by)),
          'byPerson', doc_person(coalesce(d.verified_by, d.created_by)))
          from diagnostic_report d where d.service_request_id = r.id and d.deleted_at is null)) order by r.created_at)
      from service_request r join service s on s.id = r.service_id
      where r.encounter_id = p_encounter_id and r.deleted_at is null
        and (has_perm('sensitive.read') or not sensitive_service(s.id))), '[]'::jsonb),
    'patient', (select jsonb_build_object('id', p.id, 'allergies', p.allergies, 'bloodGroup', p.blood_group, 'notes', p.notes, 'flags', p.flags)
                       || doc_patient(p.id, e.id)
      from encounter e join patient p on p.id = e.patient_id where e.id = p_encounter_id),
    'visit', doc_visit(p_encounter_id),
    'private', false,
    'view', v_view
  );
end
$$;

-- visit_journey (from 20261130090000_patient_privacy): every medicine, outside ones too.
create or replace function visit_journey(p_encounter_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_steps jsonb;
  v_vitals jsonb := '[]'::jsonb;
  v_dx jsonb := '[]'::jsonb;
  v_meds jsonb := '[]'::jsonb;
  v_tests jsonb := '[]'::jsonb;
  v_charges jsonb;
  v_payments jsonb;
  v_bill jsonb;
  v_enc encounter%rowtype;
  v_view text;
  v_handovers jsonb;
begin
  if not has_perm('patient.read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_enc from encounter where id = p_encounter_id and deleted_at is null;
  if not found then
    raise exception 'visit not found' using errcode = 'P0002';
  end if;
  v_view := case when clinical_reader() then visit_view(p_encounter_id) end;

  select coalesce(jsonb_agg(jsonb_build_object(
      'station', q.station, 'queuedAt', q.created_at, 'calledAt', q.called_at, 'startedAt', q.started_at,
      'finishedAt', q.finished_at, 'takenBy', tb.full_name, 'assignedTo', asg.full_name,
      'referredBy', rb.full_name, 'note', case when v_view is not null then q.referral_note end,
      'enteredBy', eb.full_name,
      'service', q.service, 'department', (select d.name from department d where d.id = q.department_id)
    ) order by q.created_at), '[]'::jsonb) into v_steps
  from queue_entry q
  left join profiles tb on tb.id = q.taken_by
  left join profiles asg on asg.id = q.assigned_to
  left join profiles rb on rb.id = q.referred_by
  left join profiles eb on eb.id = q.entered_by
  where q.encounter_id = p_encounter_id and q.deleted_at is null;

  if v_view is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
        'code', o.code, 'value', o.value_num, 'unit', o.unit, 'at', o.effective_at,
        'by', (select full_name from profiles where id = o.performer_id)
      ) order by o.effective_at), '[]'::jsonb) into v_vitals
    from observation o where o.encounter_id = p_encounter_id and o.deleted_at is null and o.code <> 'note';

    select coalesce(jsonb_agg(jsonb_build_object(
        'text', c.text, 'icd10', c.icd10_code, 'type', c.type, 'provisional', c.provisional, 'at', c.created_at,
        'by', (select full_name from profiles where id = c.created_by)
      ) order by c.created_at), '[]'::jsonb) into v_dx
    from condition c where c.encounter_id = p_encounter_id and c.deleted_at is null and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'));

    select coalesce(jsonb_agg(jsonb_build_object(
        'item', rx_label(m), 'quantity', m.quantity, 'dose', m.dose,
        'frequency', m.frequency, 'days', m.duration_days, 'supply', m.supply, 'givenAt', m.given_at,
        'givenBy', (select full_name from profiles where id = m.given_by), 'at', m.created_at,
        'by', (select full_name from profiles where id = m.created_by),
        'dispensed', exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null),
        'notGivenAt', m.not_given_at, 'notGivenReason', m.not_given_reason,
        'notGivenBy', (select full_name from profiles where id = m.not_given_by),
        'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
        'cancelledBy', (select full_name from profiles where id = m.cancelled_by)
      ) order by m.created_at), '[]'::jsonb) into v_meds
    from medication_request m
    where m.encounter_id = p_encounter_id and m.deleted_at is null;

    select coalesce(jsonb_agg(jsonb_build_object(
        'test', s.name_en, 'status', r.status, 'priority', r.priority, 'at', r.created_at,
        'by', (select full_name from profiles where id = r.created_by),
        'result', (select coalesce(dr.impression, dr.findings) from diagnostic_report dr where dr.service_request_id = r.id and dr.deleted_at is null order by dr.created_at desc limit 1)
      ) order by r.created_at), '[]'::jsonb) into v_tests
    from service_request r left join service s on s.id = r.service_id
    where r.encounter_id = p_encounter_id and r.deleted_at is null;

    if v_enc.status = 'closed' then
      perform log_record_access(v_enc.patient_id, p_encounter_id, v_view, 'journey');
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'description', l.description, 'quantity', l.quantity, 'unitPrice', l.unit_price,
      'total', round(l.quantity * l.unit_price), 'office', l.office, 'at', l.created_at,
      'by', (select full_name from profiles where id = l.entered_by)
    ) order by l.created_at), '[]'::jsonb) into v_charges
  from invoice_line l join invoice i on i.id = l.invoice_id
  where i.encounter_id = p_encounter_id and l.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'amount', p.amount, 'method', p.method, 'reference', p.reference, 'at', p.paid_at,
      'by', (select full_name from profiles where id = p.cashier_id)
    ) order by p.paid_at), '[]'::jsonb) into v_payments
  from payment p join invoice i on i.id = p.invoice_id
  where i.encounter_id = p_encounter_id and p.deleted_at is null;

  select jsonb_build_object('status', b.status, 'total', b.total, 'balance', b.balance, 'paid', b.paid,
                            'number', b.number, 'settledBy', b.settled_by, 'settledAt', b.settled_at)
  into v_bill from visit_bill b where b.encounter_id = p_encounter_id;

  -- who handed the patient over to whom (20261129090000_handover); the note and the reason are
  -- clinical: for the two colleagues and those who may see this visit's record
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', h.id, 'station', h.station, 'at', h.created_at, 'from', f.full_name, 'to', t.full_name,
      'note', case when v_view is not null or auth.uid() in (h.from_user, h.to_user) then h.note end,
      'status', h.status, 'answeredAt', h.answered_at,
      'answeredBy', (select full_name from profiles where id = h.answered_by),
      'reason', case when v_view is not null or auth.uid() in (h.from_user, h.to_user) then h.reason end
    ) order by h.created_at), '[]'::jsonb) into v_handovers
  from patient_handover h
  join profiles f on f.id = h.from_user
  join profiles t on t.id = h.to_user
  where h.encounter_id = p_encounter_id and h.deleted_at is null;

  return jsonb_build_object(
    'encounterId', v_enc.id, 'arrivedAt', v_enc.arrived_at, 'status', v_enc.status, 'closedAt', v_enc.closed_at,
    'triage', v_enc.triage_level,
    'triageReason', case when v_view is not null then v_enc.triage_reason end,
    'closedBy', (select full_name from profiles where id = v_enc.closed_by),
    -- the track: treatment finished, why the patient left, what they came for
    'treatmentDoneAt', v_enc.clinical_done_at, 'leftReason', v_enc.left_reason, 'service', v_enc.service,
    'steps', v_steps, 'vitals', v_vitals, 'diagnoses', v_dx, 'medicines', v_meds, 'tests', v_tests,
    'charges', v_charges, 'payments', v_payments, 'bill', v_bill, 'handovers', v_handovers,
    'private', v_view is null
  );
end
$$;

-- patient_safety_summary (from 20261130090000_patient_privacy): medicines bought outside count as
-- medicines the patient takes.
create or replace function patient_safety_summary(p_patient_id uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'allergies', p.allergies,
    'allergiesNone', coalesce(p.allergies_none, false) and p.allergies is null,
    'bloodGroup', p.blood_group,
    'alerts', p.notes,
    'flags', p.flags,
    -- long-lasting conditions: a chronic ICD-10 group, or the same diagnosis on two visits
    'chronic', coalesce((
      select jsonb_agg(jsonb_build_object('text', x.text, 'icd10', x.icd10_code, 'since', x.first_at, 'lastAt', x.created_at)
                       order by x.created_at desc)
      from (
        select distinct on (lower(c.text)) c.text, c.icd10_code, c.created_at,
               min(c.created_at) over (partition by lower(c.text)) as first_at
        from condition c join encounter e on e.id = c.encounter_id and e.deleted_at is null
        where e.patient_id = p.id and c.deleted_at is null
          and (coalesce(c.icd10_code, '') !~ '^B2[0-4]' or has_perm('sensitive.read'))
          and (coalesce(c.icd10_code, '') ~ '^(I1[0-5]|I25|I50|E0[3-5]|E1[0-4]|J4[45]|G40|N18|B18|B2[0-4]|F2[0-9]|F3[1-3])'
               or (select count(distinct c2.encounter_id) from condition c2
                   join encounter e2 on e2.id = c2.encounter_id and e2.deleted_at is null
                   where e2.patient_id = p.id and c2.deleted_at is null and lower(c2.text) = lower(c.text)) >= 2)
        order by lower(c.text), c.created_at desc
      ) x), '[]'::jsonb),
    -- medicines of the open visit, and those still running (prescribed days not over)
    'medications', coalesce((
      select jsonb_agg(jsonb_build_object(
          'item', rx_label(m), 'dose', m.dose, 'frequency', m.frequency,
          'days', m.duration_days, 'at', m.created_at, 'outside', m.supply = 'outside',
          'until', case when m.duration_days is not null then m.created_at + make_interval(days => m.duration_days) end,
          'by', (select full_name from profiles where id = coalesce(m.prescriber_id, m.created_by)))
        order by m.created_at desc)
      from medication_request m
      join encounter e on e.id = m.encounter_id and e.deleted_at is null
      where e.patient_id = p.id and m.deleted_at is null and m.cancelled_at is null
        and (m.not_given_at is null or m.supply = 'outside')
        and m.created_at > now() - interval '180 days'
        and (e.status = 'open' or m.created_at + make_interval(days => coalesce(m.duration_days, 0)) >= now())), '[]'::jsonb),
    'lastVitals', coalesce((
      select jsonb_agg(jsonb_build_object('code', v.code, 'value', v.value_num, 'unit', v.unit, 'at', v.effective_at,
                                          'by', (select full_name from profiles where id = v.performer_id))
                       order by v.code)
      from (
        select distinct on (o.code) o.code, o.value_num, o.unit, o.effective_at, o.performer_id
        from observation o join encounter e on e.id = o.encounter_id and e.deleted_at is null
        where e.patient_id = p.id and o.deleted_at is null and o.code <> 'note' and o.value_num is not null
        order by o.code, o.effective_at desc
      ) v), '[]'::jsonb),
    'lastVisitAt', (select max(e.arrived_at) from encounter e where e.patient_id = p.id and e.deleted_at is null)
  )
  from patient p where p.id = p_patient_id
$$;

-- my_prescriptions (from 20261123090000_dispensing_fixes): outside lines, state 'outside'.
create or replace function my_prescriptions(p_days integer default 7, p_from date default null, p_to date default null)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(x.j order by x.at desc), '[]'::jsonb)
  from (
    select m.created_at as at, jsonb_build_object(
      'id', m.id, 'encounterId', m.encounter_id, 'patientId', p.id,
      'patient', p.surname || ' ' || p.given_names, 'fileNumber', p.file_number,
      'item', rx_label(m), 'quantity', m.quantity,
      'dose', m.dose, 'frequency', m.frequency, 'days', m.duration_days, 'instructions', m.instructions,
      'supply', m.supply, 'at', m.created_at,
      'state', case
                 when m.cancelled_at is not null then 'cancelled'
                 when m.supply = 'outside' then 'outside'
                 when m.not_given_at is not null then 'not_given'
                 when m.supply = 'room' then 'room'
                 when m.given_at is not null
                      or exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null)
                   then 'given'
                 else 'waiting' end,
      'givenAt', m.given_at, 'notGivenReason', m.not_given_reason,
      'cancelledAt', m.cancelled_at, 'cancelReason', m.cancel_reason,
      'visitOpen', e.status = 'open') as j
    from medication_request m
    join encounter e on e.id = m.encounter_id
    join patient p on p.id = e.patient_id
    where m.deleted_at is null and coalesce(m.prescriber_id, m.created_by) = auth.uid()
      and case when p_from is not null
            then (m.created_at at time zone 'Africa/Kigali')::date between p_from and coalesce(p_to, p_from)
            else m.created_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 90))) end
    order by m.created_at desc
    limit 500
  ) x
$$;

revoke all on function rx_label(medication_request), rx_rule_warnings(text, uuid) from public, anon;
grant execute on function rx_label(medication_request), rx_rule_warnings(text, uuid) to authenticated;
revoke all on function prescribe(uuid, uuid, numeric, text, text, text, integer, text, text, station, uuid, text, text),
  rx_set_supply(uuid, text, text), rx_stock(), rx_bought_outside(date, date) from public, anon;
grant execute on function prescribe(uuid, uuid, numeric, text, text, text, integer, text, text, station, uuid, text, text),
  rx_set_supply(uuid, text, text), rx_stock(), rx_bought_outside(date, date) to authenticated;

-- analytics_staff_events (from 20261127090000_analytics): a medicine bought outside that is not
-- in the clinic's list has no item; its typed name shows instead of an empty line.
create or replace function analytics_staff_events(p_start timestamptz, p_end timestamptz, p_money boolean)
returns table (user_id uuid, at timestamptz, kind text, encounter_id uuid, patient_id uuid, amount numeric, what text)
language sql stable security definer set search_path = public
as $$
  -- registered
  select x.created_by, x.created_at, 'registered', null::uuid, x.id, null::numeric, null::text
  from patient x
  where x.deleted_at is null and x.created_by is not null and x.created_at >= p_start and x.created_at < p_end
  union all
  -- vitals, one per visit
  select v.u, v.at, 'vitals', v.enc, e.patient_id, null, null
  from (select o.performer_id as u, o.encounter_id as enc, min(o.effective_at) as at
        from observation o
        where o.deleted_at is null and o.code <> 'note' and o.performer_id is not null
          and o.effective_at >= p_start and o.effective_at < p_end
        group by 1, 2) v
  join encounter e on e.id = v.enc
  union all
  -- patients seen: took the patient from a queue, or wrote on the visit
  select s.u, s.at, 'patientsSeen', s.enc, e.patient_id, null, e.reference
  from (select a.u, a.enc, min(a.at) as at
        from (
          select q.taken_by as u, q.encounter_id as enc, coalesce(q.started_at, q.finished_at, q.created_at) as at
          from queue_entry q where q.deleted_at is null and q.taken_by is not null
          union all
          select c.created_by, c.encounter_id, c.created_at from condition c where c.deleted_at is null
          union all
          select m.prescriber_id, m.encounter_id, m.created_at from medication_request m where m.deleted_at is null
          union all
          select r.requester_id, r.encounter_id, r.created_at from service_request r where r.deleted_at is null
          union all
          select o.performer_id, o.encounter_id, o.effective_at from observation o where o.deleted_at is null and o.code = 'note'
          union all
          select x.performer_id, x.encounter_id, coalesce(x.performed_at, x.created_at) from procedure x where x.deleted_at is null
        ) a
        where a.u is not null and a.enc is not null and a.at >= p_start and a.at < p_end
        group by 1, 2) s
  join encounter e on e.id = s.enc
  union all
  -- diagnoses
  select c.created_by, c.created_at, 'diagnoses', c.encounter_id, e.patient_id, null,
         trim(coalesce(c.icd10_code || ' ', '') || coalesce(c.text, ''))
  from condition c join encounter e on e.id = c.encounter_id
  where c.deleted_at is null and c.created_by is not null and c.created_at >= p_start and c.created_at < p_end
  union all
  -- prescriptions
  select m.prescriber_id, m.created_at, 'prescriptions', m.encounter_id, e.patient_id, null,
         coalesce(item_label(m.item_id), m.medicine_name) || coalesce(' · ' || nullif(m.dose, ''), '')
  from medication_request m join encounter e on e.id = m.encounter_id
  where m.deleted_at is null and m.prescriber_id is not null and m.created_at >= p_start and m.created_at < p_end
  union all
  -- test orders
  select r.requester_id, r.created_at, 'orders', r.encounter_id, e.patient_id, null, sv.name_en
  from service_request r join encounter e on e.id = r.encounter_id left join service sv on sv.id = r.service_id
  where r.deleted_at is null and r.requester_id is not null and r.created_at >= p_start and r.created_at < p_end
  union all
  -- results (verified, else typed)
  select coalesce(d.verified_by, d.created_by), coalesce(d.verified_at, d.created_at), 'results', r.encounter_id, e.patient_id, null, sv.name_en
  from diagnostic_report d
  join service_request r on r.id = d.service_request_id
  join encounter e on e.id = r.encounter_id
  left join service sv on sv.id = r.service_id
  where d.deleted_at is null and coalesce(d.verified_by, d.created_by) is not null
    and coalesce(d.verified_at, d.created_at) >= p_start and coalesce(d.verified_at, d.created_at) < p_end
  union all
  -- procedures
  select x.performer_id, coalesce(x.performed_at, x.created_at), 'procedures', x.encounter_id, e.patient_id, null, sv.name_en
  from procedure x join encounter e on e.id = x.encounter_id left join service sv on sv.id = x.service_id
  where x.deleted_at is null and x.performer_id is not null
    and coalesce(x.performed_at, x.created_at) >= p_start and coalesce(x.performed_at, x.created_at) < p_end
  union all
  -- medicines given: handed over at the pharmacy …
  select md.dispenser_id, md.created_at, 'medicinesGiven', md.encounter_id, e.patient_id, null,
         item_label(md.item_id) || ' × ' || trim_scale(md.quantity)::text
  from medication_dispense md left join encounter e on e.id = md.encounter_id
  where md.deleted_at is null and md.dispenser_id is not null and md.created_at >= p_start and md.created_at < p_end
  union all
  -- … and given from a room store (a pharmacy hand-over also sets given_by: it is counted above,
  -- through its medication_dispense row, so only requests without one come from here)
  select m.given_by, m.given_at, 'medicinesGiven', m.encounter_id, e.patient_id, null, coalesce(item_label(m.item_id), m.medicine_name)
  from medication_request m join encounter e on e.id = m.encounter_id
  where m.deleted_at is null and m.given_by is not null and m.given_at >= p_start and m.given_at < p_end
    and not exists (select 1 from medication_dispense d where d.medication_request_id = m.id and d.deleted_at is null)
  union all
  -- charges
  select l.entered_by, l.created_at, 'charges', i.encounter_id, e.patient_id, round(l.unit_price * l.quantity), l.description
  from invoice_line l join invoice i on i.id = l.invoice_id left join encounter e on e.id = i.encounter_id
  where l.deleted_at is null and l.entered_by is not null and l.created_at >= p_start and l.created_at < p_end
  union all
  -- admissions
  select b.created_by, coalesce(b.admitted_at, b.created_at), 'admissions', b.encounter_id, e.patient_id, null, bd.name
  from bed_stay b join encounter e on e.id = b.encounter_id left join bed bd on bd.id = b.bed_id
  where b.deleted_at is null and b.created_by is not null
    and coalesce(b.admitted_at, b.created_at) >= p_start and coalesce(b.admitted_at, b.created_at) < p_end
  union all
  -- tasks done
  select k.done_by, k.done_at, 'tasksDone', k.encounter_id, k.patient_id, null, k.title
  from internal_task k
  where k.deleted_at is null and k.done_by is not null and k.done_at >= p_start and k.done_at < p_end
  union all
  select v.created_by, v.created_at, 'vaccinations', v.encounter_id, v.patient_id, null, v.vaccine
  from vaccination v
  where v.deleted_at is null and v.created_by is not null and v.created_at >= p_start and v.created_at < p_end
  union all
  -- an HIV test: never its result
  select h.created_by, coalesce(h.tested_at, h.created_at), 'hivTests', h.encounter_id, h.patient_id, null, null
  from hiv_test h
  where h.deleted_at is null and h.created_by is not null
    and coalesce(h.tested_at, h.created_at) >= p_start and coalesce(h.tested_at, h.created_at) < p_end
  union all
  select f.created_by, f.created_at, 'familyPlanning', f.encounter_id, f.patient_id, null, f.method
  from fp_event f
  where f.deleted_at is null and f.created_by is not null and f.created_at >= p_start and f.created_at < p_end
  union all
  -- money (the manager only)
  select y.cashier_id, y.paid_at, 'payments', i.encounter_id, e.patient_id, y.amount, y.method::text
  from payment y left join invoice i on i.id = y.invoice_id left join encounter e on e.id = i.encounter_id
  where p_money and y.deleted_at is null and y.cashier_id is not null and y.paid_at >= p_start and y.paid_at < p_end
  union all
  select rf.cashier_id, rf.refunded_at, 'refunds', i.encounter_id, e.patient_id, rf.amount, rf.reason
  from refund rf join invoice i on i.id = rf.invoice_id left join encounter e on e.id = i.encounter_id
  where p_money and rf.deleted_at is null and rf.cashier_id is not null and rf.refunded_at >= p_start and rf.refunded_at < p_end
  union all
  select y.voided_by, y.voided_at, 'voided', i.encounter_id, e.patient_id, y.amount, y.void_reason
  from payment y left join invoice i on i.id = y.invoice_id left join encounter e on e.id = i.encounter_id
  where p_money and y.voided_by is not null and y.voided_at >= p_start and y.voided_at < p_end
  union all
  select cs.handed_over_by, cs.handed_over_at, 'handovers', null, null, cs.total, cs.number
  from counter_sale cs
  where p_money and cs.deleted_at is null and cs.handed_over_by is not null
    and cs.handed_over_at >= p_start and cs.handed_over_at < p_end
$$;
revoke all on function analytics_staff_events(timestamptz, timestamptz, boolean) from public, anon, authenticated;


